/// Windows clipboard text ends its lines with CRLF; the core, and whatever
/// reads an OSC 52 reply, expect LF. A paste turns each LF into one CR, the
/// shell's Enter, so a CRLF left in place arrived as two: an extra empty line
/// after every pasted one, which cmd answers with an extra prompt. Takes
/// ownership of `text` and returns it, or a replacement when it had a CRLF.
pub fn lfLineEndings(alloc: std.mem.Allocator, text: [:0]u8) ![:0]u8 {
    const size = std.mem.replacementSize(u8, text, "\r\n", "\n");
    if (size == text.len) return text;
    defer alloc.free(text);
    const out = try alloc.allocSentinel(u8, size, 0);
    _ = std.mem.replace(u8, text, "\r\n", "\n", out);
    return out;
}

test "win32 clipboard text gets LF line endings" {
    const alloc = std.testing.allocator;

    const crlf = try lfLineEndings(alloc, try alloc.dupeZ(u8, "cd x\r\nnu\r\n"));
    defer alloc.free(crlf);
    try std.testing.expectEqualStrings("cd x\nnu\n", crlf);

    // A lone CR or LF is left alone, and text without a CRLF is returned as is.
    const plain = try alloc.dupeZ(u8, "a\rb\nc");
    const same = try lfLineEndings(alloc, plain);
    defer alloc.free(same);
    try std.testing.expectEqual(plain.ptr, same.ptr);
    try std.testing.expectEqualStrings("a\rb\nc", same);
}

/// The other direction: the core joins copied lines with LF, and classic
/// Win32 controls (an EDIT, older apps) show an LF-only CF_UNICODETEXT on
/// one line. Returns null when `text` has no bare LF to expand.
pub fn crlfLineEndings(alloc: std.mem.Allocator, text: []const u8) !?[]u8 {
    var bare: usize = 0;
    for (0..text.len) |i| {
        if (isBareLf(text, i)) bare += 1;
    }
    if (bare == 0) return null;
    const out = try alloc.alloc(u8, text.len + bare);
    var o: usize = 0;
    for (text, 0..) |byte, i| {
        if (isBareLf(text, i)) {
            out[o] = '\r';
            o += 1;
        }
        out[o] = byte;
        o += 1;
    }
    return out;
}

fn isBareLf(text: []const u8, i: usize) bool {
    return text[i] == '\n' and (i == 0 or text[i - 1] != '\r');
}

test "win32 clipboard writes get CRLF line endings" {
    const alloc = std.testing.allocator;

    const crlf = (try crlfLineEndings(alloc, "\na\nb\r\nc\n")).?;
    defer alloc.free(crlf);
    try std.testing.expectEqualStrings("\r\na\r\nb\r\nc\r\n", crlf);

    // Nothing to expand: a CRLF stays one, and a lone CR is left alone.
    try std.testing.expectEqual(@as(?[]u8, null), try crlfLineEndings(alloc, "a\r\nb\rc"));
}

/// The clipboard as UTF-8, for any UTF-16 another program put there. A
/// strict conversion failed the whole paste on one unpaired surrogate (a
/// cut emoji); each one becomes U+FFFD instead, which is also 3 bytes, so
/// the lossy pass runs in place.
pub fn clipboardTextToUtf8(alloc: std.mem.Allocator, text_w: []const u16) ![:0]u8 {
    const text = try std.unicode.wtf16LeToWtf8AllocZ(alloc, text_w);
    std.unicode.wtf8ToUtf8Lossy(text, text) catch unreachable; // WTF-16 always gives WTF-8
    return text;
}

test "win32 clipboard text with a lone surrogate still pastes" {
    const alloc = std.testing.allocator;
    const text = try clipboardTextToUtf8(alloc, &.{ 'a', 0xD83D, 'b', 0xD83D, 0xDE00, 0xDE00 });
    defer alloc.free(text);
    try std.testing.expectEqualStrings("a\u{FFFD}b\u{1F600}\u{FFFD}", text);
}

/// Another program can hold the clipboard open for a few milliseconds (a
/// clipboard manager, RDP's clipboard sync, Office), and one failed
/// `OpenClipboard` used to drop the whole paste or copy. Retry within a
/// 5 ms QPC budget, without timer-tick sleeps or dispatching messages.
/// Keeping the call synchronous preserves copy/paste order and the
/// confirmation that owns a pending operation. On false, `GetLastError`
/// still holds the last open's error. Scheduling and OpenClipboard itself
/// can take longer; never start another retry after the budget expires.
pub fn openClipboard(hwnd: ?HWND) bool {
    return openClipboardWith(sys.OpenClipboard, hwnd);
}

const clipboard_open_attempts = 10;
const clipboard_open_budget_ns = 5 * std.time.ns_per_ms;
const clipboard_open_interval_ns = std.time.ns_per_ms / 2;

fn openClipboardWith(open: *const fn (?HWND) callconv(.winapi) BOOL, hwnd: ?HWND) bool {
    var timer = std.time.Timer.start() catch return open(hwnd) != 0;
    return openClipboardWithClock(open, hwnd, &timer);
}

fn openClipboardWithClock(open: *const fn (?HWND) callconv(.winapi) BOOL, hwnd: ?HWND, timer: anytype) bool {
    var open_error: windows.Win32Error = .SUCCESS;
    var next_attempt: u64 = 0;
    for (0..clipboard_open_attempts) |attempt| {
        if (attempt > 0) {
            while (true) {
                const elapsed = timer.read();
                if (elapsed >= clipboard_open_budget_ns) {
                    windows.kernel32.SetLastError(open_error);
                    return false;
                }
                if (elapsed >= next_attempt) break;
                // SwitchToThread, not Sleep: offer the clipboard owner
                // the CPU without waiting for the next timer tick.
                std.Thread.yield() catch {};
            }
        }
        if (open(hwnd) != 0) return true;
        open_error = windows.kernel32.GetLastError();
        const elapsed = timer.read();
        if (elapsed >= clipboard_open_budget_ns) break;
        next_attempt = elapsed + clipboard_open_interval_ns;
    }
    windows.kernel32.SetLastError(open_error);
    return false;
}

test "win32 clipboard open retries while another program holds it" {
    const Fake = struct {
        var calls: usize = 0;
        var fail_first: usize = 0;
        elapsed: u64 = 0,

        fn read(self: *@This()) u64 {
            defer self.elapsed += std.time.ns_per_ms / 20;
            return self.elapsed;
        }

        fn open(_: ?HWND) callconv(.winapi) BOOL {
            calls += 1;
            return if (calls > fail_first) 1 else 0;
        }
    };

    Fake.calls = 0;
    Fake.fail_first = 3;
    var clock: Fake = .{};
    try std.testing.expect(openClipboardWithClock(Fake.open, null, &clock));
    try std.testing.expectEqual(@as(usize, 4), Fake.calls);

    // Held for good: gives up after the last attempt, without one more sleep.
    Fake.calls = 0;
    Fake.fail_first = std.math.maxInt(usize);
    clock = .{};
    try std.testing.expect(!openClipboardWithClock(Fake.open, null, &clock));
    try std.testing.expectEqual(@as(usize, clipboard_open_attempts), Fake.calls);
}

test "win32 clipboard contention stops retrying at its UI budget" {
    const Fake = struct {
        var calls: usize = 0;
        var owner: ?HWND = null;
        elapsed: u64 = 0,
        step: u64,

        fn read(self: *@This()) u64 {
            // A wait (or a preemption) can overrun the whole budget.
            // Clock and yield calls must not replace the open error.
            windows.kernel32.SetLastError(.INVALID_HANDLE);
            defer self.elapsed += self.step;
            return self.elapsed;
        }

        fn open(hwnd: ?HWND) callconv(.winapi) BOOL {
            calls += 1;
            owner = hwnd;
            windows.kernel32.SetLastError(.ACCESS_DENIED);
            return 0;
        }
    };

    for ([_]u64{ clipboard_open_budget_ns, 16 * std.time.ns_per_ms }) |step| {
        Fake.calls = 0;
        var clock: Fake = .{ .step = step };
        const owner: HWND = @ptrFromInt(0x1234); // passed only to the fake
        try std.testing.expect(!openClipboardWithClock(Fake.open, owner, &clock));
        try std.testing.expectEqual(@as(usize, 1), Fake.calls);
        try std.testing.expectEqual(owner, Fake.owner.?);
        try std.testing.expectEqual(windows.Win32Error.ACCESS_DENIED, windows.kernel32.GetLastError());
    }
}

test "win32 clipboard retry stops when a yield crosses its UI budget" {
    // The budget runs out while waiting for the next attempt: no second open.
    const Fake = struct {
        var calls: usize = 0;
        reads: usize = 0,

        fn read(self: *@This()) u64 {
            defer self.reads += 1;
            return switch (self.reads) {
                0 => 0,
                1 => clipboard_open_interval_ns / 2,
                else => clipboard_open_budget_ns,
            };
        }

        fn open(_: ?HWND) callconv(.winapi) BOOL {
            calls += 1;
            windows.kernel32.SetLastError(.ACCESS_DENIED);
            return 0;
        }
    };

    Fake.calls = 0;
    var clock: Fake = .{};
    try std.testing.expect(!openClipboardWithClock(Fake.open, null, &clock));
    try std.testing.expectEqual(@as(usize, 1), Fake.calls);
    try std.testing.expectEqual(windows.Win32Error.ACCESS_DENIED, windows.kernel32.GetLastError());
}

test "win32 clipboard retry uses QPC without opening the real clipboard" {
    const Fake = struct {
        var calls: usize = 0;
        var busy: bool = false;
        fn open(_: ?HWND) callconv(.winapi) BOOL {
            calls += 1;
            windows.kernel32.SetLastError(.ACCESS_DENIED);
            return if (busy) 0 else 1;
        }
    };

    Fake.calls = 0;
    Fake.busy = false;
    try std.testing.expect(openClipboardWith(Fake.open, null));
    try std.testing.expectEqual(@as(usize, 1), Fake.calls);

    Fake.calls = 0;
    Fake.busy = true;
    try std.testing.expect(!openClipboardWith(Fake.open, null));
    try std.testing.expect(Fake.calls >= 1 and Fake.calls <= clipboard_open_attempts);
    try std.testing.expectEqual(windows.Win32Error.ACCESS_DENIED, windows.kernel32.GetLastError());
}

pub fn surfaceWindowStyle() u32 {
    // Keep the terminal child surface hidden until GL + core init complete,
    // then show it explicitly from Surface.init.
    return c.WS_CHILD | c.WS_CLIPSIBLINGS;
}

const effectiveHostWindowStyle = window_state.effectiveHostWindowStyle;

pub const sharesHostWindowState = window_state.sharesHostWindowState;

pub fn shouldShowSurfaceImmediately(host_id: ?u32) bool {
    return host_id == null;
}

pub const shouldApplyConfigDecorations = window_state.shouldApplyConfigDecorations;

pub fn usesIntegratedTitlebar(
    enabled: bool,
    tab_bar_visible: bool,
    decorations_visible: bool,
) bool {
    return enabled and tab_bar_visible and decorations_visible;
}

/// Whether `window-show-tab-bar` reserves a tab strip at all. `.auto` shows
/// it unconditionally here: the strip also carries the [+] and [▾] controls,
/// which have no other home on this runtime.
pub fn tabBarVisibleForConfig(value: configpkg.Config.WindowShowTabBar) bool {
    return switch (value) {
        .always, .auto => true,
        .never => false,
    };
}

/// Whether a tab-strip chrome child -- a tab button, the Selection
/// container, the [+] / [▾] cluster -- may be shown.
///
/// `in_strip` is the child's own reason to exist (a tab button inside the
/// visible overflow range, a container with at least one tab). It is not
/// enough on its own: with the tab bar hidden the strip has zero height, so
/// every one of those children still lands as a 1 px window at the top of the
/// client area, above the terminal surface of any tab but the first, and
/// paints itself there (#244).
pub fn tabStripChildVisible(tab_bar_visible: bool, in_strip: bool) bool {
    return tab_bar_visible and in_strip;
}

pub fn hostPresentShowCommand(
    is_visible: bool,
    is_iconic: bool,
    is_zoomed: bool,
) ?i32 {
    if (is_iconic) return c.SW_RESTORE;
    if (is_visible) return null;
    return if (is_zoomed) c.SW_MAXIMIZE else c.SW_SHOW;
}

fn intResource(id: usize) INTRESOURCE {
    return @as(INTRESOURCE, @ptrFromInt(id));
}

fn appIconResource() INTRESOURCE {
    return intResource(c.ID_ICON_GHOSTTY);
}

pub fn loadAppIcon(hinstance: HINSTANCE, small: bool) HICON {
    const cx = if (small) sys.GetSystemMetrics(c.SM_CXSMICON) else sys.GetSystemMetrics(c.SM_CXICON);
    const cy = if (small) sys.GetSystemMetrics(c.SM_CYSMICON) else sys.GetSystemMetrics(c.SM_CYICON);
    return sys.LoadImageW(
        hinstance,
        appIconResource(),
        c.IMAGE_ICON,
        if (cx > 0) cx else if (small) 16 else 32,
        if (cy > 0) cy else if (small) 16 else 32,
        c.LR_SHARED,
    );
}

pub fn setWindowIcon(hwnd: HWND, hinstance: HINSTANCE) void {
    if (loadAppIcon(hinstance, false)) |icon| {
        _ = sys.SendMessageW(hwnd, c.WM_SETICON, c.ICON_BIG, @as(LPARAM, @bitCast(@intFromPtr(icon))));
    }
    if (loadAppIcon(hinstance, true)) |icon| {
        _ = sys.SendMessageW(hwnd, c.WM_SETICON, c.ICON_SMALL, @as(LPARAM, @bitCast(@intFromPtr(icon))));
    }
}

pub fn shouldDispatchOcclusion(current: ?bool, visible: bool) bool {
    return current == null or current.? != visible;
}

/// A launch chosen from the picker, the palette, a quick slot or a restored
/// session: it starts in home, unless a user profile pins its own directory
/// (`profile-working-directory`) or asks for the ordinary rules (`inherit`).
/// Restore then puts the pane's saved directory over this.
pub fn applyProfileSurfaceConfig(
    config: *configpkg.Config,
    profile: *const windows_shell.Profile,
) !void {
    // A pinned `home`, `inherit` or path is `applyProfileLaunchConfig`'s.
    if (profile.working_directory == null) {
        config.@"working-directory" = try profileHomeWorkingDirectory(config, profile);
    }
    try applyProfileLaunchConfig(config, profile);
}

/// Home for a profile launch. A bare `.home` set on a launch clone after
/// `Config.finalize` is not resolved again: Exec then starts the program in
/// noctty's own current directory (measured: the directory noctty was
/// started in), so a profile gets the path itself. For a Start menu launch
/// that directory is the install folder, the start folder of the installer's
/// shortcut (read from the installed `.lnk`, not measured by a launch). Only
/// a profile that runs `wsl.exe` keeps `.home`, which gives it `--cd ~` (the
/// Linux home) where a Windows path would give `--cd /mnt/c/Users/<name>`.
fn profileHomeWorkingDirectory(
    config: *configpkg.Config,
    profile: *const windows_shell.Profile,
) !configpkg.Config.WorkingDirectory {
    if (windows_shell.isWslCommand(profile.command)) return .home;
    var buf: [std.fs.max_path_bytes]u8 = undefined;
    const home = (internal_os.home(&buf) catch null) orelse return .home;
    return .{ .path = try config._arena.?.allocator().dupe(u8, home) };
}

/// Applies a profile's command plus the kind-specific hardening that has to
/// hold on EVERY launch path — new surface, split, and restore alike. Splits
/// used to apply only the command, which silently dropped the SSH guarantees
/// below, so both paths go through here. A user profile also brings its
/// command line, its environment and a pinned directory, `home` or a path
/// (which a split's own directory inheritance, applied after this, still
/// replaces); `inherit` leaves the ordinary rules' directory.
pub fn applyProfileLaunchConfig(
    config: *configpkg.Config,
    profile: *const windows_shell.Profile,
) !void {
    try applyProfileCommandConfig(config, profile);
    if (profile.user) |launch| try applyUserLaunchConfig(config, launch);
    if (profile.working_directory) |dir| switch (dir) {
        .path => |path| config.@"working-directory" = .{
            .path = try config._arena.?.allocator().dupe(u8, path),
        },
        .home => config.@"working-directory" = try profileHomeWorkingDirectory(config, profile),
        .inherit => {},
    };
    if (profile.kind != .ssh) return;

    try applySshLaunchHardening(config);
}

/// Give a surface's config clone a user profile's environment and command
/// line. The env goes on a copy: `newConfig` shares the app config's map, so
/// writing into it would change every later launch. A profile variable
/// replaces a global `env` variable of the same name in any case, as Windows
/// compares names (a profile `PATH` replaces a global `Path`).
pub fn applyUserLaunchConfig(
    config: *configpkg.Config,
    launch: windows_shell.UserLaunch,
) !void {
    const alloc = config._arena.?.allocator();
    var env = try config.env.clone(alloc);
    try windows_shell.layerEnv(alloc, &env, launch.env);
    config.env = env;
    config._profile_launch = try launch.clone(alloc);
}

const SurfaceLaunch = struct {
    command: ?configpkg.Command,
    user: ?windows_shell.UserLaunch,
};

/// What a new surface records as the launch it runs, for the inheritance
/// snapshot (`launch_command`, `launch_user`). The first surface of a
/// process with `initial-command` (`-e`) runs that command, which is no
/// profile's, so it records no profile line or env.
pub fn surfaceLaunchSnapshot(first: bool, config: *const configpkg.Config) SurfaceLaunch {
    if (first) if (config.@"initial-command") |command| return .{ .command = command, .user = null };
    return .{ .command = config.command, .user = config._profile_launch };
}

pub fn applySshLaunchHardening(config: *configpkg.Config) !void {
    // Shell integration injection rewrites the two-element ssh argv into a
    // space-joined, unquoted `cmd.exe /C` string. A remote session cannot use
    // it anyway: the integration scripts run locally.
    config.@"shell-integration" = .none;

    // `.home` alone loses to an inherited working directory, so resolve the
    // path explicitly and let the drive-absolute branch of the cwd resolver
    // take it. This is the same directory `ssh` itself expands `~` to.
    var home_buf: [std.fs.max_path_bytes]u8 = undefined;
    if (try windows_ssh_hosts.userProfileDir(&home_buf)) |home| {
        const alloc = config._arena.?.allocator();
        config.@"working-directory" = .{ .path = try alloc.dupe(u8, home) };
    }
}

fn applyProfileCommandConfig(
    config: *configpkg.Config,
    profile: *const windows_shell.Profile,
) !void {
    const alloc = config._arena.?.allocator();

    // newConfig() returns a shallow clone, so aliased fields such as
    // command remain owned by the source config arena. Replacing command on
    // the clone must not deinit the inherited value.
    config.command = try profile.command.clone(alloc);
    // A chosen profile: `default-profile` no longer applies to this launch.
    config._command_defaulted = false;
}

/// `default-profile`'s launch, for a launch nothing else chose: the first
/// window, a plain new tab or window, the quick terminal, a split of a pane
/// that runs no profile, a restored pane whose profile is gone. `Config`
/// has already made the profile's command the default `command`; this adds
/// the rest of the profile, as a launch from the picker gets it, except that
/// with no `profile-working-directory` the directory the ordinary rules gave
/// stays, as for `command`. Nothing when `default-profile` is unset or a
/// command was chosen already (`command`, a profile, an inherited launch).
/// The profile is the config's own; the caller records its key on the
/// surface (`App.noteProfileLaunch`).
pub fn applyDefaultProfileConfig(config: *configpkg.Config) !?*const windows_shell.Profile {
    if (!config._command_defaulted) return null;
    if (config._default_profile == null) return null;
    const profile = &config._default_profile.?;
    try applyProfileLaunchConfig(config, profile);
    return profile;
}

/// Put back `directory`, which the launch asked for explicitly (on the
/// command line, or in a forwarded new window's arguments), over the
/// directory `default-profile`'s profile pinned: the default replaces what
/// runs, not where such a launch starts. An SSH profile keeps its hardening
/// (`applySshLaunchHardening`), as a new tab from an SSH pane does: a local
/// directory means nothing to the remote shell.
pub fn keepExplicitWorkingDirectory(
    config: *configpkg.Config,
    profile: ?*const windows_shell.Profile,
    directory: ?configpkg.Config.WorkingDirectory,
) void {
    const applied = profile orelse return;
    if (applied.kind == .ssh) return;
    config.@"working-directory" = directory;
}

/// `default-profile`'s profile when `key` names it. A pane it started
/// carries its key, and the config holds the profile resolved, so a split,
/// an elevated window or a restore of that pane needs no list (no WSL probe
/// on the UI thread) and finds the profile though discovery may list none
/// such: an alias outside the SSH config, a distribution WSL did not list.
pub fn defaultProfileForKey(config: *const configpkg.Config, key: []const u8) ?*const windows_shell.Profile {
    if (config._default_profile) |*profile| {
        if (profileKeyEquals(profile.*, key)) return profile;
    }
    return null;
}

/// The profile `new_window_elevated` hands the elevated process: the
/// action's own, else the pane's, a `default-profile` pane's included.
/// `elevatesBySelector` decides whether it goes as its key or as its
/// command; either way the elevated window clears a file's
/// `initial-command`, so it runs the profile chosen. (A `default-profile`
/// the files give used to be passed as nothing, for the elevated process to
/// start itself; that let a file's `initial-command` run instead, and lost a
/// profile defined only on noctty's command line. The key does the same
/// privately.)
pub fn elevatedProfileKey(action_key: []const u8, pane_key: ?[]const u8) ?[]const u8 {
    return if (action_key.len > 0) action_key else pane_key;
}

/// Whether `new_window_elevated` names the profile `key` to the elevated
/// process (`RelaunchProfile.selector`) instead of passing its command and
/// variables: a Visual Studio shell, which the elevated process finds as the
/// picker does (a `cmd.exe /k` line with `&` in its path reaches it as
/// written), or a user profile whose live `profile-command` line was read
/// from a config file, which the elevated process reads too, so the line and
/// the variables reach it as written and stay off the elevated command line.
/// A profile defined only by a `--profile-command` option is not forwarded,
/// so it is still passed as arguments. So is every profile when elevation may
/// change the account (`same_account` false: a standard user elevated with an
/// administrator's credentials, `win32_elevation.elevationKeepsAccount`),
/// since that account reads its own config, which need not have the profile
/// or, for a Visual Studio shell, may say `visual-studio-profiles = none`.
pub fn elevatesBySelector(config: *const configpkg.Config, key: []const u8, same_account: bool) bool {
    if (!same_account) return false;
    if (std.ascii.startsWithIgnoreCase(key, "vs:")) return true;
    if (!std.ascii.startsWithIgnoreCase(key, "user:")) return false;
    const id = key["user:".len..];
    if (config.@"profile-command".get(id) == null) return false;
    if (configpkg.pane_launch.profilePlace(config, "profile-command", id) != .file) return false;
    // A variable given on the command line (`--profile-env=<id>: ...`), or a
    // `--profile-env=` that cleared them, is not forwarded either, so such a
    // profile is passed with its variables. Nor is an `--env=` argument,
    // which `%NAME%` in the profile's lines may have read.
    if (configpkg.pane_launch.profileWrittenOnCommandLine(config, "profile-env", id)) return false;
    return !configpkg.pane_launch.commandLineSetsEnv(config);
}

fn splitWorkingDirectoryCandidate(live_pwd: ?[]const u8, cached_pwd: ?[]const u8) ?[]const u8 {
    if (live_pwd) |pwd| {
        if (pwd.len > 0) return pwd;
    }
    if (cached_pwd) |pwd| {
        if (pwd.len > 0) return pwd;
    }
    return null;
}

fn applySplitWorkingDirectoryPath(
    config: *configpkg.Config,
    source_pwd: ?[]const u8,
) !bool {
    if (!config.@"split-inherit-working-directory") return false;
    const pwd = source_pwd orelse return false;
    if (pwd.len == 0) return false;

    const alloc = config._arena.?.allocator();
    config.@"working-directory" = .{ .path = try alloc.dupe(u8, pwd) };
    return true;
}

fn shouldTreatWslSplitPwdAsStartupFallback(
    alloc: Allocator,
    command: ?configpkg.Command,
    candidate: []const u8,
    startup_cwd: ?[]const u8,
) !bool {
    const cmd = command orelse return false;
    if (!windows_shell.isWslCommand(cmd)) return false;
    const startup = startup_cwd orelse return false;
    if (candidate.len == 0 or startup.len == 0) return false;

    if (std.ascii.eqlIgnoreCase(candidate, startup)) return true;
    const startup_wsl = (try windows_shell.pathToWsl(alloc, startup)) orelse return false;
    defer alloc.free(startup_wsl);
    return std.mem.eql(u8, candidate, startup_wsl);
}

pub fn applySplitWorkingDirectoryFromSource(
    app: *App,
    config: *configpkg.Config,
    source: *Surface,
    startup_cwd: ?[]const u8,
) !bool {
    if (!config.@"split-inherit-working-directory") return false;

    const alloc = config._arena.?.allocator();
    const live_pwd = (if (app.test_automation_pwd) |query|
        query(alloc, source)
    else
        source.core().pwd(alloc)) catch |err| blk: {
        log.warn("win32 split cwd inheritance could not query live cwd err={}", .{err});
        break :blk null;
    };

    if (live_pwd) |pwd| {
        if (try shouldTreatWslSplitPwdAsStartupFallback(
            alloc,
            config.command,
            pwd,
            startup_cwd,
        )) {
            if (source.pwd) |cached| {
                if (cached.len > 0) return try applySplitWorkingDirectoryPath(config, cached);
            }
            config.@"working-directory" = .home;
            return true;
        }
    }

    const candidate = splitWorkingDirectoryCandidate(live_pwd, source.pwd) orelse return false;
    if (live_pwd) |pwd| {
        if (candidate.ptr == pwd.ptr and candidate.len == pwd.len) {
            config.@"working-directory" = .{ .path = pwd };
            return true;
        }
    }
    return try applySplitWorkingDirectoryPath(config, candidate);
}

pub fn shouldInheritSplitWorkingDirectory(source_launched_ssh: bool) bool {
    return !source_launched_ssh;
}

pub fn shouldResetNewTabWorkingDirectory(
    explicit_window_target: bool,
    inherit_launch_config: bool,
    source_launched_ssh: bool,
) bool {
    return explicit_window_target or (inherit_launch_config and source_launched_ssh);
}

pub fn detectExplicitStartupWorkingDirectory(alloc: Allocator) bool {
    var iter = cli_args.argsIterator(alloc) catch return false;
    defer iter.deinit();
    while (iter.next()) |arg| {
        if (std.mem.startsWith(u8, arg, "--working-directory=")) return true;
    }
    return false;
}

pub fn getProcAddress(name: [*:0]const u8) callconv(.c) ?*const anyopaque {
    if (sys.wglGetProcAddress(name)) |ptr| {
        const raw = @intFromPtr(ptr);
        if (raw > 3 and raw != std.math.maxInt(usize)) return ptr;
    }

    const wgl = @import("win32/wgl.zig");
    const ptr = wgl.coreProcAddress(name);
    const load_error = wgl.lastLoadError();
    if (load_error != .SUCCESS) {
        recordOpenGLStartupWin32Failure(.load_opengl32, load_error);
    }
    return ptr;
}

pub const UpdateNotice = struct {
    version_text: ?[]u8 = null,
    release_url: ?[]u8 = null,
    message_text: ?[]u8 = null,
    staged: bool = false,

    pub fn init(alloc: Allocator, version_text: []const u8, release_url: []const u8, staged: bool) !UpdateNotice {
        return .{
            .version_text = try alloc.dupe(u8, version_text),
            .release_url = try alloc.dupe(u8, release_url),
            .message_text = if (staged)
                try std.fmt.allocPrint(
                    alloc,
                    "Update downloaded and verified: noctty {s} is ready to install. Installing closes all windows and running sessions.",
                    .{version_text},
                )
            else
                try std.fmt.allocPrint(
                    alloc,
                    "Update available: noctty {s} is ready on GitHub Releases.",
                    .{version_text},
                ),
            .staged = staged,
        };
    }

    test "a staged notice says that installing closes the sessions" {
        const alloc = std.testing.allocator;
        var staged = try UpdateNotice.init(alloc, "1.3.200", "https://example.invalid/release", true);
        defer staged.deinit(alloc);
        try std.testing.expect(std.mem.indexOf(u8, staged.message_text.?, "Installing closes all windows and running sessions.") != null);
        var plain = try UpdateNotice.init(alloc, "1.3.200", "https://example.invalid/release", false);
        defer plain.deinit(alloc);
        try std.testing.expect(std.mem.indexOf(u8, plain.message_text.?, "closes") == null);
    }

    pub fn deinit(self: *UpdateNotice, alloc: Allocator) void {
        if (self.version_text) |value| alloc.free(value);
        if (self.release_url) |value| alloc.free(value);
        if (self.message_text) |value| alloc.free(value);
        self.* = undefined;
    }
};

pub const UpdateCheckRequest = struct {
    alloc: Allocator,
    delivery: *AppDelivery,
    state_path: []u8,
    current_version: std.SemanticVersion,
    current_version_string: []u8,
    release_feed_url: []u8,
    force: bool,
    manual: bool,
    /// Set when a configured or environment feed URL was dropped because it
    /// is not a valid HTTPS URL, naming which one was dropped.
    ignored_feed_source: ?updatepkg.FeedSource,
    respect_dismissal: bool,
    download: bool,
    staged_kind: updatepkg.portable_apply.StagedKind,

    fn deinit(self: *UpdateCheckRequest) void {
        self.alloc.free(self.state_path);
        self.alloc.free(self.current_version_string);
        self.alloc.free(self.release_feed_url);
        self.* = undefined;
    }
};

pub const UpdateCheckCompletion = struct {
    alloc: Allocator,
    release: ?updatepkg.Release = null,
    manual_message: ?[]u8 = null,
    /// How `manual_message` reads. A check or a staging that failed is `.err`
    /// and stays in the banner until dismissed; a result ("already current",
    /// "staged") is `.info` and counts down.
    manual_kind: HostBannerKind = .info,
    staged: bool = false,
    /// The check discarded state that belonged to a previously configured
    /// feed, so a notice raised from that feed must not stay actionable.
    clear_stale_notice: bool = false,

    fn deinit(self: *UpdateCheckCompletion) void {
        if (self.release) |*value| value.deinit(self.alloc);
        if (self.manual_message) |value| self.alloc.free(value);
        self.* = undefined;
    }
};

/// A profile discovery that ran off the UI thread (`App.startProfileDiscovery`).
pub const ProfileDiscoveryCompletion = struct {
    /// Owns everything the discovery allocated, and for the detached worker
    /// the completion itself; its child is the page allocator there, so the
    /// worker borrows nothing from the App.
    arena: std.heap.ArenaAllocator,
    result: anyerror!windows_shell.ProfileDiscovery = error.NotStarted,
    /// `App.profiles_generation` when the discovery started.
    generation: u64,
    /// `App.profile_discovery_attempt` of the worker that ran it, 0 for the
    /// synchronous path.
    attempt: u64 = 0,

    /// Frees the arena, and with it a completion that lives in it.
    pub fn deinit(self: *ProfileDiscoveryCompletion) void {
        var arena = self.arena;
        arena.deinit();
    }
};

test "an undelivered profile discovery frees what it found" {
    for ([_]bool{ true, false }) |found| {
        var arena: std.heap.ArenaAllocator = .init(std.testing.allocator);
        const completion = try arena.allocator().create(ProfileDiscoveryCompletion);
        completion.* = .{ .arena = arena, .result = error.WslListTimeout, .generation = 0 };
        const alloc = completion.arena.allocator();
        if (found) {
            const profiles = try alloc.alloc(windows_shell.Profile, 1);
            const argv = try alloc.alloc([:0]const u8, 1);
            argv[0] = try alloc.dupeZ(u8, "pwsh.exe");
            profiles[0] = .{
                .kind = .pwsh,
                .key = try alloc.dupe(u8, "pwsh"),
                .label = try alloc.dupe(u8, "PowerShell"),
                .command = .{ .direct = argv },
            };
            completion.result = .{ .profiles = profiles, .complete = true };
        }
        var payload: AppDeliveryPayload = .{ .profiles = completion };
        payload.deinit();
    }
}

const AppDeliveryPayload = union(enum) {
    update: *UpdateCheckCompletion,
    toast: win32_toast_activation.ActivationTarget,
    uia_disconnect: *DeferredUiaDisconnect,
    profiles: *ProfileDiscoveryCompletion,
    jump_list: *win32_jump_list.RebuildJob,

    pub fn deinit(self: *AppDeliveryPayload) void {
        switch (self.*) {
            .update => |completion| {
                const alloc = completion.alloc;
                completion.deinit();
                alloc.destroy(completion);
            },
            .profiles => |completion| completion.deinit(),
            .jump_list => |job| job.deinit(),
            .toast => {},
            .uia_disconnect => |pending| {
                pending.release(pending.ctx);
                std.heap.page_allocator.destroy(pending);
            },
        }
    }
};
pub const AppDelivery = app_delivery.Channel(AppDeliveryPayload);

pub const RecoveryStartup = struct {
    attempts: [win32_recovery.max_attempts]win32_recovery.StartupAttempt = undefined,
    count: usize = 0,
    decision: win32_recovery.Decision = .normal,
    /// The decision set the saved session aside and the move happened; the
    /// safe-mode notice says so.
    session_set_aside: bool = false,
};

const recovery_safe_mode_banner =
    "Safe mode: repeated incomplete startups. Built-in defaults are active; your config and saved session were not loaded. Restart noctty to retry normal startup.";
const recovery_safe_mode_banner_w = blk: {
    @setEvalBranchQuota(2_000);
    break :blk std.unicode.utf8ToUtf16LeStringLiteral(recovery_safe_mode_banner);
};
const recovery_session_set_aside_banner =
    "Safe mode: noctty stopped repeatedly while restoring your saved session. Built-in defaults are active and your config was not loaded. The saved session was moved aside with a " ++
    recovery_set_aside_suffix ++ " suffix in noctty's data folder, so the next start opens a fresh window. Restart noctty to retry normal startup.";
const recovery_session_set_aside_banner_w = blk: {
    @setEvalBranchQuota(4_000);
    break :blk std.unicode.utf8ToUtf16LeStringLiteral(recovery_session_set_aside_banner);
};
/// Suffix for a saved session that the last launches died restoring.
const recovery_set_aside_suffix = ".restore-failed";
const recovery_safe_mode_caption_w = std.unicode.utf8ToUtf16LeStringLiteral("noctty safe mode");

/// Filename infix for a startup-ledger record whose write already failed and
/// whose diagnosis is waiting to be folded into the next startup's append.
/// Deliberately disjoint from the `.tmp-` infix used for live atomic-replace
/// sources so cross-instance cleanup can never delete an in-flight write.
const recovery_pending_suffix = ".pending-";

/// How long a ledger transaction waits for another instance to finish its own
/// before giving up. Holders only ever do one small read-merge-write, so a
/// wait this long means something is wrong on the other side; startup must
/// not block on it.
pub const recovery_ledger_lock_wait_ms: u32 = 2000;
const recovery_ledger_lock_poll_ms: u32 = 10;

/// Serialises every read-merge-append-replace of the startup ledger across
/// processes. Two instances launched at once — a double-click, a jump-list
/// entry plus a shortcut, `wt`-style shell integrations — each load the
/// ledger, append their own attempt and replace the file; the atomic replace
/// keeps the file well-formed but the later writer still overwrites the
/// earlier writer's record. Atomicity was never the problem, serialisation
/// was.
///
/// The lock is a byte-range lock on a sibling `.lock` file. Windows releases
/// it when the holding process exits by any means, so a crashed holder cannot
/// wedge later launches. The sibling is never deleted: removing it while
/// another instance waits on its own handle would let a third instance create
/// a fresh file and lock that instead, splitting the lock in two.
pub const RecoveryLedgerLock = struct {
    file: std.fs.File,

    /// Returns null when the lock could not be taken inside `wait_ms`; the
    /// caller decides whether that means skip or retry. Errors are the
    /// sibling file itself being unusable, which usually means the ledger
    /// directory is too.
    pub fn acquire(alloc: Allocator, ledger_path: []const u8, wait_ms: u32) !?RecoveryLedgerLock {
        try makeParentDirAbsolute(ledger_path);
        const lock_path = try std.fmt.allocPrint(alloc, "{s}.lock", .{ledger_path});
        defer alloc.free(lock_path);
        // Open-if-exists, never truncate: the file's bytes are irrelevant and
        // every instance must land on the same one.
        const file = try std.fs.createFileAbsolute(lock_path, .{ .truncate = false, .read = true });
        errdefer file.close();

        const deadline = std.time.milliTimestamp() + wait_ms;
        while (true) {
            if (try tryLockExclusive(file)) return .{ .file = file };
            if (std.time.milliTimestamp() >= deadline) {
                file.close();
                return null;
            }
            std.Thread.sleep(recovery_ledger_lock_poll_ms * std.time.ns_per_ms);
        }
    }

    pub fn release(self: *RecoveryLedgerLock) void {
        var io_status_block: windows.IO_STATUS_BLOCK = undefined;
        windows.UnlockFile(
            self.file.handle,
            &io_status_block,
            &lock_range_off,
            &lock_range_len,
            null,
        ) catch |err| {
            // Closing the handle drops the lock regardless.
            log.warn("win32 recovery: ledger unlock failed err={}", .{err});
        };
        self.file.close();
        self.* = undefined;
    }

    const lock_range_off: windows.LARGE_INTEGER = 0;
    const lock_range_len: windows.LARGE_INTEGER = 1;

    /// `std.fs.File.tryLock` does not compile on Windows in Zig 0.15.2 (its
    /// `.none` arm returns `void` from a `!bool` function), so the NT call is
    /// made directly with the same one-byte range `std` uses.
    fn tryLockExclusive(file: std.fs.File) !bool {
        var io_status_block: windows.IO_STATUS_BLOCK = undefined;
        windows.LockFile(
            file.handle,
            null,
            null,
            null,
            &io_status_block,
            &lock_range_off,
            &lock_range_len,
            null,
            windows.TRUE, // fail immediately
            windows.TRUE, // exclusive
        ) catch |err| switch (err) {
            error.WouldBlock => return false,
            else => return err,
        };
        return true;
    }
};

const RecoveryLedgerRead = union(enum) {
    /// Missing or invalid: reads as empty history.
    empty,
    /// Written by a newer build, or larger than any history this build writes
    /// (16 attempts are under 2 KiB). It is valid, only not understood here,
    /// and replacing it would reset that build's crash history: callers read
    /// it as empty and write nothing. Waiting does not change that.
    left_alone,
    /// It exists and could not be read just now (a scanner holds it, the
    /// allocator failed). It may be a newer build's, so nothing replaces it;
    /// unlike `left_alone` it may be readable a moment later, and the ready
    /// marker retries.
    unreadable,
    record: std.json.Parsed(win32_recovery.StartupAttemptRecord),

    pub fn deinit(self: *RecoveryLedgerRead) void {
        if (self.* == .record) self.record.deinit();
    }
};

/// Read and parse the ledger at `path`; `context` names the caller in the log
/// line.
pub fn readRecoveryLedgerAlloc(
    alloc: Allocator,
    path: []const u8,
    context: []const u8,
) RecoveryLedgerRead {
    // A ledger that exists but cannot be read now (a scanner holds it, the
    // allocator failed) may be a newer build's: reading it as empty would
    // replace it.
    const file = std.fs.openFileAbsolute(path, .{}) catch |err| switch (err) {
        error.FileNotFound => return .empty,
        else => {
            log.warn("win32 recovery: {s} open failed err={}; leaving it untouched", .{ context, err });
            return .unreadable;
        },
    };
    defer file.close();
    const raw = file.readToEndAlloc(alloc, 64 * 1024) catch |err| {
        if (err == error.FileTooBig) {
            log.warn("win32 recovery: {s} history is larger than this build writes; leaving it untouched", .{context});
            return .left_alone;
        }
        log.warn("win32 recovery: {s} read failed err={}; leaving it untouched", .{ context, err });
        return .unreadable;
    };
    defer alloc.free(raw);
    return .{ .record = win32_recovery.parseAlloc(alloc, raw) catch |err| {
        if (err == error.NewerSchema) {
            log.warn("win32 recovery: {s} history was written by a newer noctty; leaving it untouched", .{context});
            return .left_alone;
        }
        if (err == error.OutOfMemory) {
            log.warn("win32 recovery: {s} history could not be parsed; leaving it untouched", .{context});
            return .unreadable;
        }
        log.warn("win32 recovery: {s} ignored invalid history err={}", .{ context, err });
        return .empty;
    } };
}

/// The safe-mode text for `decision`; it names the moved session only when
/// the move happened.
pub fn recoverySafeModeNotice(decision: win32_recovery.Decision, session_set_aside: bool) ?[:0]const u16 {
    if (decision == .normal) return null;
    return if (session_set_aside) recovery_session_set_aside_banner_w else recovery_safe_mode_banner_w;
}

/// Delay before a retried ready-marker write. `GetMessageW` blocks, so an
/// otherwise idle app produces no further ticks on its own and each remaining
/// attempt has to be scheduled. The delay is what makes these retries able to
/// outlast a brief anti-virus or backup handle hold; bounded by the retry
/// budget, the safe-mode notice is released at most
/// `(recovery_ready_persist_attempts - 1) * this` late.
pub const recovery_ready_retry_delay_ms: u32 = 750;

/// May a tick spend a ready-marker attempt yet?
///
/// The retry timer only guarantees that an attempt *happens*; it cannot stop
/// an earlier unrelated tick — PTY output, a keystroke, a resize — from
/// reaching `resolveRecoveryStartup` first and spending the attempt with no
/// delay at all. A busy terminal would therefore burn the whole budget in
/// microseconds, which is the same defect as retrying on a bare wake. The
/// deadline is what actually makes the spacing real, for every transport.
pub fn recoveryRetryDue(not_before_ms: ?u64, now_ms: u64) bool {
    const deadline = not_before_ms orelse return true;
    return now_ms >= deadline;
}

/// What to do after a ready-marker attempt failed.
const RecoveryFailureAction = enum {
    /// Budget survives and a spaced retry is armed.
    retry_scheduled,
    /// Budget survives but no retry could be armed, so nothing will bring the
    /// loop back. Retrying immediately instead would spend the remaining
    /// attempts in microseconds — the busy retry the delay exists to prevent —
    /// and would still end with the marker unresolved, just with the failure
    /// counted three times and the log claiming retries that never waited.
    give_up_unschedulable,
    /// Budget exhausted, or an error that cannot clear by waiting.
    give_up_exhausted,
};

pub fn recoveryFailurePolicy(budget_exhausted: bool, scheduled: bool) RecoveryFailureAction {
    if (budget_exhausted) return .give_up_exhausted;
    return if (scheduled) .retry_scheduled else .give_up_unschedulable;
}

/// Ownerless by design; do not "fix" this to take the primary Host HWND.
///
/// The notice runs on a detached thread that nothing joins, so it can outlive
/// any terminal window: the user may close the terminal, or safe mode's quit
/// timer may fire, while the dialog is still up. Destroying an owner destroys
/// its owned windows, which would pull this box's HWND out from under a modal
/// loop running on a different thread.
///
/// An owner would also be cross-thread. `MB_APPLMODAL` disables the owner,
/// and `EnableWindow`/foreground activation against a window belonging to the
/// UI thread sends messages that thread must pump. `App.run` starts this
/// notice at the `showRecoverySafeModeNotice` call site *before* it enters its
/// `GetMessageW` loop, so there is a window where the UI thread is not
/// pumping. The App's message-only window now keeps safe mailbox work moving
/// inside native modal loops, but lifetime-changing work still waits for the
/// outer loop; this informational notice must not delay that work.
///
/// Finally, `initial-window = false` means there is no host HWND at all, so an
/// ownerless path has to exist regardless. Safe mode is a usable session; the
/// notice is informational and must not hold the terminal hostage.
/// `MB_SETFOREGROUND` plus the box's own taskbar button carry the visibility.
pub fn recoverySafeModeNoticeThread(text: [*:0]const u16) void {
    _ = sys.MessageBoxW(
        null,
        text,
        recovery_safe_mode_caption_w,
        c.MB_OK | c.MB_ICONINFORMATION | c.MB_SETFOREGROUND,
    );
}

pub fn persistMergedRecoveryReadyAtPath(
    alloc: Allocator,
    path: []const u8,
    startup: *RecoveryStartup,
    merged: win32_recovery.StartupAttemptRecord,
) !void {
    var persisted_attempts: [win32_recovery.max_attempts]win32_recovery.StartupAttempt = undefined;
    @memcpy(persisted_attempts[0..merged.attempts.len], merged.attempts);
    const persisted = persisted_attempts[0..merged.attempts.len];
    try persistRecoveryRecordAtPath(alloc, path, persisted);
    @memcpy(startup.attempts[0..persisted.len], persisted);
    startup.count = persisted.len;
}

/// Record `mark` on this launch's attempt, merged with the disk record under
/// the ledger lock like the ready marker. Around a session restore: the start
/// is on disk before the first window is restored, so a launch that ends during
/// restore leaves it behind, and the finish is on disk before any unrelated
/// startup work, so `decide` can tell a session that keeps failing to restore
/// from any other repeated failure. Best effort: an unrecorded start only
/// means the session is not set aside.
pub fn markRecoveryAttemptAtPath(
    alloc: Allocator,
    path: []const u8,
    startup: *RecoveryStartup,
    mark: win32_recovery.AttemptMark,
) void {
    if (startup.count == 0) return;
    const memory_attempts = startup.attempts[0..startup.count];
    const target_started_at = memory_attempts[memory_attempts.len - 1].started_at_unix_ms;

    var lock = RecoveryLedgerLock.acquire(alloc, path, recovery_ledger_lock_wait_ms) catch |err| {
        log.warn("win32 recovery: {s} marker skipped, ledger lock unavailable err={}", .{ @tagName(mark), err });
        return;
    } orelse {
        log.warn("win32 recovery: {s} marker skipped, ledger lock busy", .{@tagName(mark)});
        return;
    };
    defer lock.release();

    var disk_record: win32_recovery.StartupAttemptRecord = .{};
    var ledger = readRecoveryLedgerAlloc(alloc, path, @tagName(mark));
    defer ledger.deinit();
    if (ledger == .left_alone or ledger == .unreadable) return;
    if (ledger == .record) disk_record = ledger.record.value;

    var merged_attempts: [win32_recovery.max_attempts]win32_recovery.StartupAttempt = undefined;
    const merged = win32_recovery.mergeMarkAttempt(
        disk_record,
        .{ .attempts = memory_attempts },
        target_started_at,
        mark,
        &merged_attempts,
    ) catch |err| {
        log.warn("win32 recovery: {s} marker merge failed err={}", .{ @tagName(mark), err });
        return;
    };
    persistRecoveryRecordAtPath(alloc, path, merged_attempts[0..merged.attempts.len]) catch |err| {
        log.warn("win32 recovery: {s} marker persist failed err={}", .{ @tagName(mark), err });
        return;
    };
    // Memory keeps this process's own attempt last: the ready marker targets
    // it, so the merged record is not adopted here.
    win32_recovery.applyMark(&memory_attempts[memory_attempts.len - 1], mark);
}

/// Move a saved session aside that the last launches all ended restoring, so
/// the next normal launch starts fresh instead of ending again. A rename into
/// a free slot, never a delete or a replace; skipped while another live process
/// owns the session, and for any file this build would not restore (a newer
/// build's, an oversized or unreadable one, or one the restore path quarantines
/// as `.corrupt` anyway). Returns whether the session was moved.
fn setAsideCrashedSessionState(alloc: Allocator, state_path: []const u8) bool {
    const owner = SessionOwnerLock.acquire(alloc, state_path) catch |err| {
        log.warn("win32 recovery: session not set aside, ownership lock unavailable err={}", .{err});
        return false;
    } orelse {
        log.warn("win32 recovery: session not set aside, another instance owns it", .{});
        return false;
    };
    defer owner.release();
    {
        var current = win32_session_persistence.loadAlloc(
            alloc,
            state_path,
            win32_session_persistence.default_max_state_bytes,
        );
        defer current.deinit();
        if (current != .loaded) {
            if (current != .missing) log.warn("win32 recovery: session not set aside, not one this build restores ({s})", .{@tagName(current)});
            return false;
        }
    }
    const destination = win32_session_persistence.quarantineFileAlloc(
        alloc,
        state_path,
        recovery_set_aside_suffix,
        .keep_source,
    ) catch |err| {
        if (err != error.FileNotFound) {
            log.warn("win32 recovery: session not set aside path={s} err={}", .{ state_path, err });
        }
        return false;
    };
    defer alloc.free(destination);
    log.warn("win32 recovery: repeated failures while restoring the saved session; moved it to {s}", .{destination});
    return true;
}

const setAsideSessionStateAt = session_module.setAsideSessionStateAt;

/// Create the directory `path` sits in when it is missing. Only that one
/// level: its own parent must already exist.
fn makeParentDirAbsolute(path: []const u8) !void {
    const dir = std.fs.path.dirname(path) orelse return;
    std.fs.makeDirAbsolute(dir) catch |err| switch (err) {
        error.PathAlreadyExists => {},
        else => return err,
    };
}

pub fn unixMillis() u64 {
    return @intCast(@max(std.time.milliTimestamp(), 0));
}

fn utf8PrefixLen(value: []const u8, capacity: usize) usize {
    var len = @min(value.len, capacity);
    while (len > 0 and !std.unicode.utf8ValidateSlice(value[0..len])) {
        len -= 1;
    }
    return len;
}

fn settingsFileSize(size: u64) win32_settings.SaveError!usize {
    const max_config_size = 16 * 1024 * 1024;
    if (size > max_config_size) return error.SerializeFailed;
    return @intCast(size);
}

const SettingsConfigKey = @import("../config/key.zig").Key;
const SettingsEditedKeySet = std.StaticBitSet(std.enums.values(SettingsConfigKey).len);
pub fn settingsUserEditedKeys(
    original: *const configpkg.Config,
    pending: *const configpkg.Config,
) SettingsEditedKeySet {
    var edited: SettingsEditedKeySet = .initEmpty();
    inline for (win32_settings.editable_keys) |key| {
        if (original.changed(pending, key)) edited.set(@intFromEnum(key));
    }
    return edited;
}

fn settingsEditedValueMasked(
    pending: *const configpkg.Config,
    reloaded: *const configpkg.Config,
    comptime key: SettingsConfigKey,
) bool {
    // The reload's finalize fills in an unset channel and turns a Window theme
    // of auto into system for a theme pair: neither overrides what was saved
    // (a reset to the default saves exactly those).
    if (comptime key == .@"auto-update-channel" or key == .@"window-theme") {
        const fields = @import("win32_settings_fields.zig");
        const field = comptime fields.forKey(key).?.field.?;
        return !std.meta.eql(
            fields.effectiveSettingValue(fields.settingValue(pending, field)),
            fields.effectiveSettingValue(fields.settingValue(reloaded, field)),
        );
    }
    return settingsDiskValueDiffers(pending, reloaded, key);
}

/// The most bytes `settingsMaskedKeyNames` writes: every editable key, and a
/// separator after each.
pub const settings_masked_keys_capacity = capacity: {
    var total: usize = 0;
    for (win32_settings.editable_keys) |key| total += @tagName(key).len + 2;
    break :capacity total;
};

/// The config keys among the user's edits whose saved value `reloaded` does
/// not hold, because a later config file or a command-line option sets them
/// again: comma separated, in the order the settings are listed, written to
/// `buf`. Empty when the reload holds everything that was saved. It allocates
/// nothing, so it cannot fail after the file was written.
pub fn settingsMaskedKeyNames(
    buf: *[settings_masked_keys_capacity]u8,
    user_edited: SettingsEditedKeySet,
    pending: *const configpkg.Config,
    reloaded: *const configpkg.Config,
) []const u8 {
    var len: usize = 0;
    inline for (win32_settings.editable_keys) |key| {
        if (user_edited.isSet(@intFromEnum(key)) and settingsEditedValueMasked(pending, reloaded, key)) {
            if (len > 0) {
                @memcpy(buf[len..][0..2], ", ");
                len += 2;
            }
            const name = @tagName(key);
            @memcpy(buf[len..][0..name.len], name);
            len += name.len;
        }
    }
    return buf[0..len];
}

/// Whether the file now says something else, for a setting the draft changes,
/// than both the value this session started from (`original`) and the draft:
/// someone else changed what the user is changing. A file that agrees with the
/// draft lost nothing, and one that agrees with `original` holds only the
/// user's own edit to come.
///
/// `original` is a clone of the app's config, which has the app's conditional
/// state applied (a dark system picks the dark half of a `light:A,dark:B`
/// theme, and that theme can set editable keys), so the file is judged with
/// the same state applied. Raw, an untouched file would differ from
/// `original` for those keys and every Save would stop.
fn settingsDiskEditConflict(
    original: *const configpkg.Config,
    pending: *const configpkg.Config,
    disk: *const configpkg.Config,
    state: configpkg.ConditionalState,
    user_edited: SettingsEditedKeySet,
) bool {
    var applied: ?configpkg.Config = disk.changeConditionalState(state) catch |err| blk: {
        log.warn("settings save: could not apply the conditional state to the config file err={}", .{err});
        break :blk null;
    };
    defer if (applied) |*config| config.deinit();
    const effective: *const configpkg.Config = if (applied) |*config| config else disk;
    inline for (win32_settings.editable_keys) |key| {
        if (user_edited.isSet(@intFromEnum(key)) and
            settingsDiskEditDiffers(original, effective, key) and
            settingsDiskEditDiffers(pending, effective, key)) return true;
    }
    return false;
}

/// `settingsDiskValueDiffers` for the conflict check. Settings' copies hold
/// the files' `default-profile` (`SettingsWindow.useSavedValues`), while the
/// load also reads this process's command line, whose `--default-profile`
/// (a jump-list or elevated window) wins there: compare what the files say.
/// The masked check after a save keeps the value the process runs with.
fn settingsDiskEditDiffers(
    known: *const configpkg.Config,
    disk: *const configpkg.Config,
    comptime key: SettingsConfigKey,
) bool {
    if (key == .@"default-profile") {
        const mine = known.@"default-profile";
        const theirs = disk.defaultProfileFromFiles();
        if (mine == null or theirs == null) return mine != null or theirs != null;
        return !std.mem.eql(u8, mine.?, theirs.?);
    }
    return settingsDiskValueDiffers(known, disk, key);
}

/// `Config.load` takes a config file it cannot open (held without read
/// sharing, access denied, an offline share) for an absent one, or for one that
/// set nothing, and loads the rest. Judged as an edit and applied, that would
/// drop the user's own settings from every terminal, so a file that exists but
/// will not open stops the check, and the save with it. A file that is missing
/// is a first save (or an include the loader reports itself), and there is
/// nothing on disk to conflict with; a directory is not read by the loader
/// either.
///
/// The error is `FileUnopenable`, and `detail` (when given) is told which file
/// and why it is the one: `what` is "the config file" or "the included file",
/// so the status line can name it.
pub fn settingsFileOpenable(
    alloc: Allocator,
    detail: ?*win32_settings.FailureDetail,
    what: []const u8,
    path: []const u8,
) win32_settings.SaveError!void {
    _ = try settingsFileProbe(alloc, detail, what, path);
}

/// `settingsFileOpenable`, saying whether something is there: false for a
/// missing file, true for one that opens and for a directory.
fn settingsFileProbe(
    alloc: Allocator,
    detail: ?*win32_settings.FailureDetail,
    what: []const u8,
    path: []const u8,
) win32_settings.SaveError!bool {
    const file = std.fs.cwd().openFile(path, .{}) catch |err| switch (err) {
        error.FileNotFound => return false,
        error.IsDir => return true,
        else => {
            log.warn("settings save: could not open {s} to check it for edits path={s} err={}", .{ what, path, err });
            try setSettingsFailureDetail(alloc, detail, "{s} {s}", .{ what, path });
            return error.FileUnopenable;
        },
    };
    file.close();
    return true;
}

/// Tell `detail`, when the caller gave one, which file a refused save is
/// about, for the Settings status line.
fn setSettingsFailureDetail(
    alloc: Allocator,
    detail: ?*win32_settings.FailureDetail,
    comptime fmt: []const u8,
    args: anytype,
) error{OutOfMemory}!void {
    const d = detail orelse return;
    const text = try std.fmt.allocPrint(alloc, fmt, args);
    defer alloc.free(text);
    d.set(alloc, text);
}

/// `settingsFileOpenable` for every file the loaded config pulled in: the
/// list holds the nested ones too, as absolute paths.
fn settingsIncludesOpenable(
    alloc: Allocator,
    detail: ?*win32_settings.FailureDetail,
    disk: *const configpkg.Config,
) win32_settings.SaveError!void {
    for (disk.@"config-file".value.items) |entry| switch (entry) {
        .optional, .required => |path| if (path.len > 0) try settingsFileOpenable(alloc, detail, "the included file", path),
    };
}

/// The theme files the loaded config selects, by the loader's own search
/// (`themepkg.open`: an absolute path, or the name in each theme directory),
/// held to the same rule as an include. A theme that is not there is the
/// loader's to report, and the running config lacks it too; one that is there
/// and will not open is skipped by the load, and the settings it supplies
/// come back as defaults. Both the light and the dark name are checked, since
/// which one the load used depends on the system state.
fn settingsThemeOpenable(
    alloc: Allocator,
    detail: ?*win32_settings.FailureDetail,
    disk: *const configpkg.Config,
) win32_settings.SaveError!void {
    const theme = disk.theme orelse return;
    for ([_][]const u8{ theme.light, theme.dark }) |name| {
        if (std.fs.path.isAbsolute(name)) {
            try settingsFileOpenable(alloc, detail, "the theme file", name);
            continue;
        }
        // A name with a separator is rejected by the loader without a look.
        if (!std.mem.eql(u8, name, std.fs.path.basename(name))) continue;
        var arena: std.heap.ArenaAllocator = .init(alloc);
        defer arena.deinit();
        var dirs: std.ArrayListUnmanaged([]const u8) = .{};
        var it: themepkg.LocationIterator = .{ .arena_alloc = arena.allocator() };
        while (it.next() catch return error.OutOfMemory) |location| {
            dirs.append(arena.allocator(), location.dir) catch return error.OutOfMemory;
        }
        try settingsThemeNameOpenable(alloc, detail, name, dirs.items);
    }
}

/// The loader uses the first directory that has `name` and never looks at the
/// rest, so a later copy that is locked does not matter.
fn settingsThemeNameOpenable(
    alloc: Allocator,
    detail: ?*win32_settings.FailureDetail,
    name: []const u8,
    dirs: []const []const u8,
) win32_settings.SaveError!void {
    for (dirs) |dir| {
        const path = std.fs.path.join(alloc, &.{ dir, name }) catch return error.OutOfMemory;
        defer alloc.free(path);
        if (try settingsFileProbe(alloc, detail, "the theme file", path)) return;
    }
}

/// Whether the loaded `disk` config holds an edit that conflicts with the
/// draft, or an error when it is not the whole config: the save's own reload
/// would apply the same partial load, so a locked include stops the save
/// whether or not an edited setting conflicts.
pub fn settingsDiskVerdict(
    alloc: Allocator,
    detail: ?*win32_settings.FailureDetail,
    original: *const configpkg.Config,
    pending: *const configpkg.Config,
    disk: *const configpkg.Config,
    state: configpkg.ConditionalState,
    user_edited: SettingsEditedKeySet,
) win32_settings.SaveError!bool {
    try settingsIncludesOpenable(alloc, detail, disk);
    try settingsThemeOpenable(alloc, detail, disk);
    // A UTF-16 file that does not decode is skipped whole, with a diagnostic
    // and everything it set missing: as incomplete as one that will not open.
    if (disk._undecodable_file) |path| {
        try setSettingsFailureDetail(alloc, detail, "the file {s}", .{path});
        return error.UnsupportedEncoding;
    }
    return settingsDiskEditConflict(original, pending, disk, state, user_edited);
}

/// What the palette says when a theme pick could not be saved. Two causes are
/// something the person can act on; the rest share one line.
pub fn paletteThemeSaveFailureMessage(err: win32_settings.SaveError) []const u8 {
    return switch (err) {
        error.DiskChanged => "The theme changed in the config file. Reload the configuration, then pick again; reverted preview.",
        error.FileUnopenable => "A config file cannot be opened, so the theme was not saved; reverted preview.",
        error.UnsupportedEncoding, error.BinaryConfig => "The config file is not UTF-8 text, so the theme was not saved; reverted preview.",
        else => "Theme save failed; reverted preview.",
    };
}

fn settingsDiskValueDiffers(
    known: *const configpkg.Config,
    disk: *const configpkg.Config,
    comptime key: SettingsConfigKey,
) bool {
    // The window keeps a command nobody set as automatic (null); the load
    // fills in the one it found.
    if (key == .command and disk._command_defaulted and known.command == null) return false;
    return known.changed(disk, key);
}

test "win32 bounded UTF-8 prefix never splits a codepoint" {
    const value = "123\u{1f680}tail";
    try std.testing.expectEqual(@as(usize, 3), utf8PrefixLen(value, 4));
    try std.testing.expectEqual(@as(usize, 7), utf8PrefixLen(value, 7));
    try std.testing.expectEqual(value.len, utf8PrefixLen(value, value.len + 10));
}

test "win32 settings save rejects files above the read cap" {
    try std.testing.expectEqual(@as(usize, 16 * 1024 * 1024), try settingsFileSize(16 * 1024 * 1024));
    try std.testing.expectError(error.SerializeFailed, settingsFileSize(16 * 1024 * 1024 + 1));
}

/// One answer to "is this a portable install?" for the call sites that only
/// need the yes/no, with one error policy: a failed probe is not portable.
/// Every consumer treats portable as the branch that unlocks portable-only
/// behavior, so failing to `.installer` keeps those paths closed and lets the
/// staged-kind check refuse rather than guess.
///
/// `localAppDataPathAlloc` and `warnPortableIgnoredLocalData` still call
/// `portableRoot` directly: they need the root path itself, not the answer.
pub fn isPortableModeActive(alloc: Allocator) bool {
    const root = internal_os.xdg.portableRoot(alloc) catch |err| {
        log.warn("failed to probe portable mode; treating as non-portable err={}", .{err});
        return false;
    } orelse return false;
    alloc.free(root);
    return true;
}

/// Every noctty shares one AUMID (`win32_aumid.aumid_utf8`), and with it two
/// pieces of per-user state: the AppUserModelId keys that name and badge its
/// toasts, and the taskbar jump list, which the Shell stores per AUMID. A
/// portable copy keeps the AUMID, so its toasts and the single-instance pipe
/// work as before, but leaves the installed copy's state alone (D12): it gets
/// no jump list, whose commit replaced the installed copy's on every launch,
/// and it only creates the registration where none exists, since without one
/// its toasts would not show. This is the one place both are decided. Returns
/// the jump list this copy drives, null when it leaves the Shell's list alone.
pub fn claimSharedIdentity(
    alloc: Allocator,
    portable: bool,
    register: *const fn (Allocator, bool) void,
    jump_list_state: ?[]const u8,
) ?win32_jump_list.JumpList {
    register(alloc, portable);
    if (portable) return null;
    const path = jump_list_state orelse return null;
    return win32_jump_list.JumpList.init(alloc, path) catch |err| {
        log.warn("jump list state init failed err={}", .{err});
        return null;
    };
}

test "a portable copy gets no jump list and registers only as portable" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try tmp.dir.realpathAlloc(alloc, ".");
    defer alloc.free(root);
    const state = try std.fs.path.join(alloc, &.{ root, win32_jump_list.state_filename });
    defer alloc.free(state);
    const Registration = struct {
        var calls: [2]usize = .{ 0, 0 };
        fn register(_: Allocator, portable: bool) void {
            calls[@intFromBool(portable)] += 1;
        }
    };

    try std.testing.expect(claimSharedIdentity(alloc, true, &Registration.register, state) == null);
    try std.testing.expectEqual([2]usize{ 0, 1 }, Registration.calls);

    var installed = claimSharedIdentity(alloc, false, &Registration.register, state) orelse
        return error.TestUnexpectedResult;
    defer installed.deinit();
    try std.testing.expectEqual([2]usize{ 1, 1 }, Registration.calls);
}

pub fn installTerminfo(alloc: Allocator, term: []const u8) void {
    const names = terminfo.compiled.fileNames(terminfo.ghostty) catch return;
    for (names) |name| {
        if (std.mem.eql(u8, name, term)) break;
    } else return;

    var env = std.process.getEnvMap(alloc) catch return;
    defer env.deinit();
    const dir = (win32_terminfo.homeTerminfoDir(alloc, &env) catch null) orelse {
        log.info("terminfo install skipped: no local home that git.exe and the MSYS2 runtime agree on", .{});
        return;
    };
    defer alloc.free(dir);
    const result = win32_terminfo.install(alloc, terminfo.ghostty, dir);
    log.info("terminfo install dir={s} result={s}", .{ dir, @tagName(result) });
}

pub fn localAppDataPathAlloc(alloc: Allocator, name: []const u8) ?[]u8 {
    // A unit test that constructs a real `App` must never read or write the
    // developer's own profile. It used to: every full `zig build test` run
    // appended an unfinished launch to the real `startup-attempts.json`
    // through "win32 runtime can initialize config", and three runs in a row
    // put the next real noctty launch into safe mode, which ignores the
    // config file and `-e`. The same helper resolves the jump list, session
    // state, palette history and layouts, so it is gated here rather than at
    // the ledger. Every caller already treats null as "nothing to persist",
    // and the ledger's own tests pass explicit temporary paths.
    if (builtin.is_test) return null;

    if (internal_os.xdg.portableRoot(alloc) catch null) |root| {
        defer alloc.free(root);
        return std.fs.path.join(alloc, &.{ root, name }) catch null;
    }

    const local = std.process.getEnvVarOwned(alloc, "LOCALAPPDATA") catch known: {
        var buf: [std.fs.max_path_bytes]u8 = undefined;
        const path = internal_os.windows.knownFolderPathUtf8(
            &internal_os.windows.FOLDERID_LocalAppData,
            &buf,
        ) catch return null;
        break :known alloc.dupe(u8, path orelse return null) catch return null;
    };
    defer alloc.free(local);
    return std.fs.path.join(alloc, &.{ local, build_config.data_dir_name, name }) catch null;
}

pub fn warnPortableIgnoredLocalData(alloc: Allocator) void {
    const portable_root = (internal_os.xdg.portableRoot(alloc) catch return) orelse return;
    defer alloc.free(portable_root);
    const local = std.process.getEnvVarOwned(alloc, "LOCALAPPDATA") catch known: {
        var buf: [std.fs.max_path_bytes]u8 = undefined;
        const path = internal_os.windows.knownFolderPathUtf8(
            &internal_os.windows.FOLDERID_LocalAppData,
            &buf,
        ) catch return;
        break :known alloc.dupe(u8, path orelse return) catch return;
    };
    defer alloc.free(local);
    const ignored_path = std.fs.path.join(alloc, &.{ local, build_config.data_dir_name }) catch return;
    defer alloc.free(ignored_path);
    if (std.ascii.eqlIgnoreCase(portable_root, ignored_path)) return;
    var ignored_dir = std.fs.openDirAbsolute(ignored_path, .{ .iterate = true }) catch return;
    defer ignored_dir.close();
    var iter = ignored_dir.iterate();
    if ((iter.next() catch return) == null) return;
    log.warn(
        "portable mode active root={s}; existing data under {s} is not being used",
        .{ portable_root, ignored_path },
    );
}

/// `session_state_excluded` is the elevation exclusion: such a process stays
/// out of the saved session, so it never sets one aside either.
pub fn beginRecoveryStartup(alloc: Allocator, session_state_excluded: bool) RecoveryStartup {
    const path = localAppDataPathAlloc(alloc, "startup-attempts.json") orelse return .{};
    defer alloc.free(path);
    const session_path = if (session_state_excluded) null else localAppDataPathAlloc(alloc, "session-state.json");
    defer if (session_path) |value| alloc.free(value);
    return beginRecoveryStartupAtPath(alloc, path, session_path, unixMillis(), recovery_ledger_lock_wait_ms);
}

/// The whole read -> fold -> append -> replace -> cleanup sequence runs under
/// `RecoveryLedgerLock`. Without it two instances launching together both
/// load the same ledger and the second replace silently drops the first
/// instance's attempt; the `.pending-` fold has the same exposure, since its
/// delete could remove a record a concurrent startup has not folded yet.
///
/// Fail-open: when the lock cannot be taken inside `lock_wait_ms` this launch
/// still reads the ledger for its safe-mode decision but records nothing, so
/// `count` stays 0 and no later marker is attempted. An unrecorded launch is
/// an honest gap in the history; a startup blocked behind a wedged sibling is
/// the outage this ledger exists to prevent.
fn beginRecoveryStartupAtPath(
    alloc: Allocator,
    path: []const u8,
    session_path: ?[]const u8,
    now: u64,
    lock_wait_ms: u32,
) RecoveryStartup {
    var result: RecoveryStartup = .{};

    var lock = RecoveryLedgerLock.acquire(alloc, path, lock_wait_ms) catch |err| unlocked: {
        log.warn("win32 recovery: ledger lock unavailable err={}; startup will not be recorded", .{err});
        break :unlocked null;
    };
    defer if (lock) |*held| held.release();
    if (lock == null) {
        log.warn(
            "win32 recovery: ledger lock not acquired within {d}ms; startup will not be recorded",
            .{lock_wait_ms},
        );
    }

    var record: win32_recovery.StartupAttemptRecord = .{};
    var ledger = readRecoveryLedgerAlloc(alloc, path, "startup history");
    defer ledger.deinit();
    // A history that is not this build's to replace, or could not be read
    // now, is neither counted nor replaced: this launch goes unrecorded, as it
    // does when the lock is unavailable.
    if (ledger == .left_alone or ledger == .unreadable) return result;
    if (ledger == .record) record = ledger.record.value;

    var retained_paths: std.ArrayListUnmanaged([]u8) = .empty;
    defer {
        for (retained_paths.items) |retained_path| alloc.free(retained_path);
        retained_paths.deinit(alloc);
    }
    var retained_merge_buffers: [2][win32_recovery.max_attempts]win32_recovery.StartupAttempt = undefined;
    var retained_merge_buffer_index: usize = 0;
    if (std.fs.path.dirname(path)) |dir_path| retained: {
        var dir = std.fs.openDirAbsolute(dir_path, .{ .iterate = true }) catch |err| {
            log.warn("win32 recovery: retained history directory open failed err={}", .{err});
            break :retained;
        };
        defer dir.close();
        // Only `.pending-` records are folded and deleted here. They are
        // written exclusively by `retainRecoveryPersistDiagnosis`, i.e. after
        // a ledger write has already definitively failed, and are never used
        // as the source of an atomic replacement. The `.tmp-` files that
        // `persistRecoveryRecordAtPath` creates are live replacement sources
        // for whichever process owns them; a concurrently starting instance
        // that deleted one would make that process's ReplaceFileW fail and
        // send it down the in-place fallback, clobbering the record this
        // process just merged. The namespaces stay disjoint even though the
        // ledger lock now serialises ledger transactions: a `.tmp-` can also
        // be left by a writer that died mid-replace, and nothing here should
        // have to reason about whether its owner is alive.
        const retained_prefix = std.fmt.allocPrint(
            alloc,
            "{s}" ++ recovery_pending_suffix,
            .{std.fs.path.basename(path)},
        ) catch break :retained;
        defer alloc.free(retained_prefix);
        var entries = dir.iterate();
        while (true) {
            const entry = entries.next() catch |err| {
                log.warn("win32 recovery: retained history enumeration failed err={}", .{err});
                break;
            } orelse break;
            if (!std.mem.startsWith(u8, entry.name, retained_prefix)) continue;
            const retained_path = std.fs.path.join(alloc, &.{ dir_path, entry.name }) catch continue;
            const retained_file = std.fs.openFileAbsolute(retained_path, .{}) catch {
                alloc.free(retained_path);
                continue;
            };
            defer retained_file.close();
            const raw = retained_file.readToEndAlloc(alloc, 64 * 1024) catch {
                alloc.free(retained_path);
                continue;
            };
            defer alloc.free(raw);
            var parsed = win32_recovery.parseAlloc(alloc, raw) catch {
                alloc.free(retained_path);
                continue;
            };
            defer parsed.deinit();
            const merged = win32_recovery.mergeRecords(
                record,
                parsed.value,
                &retained_merge_buffers[retained_merge_buffer_index],
            ) catch {
                alloc.free(retained_path);
                continue;
            };
            retained_paths.append(alloc, retained_path) catch {
                alloc.free(retained_path);
                continue;
            };
            record = merged;
            retained_merge_buffer_index = 1 - retained_merge_buffer_index;
        }
    }

    result.decision = win32_recovery.decide(record, now, .{});
    // Everything above was read-only. Nothing below may run unlocked: the
    // append-and-replace is the lost-update window, and deleting a folded
    // `.pending-` record is only safe once its contents are on disk under
    // the same lock.
    if (lock == null) return result;

    // Acted on inside the transaction that decided it, so no launch can
    // record a restore or a ready marker in between.
    if (result.decision == .quarantine_session) if (session_path) |value| {
        result.session_set_aside = setAsideCrashedSessionState(alloc, value);
    };

    // Attempts are told apart by their start; two launches in one
    // millisecond must not share one.
    const started_at = if (record.attempts.len > 0)
        @max(now, record.attempts[record.attempts.len - 1].started_at_unix_ms + 1)
    else
        now;
    const appended = win32_recovery.appendBounded(
        record,
        .{ .started_at_unix_ms = started_at, .version = .init(build_config.version_string) },
        &result.attempts,
    ) catch |err| {
        log.warn("win32 recovery: attempt append failed err={}", .{err});
        return result;
    };
    result.count = appended.attempts.len;
    persistRecoveryRecordAtPath(alloc, path, result.attempts[0..result.count]) catch |err| {
        log.warn("win32 recovery: startup marker persist failed err={}", .{err});
        return result;
    };
    for (retained_paths.items) |retained_path| {
        win32_session_persistence.deleteFileIfPresent(retained_path) catch |err| {
            log.warn("win32 recovery: merged retained history cleanup failed path={s} err={}", .{ retained_path, err });
        };
    }
    return result;
}

fn persistRecoveryRecordAtPath(
    alloc: Allocator,
    path: []const u8,
    attempts: []win32_recovery.StartupAttempt,
) !void {
    try makeParentDirAbsolute(path);
    const encoded = try win32_recovery.encodeAlloc(alloc, .{ .attempts = attempts });
    defer alloc.free(encoded);
    const nonce = unixMillis();
    // `.tmp-` is this process's private replacement source and is never read
    // or deleted by another instance. `.pending-` is the post-failure
    // diagnosis another instance folds in and cleans up. See the namespace
    // note in `beginRecoveryStartupAtPath`.
    const temporary_path = try std.fmt.allocPrint(
        alloc,
        "{s}.tmp-{x}-{x}",
        .{ path, sys.GetCurrentProcessId(), nonce },
    );
    defer alloc.free(temporary_path);
    const pending_path = try std.fmt.allocPrint(
        alloc,
        "{s}" ++ recovery_pending_suffix ++ "{x}-{x}",
        .{ path, sys.GetCurrentProcessId(), nonce },
    );
    defer alloc.free(pending_path);
    var atomic_failure: ?win32_session_persistence.AtomicReplaceFailure = null;
    const disposition = win32_session_persistence.writeFileAtomicOrInPlace(
        path,
        temporary_path,
        encoded,
        &atomic_failure,
    ) catch |err| {
        if (atomic_failure) |failure| {
            recordRecoveryPersistFailure(attempts, failure.move_error);
            retainRecoveryPersistDiagnosis(
                alloc,
                temporary_path,
                pending_path,
                attempts,
            );
        }
        return err;
    };
    switch (disposition) {
        .atomic => {},
        .in_place => |failure| {
            recordRecoveryPersistFailure(attempts, failure.move_error);
            const diagnosed = try win32_recovery.encodeAlloc(alloc, .{ .attempts = attempts });
            defer alloc.free(diagnosed);
            win32_session_persistence.writeFileInPlace(path, diagnosed) catch |err| {
                log.warn("win32 recovery: in-place diagnosis persist failed err={}", .{err});
                retainRecoveryPersistDiagnosis(
                    alloc,
                    temporary_path,
                    pending_path,
                    attempts,
                );
            };
        },
    }
}

fn recordRecoveryPersistFailure(
    attempts: []win32_recovery.StartupAttempt,
    raw_win32_error: u32,
) void {
    if (attempts.len == 0) return;
    const latest = &attempts[attempts.len - 1];
    if (latest.ready_at_unix_ms != null) latest.phase = .ready_persist_failed;
    latest.last_win32_error = raw_win32_error;
}

fn retainRecoveryPersistDiagnosis(
    alloc: Allocator,
    temporary_path: []const u8,
    pending_path: []const u8,
    attempts: []const win32_recovery.StartupAttempt,
) void {
    const diagnosed = win32_recovery.encodeAlloc(alloc, .{ .attempts = attempts }) catch return;
    defer alloc.free(diagnosed);
    // Publish under `.pending-`, not the replacement source. The write has
    // already failed, so this record is inert: no process will ever hand it
    // to ReplaceFileW, which makes it safe for a concurrent startup to fold
    // and delete. Then drop the now-dead `.tmp-` source so it does not leak.
    win32_session_persistence.writeFileInPlace(pending_path, diagnosed) catch |err| {
        log.warn("win32 recovery: retained diagnosis persist failed err={}", .{err});
        return;
    };
    win32_session_persistence.deleteFileIfPresent(temporary_path) catch |err| {
        log.warn("win32 recovery: dead replacement source cleanup failed err={}", .{err});
    };
}

pub fn writePersistentFileAlloc(alloc: Allocator, path: []const u8, data: []const u8) !void {
    if (std.fs.path.dirname(path)) |dir| {
        // Recursive: `layouts\` sits one level below `%LOCALAPPDATA%\noctty`,
        // which itself may not exist yet on a first save.
        std.fs.cwd().makePath(dir) catch |err| switch (err) {
            error.PathAlreadyExists => {},
            else => return err,
        };
    }
    const temporary_path = try std.fmt.allocPrint(
        alloc,
        "{s}.tmp-{x}-{x}",
        .{ path, sys.GetCurrentProcessId(), unixMillis() },
    );
    defer alloc.free(temporary_path);
    try win32_session_persistence.writeFileAtomic(path, temporary_path, data);
}

pub fn layoutActionResult(success: bool) !bool {
    if (!success) return error.LayoutActionFailed;
    return true;
}

const SessionRestoreTransaction = session_module.SessionRestoreTransaction;

/// A profile named on the command line (`--default-profile=<reference>`,
/// which a jump-list link to a user profile carries) makes an explicit
/// launch, as an explicit directory does: it neither restores nor saves the
/// session, and its first window runs that profile. A link to a profile
/// with a directory of its own has no `--working-directory=` to say so.
fn startupNamesProfile(config: *const configpkg.Config) bool {
    const reference = config._default_profile_cli orelse return false;
    return reference.len > 0;
}

pub const SessionOwnerLock = session_module.SessionOwnerLock;

fn writeOpenUrlTrace(file: std.fs.File, url: []const u8) !void {
    var buffer: [1024]u8 = undefined;
    var writer = file.writer(&buffer);
    try writer.interface.print("{s}\r\n", .{url});
    try writer.interface.flush();
}

/// Explicit Debug-build test seam for URL activation. When set, the Win32
/// runtime records the requested URL instead of dispatching an uncontrolled
/// ShellExecuteW. Release builds always use the system URL handler.
pub fn recordOpenUrlForTest(alloc: Allocator, url: []const u8) !bool {
    const raw_path = std.process.getEnvVarOwned(
        alloc,
        "NOCTTY_WIN32_OPEN_URL_TRACE_FILE",
    ) catch |err| switch (err) {
        error.EnvironmentVariableNotFound => return false,
        else => return err,
    };
    defer alloc.free(raw_path);
    const path = std.mem.trim(u8, raw_path, " \t\r\n");
    if (path.len == 0) return false;

    const file = try std.fs.createFileAbsolute(path, .{ .truncate = true });
    defer file.close();
    try writeOpenUrlTrace(file, url);
    return true;
}

pub const App = app_module.App;

pub const detachHostReference = @import("win32/registry.zig").detachHostReference;

pub fn automationHostFocused(
    host_hwnd: ?HWND,
    foreground_hwnd: ?HWND,
    surface_focused_fallback: bool,
) bool {
    const hwnd = host_hwnd orelse return surface_focused_fallback;
    return foreground_hwnd == hwnd;
}

/// `App.startProfileDiscovery`'s detached worker. It holds a reference on
/// the delivery channel and allocates from the page allocator, so it may
/// outlive the App; a result nobody takes is freed by the channel. When it
/// cannot deliver, the App's watchdog timer starts another attempt.
pub fn profileDiscoveryThreadMain(
    delivery: *AppDelivery,
    include_ssh_hosts: bool,
    generation: u64,
    attempt: u64,
    user_profiles: windows_shell.UserProfiles,
) void {
    defer delivery.release();
    var user = user_profiles;
    defer user.deinit();
    var arena: std.heap.ArenaAllocator = .init(std.heap.page_allocator);
    const completion = arena.allocator().create(ProfileDiscoveryCompletion) catch {
        arena.deinit();
        log.warn("profile discovery result unavailable err=OutOfMemory", .{});
        delivery.profiles_running.store(false, .release);
        return;
    };
    completion.* = .{ .arena = arena, .generation = generation, .attempt = attempt };
    completion.result = windows_shell.discoverProfiles(completion.arena.allocator(), include_ssh_hosts, &user);
    var payload: AppDeliveryPayload = .{ .profiles = completion };
    if (!delivery.post(c.WM_WINHOSTTY_PROFILES, payload)) {
        payload.deinit();
        delivery.profiles_running.store(false, .release);
    }
}

pub fn jumpListRebuildThreadMain(delivery: *AppDelivery, job: *win32_jump_list.RebuildJob) void {
    defer delivery.release();
    job.runInOwnApartment();
    var payload: AppDeliveryPayload = .{ .jump_list = job };
    if (!delivery.post(c.WM_WINHOSTTY_JUMP_LIST, payload)) payload.deinit();
}

fn testProfileList(alloc: Allocator, keys: []const []const u8) ![]windows_shell.Profile {
    var source: [4]windows_shell.Profile = undefined;
    for (keys, 0..) |key, index| source[index] = .{
        .kind = .pwsh,
        .key = key,
        .label = key,
        .command = .{ .direct = &.{"pwsh.exe"} },
    };
    return try windows_shell.cloneProfiles(alloc, source[0..keys.len]);
}

fn testFreeHostProfiles(app: *App, hosts: []const *Host) void {
    const alloc = app.core_app.alloc;
    for (hosts) |host| {
        if (host.profiles) |profiles| windows_shell.deinitProfiles(alloc, profiles);
        host.profiles = null;
        appendOwnedString(alloc, &host.selected_profile_key, null) catch unreachable;
    }
    appendOwnedString(alloc, &app.launcher_profile_key, null) catch unreachable;
}

test "win32 a window without profiles borrows another window's complete list" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    var core_app: CoreApp = undefined;
    var app: App = undefined;
    var first: Host = undefined;
    var second: Host = undefined;
    var session: TestSession = .{};
    try session.init(.{
        .core_app = &core_app,
        .app = &app,
        .hosts = &.{
            .{ .storage = &first, .register = true, .id = 1 },
            .{ .storage = &second, .register = true, .id = 2 },
        },
    });
    defer session.deinit();
    defer testFreeHostProfiles(&app, &.{ &first, &second });

    first.profiles = try testProfileList(app.core_app.alloc, &.{ "pwsh", "cmd" });
    first.profiles_complete = true;
    const generation = app.profiles_generation;

    // No discovery: the list is copied, and the generation is left alone so
    // a discovery in flight still applies.
    try std.testing.expect(second.profilesForChrome());
    try std.testing.expect(!second.profiles_requested);
    try std.testing.expectEqual(generation, app.profiles_generation);
    try std.testing.expectEqual(@as(usize, 2), second.profiles.?.len);
    try std.testing.expectEqualStrings("cmd", second.profiles.?[1].key);
    try std.testing.expect(second.profiles.?[0].key.ptr != first.profiles.?[0].key.ptr);
}

test "win32 a finished discovery reaches only the windows that asked for it" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    var core_app: CoreApp = undefined;
    var app: App = undefined;
    var first: Host = undefined;
    var second: Host = undefined;
    var session: TestSession = .{};
    try session.init(.{
        .core_app = &core_app,
        .app = &app,
        .hosts = &.{
            .{ .storage = &first, .register = true, .id = 1 },
            .{ .storage = &second, .register = true, .id = 2 },
        },
    });
    defer session.deinit();
    defer testFreeHostProfiles(&app, &.{ &first, &second });

    second.profiles = try testProfileList(app.core_app.alloc, &.{"old"});
    second.profiles_complete = true;
    first.profiles_requested = true;

    var completion: ProfileDiscoveryCompletion = .{
        .arena = .init(std.testing.allocator),
        .generation = app.profiles_generation,
    };
    defer completion.deinit();
    completion.result = .{
        .profiles = try testProfileList(completion.arena.allocator(), &.{ "pwsh", "cmd" }),
        .complete = true,
    };
    app.handleProfileDiscovery(&completion);

    try std.testing.expect(!first.profiles_requested);
    try std.testing.expectEqual(@as(usize, 2), first.profiles.?.len);
    try std.testing.expect(first.profiles_complete);
    try std.testing.expectEqual(@as(usize, 1), second.profiles.?.len);
    try std.testing.expectEqualStrings("old", second.profiles.?[0].key);

    // An incomplete list does not replace a complete one.
    second.profiles_requested = true;
    var partial: ProfileDiscoveryCompletion = .{
        .arena = .init(std.testing.allocator),
        .generation = app.profiles_generation,
    };
    defer partial.deinit();
    partial.result = .{
        .profiles = try testProfileList(partial.arena.allocator(), &.{"partial"}),
        .complete = false,
    };
    app.handleProfileDiscovery(&partial);
    try std.testing.expect(!second.profiles_requested);
    try std.testing.expectEqualStrings("old", second.profiles.?[0].key);

    // A result that started before a list was applied is dropped.
    first.profiles_requested = false;
    second.profiles_requested = false;
    var stale: ProfileDiscoveryCompletion = .{
        .arena = .init(std.testing.allocator),
        .generation = app.profiles_generation -% 1,
    };
    defer stale.deinit();
    stale.result = .{
        .profiles = try testProfileList(stale.arena.allocator(), &.{"stale"}),
        .complete = true,
    };
    app.handleProfileDiscovery(&stale);
    try std.testing.expectEqualStrings("pwsh", first.profiles.?[0].key);
}

test "win32 Settings' profile refill reads the windows' lists and asks for none" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    var core_app: CoreApp = undefined;
    var app: App = undefined;
    var first: Host = undefined;
    var session: TestSession = .{};
    try session.init(.{
        .core_app = &core_app,
        .app = &app,
        .hosts = &.{.{ .storage = &first, .register = true, .id = 1 }},
    });
    defer session.deinit();
    defer testFreeHostProfiles(&app, &.{&first});

    // A discovery failed, so no window has a list. The refill Settings runs
    // then answers with none and starts no other discovery, which could
    // fail the same way and land here again.
    const attempt = app.profile_discovery_attempt;
    try std.testing.expect(app.settingsProfileList(false) == null);
    var choices = try settingsProfileChoicesThunk(&app, std.testing.allocator, "user:py312", null, false);
    defer choices.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 0), choices.items.len);
    try std.testing.expect(!first.profiles_requested);
    try std.testing.expectEqual(attempt, app.profile_discovery_attempt);

    // A list a window has is read without asking.
    first.profiles = try testProfileList(app.core_app.alloc, &.{ "pwsh.exe", "cmd.exe" });
    first.profiles_complete = true;
    const list = app.settingsProfileList(false).?;
    try std.testing.expectEqual(@as(usize, 2), list.profiles.len);
    try std.testing.expect(list.complete);
    try std.testing.expect(!first.profiles_requested);
}

test "win32 a finished discovery refills Settings' Default profile dropdown" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;
    try runOnHiddenDesktop(struct {
        fn rowCount(app: *App) LRESULT {
            return sys.SendMessageW(app.settings_window.fields.combo_default_profile.?, 0x0146, 0, 0); // CB_GETCOUNT
        }

        fn body() !void {
            var core_app: CoreApp = undefined;
            var app: App = undefined;
            var first: Host = undefined;
            var session: TestSession = .{};
            try session.init(.{
                .core_app = &core_app,
                .app = &app,
                .hosts = &.{.{ .storage = &first, .register = true, .id = 1 }},
            });
            defer session.deinit();
            defer testFreeHostProfiles(&app, &.{&first});
            app.initComApartment();
            if (!app.com_initialized) return error.SkipZigTest;
            defer sys.OleUninitialize();
            app.settings_window.handle.deferUiaDisconnect = null;
            const settings_class = comptime std.unicode.utf8ToUtf16LeStringLiteral("noctty.win32.settings");
            const viewport_class = comptime std.unicode.utf8ToUtf16LeStringLiteral("noctty.win32.settings.viewport");
            defer {
                app.settings_window.deinit();
                _ = sys.UnregisterClassW(settings_class, app.settings_window.handle.hinstance);
                _ = sys.UnregisterClassW(viewport_class, app.settings_window.handle.hinstance);
            }

            // The window holds a partial list, which the Shell page shows
            // without asking for another.
            first.profiles = try testProfileList(app.core_app.alloc, &.{"pwsh.exe"});
            first.profiles_complete = false;
            try app.settings_window.openSection(.shell);
            try std.testing.expectEqual(@as(LRESULT, 2), rowCount(&app));

            // The window's discovery lands: the dropdown is refilled from it.
            first.profiles_requested = true;
            var completion: ProfileDiscoveryCompletion = .{
                .arena = .init(std.testing.allocator),
                .generation = app.profiles_generation,
            };
            defer completion.deinit();
            completion.result = .{
                .profiles = try testProfileList(completion.arena.allocator(), &.{ "pwsh.exe", "cmd.exe" }),
                .complete = true,
            };
            app.handleProfileDiscovery(&completion);
            try std.testing.expect(first.profiles_complete);
            try std.testing.expectEqual(@as(LRESULT, 3), rowCount(&app));
        }
    }.body);
}

test "win32 Settings' profile choices name a resolved default the list lacks by its label" {
    const alloc = std.testing.allocator;
    const profiles = [_]windows_shell.Profile{
        .{ .kind = .pwsh, .key = "pwsh.exe", .label = "PowerShell", .command = .{ .direct = &.{} } },
        .{ .kind = .ssh, .key = "ssh:listed", .label = "SSH: listed", .command = .{ .direct = &.{} } },
    };
    // `ssh:box` is not in the SSH config, so it is not listed, but the
    // loaded config resolved it and it is what new terminals start.
    const resolved: windows_shell.Profile = .{ .kind = .ssh, .key = "ssh:box", .label = "SSH: box", .command = .{ .direct = &.{} } };
    var unlisted = try settingsProfileChoices(alloc, &profiles, true, "ssh:box", .{ .resolved = &resolved });
    defer unlisted.deinit(alloc);
    try std.testing.expectEqual(@as(?usize, null), unlisted.selected);
    try std.testing.expectEqualStrings("SSH: box", unlisted.saved_label.?);

    // A listed one is selected, by the resolved key or by the list rules.
    const listed: windows_shell.Profile = .{ .kind = .ssh, .key = "ssh:listed", .label = "SSH: listed", .command = .{ .direct = &.{} } };
    var by_key = try settingsProfileChoices(alloc, &profiles, true, "ssh:listed", .{ .resolved = &listed });
    defer by_key.deinit(alloc);
    try std.testing.expectEqual(@as(?usize, 1), by_key.selected);
    try std.testing.expect(by_key.saved_label == null);
    var by_rule = try settingsProfileChoices(alloc, &profiles, true, "pwsh", .untried);
    defer by_rule.deinit(alloc);
    try std.testing.expectEqual(@as(?usize, 0), by_rule.selected);

    // An unlisted `ssh:` value the loaded config did not look up (a window
    // started with `--default-profile`, where Settings shows the files'
    // value) gets the label it would start under.
    var untried = try settingsProfileChoices(alloc, &profiles, true, "ssh:box", .untried);
    defer untried.deinit(alloc);
    try std.testing.expectEqual(@as(?usize, null), untried.selected);
    try std.testing.expectEqualStrings("SSH: box", untried.saved_label.?);
    // One it looked up and could not start (no ssh.exe, no wsl.exe) has no
    // label: new terminals start the automatic default, and Settings marks
    // it not found.
    for ([_][]const u8{ "ssh:box", "wsl:Ubuntu" }) |value| {
        // Whatever the list: absent, partial or complete.
        for ([_]bool{ false, true }) |complete| {
            const list: []const windows_shell.Profile = if (complete) &profiles else profiles[0..1];
            var failed = try settingsProfileChoices(alloc, list, complete, value, .unresolved);
            defer failed.deinit(alloc);
            try std.testing.expectEqual(@as(?usize, null), failed.selected);
            try std.testing.expect(failed.saved_label == null);
            try std.testing.expect(failed.saved_not_found);
        }
        var unlisted_failed = try settingsProfileChoices(alloc, &.{}, false, value, .unresolved);
        defer unlisted_failed.deinit(alloc);
        try std.testing.expect(unlisted_failed.saved_not_found);
    }
    // Nor does it take a listed row by the list's rules.
    var failed_listed = try settingsProfileChoices(alloc, &profiles, true, "pwsh", .unresolved);
    defer failed_listed.deinit(alloc);
    try std.testing.expectEqual(@as(?usize, null), failed_listed.selected);

    // A value nothing resolved has no label: Settings marks it not found.
    var missing = try settingsProfileChoices(alloc, &profiles, true, "user:gone", .untried);
    defer missing.deinit(alloc);
    try std.testing.expectEqual(@as(?usize, null), missing.selected);
    try std.testing.expect(missing.saved_label == null);
    try std.testing.expect(missing.saved_not_found);
    try std.testing.expectEqual(@as(usize, 2), missing.items.len);
    // Unless the list may still lack it.
    var pending = try settingsProfileChoices(alloc, &profiles, false, "user:gone", .untried);
    defer pending.deinit(alloc);
    try std.testing.expect(!pending.saved_not_found);

    // A list from a partial Setup Configuration answer may lack the newest
    // instance, so `vs:newest:cmd`, which the loaded config could not
    // resolve, preselects no older instance's row; that row stays a choice
    // of its own, which stages its concrete key. A complete list names it.
    const vs = [_]windows_shell.Profile{
        .{ .kind = .cmd, .key = "cmd.exe", .label = "Command Prompt", .command = .{ .direct = &.{} } },
        .{ .kind = .vs_dev_cmd, .key = "vs:6bb7cfd9:cmd", .label = "Developer Command Prompt for VS 2022", .command = .{ .direct = &.{} }, .newest_visual_studio = true },
    };
    var partial = try settingsProfileChoices(alloc, &vs, false, "vs:newest:cmd", .untried);
    defer partial.deinit(alloc);
    try std.testing.expectEqual(@as(?usize, null), partial.selected);
    try std.testing.expect(partial.saved_label == null);
    try std.testing.expectEqualStrings("vs:6bb7cfd9:cmd", partial.items[1].key);
    var whole = try settingsProfileChoices(alloc, &vs, true, "vs:newest:cmd", .untried);
    defer whole.deinit(alloc);
    try std.testing.expectEqual(@as(?usize, 1), whole.selected);
    // The loaded config resolved it to an instance the cached list lacks (a
    // newer Visual Studio installed since the list was found): that one is
    // what starts, by its label, and the older row stays a choice.
    const newer: windows_shell.Profile = .{ .kind = .vs_dev_cmd, .key = "vs:0a1b2c3d:cmd", .label = "Developer Command Prompt for VS 2026", .command = .{ .direct = &.{} }, .newest_visual_studio = true };
    var moved = try settingsProfileChoices(alloc, &vs, true, "vs:newest:cmd", .{ .resolved = &newer });
    defer moved.deinit(alloc);
    try std.testing.expectEqual(@as(?usize, null), moved.selected);
    try std.testing.expectEqualStrings("Developer Command Prompt for VS 2026", moved.saved_label.?);
    // Setup Configuration did not answer the load's lookup, so new
    // terminals start the automatic default: even a complete cached list's
    // newest instance is not the saved row, which stays apart and unmarked,
    // and that instance's row is a choice that stages its own key.
    var unavailable = try settingsProfileChoices(alloc, &vs, true, "vs:newest:cmd", .unavailable);
    defer unavailable.deinit(alloc);
    try std.testing.expectEqual(@as(?usize, null), unavailable.selected);
    try std.testing.expect(unavailable.saved_label == null);
    try std.testing.expect(!unavailable.saved_not_found);
    try std.testing.expectEqualStrings("vs:6bb7cfd9:cmd", unavailable.items[1].key);

    // Every allocation can fail, the label's last, and nothing is freed twice
    // or leaked.
    try std.testing.checkAllAllocationFailures(alloc, struct {
        fn run(a: Allocator, list: []const windows_shell.Profile, saved: *const windows_shell.Profile) !void {
            var choices = try settingsProfileChoices(a, list, true, "ssh:box", .{ .resolved = saved });
            choices.deinit(a);
            var bare = try settingsProfileChoices(a, list, true, "ssh:box", .untried);
            bare.deinit(a);
        }
    }.run, .{ @as([]const windows_shell.Profile, &profiles), &resolved });
}

pub fn updateCheckThreadMain(request: *UpdateCheckRequest) void {
    const alloc = request.alloc;
    defer {
        request.deinit();
        alloc.destroy(request);
    }

    defer request.delivery.release();
    const completion = alloc.create(UpdateCheckCompletion) catch {
        request.delivery.update_running.store(false, .release);
        return;
    };
    completion.* = .{ .alloc = alloc };
    runUpdateCheck(request, completion);
    postUpdateCheckCompletion(request.delivery, completion);
}

/// The check itself, off the UI thread. What it found goes into `completion`,
/// and for a manual check what to tell the user and how loudly: a failure is
/// `.err`, so it stays in the banner until dismissed instead of counting down
/// like a result does.
fn runUpdateCheck(request: *const UpdateCheckRequest, completion: *UpdateCheckCompletion) void {
    const alloc = request.alloc;
    const outcome = updatepkg.checkLatestStableRelease(alloc, request.state_path, .{
        .current_version = request.current_version,
        .release_feed_url = request.release_feed_url,
        .force = request.force,
        .respect_dismissal = request.respect_dismissal,
    }) catch |err| {
        if (request.manual) {
            completion.manual_kind = .err;
            completion.manual_message = std.fmt.allocPrint(
                alloc,
                "Unable to check GitHub Releases right now ({s}).",
                .{@errorName(err)},
            ) catch null;
        }
        appendConfiguredFeedIgnoredNote(request, completion);
        return;
    };
    defer {
        var owned = outcome;
        owned.deinit(alloc);
    }
    completion.clear_stale_notice = outcome.feed_state_invalidated;

    switch (outcome.result) {
        .update_available => |release| {
            stage_download: {
                if (request.download) {
                    var staged = updatepkg.stageWindowsInstall(
                        alloc,
                        request.state_path,
                        request.release_feed_url,
                        &release,
                        request.staged_kind,
                    ) catch |err| {
                        log.warn("failed to stage verified updater download err={}", .{err});
                        if (request.manual) {
                            completion.manual_kind = .err;
                            completion.manual_message = updateStageFailureMessage(alloc, err) catch null;
                        }
                        break :stage_download;
                    };
                    staged.deinit(alloc);
                    completion.staged = true;
                    if (request.manual) {
                        completion.manual_message = std.fmt.allocPrint(
                            alloc,
                            "noctty {s} is downloaded, verified, and staged.",
                            .{release.version_text},
                        ) catch null;
                    }
                }
            }

            const version_text = tryOrNull(alloc, release.version_text);
            const release_url = tryOrNull(alloc, release.release_url);
            if (version_text != null and release_url != null) {
                completion.release = .{
                    .version_text = version_text.?,
                    .release_url = release_url.?,
                };
            } else {
                if (version_text) |value| alloc.free(value);
                if (release_url) |value| alloc.free(value);
                if (request.manual) {
                    completion.manual_kind = .err;
                    completion.manual_message = std.fmt.allocPrint(
                        alloc,
                        "Unable to prepare the update notice for noctty {s}.",
                        .{release.version_text},
                    ) catch null;
                }
            }
        },
        .up_to_date, .throttled => {
            if (request.manual) {
                completion.manual_message = std.fmt.allocPrint(
                    alloc,
                    "noctty {s} is already current on the stable channel.",
                    .{request.current_version_string},
                ) catch null;
            }
        },
    }

    appendConfiguredFeedIgnoredNote(request, completion);
}

test "update worker OOM clears running and releases its detached lifetime" {
    const delivery = try AppDelivery.create();
    defer delivery.release();
    delivery.update_running.store(true, .release);
    var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{ .fail_index = 0 });
    const alloc = failing.allocator();
    // Allocate request storage and strings through the backing allocator;
    // the failing wrapper delegates frees, but its first allocation (the
    // worker's completion) fails before any network or state-file access.
    const request = try std.testing.allocator.create(UpdateCheckRequest);
    request.* = .{
        .alloc = alloc,
        .delivery = delivery,
        .state_path = try std.testing.allocator.dupe(u8, "unused"),
        .current_version = .{ .major = 1, .minor = 0, .patch = 0 },
        .current_version_string = try std.testing.allocator.dupe(u8, "1.0.0"),
        .release_feed_url = try std.testing.allocator.dupe(u8, "https://example.invalid"),
        .force = false,
        .manual = false,
        .ignored_feed_source = null,
        .respect_dismissal = true,
        .download = false,
        .staged_kind = .portable,
    };
    delivery.retain();
    updateCheckThreadMain(request);
    try std.testing.expect(!delivery.update_running.load(.acquire));
    try std.testing.expectEqual(@as(usize, 1), delivery.refs.load(.acquire));
}

test "update completion post failure clears running and frees its payload" {
    const delivery = try AppDelivery.create();
    defer delivery.release();
    delivery.update_running.store(true, .release);
    const completion = try std.testing.allocator.create(UpdateCheckCompletion);
    completion.* = .{ .alloc = std.testing.allocator, .manual_message = try std.testing.allocator.dupe(u8, "status") };
    postUpdateCheckCompletion(delivery, completion);
    try std.testing.expect(!delivery.update_running.load(.acquire));
    try std.testing.expect(delivery.pop() == null);
}

/// A manual or automatic update check against a state file the check can
/// answer from without the network: a throttled one, or one that remembers a
/// newer release. A directory where the state file belongs makes it fail.
fn testRunUpdateCheck(
    alloc: Allocator,
    state_path: []const u8,
    manual: bool,
    download: bool,
) !UpdateCheckCompletion {
    const feed = "https://feed.invalid/releases/latest";
    var request: UpdateCheckRequest = .{
        .alloc = alloc,
        // The check itself never touches it; posting the result does.
        .delivery = undefined,
        .state_path = @constCast(state_path),
        .current_version = .{ .major = 1, .minor = 0, .patch = 0 },
        .current_version_string = @constCast("1.0.0"),
        .release_feed_url = @constCast(feed),
        .force = false,
        .manual = manual,
        .ignored_feed_source = null,
        .respect_dismissal = true,
        .download = download,
        .staged_kind = .installer,
    };
    var completion: UpdateCheckCompletion = .{ .alloc = alloc };
    errdefer completion.deinit();
    runUpdateCheck(&request, &completion);
    return completion;
}

test "a manual update check reports a failure as an error and a result as information" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try tmp.dir.realpathAlloc(alloc, ".");
    defer alloc.free(root);

    // The check fails: a directory stands where the state file belongs. A
    // failure stays in the banner until dismissed.
    var failed = try testRunUpdateCheck(alloc, root, true, false);
    defer failed.deinit();
    try std.testing.expectEqual(HostBannerKind.err, failed.manual_kind);
    try std.testing.expect(std.mem.startsWith(u8, failed.manual_message.?, "Unable to check GitHub Releases right now ("));
    // An automatic check says nothing, whatever happened.
    var silent = try testRunUpdateCheck(alloc, root, false, false);
    defer silent.deinit();
    try std.testing.expectEqual(@as(?[]u8, null), silent.manual_message);

    // A throttled check with nothing newer remembered: "already current" is
    // a result, and counts down like one.
    const state_path = try std.fs.path.join(alloc, &.{ root, "update-state.json" });
    defer alloc.free(state_path);
    var state: updatepkg.State = .{
        .last_checked_at = std.time.timestamp() - 60,
        .release_feed_url = try alloc.dupe(u8, "https://feed.invalid/releases/latest"),
        .release_url = try alloc.dupe(u8, "https://example.invalid/releases/tag/v99.0.0"),
    };
    defer state.deinit(alloc);
    try updatepkg.saveState(state_path, &state);
    var current = try testRunUpdateCheck(alloc, state_path, true, false);
    defer current.deinit();
    try std.testing.expectEqual(HostBannerKind.info, current.manual_kind);
    try std.testing.expect(std.mem.indexOf(u8, current.manual_message.?, "is already current") != null);

    // A newer release is remembered but cannot be staged (the throttle cache
    // keeps no assets): the notice is raised, and the failure to stage it is
    // an error. Without a download there is nothing to report.
    state.last_seen_version = try alloc.dupe(u8, "99.0.0");
    try updatepkg.saveState(state_path, &state);
    var unstaged = try testRunUpdateCheck(alloc, state_path, true, true);
    defer unstaged.deinit();
    try std.testing.expect(unstaged.release != null);
    try std.testing.expectEqual(HostBannerKind.err, unstaged.manual_kind);
    try std.testing.expect(std.mem.startsWith(u8, unstaged.manual_message.?, "Update found, but it could not be verified or staged"));
    var found = try testRunUpdateCheck(alloc, state_path, true, false);
    defer found.deinit();
    try std.testing.expect(found.release != null);
    try std.testing.expectEqual(HostBannerKind.info, found.manual_kind);
    try std.testing.expectEqual(@as(?[]u8, null), found.manual_message);
}

test "the update check's banner keeps a failure up and lets a result count down" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    var core_app: CoreApp = undefined;
    var app: App = undefined;
    var host: Host = undefined;
    var session: TestSession = .{};
    try session.init(.{
        .core_app = &core_app,
        .app = &app,
        .hosts = &.{.{ .storage = &host, .register = true }},
    });
    defer session.deinit();

    var failure: UpdateCheckCompletion = .{
        .alloc = std.testing.allocator,
        .manual_message = try std.testing.allocator.dupe(u8, "Unable to check GitHub Releases right now (error.ConnectionRefused)."),
        .manual_kind = .err,
    };
    defer failure.deinit();
    app.handleUpdateCheckCompletion(&failure);
    try std.testing.expectEqual(HostBannerKind.err, host.banner_kind);
    try std.testing.expectEqualStrings(failure.manual_message.?, host.banner_text.?);

    var result: UpdateCheckCompletion = .{
        .alloc = std.testing.allocator,
        .manual_message = try std.testing.allocator.dupe(u8, "noctty 1.0.0 is already current on the stable channel."),
    };
    defer result.deinit();
    app.handleUpdateCheckCompletion(&result);
    try std.testing.expectEqual(HostBannerKind.info, host.banner_kind);
    try std.testing.expectEqualStrings(result.manual_message.?, host.banner_text.?);
}

fn tryOrNull(alloc: Allocator, text: []const u8) ?[]u8 {
    return alloc.dupe(u8, text) catch null;
}

fn appendConfiguredFeedIgnoredNote(
    request: *const UpdateCheckRequest,
    completion: *UpdateCheckCompletion,
) void {
    if (!request.manual) return;
    const ignored = request.ignored_feed_source orelse return;

    const note = switch (ignored) {
        .configured => "Configured update feed ignored because its URL is not a valid HTTPS URL.",
        .environment => "NOCTTY_UPDATE_FEED_URL ignored because its URL is not a valid HTTPS URL.",
        .default => return,
    };
    const message = if (completion.manual_message) |existing|
        std.fmt.allocPrint(request.alloc, "{s} {s}", .{ existing, note }) catch return
    else
        request.alloc.dupe(u8, note) catch return;
    if (completion.manual_message) |existing| request.alloc.free(existing);
    completion.manual_message = message;
}

fn updateStageFailureMessage(alloc: Allocator, err: anyerror) ![]u8 {
    const detail = switch (err) {
        error.WindowsInstallNotEligible => "the release is missing a Windows installer or SHA256SUMS.txt",
        error.PortableInstallNotEligible => "the release is missing the portable ZIP",
        error.PortablePayloadManifestUnavailable => "the release is missing the signed portable payload manifest; use the release page",
        error.InvalidPortablePayloadManifest => "the signed portable payload manifest is invalid",
        error.PortablePayloadManifestEntryMissing,
        error.PortablePayloadManifestEntryDuplicate,
        error.PortablePayloadManifestFileSetMismatch,
        => "the signed portable payload manifest does not cover exactly the extracted files",
        error.PortablePayloadManifestMismatch => "a portable payload file did not match the signed manifest",
        error.PortableUpdateTransactionActive => "another portable apply or rollback transaction is active",
        error.InstallerChecksumMissing => "SHA256SUMS.txt does not include the selected Windows asset",
        error.InvalidChecksum => "SHA256SUMS.txt contains an invalid checksum",
        error.InstallerVersionInfoUnavailable => "the installer VersionInfo block was missing or unreadable",
        error.InstallerVersionOlderThanRelease => "the installer version was older than the release feed version",
        error.InstallerChecksumMismatch => "the downloaded Windows asset did not match SHA256SUMS.txt",
        error.InvalidAuthenticodeSignature => "an executable Authenticode signature could not be trusted",
        error.UntrustedConPtyRedistributable => "a bundled ConPTY file did not match its pinned SHA-256",
        error.UnsafePortableArchiveEntry => "the portable ZIP contains an unsafe path",
        error.DuplicatePortableArchiveEntry => "the portable ZIP contains duplicate paths",
        error.InvalidPortableArchive, error.InvalidPortableArchiveRoot => "the portable ZIP layout is invalid",
        error.PortableArchiveChecksumMismatch => "a portable ZIP entry failed its CRC-32 check",
        error.UnsupportedPortableArchive => "the portable ZIP uses an unsupported format",
        error.PortableArchiveTooLarge => "the portable ZIP exceeds safe extraction limits",
        error.IncompletePortablePayload => "the portable ZIP payload is incomplete",
        error.AuthenticodeRequiresWindows => "Authenticode verification is only available on Windows",
        error.SignatureVerifierUnavailable => "Windows signature verification is unavailable",
        error.InvalidStatePath => "the updater state directory could not be resolved",
        error.InvalidDownloadPath => "the staging download path was invalid",
        error.UpdateHttpUnauthorized => "GitHub rejected the download request as unauthorized",
        error.UpdateHttpForbidden => "GitHub blocked the download request",
        error.UpdateHttpNotFound => "a required release asset was not found",
        error.UpdateHttpRateLimited => "GitHub rate limited the update download",
        error.UnexpectedHttpStatus => "GitHub returned an unexpected HTTP status",
        error.UnsupportedContentEncoding => "the download was sent compressed although only identity was accepted",
        else => null,
    };

    if (detail) |text| {
        return std.fmt.allocPrint(
            alloc,
            "Update found, but it could not be verified or staged: {s} ({s}).",
            .{ text, @errorName(err) },
        );
    }

    return std.fmt.allocPrint(
        alloc,
        "Update found, but it could not be verified or staged ({s}).",
        .{@errorName(err)},
    );
}

pub fn updateApplyFailureMessage(err: anyerror) []const u8 {
    return switch (err) {
        error.NoStagedWindowsInstall => "No verified staged update is available. Run Check for Updates again.",
        error.StagedInstallFeedMismatch => "The staged update came from a different update feed. Run Check for Updates again.",
        error.NoStagedPortableInstall => "No verified staged portable ZIP is available. Run Check for Updates again.",
        error.InvalidStagedInstallerPath => "The staged update path is invalid. Run Check for Updates again.",
        error.InvalidInstallPath => "The current install path is invalid. The staged update was not launched.",
        error.InstallerChecksumMismatch => "The staged update no longer matches its verified checksum. Run Check for Updates again.",
        error.InvalidAuthenticodeSignature => "The staged update signature is no longer trusted. Run Check for Updates again.",
        error.PortablePayloadManifestUnavailable => "The staged portable update has no signed payload manifest. Open its release page to update manually.",
        error.InvalidPortablePayloadManifest,
        error.PortablePayloadManifestEntryMissing,
        error.PortablePayloadManifestEntryDuplicate,
        error.PortablePayloadManifestFileSetMismatch,
        error.PortablePayloadManifestMismatch,
        => "The staged portable payload no longer matches its signed manifest. Open its release page to update manually.",
        error.AuthenticodeRequiresWindows => "The staged update can only be applied on Windows.",
        error.SignatureVerifierUnavailable => "Windows signature verification is unavailable. The staged update was not launched.",
        error.StagedKindMismatch => "The staged update does not match this install type. Run Check for Updates again.",
        error.UpdateApplyLaunchFailed => "Windows could not launch the staged installer. The update was not applied.",
        else => "The staged update could not be verified. Run Check for Updates again.",
    };
}

pub fn currentInstallDir(alloc: Allocator) ![]u8 {
    const exe_path = try std.fs.selfExePathAlloc(alloc);
    errdefer alloc.free(exe_path);
    const dir = std.fs.path.dirname(exe_path) orelse return error.InvalidInstallPath;
    return alloc.realloc(exe_path, dir.len);
}

pub fn buildInstallerApplyArgs(alloc: Allocator, install_dir: []const u8, log_path: []const u8) ![]u8 {
    var buf: std.ArrayList(u8) = .empty;
    defer buf.deinit(alloc);

    // /RELAUNCH=1 is ours, not Inno's: dist/windows/noctty.iss starts noctty
    // again when it is given and Setup is silent. noctty has quit by the time
    // Setup replaces its files, and a process applying an update never
    // registers for a restart (`App.onQueryEndSession`), nor does another
    // noctty process while this Setup runs (`App.registerInstallerRestart`),
    // so /RESTARTAPPLICATIONS has no noctty to restart.
    try buf.appendSlice(alloc, "/VERYSILENT /SUPPRESSMSGBOXES /NORESTART /CLOSEAPPLICATIONS /RESTARTAPPLICATIONS /RELAUNCH=1");
    try appendInnoQuotedArg(alloc, &buf, " /DIR=", install_dir);
    try appendInnoQuotedArg(alloc, &buf, " /LOG=", log_path);
    return try buf.toOwnedSlice(alloc);
}

fn appendInnoQuotedArg(
    alloc: Allocator,
    buf: *std.ArrayList(u8),
    prefix: []const u8,
    value: []const u8,
) !void {
    try buf.appendSlice(alloc, prefix);
    try buf.append(alloc, '"');
    for (value) |char| {
        if (char == '"') try buf.append(alloc, '"');
        try buf.append(alloc, char);
    }
    try buf.append(alloc, '"');
}

fn postUpdateCheckCompletion(delivery: *AppDelivery, completion: *UpdateCheckCompletion) void {
    if (delivery.post(c.WM_WINHOSTTY_UPDATE, .{ .update = completion })) return;
    delivery.update_running.store(false, .release);
    var payload: AppDeliveryPayload = .{ .update = completion };
    payload.deinit();
}

pub fn queueTerminalHandoff(ctx: *anyopaque, pending: *win32_terminal_handoff.PendingSession) bool {
    const self: *App = @ptrCast(@alignCast(ctx));
    const delivery = self.delivery orelse return false;
    const server = self.terminal_handoff_server orelse return false;
    const id = server.queuePending(pending) catch return false;
    return finishTerminalHandoffNotification(server, id, delivery.notify(c.WM_WINHOSTTY_TERMINAL_HANDOFF, id));
}

fn finishTerminalHandoffNotification(server: *win32_terminal_handoff.Server, id: win32_terminal_handoff.PendingId, notified: bool) bool {
    if (notified) return true;
    // The UI backstop can claim ownership before notification fails. Only
    // return it to the RPC caller if rollback actually recovers the session.
    return server.takePending(id) == null;
}

test "win32 handoff notification failure returns ownership only when rollback claims it" {
    const Queue = struct {
        fn call(_: *anyopaque, _: *win32_terminal_handoff.PendingSession) bool {
            return false;
        }
    };
    var context: u8 = 0;
    var server = win32_terminal_handoff.Server.init(std.testing.allocator, &context, Queue.call);
    defer server.pending.entries.deinit(std.testing.allocator);

    inline for (.{ false, true }) |claimed| {
        var session: win32_terminal_handoff.PendingSession = undefined;
        const id = try server.queuePending(&session);
        if (claimed) try std.testing.expectEqual(&session, server.pending.takeOldest().?);
        try std.testing.expectEqual(claimed, finishTerminalHandoffNotification(&server, id, false));
        try std.testing.expect(server.takePending(id) == null);
    }

    var session: win32_terminal_handoff.PendingSession = undefined;
    const id = try server.queuePending(&session);
    try std.testing.expect(finishTerminalHandoffNotification(&server, id, true));
    try std.testing.expectEqual(&session, server.takePending(id).?);
}

pub fn winrtToastActivationCallback(ctx: *anyopaque, launch: []const u8) void {
    // The agile WinRT handler owns a reference to this channel, never App.
    const delivery: *AppDelivery = @ptrCast(@alignCast(ctx));
    const parsed = win32_toast_activation.parseLaunchArg(launch) catch return;
    if (delivery.toast_pending.swap(true, .acq_rel)) return;
    if (!delivery.post(c.WM_WINHOSTTY_TOAST_ACTIVATION, .{ .toast = parsed })) {
        delivery.toast_pending.store(false, .release);
    }
}

/// The toast activator's sink in a running App: the channel the toast's own
/// `Activated` handler posts to, so a click resolves the same way whichever
/// route it took.
pub fn toastActivatorSink(delivery: *AppDelivery) win32_toast_activator.Sink {
    return .{
        .ctx = delivery,
        .deliver = winrtToastActivationCallback,
        .retain = retainToastDelivery,
        .release = releaseToastDelivery,
    };
}

/// Dispatch this thread's messages until `capture` has its call or
/// `timeout_ms` has passed, and say whether the call came. COM hands an
/// incoming call to this STA as a message, so the dispatch is what runs
/// `Activate`. The deadline is the wait's own, with no timer that could fail
/// to arm, and a quit met on the way is put back for the main loop.
pub fn pumpUntilColdToastActivation(capture: *const ColdToastCapture, timeout_ms: u32) bool {
    const deadline = sys.GetTickCount64() + timeout_ms;
    var msg: MSG = undefined;
    while (!capture.received) {
        while (sys.PeekMessageW(&msg, null, 0, 0, c.PM_REMOVE) != 0) {
            if (msg.message == c.WM_QUIT) {
                sys.PostQuitMessage(@bitCast(@as(u32, @truncate(msg.wParam))));
                return capture.received;
            }
            _ = sys.TranslateMessage(&msg);
            _ = sys.DispatchMessageW(&msg);
            if (capture.received) return true;
        }
        const now = sys.GetTickCount64();
        if (now >= deadline) break;
        const remaining: DWORD = @intCast(deadline - now);
        if (sys.MsgWaitForMultipleObjectsEx(0, null, remaining, c.QS_ALLINPUT, c.MWMO_INPUTAVAILABLE) == c.WAIT_FAILED) break;
    }
    return capture.received;
}

const ColdToastWaitTest = struct {
    const Timer = struct {
        var capture: ColdToastCapture = .{};

        fn fire(_: ?HWND, _: UINT, id: UINT_PTR, _: DWORD) callconv(.winapi) void {
            _ = sys.KillTimer(null, id);
            ColdToastCapture.deliver(&capture, "wgh://activate?surface=3&pid=8&action=focus");
        }
    };

    fn body() !void {
        // Nothing comes: the wait returns at its deadline, not later.
        var none: ColdToastCapture = .{};
        const start = sys.GetTickCount64();
        try std.testing.expect(!pumpUntilColdToastActivation(&none, 60));
        const waited = sys.GetTickCount64() - start;
        try std.testing.expect(waited >= 40);
        try std.testing.expect(waited < 2000);

        // A call dispatched by the pump (here a timer procedure, as COM's call
        // is a dispatched message) ends it well before the deadline.
        Timer.capture = .{};
        try std.testing.expect(sys.SetTimer(null, 0, 10, @ptrCast(&Timer.fire)) != 0);
        const call_start = sys.GetTickCount64();
        try std.testing.expect(pumpUntilColdToastActivation(&Timer.capture, 10_000));
        try std.testing.expect(sys.GetTickCount64() - call_start < 5000);
        try std.testing.expect(Timer.capture.target().eql(.{ .surface_id = 3, .pid = 8, .action = .focus }));

        // A quit ends the wait and stays queued for the main loop.
        var quit_capture: ColdToastCapture = .{};
        sys.PostQuitMessage(7);
        try std.testing.expect(!pumpUntilColdToastActivation(&quit_capture, 10_000));
        var msg: MSG = undefined;
        try std.testing.expect(sys.PeekMessageW(&msg, null, c.WM_QUIT, c.WM_QUIT, c.PM_REMOVE) != 0);
        try std.testing.expectEqual(@as(WPARAM, 7), msg.wParam);
    }
};

test "the cold toast activation wait ends on its call or at its deadline" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;
    // A fresh thread, so the pump dispatches nothing another test queued.
    try runOnHiddenDesktop(ColdToastWaitTest.body);
}

/// Receives the first `Activate` of a cold start, before the App channel
/// exists. `Activate` runs on this thread, inside the wait's message pump.
pub const ColdToastCapture = struct {
    received: bool = false,
    activation: win32_toast_activation.ActivationTarget = .{},

    pub fn sink(self: *ColdToastCapture) win32_toast_activator.Sink {
        return .{ .ctx = self, .deliver = deliver };
    }

    fn deliver(ctx: *anyopaque, launch: []const u8) void {
        const self: *ColdToastCapture = @ptrCast(@alignCast(ctx));
        if (self.received) return;
        self.received = true;
        self.activation = win32_toast_activation.parseLaunchArg(launch) catch .{};
    }

    pub fn target(self: *const ColdToastCapture) win32_toast_activation.ActivationTarget {
        return self.activation;
    }
};

test "a cold toast activation start keeps the first call and reads nothing else as a target" {
    const callback = win32_toast_activator.testCallback();
    const aumid = std.unicode.utf8ToUtf16LeStringLiteral("io.github.amanthanvi.noctty");

    var capture: ColdToastCapture = .{};
    win32_toast_activator.bind(capture.sink());
    defer win32_toast_activator.bind(null);
    _ = callback.vtbl.Activate(callback, aumid, std.unicode.utf8ToUtf16LeStringLiteral("wgh://activate?surface=3&pid=8&action=focus"), null, 0);
    _ = callback.vtbl.Activate(callback, aumid, std.unicode.utf8ToUtf16LeStringLiteral("wgh://activate?surface=4&pid=8"), null, 0);
    try std.testing.expect(capture.received);
    try std.testing.expect(capture.target().eql(.{ .surface_id = 3, .pid = 8, .action = .focus }));

    // A call that carried nothing readable still ends the wait, and its
    // target is the empty one, which only presents the primary window.
    var unreadable: ColdToastCapture = .{};
    win32_toast_activator.bind(unreadable.sink());
    _ = callback.vtbl.Activate(callback, aumid, std.unicode.utf8ToUtf16LeStringLiteral("--command=evil.exe"), null, 0);
    try std.testing.expect(unreadable.received);
    try std.testing.expect(unreadable.target().eql(.{}));
}

pub fn retainToastDelivery(ctx: *anyopaque) void {
    const delivery: *AppDelivery = @ptrCast(@alignCast(ctx));
    delivery.retain();
}

pub fn releaseToastDelivery(ctx: *anyopaque) void {
    const delivery: *AppDelivery = @ptrCast(@alignCast(ctx));
    delivery.release();
}

/// Which caption button (integrated titlebar) the cursor is hovering.
pub const CaptionButton = enum { none, minimize, maximize, close };

pub const TitlebarButtonRole = enum {
    none,
    minimize,
    maximize,
    close,
    new_tab,
    dropdown,
};

pub const TitlebarGlyphKind = enum {
    minimize,
    maximize,
    restore,
    close,
    new_tab,
    dropdown,
};

const TitlebarButtonVisual = struct {
    bg: ?u32 = null,
    glyph: u32,
};

fn titlebarGlyphCodepoint(kind: TitlebarGlyphKind) u16 {
    return switch (kind) {
        .minimize => 0xE921,
        .maximize => 0xE922,
        .restore => 0xE923,
