fn titlebarFallbackIcon(kind: TitlebarGlyphKind) win32_icons.Kind {
    return switch (kind) {
        .minimize => .minimize,
        .maximize => .maximize,
        .restore => .restore,
        .close => .close,
        .new_tab => .plus,
