const search_icon_font_face = search_controls.search_icon_font_face;

const search_icon_font_px = search_controls.search_icon_font_px;
const search_icon_font_registration = &search_controls.search_icon_font_registration;

/// An icon font of `face` with a `height_px` device-pixel em.
fn createIconFontForFace(face: [*:0]const u16, height_px: i32) ?*anyopaque {
    var lf: LOGFONTW = .{};
    lf.lfHeight = -height_px;
    lf.lfWeight = c.FW_NORMAL;
    lf.lfQuality = c.CLEARTYPE_QUALITY;
    const name = std.mem.span(face);
    const copy_len = @min(name.len, c.LF_FACESIZE - 1);
    @memcpy(lf.lfFaceName[0..copy_len], name[0..copy_len]);
    return sys.CreateFontIndirectW(&lf);
}

const search_codicon_glyphs = search_controls.search_codicon_glyphs;

const fontHasSearchCodicons = search_controls.fontHasSearchCodicons;

/// What `fontGlyphCoverage` found.
pub const GlyphCoverage = enum {
    all,
    /// At least one glyph is not in the font.
    missing,
    /// GDI failed before it could say. Unlike `missing`, a later attempt
    /// may succeed.
    unknown,
};

/// Tests set this to fail `fontGlyphCoverage` as a GDI error would, which
/// nothing else can do on demand.
pub var test_glyph_check_fails: if (builtin.is_test) bool else void = if (builtin.is_test) false else {};

/// Whether `font` has a glyph for every UTF-16 unit in `units`. This, not
/// the face name, decides whether an icon font is used: GDI never fails a
/// missing face but hands back a substitute such as Arial, which has none of
/// these private-use code points.
pub fn fontGlyphCoverage(font: *anyopaque, units: []const u16) GlyphCoverage {
    if (builtin.is_test) {
        if (test_glyph_check_fails) return .unknown;
    }
    const hdc = sys.CreateCompatibleDC(null) orelse return .unknown;
    defer _ = sys.DeleteDC(hdc);
    const old_font = sys.SelectObject(hdc, font) orelse return .unknown;
    defer _ = sys.SelectObject(hdc, old_font);
    for (units) |unit| {
        const glyph = [1]u16{unit};
        var index: [1]u16 = undefined;
        if (sys.GetGlyphIndicesW(
            hdc,
            &glyph,
            1,
            &index,
            c.GGI_MARK_NONEXISTING_GLYPHS,
        ) != 1) return .unknown;
        if (index[0] == 0xFFFF) return .missing;
    }
    return .all;
}

/// The titlebar icon faces, best first. Windows 11 ships Segoe Fluent Icons;
/// Windows 10 ships only Segoe MDL2 Assets, which has the same code points.
pub const titlebar_icon_faces = [_][*:0]const u16{ titlebar_icon_font_fluent, titlebar_icon_font_mdl2 };

/// Every glyph `drawTitlebarGlyph` draws. Both titlebar icon fonts must have
/// all of them, so the caption buttons and the tab row's buttons come from
/// the same face.
pub const titlebar_icon_glyphs = glyphs: {
    const kinds = std.enums.values(TitlebarGlyphKind);
    var units: [kinds.len]u16 = undefined;
    for (kinds, &units) |kind, *unit| unit.* = titlebarGlyphText(kind)[0];
    break :glyphs units;
};

/// An icon font from `createIconFontWithGlyphs`.
pub const IconFontChoice = struct {
    font: ?*anyopaque = null,
    /// No font: every face was created and checked, and none has the
    /// glyphs, so the caller draws `win32_icons` by design. Without this, a
    /// null font means GDI failed to create or check one, which a later
    /// theme message retries.
    geometric: bool = false,
};

/// The first of `faces` whose font has every one of `glyphs`, at a
/// `height_px` device-pixel em. `CreateFontIndirectW` succeeding says
/// nothing: it substitutes another face for a missing one (Arial for
/// "Segoe Fluent Icons" on Windows 10), so the glyph table decides. A face
/// GDI failed to create or check is passed over like a missing one, but
/// the result is then not `geometric`.
pub fn createIconFontWithGlyphs(
    faces: []const [*:0]const u16,
    glyphs: []const u16,
    height_px: i32,
) IconFontChoice {
    var checked_every_face = true;
    for (faces) |face| {
        const font = createIconFontForFace(face, height_px) orelse {
            checked_every_face = false;
            continue;
        };
        switch (fontGlyphCoverage(font, glyphs)) {
            .all => return .{ .font = font },
            .missing => {},
            .unknown => checked_every_face = false,
        }
        _ = sys.DeleteObject(font);
    }
    return .{ .geometric = checked_every_face };
}

pub fn titlebarRoleFromCaption(button: CaptionButton) TitlebarButtonRole {
    return switch (button) {
        .none => .none,
        .minimize => .minimize,
        .maximize => .maximize,
        .close => .close,
    };
}

pub fn titlebarCaptionFromHitTest(ht: i32) CaptionButton {
    return switch (ht) {
        c.HTMINBUTTON => .minimize,
        c.HTMAXBUTTON => .maximize,
        c.HTCLOSE => .close,
        else => .none,
    };
}

/// Whether a right-click the host received as `WM_NCRBUTTONUP` opens the
/// window menu here. Only on a caption row the host keeps in its client
/// area (`Host.clientCaptionHeight` non-null): DefWindowProc turns the
/// right-click into `WM_CONTEXTMENU`, whose handler looks for the caption
/// in the stock frame's geometry instead of asking `WM_NCHITTEST`, and
/// `WM_NCCALCSIZE` has made that row client area, so it opens nothing.
/// Where Windows draws the caption (null) it keeps the right-click.
fn captionRightClickOpensWindowMenu(ht: i32, client_caption_height: ?i32) bool {
    return ht == c.HTCAPTION and client_caption_height != null;
}

/// What the host does with a right-button message on a client-area caption,
/// or null to leave it to DefWindowProc. The press is swallowed, not only
/// the release: measured on build 26200, DefWindowProc given
/// `WM_NCRBUTTONDOWN` HTCAPTION on an active window runs a modal loop that
/// ends only when it removes the `WM_RBUTTONUP` the captured release turns
/// into, and neither `WM_NCRBUTTONUP` nor `WM_CONTEXTMENU` follows, so the
/// release never reached the menu. A quick second press arrives as
/// `WM_NCRBUTTONDBLCLK`, which needs no `CS_DBLCLKS`.
const CaptionRightClick = enum { swallow, open_menu };

fn captionRightClick(msg: UINT, ht: i32, client_caption_height: ?i32) ?CaptionRightClick {
    if (!captionRightClickOpensWindowMenu(ht, client_caption_height)) return null;
    return switch (msg) {
        c.WM_NCRBUTTONDOWN, c.WM_NCRBUTTONDBLCLK => .swallow,
        c.WM_NCRBUTTONUP => .open_menu,
        else => null,
    };
}

/// Which window-menu commands a window style allows, and the bold default,
/// by the rules DefWindowProc applies before it opens the menu from a stock
/// caption. The menu `GetSystemMenu` returns keeps whatever state it was
/// last given, and `TrackPopupMenu` does not refresh it: without this a
/// maximized window offered Maximize, Move and Size and grayed Restore.
/// Close is left as Windows keeps it. Measured on build 26200: Move stays
/// enabled on a minimized window, and Close is the default unless the
/// window is minimized.
const WindowMenuState = struct {
    restore: bool,
    move: bool,
    size: bool,
    minimize: bool,
    maximize: bool,
    default_command: WPARAM,
};

fn windowMenuState(style: u32) WindowMenuState {
    const maximized = style & c.WS_MAXIMIZE != 0;
    const minimized = style & c.WS_MINIMIZE != 0;
    return .{
        .restore = maximized or minimized,
        .move = !maximized,
        .size = style & c.WS_THICKFRAME != 0 and !maximized and !minimized,
        .minimize = style & c.WS_MINIMIZEBOX != 0 and !minimized,
        .maximize = style & c.WS_MAXIMIZEBOX != 0 and !maximized,
        .default_command = if (minimized) c.SC_RESTORE else c.SC_CLOSE,
    };
}

/// Shows the window menu at the screen point of a `WM_NCRBUTTONUP` and
/// runs the chosen command. `TPM_RETURNCMD` and a posted `WM_SYSCOMMAND`
/// run it after the menu loop has returned, as Windows Terminal does for
/// its own caption.
fn openWindowMenuAt(hwnd: HWND, lParam: LPARAM) void {
    const bits: u32 = @truncate(@as(u64, @bitCast(lParam)));
    const x: i32 = @as(i16, @bitCast(@as(u16, @truncate(bits))));
    const y: i32 = @as(i16, @bitCast(@as(u16, @truncate(bits >> 16))));
    // Track a fresh copy of the window menu. Measured on build 26300, on an
    // active window the copy the first `GetSystemMenu(hwnd, FALSE)` returns
    // passes `IsMenu` but `TrackPopupMenu` rejects it with
    // ERROR_INVALID_MENU_HANDLE, so a real right-click opened nothing; the
    // copy taken after reverting it tracks. Nothing customizes this menu.
    _ = sys.GetSystemMenu(hwnd, 1);
    const menu = sys.GetSystemMenu(hwnd, 0) orelse return;
    const style: u32 = @truncate(@as(usize, @bitCast(sys.GetWindowLongPtrW(hwnd, c.GWL_STYLE))));
    const state = windowMenuState(style);
    for ([_]struct { WPARAM, bool }{
        .{ c.SC_RESTORE, state.restore },
        .{ c.SC_MOVE, state.move },
        .{ c.SC_SIZE, state.size },
        .{ c.SC_MINIMIZE, state.minimize },
        .{ c.SC_MAXIMIZE, state.maximize },
    }) |item| {
        _ = sys.EnableMenuItem(menu, @intCast(item[0]), c.MF_BYCOMMAND | if (item[1]) c.MF_ENABLED else c.MF_GRAYED);
    }
    _ = sys.SetMenuDefaultItem(menu, @intCast(state.default_command), 0);
    const cmd = sys.TrackPopupMenu(menu, c.TPM_RETURNCMD | c.TPM_RIGHTBUTTON, x, y, 0, hwnd, null);
    if (cmd > 0) _ = sys.PostMessageW(hwnd, c.WM_SYSCOMMAND, @intCast(cmd), 0);
}

fn captionButtonSysCommand(ht: i32, is_zoomed: bool) ?WPARAM {
    return switch (ht) {
        c.HTMINBUTTON => c.SC_MINIMIZE,
        c.HTMAXBUTTON => if (is_zoomed) c.SC_RESTORE else c.SC_MAXIMIZE,
        else => null,
    };
}

/// Hit-test code the mouse path produces for a caption button. Lets the
/// UIA Invoke path reuse `captionButtonSysCommand` instead of restating
/// the minimize / maximize / restore mapping.
fn captionButtonHitTest(kind: win32_uia.CaptionButtonKind) i32 {
    return switch (kind) {
        .minimize => c.HTMINBUTTON,
        .maximize => c.HTMAXBUTTON,
        .close => c.HTCLOSE,
    };
}

/// The `WM_SYSCOMMAND` the mouse path sends for a caption button.
/// `captionButtonSysCommand` owns minimize and maximize, including the
/// zoomed to restore flip; close comes from the `WM_NCLBUTTONUP` branch,
/// which sends `SC_CLOSE` on its own.
fn captionButtonCommand(kind: win32_uia.CaptionButtonKind, is_zoomed: bool) ?WPARAM {
    return switch (kind) {
        .close => c.SC_CLOSE,
        .minimize, .maximize => captionButtonSysCommand(
            captionButtonHitTest(kind),
            is_zoomed,
        ),
    };
}

pub fn ncRectToWin32(rect: win32_nc_layout.Rect) RECT {
    return .{
        .left = rect.left,
        .top = rect.top,
        .right = rect.right,
        .bottom = rect.bottom,
    };
}

pub fn win32RectToNc(rect: RECT) win32_nc_layout.Rect {
    return .{
        .left = rect.left,
        .top = rect.top,
        .right = rect.right,
        .bottom = rect.bottom,
    };
}

fn titlebarSubtleFill(parent_bg: u32, is_dark: bool, pressed: bool) u32 {
    const overlay = if (is_dark) rgb(0xFF, 0xFF, 0xFF) else rgb(0x00, 0x00, 0x00);
    const alpha: f32 = if (pressed) 0.04 else 0.06;
    return blendColorRGB(parent_bg, overlay, alpha);
}

pub fn titlebarButtonVisual(
    theme: *const ThemeColors,
    role: TitlebarButtonRole,
    parent_bg: u32,
    hover_alpha: f32,
    pressed: bool,
    high_contrast: bool,
    window_active: bool,
) TitlebarButtonVisual {
    const active = pressed or hover_alpha > 0.0;
    if (high_contrast) {
        return .{
            .bg = if (active) theme.button_active_bg else null,
            .glyph = if (active) theme.button_active_fg else theme.text_primary,
        };
    }

    const idle_glyph = win32_theme.windowChromeTextColor(theme, switch (role) {
        .new_tab, .dropdown => theme.button_chrome_fg,
        else => theme.text_primary,
    }, window_active, high_contrast);
    if (!active) return .{ .bg = null, .glyph = idle_glyph };

    const target_bg = switch (role) {
        .close => rgb(0xC4, 0x2B, 0x1C),
        .minimize, .maximize, .new_tab, .dropdown => titlebarSubtleFill(parent_bg, theme.is_dark, pressed),
        .none => parent_bg,
    };
    const target_glyph = switch (role) {
        .close => if (pressed) blendColorRGB(target_bg, rgb(0xFF, 0xFF, 0xFF), 0.70) else rgb(0xFF, 0xFF, 0xFF),
        .minimize, .maximize => theme.text_primary,
        .new_tab, .dropdown => theme.text_primary,
        .none => idle_glyph,
    };

    const alpha: f32 = if (pressed) 1.0 else std.math.clamp(hover_alpha, 0.0, 1.0);
    return .{
        .bg = blendColorRGB(parent_bg, target_bg, alpha),
        .glyph = blendColorRGB(idle_glyph, target_glyph, alpha),
    };
}

pub const HostTabStatus = labels.HostTabStatus;

pub const ConfirmPrompt = overlay_session.ConfirmPrompt;

/// How long a program's prompt ignores Allow after it opens: longer than
/// the gap between two keys of someone typing, shorter than reading it.
const program_confirm_arming_ms = 500;

/// What a close that ends several terminals at once is closing. One pane
/// keeps its own prompt in `Surface.close`. The userdata of a `.this_tab`
/// prompt is the Surface of the tab, which names the tab when it is behind.
pub const CloseScope = enum { window, this_tab, other_tabs, right_tabs, app, update };

/// The prompt for a close that would end `count` (at least 1) terminals
/// that `confirm-close-surface` asks about. The body may live in `body_buf`.
pub fn closeScopePrompt(scope: CloseScope, count: usize, body_buf: *[256]u8) ConfirmPrompt {
    switch (scope) {
        inline else => |comptime_scope| {
            const text: struct { title: []const u8, accept: []const u8, one: []const u8, many: []const u8 } = comptime switch (comptime_scope) {
                .window => .{
                    .title = "Close this window?",
                    .accept = "Close",
                    .one = "A process is still running in this window. Closing the window will terminate it.",
                    .many = "Processes are still running in {d} terminals in this window. Closing the window will terminate them.",
                },
                .this_tab => .{
                    .title = "Close this tab?",
                    .accept = "Close tab",
                    .one = "A process is still running in this tab. Closing the tab will terminate it, and undo is off.",
                    .many = "Processes are still running in {d} terminals in this tab. Closing the tab will terminate them, and undo is off.",
                },
                .other_tabs => .{
                    .title = "Close the other tabs?",
                    .accept = "Close tabs",
                    .one = "A process is still running in another tab. Closing the other tabs will terminate it.",
                    .many = "Processes are still running in {d} terminals in the other tabs. Closing those tabs will terminate them.",
                },
                .right_tabs => .{
                    .title = "Close the tabs to the right?",
                    .accept = "Close tabs",
                    .one = "A process is still running in a tab to the right. Closing those tabs will terminate it.",
                    .many = "Processes are still running in {d} terminals in the tabs to the right. Closing those tabs will terminate them.",
                },
                .app => .{
                    .title = "Quit noctty?",
                    .accept = "Quit",
                    .one = "A process is still running. Quitting noctty will terminate it.",
                    .many = "Processes are still running in {d} terminals. Quitting noctty will terminate them.",
                },
                .update => .{
                    .title = "Install the update?",
                    .accept = "Install",
                    .one = "A process is still running. Installing the update closes noctty and will terminate it.",
                    .many = "Processes are still running in {d} terminals. Installing the update closes noctty and will terminate them.",
                },
            };
            return .{
                .title = text.title,
                .body = if (count <= 1) text.one else std.fmt.bufPrint(body_buf, text.many, .{count}) catch text.one,
                .accept_label = text.accept,
                .cancel_label = "Cancel",
            };
        },
    }
}

/// How many panes in `tabs` `confirm-close-surface` asks about.
pub fn tabsCloseConfirmCount(tabs: []Tab) usize {
    return countPanesWhere(tabs, Surface.needsCloseConfirm);
}

/// `tabsCloseConfirmCount` without waiting for a renderer mutex
/// (`Surface.needsCloseConfirmNoWait`).
pub fn tabsCloseConfirmCountNoWait(tabs: []Tab) usize {
    return countPanesWhere(tabs, Surface.needsCloseConfirmNoWait);
}

fn countPanesWhere(tabs: []Tab, comptime predicate: fn (*Surface) bool) usize {
    var count: usize = 0;
    for (tabs) |*tab| {
        var it = tab.tree.iterator();
        while (it.next()) |entry| {
            if (predicate(entry.view)) count += 1;
        }
    }
    return count;
}

