pub const SplitTreeSurface = SplitTree(Surface);

pub const Tab = struct {
    alloc: Allocator,
    id: u32,
    shell_id: ?win32_shell.model.TabId = null,
    tree: SplitTreeSurface,
    focused: SplitTreeSurface.Node.Handle = .root,
    button_hwnd: ?HWND = null,
    button_prev_proc: ?*const anyopaque = null,
    uia_provider: ?*win32_uia.ChromeControlProvider = null,
    cached_button_title: ?[:0]const u8 = null,
    /// The label was built with the bell glyph; see `Host.syncTabButtons`.
    cached_button_bell: bool = false,
    cached_button_label: ?[:0]const u8 = null,
    cached_button_index: usize = 0,
    cached_button_active: bool = false,
    cached_button_pane_count: usize = 0,
    cached_button_label_max_width: usize = 0,
    cached_button_show_pane_count: bool = false,
    button_label_cache_valid: bool = false,
    button_placement: child_window.ChildPlacement = .{},
    /// What the tab strip shows for the programs in this tab (OSC 7501),
    /// kept so a change repaints the button and reaches assistive
    /// technology once. Owned by `Host.refreshTabStatus`.
    status_indicator: win32_program_status.Indicator = .none,
    /// What `ItemStatus` last announced, as `tabStatusKey`; 0 for nothing.
    status_key: u64 = 0,

    pub fn init(alloc: Allocator, id: u32, surface: *Surface) !Tab {
        return .{
            .alloc = alloc,
            .id = id,
            .tree = try SplitTreeSurface.init(alloc, surface),
            .focused = .root,
        };
    }

    pub fn deinit(self: *Tab) void {
        std.debug.assert(self.uia_provider == null);
        if (self.cached_button_title) |value| self.alloc.free(value);
        if (self.cached_button_label) |value| self.alloc.free(value);
        destroySubclassedWindow(&self.button_hwnd, &self.button_prev_proc);
        self.tree.deinit();
        self.* = undefined;
    }

    pub fn focusedSurface(self: *const Tab) ?*Surface {
        if (self.tree.nodes.len == 0) return null;
        return switch (self.tree.nodes[self.focused.idx()]) {
            .leaf => |surface| surface,
            .split => null,
        };
    }

    pub fn findHandle(self: *const Tab, surface: *Surface) ?SplitTreeSurface.Node.Handle {
        var it = self.tree.iterator();
        while (it.next()) |entry| {
            if (entry.view == surface) return entry.handle;
        }
        return null;
    }

    pub fn findSurfaceByCoreId(self: *const Tab, surface_id: u64) ?*Surface {
        var it = self.tree.iterator();
        while (it.next()) |entry| {
            if (entry.view.core().id == surface_id) return entry.view;
        }
        return null;
    }

    pub fn leafCount(self: *const Tab) usize {
        var count: usize = 0;
        var it = self.tree.iterator();
        while (it.next()) |_| count += 1;
        return count;
    }

    /// A terminal in the tab rang the bell and has not been focused or typed
    /// into since (`bell-features = title`).
    pub fn bellRinging(self: *const Tab) bool {
        var it = self.tree.iterator();
        while (it.next()) |entry| if (entry.view.bell_ringing) return true;
        return false;
    }

    pub fn clearRedoHistory(self: *Tab) void {
        var it = self.tree.iterator();
        while (it.next()) |entry| {
            entry.view.undo_stack.clearRedo();
        }
    }

    pub fn clearRedoHistoryExcept(self: *Tab, skip: *Surface) void {
        var it = self.tree.iterator();
        while (it.next()) |entry| {
            if (entry.view == skip) continue;
            entry.view.undo_stack.clearRedo();
        }
    }
};

pub const ChromeTextDirty = win32_chrome_state.TextDirty;
pub const ChromeRepaintMask = win32_chrome_state.RepaintMask;
pub const QuickTerminalAnimation = quick_terminal_host.QuickTerminalAnimation;

pub const Host = host_module.Host;

pub fn destroyChildWindow(hwnd_slot: *?HWND) void {
    const hwnd = hwnd_slot.* orelse return;

    hwnd_slot.* = null;
    if (sys.IsWindow(hwnd) == 0) return;

    setWindowData(hwnd, null);
    _ = sys.DestroyWindow(hwnd);
}

pub fn destroySubclassedWindowWithPrev(
    hwnd_slot: *?HWND,
    prev_proc: ?*const anyopaque,
) void {
    const hwnd = hwnd_slot.* orelse return;

    // Detach host state before destroying the control. DestroyWindow is
    // synchronous and can reenter our subclass proc during WM_DESTROY /
    // WM_NCDESTROY, so leaving the HWND discoverable via host tabs/buttons
    // risks callbacks touching half-torn state.
    hwnd_slot.* = null;
    if (sys.IsWindow(hwnd) == 0) return;

    setWindowData(hwnd, null);
    if (prev_proc) |proc| {
        _ = sys.SetWindowLongPtrW(
            hwnd,
            c.GWLP_WNDPROC,
            @as(LONG_PTR, @intCast(@intFromPtr(proc))),
        );
    }
    _ = sys.DestroyWindow(hwnd);
}

pub fn destroySubclassedWindow(
    hwnd_slot: *?HWND,
    prev_proc_slot: *?*const anyopaque,
) void {
    const prev_proc = prev_proc_slot.*;
    prev_proc_slot.* = null;
    destroySubclassedWindowWithPrev(hwnd_slot, prev_proc);
}

pub const SurfaceInitOptions = struct {
    quick_terminal: bool = false,
    host_id: ?u32 = null,
    tab_id: ?u32 = null,
    tab_insert_index: ?usize = null,
    clone_state_from: ?*const Surface = null,
    split_direction: SplitTreeSurface.Split.Direction = .right,
    /// How the newly-created host HWND first appears, once GL and core
    /// initialization succeed. Used by the quick-terminal passive mode
    /// (`quick-terminal-keyboard-interactivity = none`) on first toggle-on,
    /// and by a handed-off console that asked not to take focus.
    show: InitialShow = .activate,
    adopted_session: ?*win32_terminal_handoff.PendingSession = null,
    /// Whether a new window takes `maximize` and `fullscreen` from `config`
    /// while `Surface.init` shows it. Session restore turns this off: it
    /// moves the window to its saved rect first and applies them afterwards
    /// (`App.restoreSessionWindow`).
    config_window_start: bool = true,
    /// The argv a forwarded launch (a second `noctty`, or `noctty
    /// +new-window`) applied to `config`, for `WindowKeeps`.
    forwarded_arguments: ?[]const [:0]const u8 = null,
};

pub const WindowKeeps = window_state.WindowKeeps;

pub const WindowStart = window_state.WindowStart;

/// The first show of a new host window.
pub const InitialShow = enum {
    /// Shown and presented with focus.
    activate,
    /// Visible without stealing focus from the caller's foreground window.
    no_activate,
    /// Minimized, without activation: the window exists but stays out of the
    /// way, and the taskbar button is all the user sees.
    minimized,
    /// Maximized, with focus.
    maximized,

    /// The `ShowWindow` command for the first show, if it is not left to
    /// `presentWindow`. A maximize is followed by `presentWindow` for focus.
    pub fn showCommand(self: InitialShow) ?i32 {
        return switch (self) {
            .activate => null,
            .no_activate => c.SW_SHOWNOACTIVATE,
            .minimized => c.SW_SHOWMINNOACTIVE,
            .maximized => c.SW_MAXIMIZE,
        };
    }

    pub fn takesFocus(self: InitialShow) bool {
        return self == .activate or self == .maximized;
    }
};

/// The first show a handed-off console asked for in its `STARTUPINFO`.
///
/// `wShowWindow` means something only when `STARTF_USESHOWWINDOW` is set; it
/// is whatever the client left there otherwise. Conhost hands over consoles
/// started with `SW_HIDE` too (only `CREATE_NO_WINDOW` keeps a console
/// windowless), and a host with no way to be shown again is worse than a
/// minimized one, so a hide becomes a minimize that takes no focus.
pub fn adoptedInitialShow(startup_flags: u32, show_window: u16) InitialShow {
    if (startup_flags & win32_terminal_handoff.STARTF_USESHOWWINDOW == 0) return .activate;
    return switch (show_window) {
        c.SW_SHOWNOACTIVATE, c.SW_SHOWNA => .no_activate,
        c.SW_HIDE, c.SW_SHOWMINIMIZED, c.SW_MINIMIZE, c.SW_SHOWMINNOACTIVE, c.SW_FORCEMINIMIZE => .minimized,
        c.SW_MAXIMIZE => .maximized,
        else => .activate,
    };
}

pub const SplitSurfaceAttachRollback = struct {
    tab: *Tab,
    tree: SplitTreeSurface,
    focused: SplitTreeSurface.Node.Handle,
};

pub fn rollbackFailedSurfaceAttach(
    tabs: *std.ArrayListUnmanaged(Tab),
    active_tab: *usize,
    prev_active_tab: usize,
    prev_tab_count: usize,
    inserted_tab_index: ?usize,
    split_rollback: *?SplitSurfaceAttachRollback,
) void {
    if (split_rollback.*) |state| {
        state.tab.tree.deinit();
        state.tab.tree = state.tree;
        state.tab.focused = state.focused;
        split_rollback.* = null;
    } else if (tabs.items.len > prev_tab_count) {
        // Null inserted_tab_index means no caller-recorded tab insert index;
        // remove the newest tab as a best-effort rollback for legacy callers.
        const remove_index = clampTabInsertIndex(inserted_tab_index orelse tabs.items.len - 1, tabs.items.len - 1);
        var removed = tabs.orderedRemove(remove_index);
        removed.deinit();
    }

    active_tab.* = @min(prev_active_tab, if (tabs.items.len > 0) tabs.items.len - 1 else 0);
}

pub fn commitSplitSurfaceAttach(split_rollback: *?SplitSurfaceAttachRollback) void {
    if (split_rollback.*) |*state| {
        state.tree.deinit();
        split_rollback.* = null;
    }
}

pub fn windowNewTabInsertIndex(
    host: *const Host,
    position: configpkg.Config.WindowNewTabPosition,
) usize {
    return switch (position) {
        .current => clampTabInsertIndex(host.active_tab + 1, host.tabs.items.len),
        .end => host.tabs.items.len,
    };
}

pub fn requestedTabInsertIndex(requested: ?usize, tab_count: usize) usize {
    return clampTabInsertIndex(requested orelse tab_count, tab_count);
}

pub fn clampTabInsertIndex(index: usize, tab_count: usize) usize {
    return @min(index, tab_count);
}

pub const RestoredTerminalUndoState = struct {
    title: ?[]const u8 = null,
    pwd: ?[]const u8 = null,
    scrollbar: terminal.Scrollbar = .zero,
};

const undo_snapshot_magic = "WUH3";

fn terminalUndoTrailingBlankRows(terminal_state: *const terminal.Terminal) usize {
    var rows: usize = 0;
    var it = terminal_state.screens.active.pages.getBottomRight(.screen).?.rowIterator(.left_up, null);
    while (it.next()) |pin| {
        // Match the formatter's trailing-row trimming predicate.
        if (terminal.page.Cell.hasTextAny(pin.cells(.all))) break;
        rows += 1;
    }
    return rows;
}

pub fn captureTerminalUndoStateBytes(
    alloc: Allocator,
    terminal_state: *const terminal.Terminal,
) ![]u8 {
    var vt_buf: std.Io.Writer.Allocating = .init(alloc);
    defer vt_buf.deinit();

    var formatter = terminal.formatter.TerminalFormatter.init(
        terminal_state,
        .vt,
    );
    formatter.extra = .all;
    formatter.extra.pwd = false;
    try formatter.format(&vt_buf.writer);

    const vt_bytes = try vt_buf.toOwnedSlice();
    defer alloc.free(vt_bytes);

    const title = terminal_state.getTitle() orelse "";
    const pwd = terminal_state.getPwd() orelse "";

    var buf: std.Io.Writer.Allocating = .init(alloc);
    defer buf.deinit();
    try buf.writer.writeAll(undo_snapshot_magic);
    try buf.writer.writeInt(u32, @intCast(title.len), .little);
    try buf.writer.writeInt(u32, @intCast(pwd.len), .little);
    try buf.writer.writeInt(u32, terminal_state.cols, .little);
    // The formatter trims trailing blank rows, and replay may prune older
    // history at different page boundaries. Anchor the cursor to the last
    // text row so neither changes which content is shifted to the live row.
    try buf.writer.writeInt(i64, @as(i64, terminal_state.screens.active.cursor.y) -
        @as(i64, terminal_state.rows - 1) +
        @as(i64, @intCast(terminalUndoTrailingBlankRows(terminal_state))), .little);
    try buf.writer.writeAll(title);
    try buf.writer.writeAll(pwd);
    try buf.writer.writeAll(vt_bytes);
    return try buf.toOwnedSlice();
}

test "win32 terminal undo shifts restored rows to the live ConPTY cursor" {
    const alloc = std.testing.allocator;
    var t = try terminal.Terminal.init(alloc, .{ .cols = 12, .rows = 5 });
    defer t.deinit(alloc);
    var stream = t.vtStream();
    defer stream.deinit();
    stream.nextSlice("one\r\ntwo\r\nthree\r\nfour");
    const snapshot = try captureTerminalUndoStateBytes(alloc, &t);
    defer alloc.free(snapshot);

    // An off-prompt clear keeps the cursor column; reset homes it too.
    for ([_]terminal.size.CellCountInt{ 0, 4 }) |live_x| {
        t.fullReset();
        t.screens.active.cursorAbsolute(live_x, 0);
        _ = restoreTerminalUndoState(&t, snapshot, true);
        try std.testing.expectEqual(@as(terminal.size.CellCountInt, 0), t.screens.active.cursor.y);
        try std.testing.expectEqual(live_x, t.screens.active.cursor.x);
        const plain = try t.screens.active.dumpStringAlloc(alloc, .{ .screen = .{} });
        defer alloc.free(plain);
        try std.testing.expect(std.mem.indexOf(u8, plain, "one\ntwo\nthree\nfour") != null);
        const active = try t.screens.active.dumpStringAlloc(alloc, .{ .active = .{} });
        defer alloc.free(active);
        try std.testing.expect(std.mem.startsWith(u8, active, "four"));

        // Absolute moves after undo use the live console's coordinate space.
        stream.nextSlice("\x1b[2;3HX");
        try std.testing.expectEqual(@as(terminal.size.CellCountInt, 1), t.screens.active.cursor.y);
        try std.testing.expectEqual(@as(terminal.size.CellCountInt, 3), t.screens.active.cursor.x);
    }
}

test "win32 terminal undo keeps nonzero live rows, wrap and snapshot margins" {
    const alloc = std.testing.allocator;
    var t = try terminal.Terminal.init(alloc, .{ .cols = 12, .rows = 6 });
    defer t.deinit(alloc);
    var stream = t.vtStream();
    defer stream.deinit();
    stream.nextSlice("one\r\ntwo\r\nthree\r\nfour\x1b[2;5r\x1b[4;5H");
    const region = t.scrolling_region;
    const snapshot = try captureTerminalUndoStateBytes(alloc, &t);
    defer alloc.free(snapshot);

    // Output can arrive between a clear and undo. Both upward and downward
    // shifts use the live row and scroll the whole screen despite margins.
    for ([_]terminal.size.CellCountInt{ 1, 4 }) |live_y| {
        t.fullReset();
        t.screens.active.cursorAbsolute(11, live_y);
        t.screens.active.cursor.pending_wrap = true;
        _ = restoreTerminalUndoState(&t, snapshot, true);
        try std.testing.expectEqual(live_y, t.screens.active.cursor.y);
        try std.testing.expectEqual(@as(terminal.size.CellCountInt, 11), t.screens.active.cursor.x);
        try std.testing.expect(t.screens.active.cursor.pending_wrap);
        try std.testing.expectEqual(region, t.scrolling_region);
        const row = t.screens.active.cursor.page_row;
        const cells = t.screens.active.cursor.page_pin.node.page().getCells(row);
        try std.testing.expectEqual(@as(u21, 'f'), cells[0].codepoint());
    }
}

test "win32 terminal undo keeps alternate screen rows while preserving the live cursor" {
    const alloc = std.testing.allocator;
    var t = try terminal.Terminal.init(alloc, .{ .cols = 12, .rows = 5 });
    defer t.deinit(alloc);
    var stream = t.vtStream();
    defer stream.deinit();
    stream.nextSlice("\x1b[?1049hone\r\ntwo\r\nthree\r\nfour");
    const snapshot = try captureTerminalUndoStateBytes(alloc, &t);
    defer alloc.free(snapshot);
    t.fullReset();
    _ = restoreTerminalUndoState(&t, snapshot, true);
    try std.testing.expect(t.screens.active_key == .alternate);
    try std.testing.expectEqual(@as(terminal.size.CellCountInt, 0), t.screens.active.cursor.y);
    try std.testing.expectEqual(@as(terminal.size.CellCountInt, 0), t.screens.active.cursor.x);
    const active = try t.screens.active.dumpStringAlloc(alloc, .{ .active = .{} });
    defer alloc.free(active);
    try std.testing.expect(std.mem.startsWith(u8, active, "one\ntwo\nthree\nfour"));
}

test "win32 terminal undo anchors a cursor above or below the last text row" {
    const alloc = std.testing.allocator;
    for ([_]terminal.size.CellCountInt{ 1, 5 }) |saved_y| {
        var t = try terminal.Terminal.init(alloc, .{ .cols = 12, .rows = 6 });
        defer t.deinit(alloc);
        var stream = t.vtStream();
        defer stream.deinit();
        stream.nextSlice("one\r\ntwo\r\nthree\r\nfour");
        t.screens.active.cursorAbsolute(0, saved_y);
        const snapshot = try captureTerminalUndoStateBytes(alloc, &t);
        defer alloc.free(snapshot);
        t.fullReset();
        _ = restoreTerminalUndoState(&t, snapshot, true);
        const row = t.screens.active.cursor.page_row;
        const cells = t.screens.active.cursor.page_pin.node.page().getCells(row);
        try std.testing.expectEqual(@as(u21, if (saved_y == 1) 't' else 0), cells[0].codepoint());
        try std.testing.expectEqual(@as(terminal.size.CellCountInt, 0), t.screens.active.cursor.y);
    }
}

test "win32 terminal undo aligns content after replay prunes history" {
    const alloc = std.testing.allocator;
    var t = try terminal.Terminal.init(alloc, .{ .cols = 80, .rows = 5, .max_scrollback = 16 * 1024 * 1024 });
    defer t.deinit(alloc);
    var stream = t.vtStream();
    defer stream.deinit();
    const history_lines = @as(usize, t.screens.active.pages.pages.first.?.capacity().rows) * 4;
    for (0..history_lines) |_| stream.nextSlice("history\r\n");
    stream.nextSlice("\x1b[4;1H\x1b[Jprompt");
    const captured_rows = t.screens.active.pages.total_rows;
    try std.testing.expect(captured_rows > history_lines);
    const snapshot = try captureTerminalUndoStateBytes(alloc, &t);
    defer alloc.free(snapshot);
    // Replay can retain fewer history rows due to page packing at the cap.
    // A smaller cap makes that pruning deterministic without relying on a
    // particular page's style/grapheme allocation layout.
    t.screens.active.pages.explicit_max_size = 0;
    t.fullReset();
    _ = restoreTerminalUndoState(&t, snapshot, true);
    try std.testing.expect(t.screens.active.pages.total_rows < captured_rows);
    const row = t.screens.active.cursor.page_row;
    const cells = t.screens.active.cursor.page_pin.node.page().getCells(row);
    try std.testing.expectEqual(@as(u21, 'p'), cells[0].codepoint());
    try std.testing.expectEqual(@as(terminal.size.CellCountInt, 0), t.screens.active.cursor.y);
}

test "win32 terminal undo aligns content with scrollback and trailing blank rows" {
    const alloc = std.testing.allocator;
    var t = try terminal.Terminal.init(alloc, .{ .cols = 12, .rows = 5 });
    defer t.deinit(alloc);
    var stream = t.vtStream();
    defer stream.deinit();
