    const snapshot = try captureTerminalUndoStateBytes(alloc, &t);
    defer alloc.free(snapshot);
    t.fullReset();
    _ = restoreTerminalUndoState(&t, snapshot, true);
    try std.testing.expectEqual(@as(terminal.size.CellCountInt, 0), t.screens.active.cursor.y);
    const row = t.screens.active.cursor.page_row;
    const cells = t.screens.active.cursor.page_pin.node.page().getCells(row);
    try std.testing.expectEqual(@as(u21, 'p'), cells[0].codepoint());
    const all = try t.screens.active.dumpStringAlloc(alloc, .{ .screen = .{} });
    defer alloc.free(all);
    try std.testing.expect(std.mem.indexOf(u8, all, "1\n2\n3\n4\n5\nprompt") != null);
}

pub fn restoreTerminalUndoState(
    terminal_state: *terminal.Terminal,
    state_bytes: []const u8,
    preserve_cursor: bool,
) RestoredTerminalUndoState {
    const live_x = terminal_state.screens.active.cursor.x;
    const live_y = terminal_state.screens.active.cursor.y;
    const live_wrap = terminal_state.screens.active.cursor.pending_wrap;
    var title_bytes: []const u8 = "";
    var pwd_bytes: []const u8 = "";
    var vt_bytes = state_bytes;
    var cursor_from_last_text: ?i64 = null;
    if (state_bytes.len >= 24 and std.mem.eql(u8, state_bytes[0..4], undo_snapshot_magic)) {
        const title_len: usize = std.mem.readInt(u32, state_bytes[4..8], .little);
        const pwd_len: usize = std.mem.readInt(u32, state_bytes[8..12], .little);
        const captured_cols = std.mem.readInt(u32, state_bytes[12..16], .little);
        if (captured_cols == terminal_state.cols) {
            cursor_from_last_text = std.mem.readInt(i64, state_bytes[16..24], .little);
        }
        const title_start = 24;
        const pwd_start = title_start + title_len;
        const vt_start = pwd_start + pwd_len;
        if (vt_start <= state_bytes.len) {
            title_bytes = state_bytes[title_start..pwd_start];
            pwd_bytes = state_bytes[pwd_start..vt_start];
            vt_bytes = state_bytes[vt_start..];
        }
    }

    terminal_state.fullReset();
    var stream = terminal_state.vtStream();
    defer stream.deinit();
    stream.nextSlice(vt_bytes);
    if (preserve_cursor) {
        // ConPTY cannot restore a snapshot. Keep its live coordinate space:
        // move the saved cursor's row to the live row, with displaced rows
        // above the screen retained in scrollback. Ignore the snapshot's
        // margins while shifting the whole screen, then put them back.
        const saved_y: u64 = if (cursor_from_last_text) |offset| row: {
            const last_text_y = @as(i64, terminal_state.rows - 1) -
                @as(i64, @intCast(terminalUndoTrailingBlankRows(terminal_state)));
            break :row @intCast(@max(0, last_text_y + offset));
        } else terminal_state.screens.active.cursor.y;
        const region = terminal_state.scrolling_region;
        terminal_state.scrolling_region = .{
            .top = 0,
            .bottom = terminal_state.rows - 1,
            .left = 0,
            .right = terminal_state.cols - 1,
        };
        // Alternate screens have no scrollback to retain shifted-out rows.
        // Preserve their full-screen picture for the application's redraws.
        const shift_rows = terminal_state.screens.active_key == .primary;
        if (shift_rows and saved_y > live_y) {
            // Trailing blanks can put the saved line beyond the replayed
            // active area. SU clamps to one screen, so scroll in chunks.
            var remaining = saved_y - live_y;
            while (remaining > 0) {
                const count = @min(remaining, terminal_state.rows);
                terminal_state.scrollUp(@intCast(count)) catch |err| {
                    log.warn("undo snapshot shift failed err={}", .{err});
                    break;
                };
                remaining -= count;
            }
        } else if (shift_rows and saved_y < live_y) {
            terminal_state.scrollDown(@intCast(live_y - saved_y));
        }
        terminal_state.scrolling_region = region;
        terminal_state.screens.active.cursorAbsolute(live_x, live_y);
        terminal_state.screens.active.cursor.pending_wrap = live_wrap;
    }
    if (title_bytes.len > 0) {
        terminal_state.setTitle(title_bytes) catch |err| {
            log.warn("undo snapshot title restore failed err={}", .{err});
        };
    }
    if (pwd_bytes.len > 0) {
        terminal_state.setPwd(pwd_bytes) catch |err| {
            log.warn("undo snapshot pwd restore failed err={}", .{err});
        };
    }

    return .{
        .title = terminal_state.getTitle(),
        .pwd = terminal_state.getPwd(),
        .scrollbar = terminal_state.screens.active.pages.scrollbar(),
    };
}

pub const HostBannerKind = labels.HostBannerKind;

/// A button of the host banner: `primary` is Open Release or Install on the
/// update notice; `dismiss` is Dismiss there and the close button otherwise.
pub const BannerButton = enum(u1) { primary, dismiss };

const LaunchTargetButtonKeyAction = labels.LaunchTargetButtonKeyAction;
pub const ProfileOpenTarget = labels.ProfileOpenTarget;

fn parseProfileOpenTarget(raw: []const u8) ?ProfileOpenTarget {
    if (std.ascii.eqlIgnoreCase(raw, "tab")) return .tab;
    if (std.ascii.eqlIgnoreCase(raw, "window") or std.ascii.eqlIgnoreCase(raw, "win")) return .window;
    if (std.ascii.eqlIgnoreCase(raw, "split") or std.ascii.eqlIgnoreCase(raw, "pane")) return .split;
    return null;
}

fn resolveProfileOpenTarget(default_target: ProfileOpenTarget, shift: bool, control: bool) ProfileOpenTarget {
    if (control) return .split;
    if (shift) return .window;
    return default_target;
}

pub fn cycleProfileOpenTarget(current: ProfileOpenTarget, reverse: bool) ProfileOpenTarget {
    return switch (current) {
        .tab => if (reverse) .split else .window,
        .window => if (reverse) .tab else .split,
        .split => if (reverse) .window else .tab,
    };
}

fn launchTargetButtonKeyAction(vk: WPARAM) ?LaunchTargetButtonKeyAction {
    return switch (vk) {
        c.VK_LEFT, c.VK_UP => .previous,
        c.VK_RIGHT, c.VK_DOWN, c.VK_RETURN, c.VK_SPACE => .next,
        c.VK_HOME => .first,
        c.VK_END => .last,
        else => null,
    };
}

/// True when `title` contains a byte that must not survive into a stored
/// window/tab title. See `sanitizeTitleAlloc` for why.
/// Control code points that must never survive into a stored title.
fn isTitleControlCodepoint(cp: u21) bool {
    // C0 controls and DEL.
    if (cp < 0x20 or cp == 0x7F) return true;
    // C1 controls U+0080..U+009F, which include 8-bit CSI (U+009B) and
    // 8-bit ST (U+009C).
    if (cp >= 0x80 and cp <= 0x9F) return true;
    return false;
}

/// One scanned unit of a title: the bytes to keep (empty when the unit must
/// be dropped) and the offset of the next unit.
const TitleUnit = struct {
    keep: []const u8,
    next: usize,
};

/// Decode one UTF-8 unit, dropping controls and anything that is not valid
/// UTF-8.
///
/// This is deliberately CODE-POINT oriented rather than byte oriented. A
/// byte-level filter for the range 0x80..0x9F would corrupt ordinary text,
/// because those bytes also occur as UTF-8 CONTINUATION bytes -- `U+20AC`
/// (the euro sign) is `E2 82 AC`, whose second byte is 0x82. Decoding first
/// means a raw `0x9B` is recognized as an 8-bit CSI and removed while `€`
/// survives intact.
///
/// Invalid UTF-8 is dropped one byte at a time rather than passed through:
/// it cannot be rendered meaningfully, and letting it through would also let
/// an OVERLONG encoding of a C1 control (for example `E0 82 9B`) evade the
/// control check. `std.unicode.utf8Decode` rejects overlong forms and
/// surrogates, so this fails closed. Dropping the trailing bytes of a
/// truncated sequence also removes the lone-`0xC2` tail that would otherwise
/// leave invalid UTF-8 in the stored title.
fn nextTitleUnit(title: []const u8, i: usize) TitleUnit {
    const len = std.unicode.utf8ByteSequenceLength(title[i]) catch {
        return .{ .keep = "", .next = i + 1 };
    };
    if (i + len > title.len) return .{ .keep = "", .next = title.len };

    const seq = title[i .. i + len];
    const cp = std.unicode.utf8Decode(seq) catch {
        return .{ .keep = "", .next = i + 1 };
    };
    if (isTitleControlCodepoint(cp)) return .{ .keep = "", .next = i + len };
    return .{ .keep = seq, .next = i + len };
}

fn titleNeedsSanitize(title: []const u8) bool {
    var i: usize = 0;
    while (i < title.len) {
        const unit = nextTitleUnit(title, i);
        // A kept unit is always at least one byte, so an empty `keep` means
        // this unit was dropped.
        if (unit.keep.len == 0) return true;
        i = unit.next;
    }
    return false;
}

/// Strip C0 controls, DEL, and C1 controls from a title.
///
/// A stored title is not display-only: with `title-report = true` the child
/// process can issue `CSI 21 t` and the surface answers with
/// `ESC ] l <title> ESC \` written back to the pty
/// (`Surface.handleMessage` `.report_title`). Titles arrive from two places
/// — OSC 0/2 from the child, and `set_surface_title` / `set_tab_title`
/// performed over the automation IPC pipe — and the IPC path does not honor
/// the `config.title != null` guard that the OSC path checks. Sanitizing at
/// the apprt setters covers both, so an IPC peer cannot smuggle an escape
/// sequence into the terminal by way of the title.
///
/// Returns null when `title` is already clean, so the common path allocates
/// nothing. Otherwise returns an owned copy the caller must free.
pub fn sanitizeTitleAlloc(alloc: Allocator, title: []const u8) Allocator.Error!?[]u8 {
    if (!titleNeedsSanitize(title)) return null;

    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(alloc);
    try out.ensureTotalCapacity(alloc, title.len);

    var i: usize = 0;
    while (i < title.len) {
        const unit = nextTitleUnit(title, i);
        out.appendSliceAssumeCapacity(unit.keep);
        i = unit.next;
    }

    return try out.toOwnedSlice(alloc);
}

const appendOwnedString = paint_text.appendOwnedString;

pub fn appendSanitizedTitle(
    alloc: Allocator,
    target: *?[:0]const u8,
    title: ?[]const u8,
) !void {
    const sanitized = if (title) |value| try sanitizeTitleAlloc(alloc, value) else null;
    defer if (sanitized) |value| alloc.free(value);
    try appendOwnedString(alloc, target, if (sanitized) |value| value else title);
}

pub const overlayEditText = overlay_session.overlayEditText;

/// Raise `child` to the top of its siblings, for a chrome child shown over
/// a terminal pane. A child is created at the bottom of the z-order, below
/// every pane that already exists, and nothing restacks a pane (measured:
/// the palette list, created at the first open, came out under the first
/// pane). Below a pane it is not seen: `WS_CLIPSIBLINGS` on the pane spares
/// only siblings above it, so an OpenGL present paints over it, and a D3D11
/// swap chain, which DWM composes in z-order, hides it altogether.
pub fn raiseChildToTop(parent: HWND, child: HWND) void {
    if (sys.GetWindow(parent, c.GW_CHILD) == child) return;
    _ = sys.SetWindowPos(child, null, 0, 0, 0, 0, c.SWP_NOMOVE | c.SWP_NOSIZE | c.SWP_NOACTIVATE);
}

/// Put `child` directly above its sibling `pane` and leave every other child
/// where it is: a child that belongs to one pane, such as its scrollbar,
/// covers that pane without rising over chrome raised by `raiseChildToTop`.
pub fn stackChildAbove(child: HWND, pane: HWND) void {
    const above = sys.GetWindow(pane, c.GW_HWNDPREV);
    if (above == child) return;
    // `SetWindowPos` puts `child` just below the window it is given; null is
    // HWND_TOP, for a pane that is the topmost child.
    const insert_after: ?*anyopaque = if (above) |window| @ptrCast(window) else null;
    _ = sys.SetWindowPos(child, insert_after, 0, 0, 0, 0, c.SWP_NOMOVE | c.SWP_NOSIZE | c.SWP_NOACTIVATE);
}

pub const paletteVisibleRowCapacity = palette_controller.paletteVisibleRowCapacity;

pub const paletteListRect = palette_controller.paletteListRect;

pub const paletteListWidthIsReadable = palette_controller.paletteListWidthIsReadable;

