const SurfaceLayoutRuntimeSync = struct {
    scrollbar_refresh: bool,
    core_size_sync: bool,
};

pub const ScrollbarPaintKey = struct {
    rect: RECT,
    total: usize,
    len: usize,
    offset: usize,
    dpi: u32,
    hovered: bool,
    dragging: bool,
    marker_revision: u64,
};

pub fn surfaceLayoutRuntimeSync(visibility_changed: bool, pane_rect_changed: bool) SurfaceLayoutRuntimeSync {
    return .{
        .scrollbar_refresh = visibility_changed or pane_rect_changed,
        .core_size_sync = pane_rect_changed,
    };
}

fn scaleInitialClientSize(size: apprt.SurfaceSize, scale: apprt.ContentScale) apprt.SurfaceSize {
    return .{
        .width = scaleInitialClientAxis(size.width, scale.x),
        .height = scaleInitialClientAxis(size.height, scale.y),
    };
}

fn scaleInitialClientAxis(value: u32, scale: f32) u32 {
    const scaled = @ceil(@as(f64, @floatFromInt(value)) * @as(f64, @floatCast(scale)));
    const max_u32: f64 = @floatFromInt(std.math.maxInt(u32));
    return @intFromFloat(@min(max_u32, @max(1, scaled)));
}

pub fn surfaceActivationNeedsHostSync(
    was_windows_hidden: bool,
    host_window_visible: bool,
    target_tab_index: usize,
    active_tab_index: usize,
    target_window_visible: bool,
) bool {
    return was_windows_hidden or
        !host_window_visible or
        target_tab_index != active_tab_index or
        !target_window_visible;
}

pub fn surfaceFocusedActivationNeedsHostSync(
    was_windows_hidden: bool,
    host_window_visible: bool,
    target_tab_index: usize,
    active_tab_index: usize,
    target_window_visible: bool,
    target_window_focused: bool,
) bool {
    return surfaceActivationNeedsHostSync(
        was_windows_hidden,
        host_window_visible,
        target_tab_index,
        active_tab_index,
        target_window_visible,
    ) or !target_window_focused;
}

pub fn surfaceFocusStateChanged(
    active_tab_index: usize,
    focused_handle: SplitTreeSurface.Node.Handle,
    target_tab_index: usize,
    target_handle: SplitTreeSurface.Node.Handle,
) bool {
    return active_tab_index != target_tab_index or focused_handle != target_handle;
}

pub fn hostChromeNeedsFocusRepaint(pane_count: usize) bool {
    return win32_chrome_state.focusRepaintNeeded(pane_count);
}

pub fn scrollbarNeedsHeartbeatForState(
    policy: ScrollbarPolicy,
    window_visible: bool,
    scrollable: bool,
    visibility: win32_scrollbar_geometry.Visibility,
) bool {
    if (policy != .dynamic) return false;
    if (!window_visible or !scrollable) return false;
    return visibility != .hidden;
}

pub fn scrollbarPaintKeyChanged(previous: ?ScrollbarPaintKey, next: ScrollbarPaintKey) bool {
    const value = previous orelse return true;
    return !rectEquals(value.rect, next.rect) or
        value.total != next.total or
        value.len != next.len or
        value.offset != next.offset or
        value.dpi != next.dpi or
        value.hovered != next.hovered or
        value.dragging != next.dragging or
        value.marker_revision != next.marker_revision;
}

pub fn highContrastThemeFromSysColors() ThemeColors {
    const win_bg = sys.GetSysColor(c.COLOR_WINDOW);
    const win_fg = sys.GetSysColor(c.COLOR_WINDOWTEXT);
    const win_frame = sys.GetSysColor(c.COLOR_WINDOWFRAME);
    const btn_bg = sys.GetSysColor(c.COLOR_BTNFACE);
    const btn_fg = sys.GetSysColor(c.COLOR_BTNTEXT);
    const hi_bg = sys.GetSysColor(c.COLOR_HIGHLIGHT);
    const hi_fg = sys.GetSysColor(c.COLOR_HIGHLIGHTTEXT);
    const gray = sys.GetSysColor(c.COLOR_GRAYTEXT);

    return .{
        .chrome_bg = win_bg,
        .chrome_border = win_frame,
        .overlay_bg = win_bg,
        .overlay_border = win_frame,
        .edit_bg = win_bg,
        .edit_frame_bg = win_bg,
        .inspector_bg = win_bg,

        .text_primary = win_fg,
        .text_secondary = win_fg,
        .text_disabled = gray,
        .edit_fg = win_fg,
        .overlay_label_fg = win_fg,
        .info_fg = win_fg,
        .error_fg = win_fg,

        .accent = hi_bg,
        .accent_hover = hi_bg,
        .chrome_accent_idle = win_frame,
        .edit_border_unfocused = win_frame,

        .button_bg = btn_bg,
        .button_border = btn_fg,
        .button_fg = btn_fg,

        .button_overlay_bg = btn_bg,
        .button_overlay_border = btn_fg,
        .button_overlay_fg = btn_fg,
        .button_chrome_fg = btn_fg,

        .button_active_bg = hi_bg,
        .button_active_border = hi_fg,
        .button_active_fg = hi_fg,

        .button_accept_bg = hi_bg,
        .button_accept_border = hi_fg,
        .button_accept_fg = hi_fg,

        .button_disabled_bg = btn_bg,
        .button_disabled_border = gray,
        .button_disabled_fg = gray,

        .button_focus_ring = hi_bg,
        .button_overlay_focus_ring = hi_bg,
        .button_active_focus_ring = hi_fg,
        .button_accept_focus_ring = hi_fg,

        // Unfocused dividers use COLOR_WINDOWFRAME
        // so multi-pane layouts stay visually separated; focused dividers
        // use COLOR_HIGHLIGHT to preserve the focus cue.
        .pane_divider = win_frame,
        .pane_divider_focused = hi_bg,

        .is_dark = false,
    };
}

pub fn isHighContrastActive() bool {
    const HIGHCONTRASTW = extern struct {
        cbSize: UINT,
        dwFlags: DWORD,
        lpszDefaultScheme: ?[*:0]u16,
    };
    var hc: HIGHCONTRASTW = .{
        .cbSize = @sizeOf(HIGHCONTRASTW),
        .dwFlags = 0,
        .lpszDefaultScheme = null,
    };
    if (sys.SystemParametersInfoW(c.SPI_GETHIGHCONTRAST, @sizeOf(HIGHCONTRASTW), @ptrCast(&hc), 0) != 0) {
        return (hc.dwFlags & c.HCF_HIGHCONTRASTON) != 0;
    }
    return false;
}

/// The color scheme Windows reports for apps. The lookup is shared with the
/// command line actions (`os/color_scheme.zig`), which apply the same scheme
/// to the configuration they load.
pub fn isSystemDarkMode() bool {
    return internal_os.color_scheme.isDark();
}

const immersive_color_set_w = std.unicode.utf8ToUtf16LeStringLiteral("ImmersiveColorSet");

/// The setting a `WM_SETTINGCHANGE` names in its lParam, or null when it
/// names none.
fn settingChangeName(lParam: LPARAM) ?[:0]const u16 {
    if (lParam == 0) return null;
    const name: [*:0]const u16 = @ptrFromInt(@as(usize, @bitCast(lParam)));
    return std.mem.span(name);
}

fn settingChangeIsImmersiveColorSet(lParam: LPARAM) bool {
    const name = settingChangeName(lParam) orelse return false;
    return std.mem.eql(u16, name, immersive_color_set_w);
}

pub fn settingChangeAffectsTheme(lparam: LPARAM) bool {
    const name = settingChangeName(lparam) orelse return true;
    inline for (.{ "Environment", "intl", "Policy" }) |irrelevant| {
        const value = std.unicode.utf8ToUtf16LeStringLiteral(irrelevant);
        if (std.mem.eql(u16, name, value)) return false;
    }
    return true;
}

test "issue149 Windows setting change filters terminal color sync" {
    const immersive = std.unicode.utf8ToUtf16LeStringLiteral("ImmersiveColorSet");
    const unrelated = std.unicode.utf8ToUtf16LeStringLiteral("Environment");
    try std.testing.expect(settingChangeIsImmersiveColorSet(@bitCast(@intFromPtr(immersive))));
    try std.testing.expect(!settingChangeIsImmersiveColorSet(@bitCast(@intFromPtr(unrelated))));
    try std.testing.expect(!settingChangeIsImmersiveColorSet(0));
}

pub fn readDynamicScrollbars(default_value: bool) bool {
    const subkey = std.unicode.utf8ToUtf16LeStringLiteral("Control Panel\\Accessibility");
    const value_name = std.unicode.utf8ToUtf16LeStringLiteral("DynamicScrollbars");
    var hkey: sys.HKEY = undefined;
    if (sys.RegOpenKeyExW(@ptrFromInt(c.HKEY_CURRENT_USER), subkey, 0, c.KEY_READ, &hkey) != c.ERROR_SUCCESS) {
        return default_value;
    }
    defer _ = sys.RegCloseKey(hkey);

    var data: u32 = if (default_value) 1 else 0;
    var data_size: DWORD = @sizeOf(u32);
    var reg_type: DWORD = 0;
    if (sys.RegQueryValueExW(hkey, value_name, null, &reg_type, @ptrCast(&data), &data_size) != c.ERROR_SUCCESS) {
        return default_value;
    }
    if (reg_type != c.REG_DWORD or data_size != @sizeOf(u32)) return default_value;

    return data != 0;
}

pub fn resolveTheme(config: *const configpkg.Config) ThemeColors {
    if (isHighContrastActive()) return highContrastThemeFromSysColors();
    const theme = switch (config.@"window-theme") {
        .dark => darkTheme(),
        .light => lightTheme(),
        .system => if (isSystemDarkMode()) darkTheme() else lightTheme(),
        .auto => if (isSystemDarkMode()) darkTheme() else lightTheme(),
        .ghostty => darkTheme(),
    };
    return withSplitDividerColor(theme, config.@"split-divider-color");
}

/// `split-divider-color` recolors the gap between split panes; unset, the
/// theme's divider stays. The focused pane's accent is not this color. High
/// Contrast never gets here (`resolveTheme`), so it keeps system colors.
fn withSplitDividerColor(theme: ThemeColors, color: ?configpkg.Config.Color) ThemeColors {
    var result = theme;
    if (color) |value| result.pane_divider = rgb(value.r, value.g, value.b);
    return result;
}

test "split-divider-color recolors the pane gap" {
    const dark = darkTheme();
    const recolored = withSplitDividerColor(dark, .{ .r = 0x12, .g = 0x34, .b = 0x56 });
    try std.testing.expectEqual(rgb(0x12, 0x34, 0x56), recolored.pane_divider);
    try std.testing.expectEqual(dark.pane_divider_focused, recolored.pane_divider_focused);
    try std.testing.expectEqual(dark.pane_divider, withSplitDividerColor(dark, null).pane_divider);
    try std.testing.expectEqual(lightTheme().pane_divider, withSplitDividerColor(lightTheme(), null).pane_divider);

    // Through the config, as a reload resolves it.
    var config = try configpkg.Config.default(std.testing.allocator);
    defer config.deinit();
    config.@"window-theme" = .dark;
    config.@"split-divider-color" = .{ .r = 0x12, .g = 0x34, .b = 0x56 };
    if (!isHighContrastActive()) {
        try std.testing.expectEqual(rgb(0x12, 0x34, 0x56), resolveTheme(&config).pane_divider);
    }
}

/// One notice for a setting Win32 cannot honour, shared by startup and the
/// config-change path so the two cannot drift. Not a config diagnostic: the
/// value parses and other platforms honour it.
pub fn logBackgroundBlurUnsupported() void {
    log.warn(
        "background-blur has no effect on Windows in this build: noctty paints its " ++
            "window opaquely and opts into no DWM transparency mechanism, so no backdrop " ++
            "material can reach a visible pixel. background-opacity is a flat " ++
            "window-wide tint, not a blur",
        .{},
    );
}

/// Whether this Windows build accepts `DWMWA_SYSTEMBACKDROP_TYPE` at all.
/// Older builds reject the attribute with `E_INVALIDARG`, so the write is
/// skipped there rather than failing on every theme apply.
fn supportsDwmSystemBackdropAttribute(os_build: u32) bool {
    return os_build >= c.OS_BUILD_WIN11_22H2;
}

pub fn configuredHostWindowPosition(config: *const configpkg.Config) ?struct { x: i32, y: i32 } {
    const x = config.@"window-position-x" orelse return null;
    const y = config.@"window-position-y" orelse return null;
    return .{
        .x = x,
        .y = y,
    };
}

fn titlebarCaptionColor(theme: *const ThemeColors, config: *const configpkg.Config) u32 {
    if (config.@"window-theme" == .ghostty) {
        if (config.@"window-titlebar-background") |color| {
            return rgb(color.r, color.g, color.b);
        }
    }

    return theme.chrome_bg;
}

fn titlebarTextColor(theme: *const ThemeColors, config: *const configpkg.Config) u32 {
    if (config.@"window-theme" == .ghostty) {
        if (config.@"window-titlebar-foreground") |color| {
            return rgb(color.r, color.g, color.b);
        }
    }

    return theme.text_primary;
}

/// Unpack a Win32 COLORREF (0x00BBGGRR) into an RGB triple.
fn rgbFromColorRef(color: u32) terminal.color.RGB {
    return .{
        .r = @truncate(color & 0xFF),
        .g = @truncate((color >> 8) & 0xFF),
        .b = @truncate((color >> 16) & 0xFF),
    };
}

/// Which palette a configured titlebar background should be painted with.
///
/// The point of deriving a polarity at all is readability, so decide it by
/// the readability itself rather than by a fixed luminance cutoff. A cutoff
/// misclassifies saturated midtones: `#00C800` sits at ~0.46 perceived
/// luminance, so `< 0.5` calls it dark and puts the dark palette's near-white
/// glyphs on bright green at roughly 1.7:1, where the light palette's dark
/// glyphs reach about 7.6:1. Comparing the two candidates' actual WCAG
/// contrast against the configured background picks the readable side and
/// still agrees with the cutoff on ordinary near-black and near-white values.
fn titlebarBandIsDark(background: terminal.color.RGB) bool {
    const dark_text = rgbFromColorRef(darkTheme().text_primary);
    const light_text = rgbFromColorRef(lightTheme().text_primary);
    return background.contrast(dark_text) >= background.contrast(light_text);
}

pub fn clientTitlebarTheme(
    theme: *const ThemeColors,
    config: *const configpkg.Config,
    integrated: bool,
    high_contrast: bool,
) ThemeColors {
    var result = theme.*;
    if (!integrated or high_contrast or config.@"window-theme" != .ghostty) return result;

    if (config.@"window-titlebar-background") |background| {
        result.chrome_bg = titlebarCaptionColor(theme, config);

        // The band's polarity is whatever the configured background says it
        // is, not whatever the base theme was. Every polarity-dependent token
        // the client-drawn band consumes has to move with it: leaving them
        // behind is what puts dark borders, dark disabled glyphs and a dark
        // focus ring on a light band. `chrome_bg` stays the explicit value,
        // and `accent` stays the theme's own — `themeSurface` already adapts
        // the accent through `is_dark`.
        result.is_dark = titlebarBandIsDark(.{
            .r = background.r,
            .g = background.g,
            .b = background.b,
        });
        const derived_theme = if (result.is_dark) darkTheme() else lightTheme();
        result.text_primary = derived_theme.text_primary;
        result.text_secondary = derived_theme.text_secondary;
        result.text_disabled = derived_theme.text_disabled;
        result.chrome_border = derived_theme.chrome_border;
        result.button_chrome_fg = derived_theme.text_primary;
        result.button_focus_ring = derived_theme.button_focus_ring;
        result.button_active_focus_ring = derived_theme.button_active_focus_ring;
        result.button_disabled_bg = derived_theme.button_disabled_bg;
        result.button_disabled_border = derived_theme.button_disabled_border;
        result.button_disabled_fg = derived_theme.button_disabled_fg;
    }
    if (config.@"window-titlebar-foreground" != null) {
        const foreground = titlebarTextColor(theme, config);
        result.text_primary = foreground;
        // Preserve an explicit readable foreground when the window deactivates.
        result.text_secondary = foreground;
        result.button_chrome_fg = foreground;
    }
    return result;
}

/// The colors the active tab draws over `background`, its terminal's
/// background, which it takes so it reads as part of the terminal below it
/// (Windows Terminal's `terminalBackground` tab). Where `background` has the
/// band's polarity these are `theme`'s, so a configured titlebar foreground
/// still applies where it reads. A terminal of the other polarity, such as the default dark
/// terminal under the light window theme, gets that polarity's label, close
/// glyph, status badge and focus ring colors, the way `clientTitlebarTheme`
/// does for a configured band; `theme`'s would be unreadable there (1.23:1
/// for the light label on `#282C34`).
///
/// Neither palette reads on every background: on a mid-tone such as
/// `#777777` the light label reaches 3.85:1 and its inactive-window shade
/// 1.40:1. The label carries the `* ` marker, the active tab's essential cue,
/// so the label's two colors are moved toward black or white until they
/// reach 4.5:1 and the focus ring until it reaches 3:1 (DESIGN.md); the
/// status badge is held to 3:1 where it is drawn (`tabStatusBadgeColor`).
pub fn activeTabTheme(theme: *const ThemeColors, background: u32) ThemeColors {
    var result = theme.*;
    const is_dark = titlebarBandIsDark(rgbFromColorRef(background));
    if (is_dark != theme.is_dark) {
        const derived = if (is_dark) darkTheme() else lightTheme();
        result.is_dark = is_dark;
        result.text_primary = derived.text_primary;
        result.text_secondary = derived.text_secondary;
        result.text_disabled = derived.text_disabled;
        result.button_chrome_fg = derived.button_chrome_fg;
        result.accent = derived.accent;
        result.error_fg = derived.error_fg;
        result.button_active_focus_ring = derived.button_active_focus_ring;
    }
    result.text_primary = readableOn(result.text_primary, background, 4.5);
    result.text_secondary = readableOn(result.text_secondary, background, 4.5);
    result.button_active_focus_ring = readableOn(result.button_active_focus_ring, background, 3.0);
    return result;
}

/// `color`, or the least mix of it toward black or white (whichever stands
/// further from `background`) that reaches `minimum` contrast on
/// `background`: that extreme itself where nothing reaches it. Black or
/// white reaches at least 4.58:1 on any background.
fn readableOn(color: u32, background: u32, minimum: f64) u32 {
    const surface = rgbFromColorRef(background);
    if (rgbFromColorRef(color).contrast(surface) >= minimum) return color;
    const black = rgb(0, 0, 0);
    const white = rgb(0xFF, 0xFF, 0xFF);
    const extreme = if (rgbFromColorRef(black).contrast(surface) >= rgbFromColorRef(white).contrast(surface)) black else white;
    const steps = 20;
    for (1..steps) |step| {
        const mixed = blendColorRGB(color, extreme, @as(f32, @floatFromInt(step)) / steps);
        if (rgbFromColorRef(mixed).contrast(surface) >= minimum) return mixed;
    }
    return extreme;
}

/// The color of a tab's status badge on `background`, the tab's fill: the
/// status's own color, moved toward black or white until it reaches 3:1
/// there (DESIGN.md's floor for essential non-text indicators). On the
/// chrome's own tab fills every status color already does; on an active
/// tab's terminal background it may not (the light palette's accent ring on
/// a `#0078D4` terminal is that very color).
pub fn tabStatusBadgeColor(status: win32_program_status.Indicator, theme: *const ThemeColors, background: u32) u32 {
    return readableOn(win32_program_status.badgeColor(status, theme.is_dark, theme.accent, theme.error_fg), background, 3.0);
}

test "the active tab draws over its terminal background with readable colors" {
    const terminal_default = rgb(0x28, 0x2C, 0x34);
    const white = rgb(0xFF, 0xFF, 0xFF);
    const dark = darkTheme();
    const light = lightTheme();
    // Same polarity: the band's colors, unchanged.
    try std.testing.expectEqualDeep(dark, activeTabTheme(&dark, terminal_default));
    try std.testing.expectEqualDeep(light, activeTabTheme(&light, white));
    // The default dark terminal under the light window theme, and a light
    // terminal under the dark one, take the other palette's tokens.
    const crossed = [_]struct { theme: ThemeColors, background: u32 }{
        .{ .theme = light, .background = terminal_default },
        .{ .theme = dark, .background = white },
    };
    for (crossed) |case| {
        const tab = activeTabTheme(&case.theme, case.background);
        try std.testing.expect(tab.is_dark != case.theme.is_dark);
        const surface = rgbFromColorRef(case.background);
        try std.testing.expect(rgbFromColorRef(tab.text_primary).contrast(surface) >= 4.5);
        try std.testing.expect(rgbFromColorRef(tab.button_chrome_fg).contrast(surface) >= 4.5);
        try std.testing.expect(rgbFromColorRef(tab.button_active_focus_ring).contrast(surface) >= 3.0);
        try std.testing.expect(rgbFromColorRef(case.theme.text_primary).contrast(surface) < 3.0);
        // What the band itself is painted with stays the band's.
        try std.testing.expectEqual(case.theme.chrome_bg, tab.chrome_bg);
        try std.testing.expectEqual(case.theme.chrome_border, tab.chrome_border);
    }
}

test "TABLINE the active tab's label reads on mid-tone terminal backgrounds" {
    // Mid-tones where neither palette's label reaches 4.5:1 (#777777: the
    // light label 3.85:1, its inactive-window shade 1.40:1), and saturated
    // ones: pure red, and the Windows accent blue, where black and white
    // are close to their worst.
    const backgrounds = [_]u32{ rgb(0x77, 0x77, 0x77), rgb(0x80, 0x80, 0x80), rgb(0xFF, 0x00, 0x00), rgb(0x00, 0x78, 0xD4) };
    for ([_]ThemeColors{ darkTheme(), lightTheme() }) |theme| {
        for (backgrounds) |background| {
            const tab = activeTabTheme(&theme, background);
            const surface = rgbFromColorRef(background);
            try std.testing.expect(rgbFromColorRef(tab.text_primary).contrast(surface) >= 4.5);
            try std.testing.expect(rgbFromColorRef(tab.text_secondary).contrast(surface) >= 4.5);
            try std.testing.expect(rgbFromColorRef(tab.button_active_focus_ring).contrast(surface) >= 3.0);
            for ([_]win32_program_status.Indicator{ .{ .working = null }, .{ .blocked = null }, .done, .failed }) |status| {
                try std.testing.expect(rgbFromColorRef(tabStatusBadgeColor(status, &tab, background)).contrast(surface) >= 3.0);
            }
        }
    }
    // A color that already reads is kept, and one that cannot reach the floor
    // takes the extreme that comes closest.
    try std.testing.expectEqual(rgb(0x12, 0x34, 0x56), readableOn(rgb(0x12, 0x34, 0x56), rgb(0xFF, 0xFF, 0xFF), 4.5));
    try std.testing.expectEqual(rgb(0, 0, 0), readableOn(rgb(0x40, 0x40, 0x40), rgb(0x77, 0x77, 0x77), 21));
}

pub fn applyDwmThemeWithBuild(hwnd: HWND, theme: *const ThemeColors, config: *const configpkg.Config, os_build: u32) void {
    const caption_color = titlebarCaptionColor(theme, config);
    const text_color = titlebarTextColor(theme, config);
    win32_theme.WindowThemeAdapter.applyHost(
        hwnd,
        theme.*,
        isHighContrastActive(),
        caption_color,
        text_color,
        // Host windows never carry a DWM backdrop material, because nothing
        // in this runtime can show one: the chrome is painted opaquely with
        // GDI, the terminal is an opaque OpenGL child whose framebuffer alpha
        // DWM discards, and nothing opts into `DwmExtendFrameIntoClientArea`,
        // `DwmEnableBlurBehindWindow` or `WS_EX_NOREDIRECTIONBITMAP`. The
        // attribute used to be set to `DWMSBT_TABBEDWINDOW` whenever
        // `background-opacity < 1` and `background-blur` were both set, which
        // only ever cost a DWM call and made the docs promise a material the
        // window could not show. Measured on Windows 11 build 26200 over a
        // striped desktop: `--background-opacity=0.8 --background-blur=true`
        // (backdrop 4) and `--background-blur=false` (backdrop 1) produced
        // byte-identical screenshots, and flipping the attribute from outside
        // the process on the same window with `WS_EX_LAYERED` stripped by
        // hand changed nothing either. The layered alpha that implements
        // `background-opacity` is NOT the obstacle: a synthetic window that
        // does extend its frame shows a different material per backdrop type
        // whether or not it is layered.
        c.DWMSBT_NONE,
        supportsDwmSystemBackdropAttribute(os_build),
    );
}

pub fn quickSelectNameThunk(ctx: *anyopaque, buf: []u8) []const u8 {
    const surface: *const Surface = @ptrCast(@alignCast(ctx));
    return surface.buildQuickSelectName(buf);
}

pub fn quickSelectFocusedThunk(ctx: *anyopaque) bool {
    const surface: *const Surface = @ptrCast(@alignCast(ctx));
    const hwnd = surface.quick_select_hwnd orelse return false;
    return sys.GetFocus() == hwnd;
}

pub fn quickSelectRowCountThunk(ctx: *anyopaque) usize {
    const surface: *const Surface = @ptrCast(@alignCast(ctx));
    const session = if (surface.quick_select_session) |*value| value else return 0;
    return session.labels.count;
}

pub fn quickSelectSelectedIndexThunk(ctx: *anyopaque) ?usize {
    const surface: *const Surface = @ptrCast(@alignCast(ctx));
    return surface.quickSelectFirstRemainingIndex();
}

pub fn quickSelectRowNameThunk(ctx: *anyopaque, index: usize, buf: []u8) []const u8 {
    const surface: *const Surface = @ptrCast(@alignCast(ctx));
    const session = if (surface.quick_select_session) |*value| value else return "Quick select target";
    if (index >= session.labels.count or index >= session.scan.matches.len) return "Quick select target";
    return win32_hints.accessibleTargetName(
        buf,
        index,
        session.labels.count,
        session.labels.get(index),
        session.scan.matchText(index),
    );
}

pub fn quickSelectRowEnabledThunk(ctx: *anyopaque, index: usize) bool {
    const surface: *const Surface = @ptrCast(@alignCast(ctx));
    const session = if (surface.quick_select_session) |*value| value else return false;
    return index < session.labels.count and session.labels.startsWith(index, session.prefix.typed());
}

pub fn quickSelectRowIdThunk(_: *anyopaque, index: usize) u64 {
    return index + 1;
}

pub fn quickSelectRowBoundsThunk(ctx: *anyopaque, index: usize) ?win32_uia.PaletteListRowBounds {
    const surface: *Surface = @ptrCast(@alignCast(ctx));
    const hwnd = surface.quick_select_hwnd orelse return null;
    const host = surface.host orelse return null;
    var client: RECT = undefined;
    if (sys.GetClientRect(hwnd, &client) == 0) return null;
    const metrics: win32_theme.ThemeMetrics = if (isHighContrastActive())
        .highContrast()
    else
        .{};
    const bounds = surface.quickSelectLabelRect(
        index,
        client,
        metrics,
        host.current_dpi,
    ) orelse return null;
    var origin: POINT = .{ .x = bounds.left, .y = bounds.top };
    if (sys.ClientToScreen(hwnd, &origin) == 0) return null;
    return .{
        .left = @floatFromInt(origin.x),
        .top = @floatFromInt(origin.y),
        .width = @floatFromInt(bounds.right - bounds.left),
        .height = @floatFromInt(bounds.bottom - bounds.top),
    };
}

pub fn quickSelectSelectRowThunk(ctx: *anyopaque, index: usize) void {
    const surface: *Surface = @ptrCast(@alignCast(ctx));
    const session = if (surface.quick_select_session) |*value| value else return;
    if (index >= session.labels.count or !session.labels.startsWith(index, session.prefix.typed())) return;
    const label = session.labels.get(index);
    @memcpy(session.prefix.bytes[0..label.len], label);
    session.prefix.len = label.len;
    surface.quickSelectPrefixChanged();
}

pub fn quickSelectInvokeRowThunk(ctx: *anyopaque, index: usize) void {
    const surface: *Surface = @ptrCast(@alignCast(ctx));
    surface.fireQuickSelect(index, false, false) catch |err| {
        log.warn("quick select UIA action failed err={}", .{err});
    };
}

/// Thunks adapting `*App` into the `AppHandle` callback shape used by
/// `win32_settings.SettingsWindow`. Kept inline so a theme swap is
/// picked up on the next paint without cache invalidation.
pub fn settingsAppIconThunk(ctx: *anyopaque, small: bool) HICON {
    const app: *App = @ptrCast(@alignCast(ctx));
    return loadAppIcon(app.hinstance, small);
}

pub fn settingsOwnerWindowThunk(ctx: *anyopaque) ?HWND {
    const app: *App = @ptrCast(@alignCast(ctx));
    const focused = app.registry.focusedSurfaceForUndoRedo();
    if (focused) |surface| app.settings_restore_surface_id = surface.core().id;
    const surface = focused orelse
        (if (app.settings_restore_surface_id) |id| app.registry.findSurfaceById(id) else null) orelse
        app.registry.primarySurface() orelse return null;
    return surface.windowHwnd();
}

pub fn settingsCustomUiaProvidersEnabledThunk(ctx: *anyopaque) bool {
    const app: *const App = @ptrCast(@alignCast(ctx));
    return app.com_initialized;
}

fn settingsRestoreCandidateOrder(
    saved: ?u64,
    focused: ?u64,
    primary: ?u64,
) [3]?u64 {
    return .{ saved, focused, primary };
}

test "settings close prefers the originating surface in a two-host session" {
    const order = settingsRestoreCandidateOrder(202, null, 101);
    try std.testing.expectEqual(@as(?u64, 202), order[0]);
    try std.testing.expectEqual(@as(?u64, null), order[1]);
    try std.testing.expectEqual(@as(?u64, 101), order[2]);
}

fn settingsRestoreSurface(app: *App, saved: ?u64) ?*Surface {
    const focused = app.registry.focusedSurfaceForUndoRedo();
    const primary = app.registry.primarySurface();
    const order = settingsRestoreCandidateOrder(
        saved,
        if (focused) |surface| surface.core().id else null,
        if (primary) |surface| surface.core().id else null,
    );
    for (order) |candidate| {
        if (candidate) |id| {
            if (app.registry.findSurfaceById(id)) |surface| return surface;
        }
    }
    return null;
}

pub fn settingsChromeBgThunk(ctx: *anyopaque) u32 {
    const app: *const App = @ptrCast(@alignCast(ctx));
