pub fn settingsNotifySuccessThunk(ctx: *anyopaque, title: []const u8, body: []const u8) void {
    const app: *App = @ptrCast(@alignCast(ctx));
    const saved_title = if (app.safe_mode) "Settings saved; restart noctty to apply them" else title;
    // Always show local chrome feedback for the Save button, even
    // when system/reload notifications are disabled.
    const alloc = app.core_app.alloc;
    // Problems the save's reload found are an error that stays until
    // dismissed. An info banner would replace it and then expire, and so
    // would the banner a refused system toast falls back to, so neither is
    // raised: the Settings status line already says the save went through.
    if (app.config_problems.count() > 0 and app.showConfigProblemsBanner()) return;
    const banner_text = std.fmt.allocPrint(alloc, "{s}{s}{s}", .{
        saved_title,
        if (body.len > 0) ": " else "",
        body,
    }) catch null;
    const banner_shown: bool = if (banner_text) |msg| blk: {
        defer alloc.free(msg);
        // `showHostBanner(.app, …)` routes through `primarySurface()`
        // and returns false when no terminal host is open (e.g.
        // settings window is the only UI window after the last tab
        // closed). Capture that so we know to fall back to the
        // always-visible in-settings confirm strip below.
        break :blk app.showHostBanner(.app, .info, msg) catch false;
    } else false;

    // System-level WinRT toast + local fallback. Gated on
    // `app-notifications.config-reload` because Settings save also
    // reloads config; users who disabled reload notifications should
    // not get a system toast on every Save. If no host banner can
    // render, force the fallback so settings-only saves still show
    // visible confirmation.
    if (!app.config.@"app-notifications".@"config-reload" and banner_shown) return;

    // WinRT notification strings must be sentinel-terminated. On
    // allocation failure, keep any banner already shown and skip the
    // system path.
    const title_z = alloc.dupeZ(u8, saved_title) catch return;
    defer alloc.free(title_z);
    const body_z = alloc.dupeZ(u8, body) catch return;
    defer alloc.free(body_z);
    app.showDesktopNotification(.app, title_z, body_z) catch |err| {
        std.log.warn("settings: desktop notification failed err={}", .{err});
    };
}

pub const ToastRequest = win32_toast_winrt.ToastRequest;

/// Where `App.showToast` sends a toast: WinRT in the product
/// (`ToastSink.winrt`), a recorder in tests, so no test can reach Action
/// Center.
pub const ToastSink = struct {
    ctx: *anyopaque,
    show: *const fn (ctx: *anyopaque, request: ToastRequest) anyerror!void,
    /// Take the toast tagged `tag` in `group` out of Action Center.
    remove_tag: *const fn (ctx: *anyopaque, tag: []const u8, group: []const u8) anyerror!void,
    /// Take every toast in `group` out of Action Center.
    remove_group: *const fn (ctx: *anyopaque, group: []const u8) anyerror!void,

    pub fn winrt(toast: *win32_toast_winrt.WinrtToast) ToastSink {
        return .{ .ctx = toast, .show = showWinrt, .remove_tag = removeTagWinrt, .remove_group = removeGroupWinrt };
    }

    fn showWinrt(ctx: *anyopaque, request: ToastRequest) anyerror!void {
        const toast: *win32_toast_winrt.WinrtToast = @ptrCast(@alignCast(ctx));
        try toast.show(request, .info);
    }

    fn removeTagWinrt(ctx: *anyopaque, tag: []const u8, group: []const u8) anyerror!void {
        const toast: *win32_toast_winrt.WinrtToast = @ptrCast(@alignCast(ctx));
        try toast.removeGroupedTag(tag, group);
    }

    fn removeGroupWinrt(ctx: *anyopaque, group: []const u8) anyerror!void {
        const toast: *win32_toast_winrt.WinrtToast = @ptrCast(@alignCast(ctx));
        try toast.removeGroup(group);
    }
};

/// A pane's toast tag: its core surface id, 16 hex digits. One tag per pane,
/// so a newer toast from the pane replaces its older one in Action Center.
pub fn toastTag(buf: *[16]u8, surface_id: u64) []const u8 {
    return std.fmt.bufPrint(buf, "{x:0>16}", .{surface_id}) catch unreachable;
}

/// This process's toast group, `noctty-<pid>`: other noctty processes share
/// the AUMID, so everything this process removes at once is named by it.
pub fn toastGroup(buf: *[toast_group_max]u8) []const u8 {
    return std.fmt.bufPrint(buf, "noctty-{d}", .{sys.GetCurrentProcessId()}) catch unreachable;
}

pub const toast_group_max = "noctty-".len + std.fmt.count("{d}", .{std.math.maxInt(DWORD)});

pub fn buildToastLaunchForSurface(
    alloc: Allocator,
    surface: *Surface,
) Allocator.Error![]u8 {
    const tab_id = if (surface.host) |host| blk: {
        for (host.tabs.items) |*tab| {
            if (tab.findHandle(surface) != null) break :blk tab.id;
        }
        break :blk null;
    } else null;

    return try win32_toast_activation.buildLaunchArg(alloc, .{
        .surface_id = surface.core().id,
        .tab_id = tab_id,
        .window_id = surface.host_id,
        .pid = sys.GetCurrentProcessId(),
        .action = .focus,
    });
}

/// The active tab's index once tab `removed` is gone and `remaining` tabs
/// are left: the same tab when another one closed; when the active tab
/// itself closed, the tab now at its place, or the last one. The shell
/// model's `closeTab` and `detachTab` choose the same way.
pub fn activeTabAfterRemoval(active: usize, removed: usize, remaining: usize) usize {
    if (remaining == 0) return 0;
    if (removed < active) return @min(active - 1, remaining - 1);
    return @min(active, remaining - 1);
}

test "win32 closing a tab keeps the active tab active" {
    // [A, B, C] with B active.
    try std.testing.expectEqual(@as(usize, 0), activeTabAfterRemoval(1, 0, 2)); // A closes: B
    try std.testing.expectEqual(@as(usize, 1), activeTabAfterRemoval(1, 2, 2)); // C closes: B
    try std.testing.expectEqual(@as(usize, 1), activeTabAfterRemoval(1, 1, 2)); // B closes: C
    try std.testing.expectEqual(@as(usize, 1), activeTabAfterRemoval(2, 2, 2)); // last closes: new last
    try std.testing.expectEqual(@as(usize, 0), activeTabAfterRemoval(0, 0, 0));
}

/// Whether the user can see tab `index` of `host` right now: it is the
/// window's active tab, and the window is the foreground window and not
/// minimized.
pub fn tabSeenByUser(host: *const Host, index: usize) bool {
    return tabSeenWithForeground(host, index, sys.GetForegroundWindow());
}

pub fn tabSeenWithForeground(host: *const Host, index: usize, foreground: ?HWND) bool {
    if (index != host.active_tab) return false;
    const hwnd = host.hwnd orelse return false;
    return foreground == hwnd and sys.IsIconic(hwnd) == 0;
}

const TabProgramStatus = struct {
    surface: *Surface,
    record: *const win32_program_status.Record,
};

/// The program status record a tab shows: the most urgent headline among
/// its surfaces, the first one in the split tree on a tie.
pub fn tabStatusHeadline(tab: *const Tab) ?TabProgramStatus {
    var best: ?TabProgramStatus = null;
    var it = tab.tree.iterator();
    while (it.next()) |entry| {
        const record = entry.view.program_status.headline() orelse continue;
        if (best) |current| {
            const rank = win32_program_status.Indicator.of(record).rank();
            if (rank <= win32_program_status.Indicator.of(current.record).rank()) continue;
        }
        best = .{ .surface = entry.view, .record = record };
    }
    return best;
}

/// What a screen reader is told about a tab's status, as a hash that
/// progress alone doesn't change; never 0, which stands for no status.
pub fn tabStatusKey(status: TabProgramStatus) u64 {
    var hasher = std.hash.Wyhash.init(0);
    win32_program_status.hashAnnounced(&hasher, &status.surface.program_status, status.record);
    return hasher.final() | 1;
}

/// Accept callback for the `confirm-close-surface` overlay. Fires
/// from the Host's overlay machinery once the user picks Accept /
/// presses Enter. `userdata` is the `*Surface` pointer passed into
/// `showConfirm`. The Surface's HWND may already be gone (defensive
/// null-check) — if so this is a no-op.
pub fn surfaceConfirmCloseAccept(userdata: ?*anyopaque) void {
    const ud = userdata orelse return;
    const surface: *Surface = @ptrCast(@alignCast(ud));
    _ = surface.requestClose();
}

/// Close for the window-close prompt. `userdata` is the Host that shows
/// the prompt, so it is alive whenever the prompt can be answered.
pub fn hostCloseConfirmAccept(userdata: ?*anyopaque) void {
    const host: *Host = @ptrCast(@alignCast(userdata orelse return));
    host.closeConfirmed();
}

/// Quit for the quit prompt. `userdata` is the App, which outlives every
/// window the quit destroys, including the one showing the prompt.
pub fn appQuitConfirmAccept(userdata: ?*anyopaque) void {
    const app: *App = @ptrCast(@alignCast(userdata orelse return));
    // Settings may have gained unsaved edits while this prompt waited.
    if (app.settings_window.holdQuitForUnsavedChanges()) return;
    app.quitConfirmed();
}

/// Install for the update prompt. `userdata` is the App, which outlives every
/// window the install destroys, including the one showing the prompt. This
/// runs inside the overlay's handlers, so it only queues the install: the
/// message loop applies it once this has returned, and checks for unsaved
/// Settings edits then.
pub fn updateApplyConfirmAccept(userdata: ?*anyopaque) void {
    const app: *App = @ptrCast(@alignCast(userdata orelse return));
    app.queueApplyStagedUpdate() catch |err| {
        log.warn("failed to queue the staged update apply after confirm err={}", .{err});
    };
}

/// Close tabs for the other-tabs prompt. `userdata` is the Surface the
/// tabs are kept beside: its destruction cancels the prompt
/// (`cancelConfirmIfOwnedBy`), and the tabs are found again here because
/// they may have changed while the prompt was open.
pub fn closeOtherTabsConfirmAccept(userdata: ?*anyopaque) void {
    const surface: *Surface = @ptrCast(@alignCast(userdata orelse return));
    _ = surface.app.closeTabsBeside(surface, .other) catch |err| {
        log.warn("close other tabs after confirm failed err={}", .{err});
    };
}

/// Close the tab for the undo-is-off prompt. `userdata` is the Surface the
/// close was asked on: its destruction cancels the prompt
/// (`cancelConfirmIfOwnedBy`), and its tab is found again here because it
/// may have moved while the prompt was open.
pub fn closeThisTabConfirmAccept(userdata: ?*anyopaque) void {
    const surface: *Surface = @ptrCast(@alignCast(userdata orelse return));
    const app = surface.app;
    const found = Host.findTabForSurface(surface) orelse return;
    _ = app.closeTabUndoable(found.host, found.index) catch |err| {
        log.warn("close tab after confirm failed err={}", .{err});
    };
}

/// Close tabs for the tabs-to-the-right prompt; see `closeOtherTabsConfirmAccept`.
pub fn closeRightTabsConfirmAccept(userdata: ?*anyopaque) void {
    const surface: *Surface = @ptrCast(@alignCast(userdata orelse return));
    _ = surface.app.closeTabsBeside(surface, .right) catch |err| {
        log.warn("close tabs to the right after confirm failed err={}", .{err});
    };
}

/// Accept callback for a deferred paste confirm. Ownership of the
/// duplicated payload passes here and is released after synchronous
/// core ingestion.
pub fn surfaceConfirmPasteAccept(userdata: ?*anyopaque) void {
    const ud = userdata orelse return;
    const surface: *Surface = @ptrCast(@alignCast(ud));
    const op = surface.pending_clipboard_op orelse return;
    if (op != .paste) return;
    const pending = op.paste;
    // Snapshot the allocator by value BEFORE dispatching. If
    // `completeClipboardRequest` synchronously destroys the surface
    // (for example via close_surface), `surface.app` at defer
    // time is a dangling read. `std.mem.Allocator` is a pod value
    // (vtable + ctx ptr); the ctx is owned by the app arena which
    // outlives the surface, so the snapshot stays valid.
    const alloc = surface.app.core_app.alloc;
    surface.pending_clipboard_op = null;
    defer alloc.free(pending.data);
    surface.core_surface.completeClipboardRequest(
        pending.request,
        pending.data,
        true, // confirmed
    ) catch |err| {
        std.log.warn("pending clipboard paste accept failed err={}", .{err});
    };
}

pub fn surfaceConfirmPasteCancel(userdata: ?*anyopaque, reason: ConfirmCancelReason) void {
    const ud = userdata orelse return;
    const surface: *Surface = @ptrCast(@alignCast(ud));
    var op = surface.pending_clipboard_op orelse return;
    const alloc = surface.app.core_app.alloc;
    surface.pending_clipboard_op = null;
    defer op.deinit(alloc);
    if (reason != .explicit or op != .paste or
        op.paste.request != .osc_52_read or !surface.core_initialized or
        surface.core_surface.config.clipboard_read == .deny) return;

    // Finish this read without revealing clipboard contents. Reuse the
    // OSC 52 serializer so the reply echoes the requested selection.
    surface.core_surface.completeClipboardRequest(op.paste.request, "", true) catch |err| {
        log.warn("pending clipboard read cancel reply failed err={}", .{err});
    };
}

/// Accept callback for a deferred clipboard-write confirm. Mirrors
/// the body of `Surface.setClipboard` (html-first, then plain text)
/// because the confirm-write path only fires from the standard
/// clipboard — OSC 52 writes use a different code path.
pub fn surfaceConfirmWriteAccept(userdata: ?*anyopaque) void {
    const ud = userdata orelse return;
    const surface: *Surface = @ptrCast(@alignCast(ud));
    const op = surface.pending_clipboard_op orelse return;
    if (op != .write) return;
    const pending = op.write;
    const alloc = surface.app.core_app.alloc;
    surface.pending_clipboard_op = null;
    defer {
        for (pending.contents) |*content| {
            alloc.free(content.mime);
            alloc.free(content.data);
        }
        alloc.free(pending.contents);
    }
    if (pending.clipboard != .standard) return;
    var html_content: ?[]const u8 = null;
    var plain_content: ?[]const u8 = null;
    for (pending.contents) |content| {
        if (std.mem.eql(u8, content.mime, "text/html")) {
            html_content = content.data;
        } else if (std.mem.eql(u8, content.mime, "text/plain")) {
            plain_content = content.data;
        }
    }
    if (html_content) |html| {
        surface.writeClipboardHtml(html, plain_content) catch |err| {
            std.log.warn("pending clipboard html write failed err={}", .{err});
        };
        return;
    }
    if (plain_content) |plain| {
        surface.writeClipboardText(plain) catch |err| {
            std.log.warn("pending clipboard text write failed err={}", .{err});
        };
    }
}

pub fn surfaceConfirmWriteCancel(userdata: ?*anyopaque, _: ConfirmCancelReason) void {
    const ud = userdata orelse return;
    const surface: *Surface = @ptrCast(@alignCast(ud));
    if (surface.pending_clipboard_op) |*op| op.deinit(surface.app.core_app.alloc);
    surface.pending_clipboard_op = null;
}

/// What a clipboard read found.
pub const ClipboardContents = union(enum) {
    /// No text and, for a read that takes files, no copied files (an image,
    /// say).
    none,
    /// CF_UNICODETEXT, with LF line endings.
    text: [:0]u8,
    /// CF_HDROP, from Explorer's Copy: the paths as a drop formats them, in
    /// one string.
    files: [:0]u8,

    /// The paths of a borrowed HDROP, which stays its owner's. Every field is
    /// owned by `alloc`.
    fn fromHdrop(alloc: std.mem.Allocator, hdrop: *anyopaque) !ClipboardContents {
        const payload = try win32_ole.extractHdrop(alloc, hdrop, .{});
        defer alloc.free(payload);
        if (payload.len == 0) return .none;
        return .{ .files = try alloc.dupeZ(u8, payload) };
    }
};

/// The two formats of an open clipboard that a paste reads. The system
/// clipboard is one source (`system_clipboard`); a test supplies its own, so
/// `selectClipboardContents` is the code both run.
pub const ClipboardSource = struct {
    /// The CF_UNICODETEXT text, with LF line endings, owned by `alloc`; null
    /// when there is none.
    text: *const fn (alloc: std.mem.Allocator) anyerror!?[:0]u8,
    /// The CF_HDROP handle, borrowed from the clipboard; null when there is
    /// none.
    hdrop: *const fn () ?*anyopaque,
};

/// What `source` holds for a request: its text, else (for `include_files`,
/// a user's paste) the paths of its copied files, else nothing. An empty
/// text is no text when files may be taken, so copied files that sit beside
/// one paste; a program's read (`include_files` false) takes the text as it
/// is and never looks for files.
pub fn selectClipboardContents(
    alloc: std.mem.Allocator,
    include_files: bool,
    source: ClipboardSource,
) !ClipboardContents {
    if (try source.text(alloc)) |text| {
        if (text.len > 0 or !include_files) return .{ .text = text };
        alloc.free(text);
    }
    if (!include_files) return .none;

    const hdrop = source.hdrop() orelse return .none;
    return try ClipboardContents.fromHdrop(alloc, hdrop);
}

/// Pastes the paths of dropped or copied files. `payload` is borrowed and
/// NUL-terminated.
///
/// Route through `completeClipboardRequest(.paste, …, confirmed=false)`
/// rather than `textCallback` so `clipboard-paste-protection`
/// actually applies. `textCallback` hard-codes `allow_unsafe=true`
/// (it's the terminal-typed path, where newlines ARE the user's
/// intent), which would defeat paste protection for file names.
pub fn pasteFilePayload(surface: *Surface, payload: [:0]const u8) !void {
    // Defense-in-depth classifier pass.
    //
    // Core's `isSafe` only flags newlines + bracketed-paste-end
    // sequences. That's correct for generic clipboard pastes but
    // insufficient for file names where a crafted name like
    // `%USERPROFILE%\x.txt` (cmd `%VAR%`), `$HOME.txt` (PowerShell),
    // or a name containing control bytes / a URL embedded in
    // other text would bypass confirmation. Consult the full
    // `win32_paste_protection.inspect` verdict — which covers
    // control_chars, shell_metachar, AND mixed_content — not just
    // `hasShellMetachar`. When the verdict isn't `.safe`, fire the
    // same confirm path as the core `.UnsafePaste` branch.
    if (surface.app.config.@"clipboard-paste-protection") {
        const verdict = win32_paste_protection.inspect(payload);
        if (verdict.severity != .safe) {
            std.log.info("file payload flagged severity={s} reason={s}", .{
                @tagName(verdict.severity),
                verdict.reason,
            });
            // Non-modal confirm overlay; dupes payload so it survives
            // the caller's teardown. Paste completes asynchronously
            // on accept via `surfaceConfirmPasteAccept`.
            try surface.requestPasteConfirm(.paste, payload);
            return;
        }
    }

    surface.core_surface.completeClipboardRequest(.paste, payload, false) catch |err| switch (err) {
        // Unsafe content (newlines, control sequences, etc.). Defer to
        // the non-modal confirm overlay; the Accept callback re-submits
        // with `confirmed = true`.
        error.UnsafePaste, error.UnauthorizedPaste => try surface.requestPasteConfirm(.paste, payload),
        else => return err,
    };
}

/// IDropTarget payload callback. Runs on the STA UI thread (COM
/// guarantees). `payload` is owned by the module and lives only for
/// the duration of this callback — the apprt must not retain it.
pub fn surfaceDropPayloadCallback(ctx: *anyopaque, payload: []const u8) void {
    const surface: *Surface = @ptrCast(@alignCast(ctx));
    if (payload.len == 0) return;
    surface.noteProgramInput();
    const alloc = surface.app.core_app.alloc;
    const payload_z = alloc.dupeZ(u8, payload) catch |err| {
        std.log.warn("drop payload dupe failed err={}", .{err});
        return;
    };
    defer alloc.free(payload_z);

    pasteFilePayload(surface, payload_z) catch |err| {
        std.log.warn("drop payload paste failed err={}", .{err});
    };
}

fn rectEqual(a: RECT, b: RECT) bool {
    return a.left == b.left and
        a.top == b.top and
        a.right == b.right and
        a.bottom == b.bottom;
}

pub const setQuickTerminalRect = quick_terminal_host.setQuickTerminalRect;

pub const runOnHiddenDesktop = test_support.runOnHiddenDesktop;

pub const FullscreenMonitor = window_state.FullscreenMonitor;

const fitRectInWork = window_state.fitRectInWork;

const workspaceRectToScreen = window_state.workspaceRectToScreen;

const setMinimizedNormalRect = window_state.setMinimizedNormalRect;

const monitorInfo = quick_terminal_host.monitorInfo;

const restoresMaximized = window_state.restoresMaximized;

/// The work areas of the monitors there are now, in screen coordinates.
const WorkAreas = struct {
    rects: [16]RECT = undefined,
    count: usize = 0,

    pub fn collect() WorkAreas {
        var areas: WorkAreas = .{};
        _ = sys.EnumDisplayMonitors(null, null, enumProc, @as(LPARAM, @bitCast(@intFromPtr(&areas))));
        return areas;
    }

    pub fn slice(self: *const WorkAreas) []const RECT {
        return self.rects[0..self.count];
    }

    fn enumProc(monitor: sys.HMONITOR, _: HDC, _: *RECT, data: LPARAM) callconv(.winapi) BOOL {
        const areas: *WorkAreas = @ptrFromInt(@as(usize, @bitCast(data)));
        if (areas.count == areas.rects.len) return 0;
        var info: MONITORINFO = std.mem.zeroes(MONITORINFO);
        info.cbSize = @sizeOf(MONITORINFO);
        if (sys.GetMonitorInfoW(monitor, &info) == 0) return 1;
        areas.rects[areas.count] = info.rcWork;
        areas.count += 1;
        return 1;
    }
};

/// How much of a restored window's title bar must be on a monitor for the
/// user to be able to grab it: this wide and half as tall, in physical
/// pixels. The saved rect is in the pixels of a monitor this process may not
/// have seen yet, and the host being placed is on another, so no DPI is
/// right to scale by; a caption at 100%, still a target at 300%.
const restore_grab: i32 = 48;

/// Where a window saved at `rect` (screen coordinates) goes now that the
/// monitors' work areas are `works`. One whose title bar can still be grabbed
/// stays exactly where it was, whatever its other edges do: a snapped window
/// overhangs its monitor by its invisible frame. One that cannot (its monitor
/// was unplugged, or the layout changed) moves to the nearest work area, its
/// size capped to it.
fn restoredRectOnScreen(rect: RECT, works: []const RECT, grab: i32) RECT {
    if (works.len == 0) return rect;
    // The rect comes from a file on disk: any i32 is possible, so differences
    // of coordinates are taken in 64 bits.
    const grab_width = @min(grab, rect.right - rect.left);
    var nearest = works[0];
    var nearest_gap: i64 = std.math.maxInt(i64);
    for (works) |work| {
        const visible_width = @as(i64, @min(rect.right, work.right)) - @max(rect.left, work.left);
        const visible_height = @as(i64, @min(rect.top, work.bottom - grab) + grab) - @max(rect.top, work.top);
        if (visible_width >= grab_width and visible_height >= @divTrunc(grab, 2)) return rect;

        const gap_x: i64 = @max(0, @max(@as(i64, work.left) - rect.right, @as(i64, rect.left) - work.right));
        const gap_y: i64 = @max(0, @max(@as(i64, work.top) - rect.bottom, @as(i64, rect.top) - work.bottom));
        const gap = gap_x + gap_y;
        if (gap < nearest_gap) {
            nearest = work;
            nearest_gap = gap;
        }
    }
    return fitRectInWork(rect.left, rect.top, rect.right - rect.left, rect.bottom - rect.top, nearest);
}

// Keep helper modules reachable from the exe's module graph. Zig prunes
// unreferenced module-level decls, so this block also keeps their tests
// and public entry points type-checked.
comptime {
    // Surface-level drag-drop payload parsing helpers.
    _ = win32_surface_drop.parentDir;
    _ = win32_surface_drop.requiresQuoting;
    _ = win32_surface_drop.formatFilePayload;
    _ = win32_surface_drop.formatTextPayload;
    _ = win32_surface_drop.extractShellUrl;
    _ = win32_surface_drop.extractHtmlFragment;
    // GDI icon helpers used by palette rows, search toggles, caption
    // buttons, and toast severity glyphs.
    _ = win32_icons.drawIcon;
    _ = win32_icons.insetRect;
    _ = win32_icons.centerSquare;
    _ = win32_icons.iconContentRect;
    _ = win32_icons.isDrawable;
    // Paste-protection severity classification.
    _ = win32_paste_protection.inspect;
    _ = win32_paste_protection.hasControlChars;
    _ = win32_paste_protection.hasNewline;
    _ = win32_paste_protection.hasShellMetachar;
    _ = win32_paste_protection.hasMixedContent;
    // Scrollbar geometry helpers.
    _ = win32_scrollbar_geometry.ScrollbarState;
    _ = win32_scrollbar_geometry.trackRect;
    _ = win32_scrollbar_geometry.thumbRect;
    _ = win32_scrollbar_geometry.rowFromCursor;
    _ = win32_scrollbar_geometry.pointOverTrack;
    _ = win32_scrollbar_geometry.pointOverThumb;
    // Integrated-titlebar NC layout helpers.
    _ = win32_nc_layout.calcNcClientRect;
    _ = win32_nc_layout.hitTest;
    _ = win32_nc_layout.captionButtonsRect;
    _ = win32_nc_layout.metricsDefault;
    // Tab visual-state helpers.
    _ = win32_tab_visual.CloseState;
    _ = win32_tab_visual.easeInOutCubic;
    _ = win32_tab_visual.closeHitRect;
}

/// Scan argv for a `wgh://activate?...` entry. Malformed activation
/// strings are swallowed so they cannot be misrouted as startup args.
/// Windows does not pass a toast's launch string on the command line of an
/// unpackaged app: Action Center clicks arrive through the COM activator.
/// This reads a launch by hand or a script.
pub fn scanToastActivationArg(alloc: std.mem.Allocator) ?win32_toast_activation.ActivationTarget {
    const argv = std.process.argsAlloc(alloc) catch return null;
    defer std.process.argsFree(alloc, argv);
    return win32_toast_activation.scanLaunchArgs(argv[1..]);
}

pub fn scanForwardedToastActivation(
    arguments: ?[]const [:0]const u8,
) win32_toast_activation.ScanLaunchArgsResult {
    const argv = arguments orelse return .none;
    return win32_toast_activation.scanLaunchArgsDetailed(argv);
}

pub fn forwardedActivationExtraArgCount(arguments: ?[]const [:0]const u8) usize {
    const argv = arguments orelse return 0;
    if (win32_toast_activation.scanLaunchArgs(argv) == null) return 0;
    return if (argv.len > 1) argv.len - 1 else 0;
}

/// The last `--visual-studio-profiles=` argument on this process's command
/// line, as written (`App.cli_visual_studio_profiles_arg`).
pub fn cliVisualStudioProfilesArg(alloc: std.mem.Allocator) !?[]u8 {
    const argv = std.process.argsAlloc(alloc) catch return null;
    defer std.process.argsFree(alloc, argv);
    return cliVisualStudioProfilesArgArgs(alloc, argv);
}

/// The last `--visual-studio-profiles=` argument in `argv` (argv[0]
/// included) that the loader accepts, duplicated, or null. The loader keeps
/// the value before a rejected one (`--visual-studio-profiles=all
/// --visual-studio-profiles=latest` runs `all`), so the rejected one is
/// skipped; an empty value is accepted (it means the default). Like the
/// loader, it stops at `-e` and at a COM activation switch.
fn cliVisualStudioProfilesArgArgs(alloc: std.mem.Allocator, argv: []const []const u8) !?[]u8 {
    const prefix = "--visual-studio-profiles=";
    var last: ?[]const u8 = null;
    for (argv[@min(1, argv.len)..]) |arg| {
        if (std.mem.eql(u8, arg, "-e") or
            std.ascii.eqlIgnoreCase(arg, "-Embedding") or
            std.ascii.eqlIgnoreCase(arg, win32_toast_activator.launch_switch)) break;
        if (!std.mem.startsWith(u8, arg, prefix)) continue;
        const value = arg[prefix.len..];
        if (value.len == 0 or std.meta.stringToEnum(windows_shell.VisualStudioProfiles, value) != null) last = arg;
    }
    return if (last) |arg| try alloc.dupe(u8, arg) else null;
}

test "the jump list passes on only a visual-studio-profiles argument noctty was given" {
    const alloc = std.testing.allocator;
    try std.testing.expect((try cliVisualStudioProfilesArgArgs(alloc, &.{"noctty.exe"})) == null);
    try std.testing.expect((try cliVisualStudioProfilesArgArgs(alloc, &.{ "noctty.exe", "--font-size=12" })) == null);
    const last = (try cliVisualStudioProfilesArgArgs(alloc, &.{
        "noctty.exe",
        "--visual-studio-profiles=none",
        "--visual-studio-profiles=all",
        "-e",
        "--visual-studio-profiles=newest",
    })).?;
    defer alloc.free(last);
    try std.testing.expectEqualStrings("--visual-studio-profiles=all", last);
    // argv[0] is not an option, and an empty value (back to the default)
    // is passed on as written.
    try std.testing.expect((try cliVisualStudioProfilesArgArgs(alloc, &.{"--visual-studio-profiles=all"})) == null);
    const empty = (try cliVisualStudioProfilesArgArgs(alloc, &.{ "noctty.exe", "--visual-studio-profiles=" })).?;
    defer alloc.free(empty);
    try std.testing.expectEqualStrings("--visual-studio-profiles=", empty);
    // A value the loader rejects leaves the one before it running, so the
    // link passes that one on (or none).
    const kept = (try cliVisualStudioProfilesArgArgs(alloc, &.{ "noctty.exe", "--visual-studio-profiles=all", "--visual-studio-profiles=latest", "--visual-studio-profiles=All" })).?;
    defer alloc.free(kept);
    try std.testing.expectEqualStrings("--visual-studio-profiles=all", kept);
    try std.testing.expect((try cliVisualStudioProfilesArgArgs(alloc, &.{ "noctty.exe", "--visual-studio-profiles=latest" })) == null);
    var cfg = try configpkg.Config.default(alloc);
    defer cfg.deinit();
    var iter: cli_args.ArgsIterator(cli_args.SliceIterator) = .{
        .iterator = cli_args.sliceIterator(&.{ "--visual-studio-profiles=all", "--visual-studio-profiles=latest", "--visual-studio-profiles=All" }),
    };
    try cfg.loadIter(alloc, &iter);
    try std.testing.expect(cfg.@"visual-studio-profiles" == .all);
}

/// Return the last CLI `--config-file` override as an absolute path.
/// Settings save targets the last file because later config files
/// override earlier ones.
pub fn cliConfigFileOverride(alloc: std.mem.Allocator) !?[]u8 {
    const argv = std.process.argsAlloc(alloc) catch return null;
    defer std.process.argsFree(alloc, argv);
    return cliConfigFileOverrideArgs(alloc, argv);
}

pub fn cliConfigFileOverrideArgs(alloc: std.mem.Allocator, argv: []const []const u8) !?[]u8 {
    const key = "--config-file";
    // Take the files exactly as the loader does: its own list type reads
    // each value, so the optional marker, quotes, an empty value that clears
    // the list and a bare key that has no value all mean what they mean to
    // `Config.loadCliArgs`. A separate parser disagreed with it: `--config-file
    // x` (a spelling the loader rejects) made Save write a file the loader
    // never reads, and `--config-file=?x` named a file called `?x`.
    var arena: std.heap.ArenaAllocator = .init(alloc);
    defer arena.deinit();
    var files: configpkg.RepeatablePath = .{};
    for (argv[@min(1, argv.len)..]) |arg| {
        // Config.parseManuallyHook consumes everything after -e as child argv,
        // and stops at a COM activation switch.
        if (std.mem.eql(u8, arg, "-e") or
            std.ascii.eqlIgnoreCase(arg, "-Embedding") or
            std.ascii.eqlIgnoreCase(arg, win32_toast_activator.launch_switch)) break;
        const value: ?[]const u8 = if (std.mem.eql(u8, arg, key))
            null
        else if (std.mem.startsWith(u8, arg, key ++ "="))
            arg[key.len + 1 ..]
        else
            continue;
        files.parseCLI(arena.allocator(), value) catch |err| switch (err) {
            error.ValueRequired => {},
            error.OutOfMemory => return error.OutOfMemory,
        };
    }
    // The LAST file, not the first: `Config.loadRecursiveFiles` applies files
    // in argv order and later files override earlier ones. Saving into the
    // first file when a second exists would be the wrong layer — the saved
    // value would be masked on reload.
    const last = files.value.getLastOrNull() orelse return null;
    return try absolutizePath(alloc, switch (last) {
        .optional, .required => |name| name,
    });
}

/// The value of the last CLI `--class=` override.
pub fn cliClass(alloc: std.mem.Allocator) !?[]u8 {
    const argv = std.process.argsAlloc(alloc) catch return null;
    defer std.process.argsFree(alloc, argv);
    const class = cliClassArgs(argv) orelse return null;
    return try alloc.dupe(u8, class);
}

fn cliClassArgs(argv: []const []const u8) ?[]const u8 {
    const key = "--class=";
    var class: ?[]const u8 = null;
    for (argv[@min(1, argv.len)..]) |arg| {
        // As `cliConfigFileOverrideArgs`: the rest is the child's argv, or
        // COM's.
        if (std.mem.eql(u8, arg, "-e") or
            std.ascii.eqlIgnoreCase(arg, "-Embedding") or
            std.ascii.eqlIgnoreCase(arg, win32_toast_activator.launch_switch)) break;
        if (std.mem.startsWith(u8, arg, key)) class = arg[key.len..];
    }
    return class;
}

/// RESTART_MAX_CMD_LINE (winbase.h): `RegisterApplicationRestart` takes up to
/// 1023 characters and the NUL, and returns E_INVALIDARG for 1024 (measured
/// on build 26300).
pub const restart_max_cmd_line = 1024;

/// The arguments Setup's restart replays (`App.registerInstallerRestart`):
/// the launch's last `--config-file`, as the absolute path `App.init` resolved
/// (the restart's working directory is not the launch's), and its `--class`,
/// which names the single-instance pipe. Nothing else: not `-e`, a
/// `+action`, `-Embedding` or `--working-directory`, since the restart only
/// brings the saved session back. Quoted for `CommandLineToArgvW`. Empty when
/// there is nothing to replay; null when the line would be too long to
/// register.
pub fn installerRestartCommandLine(
    alloc: Allocator,
    config_file: ?[]const u8,
    class: ?[]const u8,
) !?[:0]u16 {
    var line: std.Io.Writer.Allocating = .init(alloc);
    defer line.deinit();
    var arg: std.Io.Writer.Allocating = .init(alloc);
    defer arg.deinit();
    for ([_]struct { []const u8, ?[]const u8 }{
        .{ "--config-file=", config_file },
        .{ "--class=", class },
    }) |entry| {
        const value = entry[1] orelse continue;
        arg.clearRetainingCapacity();
        try arg.writer.print("{s}{s}", .{ entry[0], value });
        if (line.written().len != 0) try line.writer.writeByte(' ');
        try win32_elevation.writeWindowsArgument(&line.writer, arg.written());
    }
    const wide = try std.unicode.wtf8ToWtf16LeAllocZ(alloc, line.written());
    if (wide.len < restart_max_cmd_line) return wide;
    alloc.free(wide);
    return null;
}

/// Resolve a possibly-relative path to an absolute one WITHOUT
/// requiring the leaf to exist. `std.fs.realpathAlloc` calls
/// `GetFullPathNameW` + `CreateFileW` to canonicalise, which fails
/// with `FileNotFound` before the first save has written the file.
/// For the settings save path, we need an absolute path regardless
/// of whether the file exists yet — the atomic rename will create
/// it. `std.fs.path.isAbsolute` handles the already-absolute case;
/// otherwise join with cwd. No canonicalisation (symlink resolution
/// etc.) — that's not required for an atomic rename target.
fn absolutizePath(alloc: std.mem.Allocator, path: []const u8) ![]u8 {
    if (std.fs.path.isAbsolute(path)) {
        return try alloc.dupe(u8, path);
    }
    const cwd = try std.process.getCwdAlloc(alloc);
    defer alloc.free(cwd);
    return try std.fs.path.join(alloc, &.{ cwd, path });
}

/// Count the number of leading whitespace (space / tab) bytes.
fn leadingIndentLen(line: []const u8) usize {
    var i: usize = 0;
    while (i < line.len and (line[i] == ' ' or line[i] == '\t')) : (i += 1) {}
    return i;
}

/// Return an assignment's key without treating literal value text as comments.
fn settingsAssignmentKey(line: []const u8) ?SettingsConfigKey {
    const stripped = std.mem.trimLeft(u8, line, " \t");
    if (stripped.len == 0 or stripped[0] == '#' or stripped[0] == ';') return null;
    const eq = std.mem.indexOfScalar(u8, stripped, '=') orelse return null;
    return std.meta.stringToEnum(SettingsConfigKey, std.mem.trimRight(u8, stripped[0..eq], " \t"));
}

fn appendSettingsPayload(alloc: std.mem.Allocator, out: *std.ArrayListUnmanaged(u8), payload: []const u8, ending: []const u8) !void {
    var start: usize = 0;
    for (payload, 0..) |byte, i| {
        if (byte != '\n') continue;
        try out.appendSlice(alloc, payload[start..i]);
        try out.appendSlice(alloc, ending);
        start = i + 1;
    }
    try out.appendSlice(alloc, payload[start..]);
}

/// UTF-8 patching cannot edit UTF-16 or UTF-32 text: appending ASCII lines to
/// it leaves a file that mixes encodings, of which the loader reads only the
/// appended lines. A byte-order mark, or a NUL byte anywhere (UTF-16 and UTF-32
/// without one), marks such a file; a config never contains NUL.
///
/// Why `raw` cannot be patched, or null when it can, named for the status
/// line: a byte order mark says UTF-16 (what Windows PowerShell 5.1 writes),
/// bare NUL bytes say a binary file or UTF-16/UTF-32 without a mark.
fn settingsTextProblem(raw: []const u8) ?win32_settings.SaveError {
    if (std.mem.startsWith(u8, raw, "\xff\xfe") or std.mem.startsWith(u8, raw, "\xfe\xff")) return error.UnsupportedEncoding;
    if (std.mem.indexOfScalar(u8, raw, 0) != null) return error.BinaryConfig;
    return null;
}

/// Write the settings the user edited into the config file behind
/// `config_path`: read it, patch only the edited assignments, and put the
/// result back where the file lives (see `save_target`).
pub fn persistSettings(
    alloc: Allocator,
    config_path: []const u8,
    pending: *const configpkg.Config,
    user_edited: SettingsEditedKeySet,
    detail: ?*win32_settings.FailureDetail,
) win32_settings.SaveError!void {
    // A config kept behind a link is edited where it lives, so the link
    // survives and a dotfiles repository sees the change. A dangling link is
    // refused: there is no file to patch, and writing would replace the link.
    const target = try save_target.resolve(alloc, config_path);
    defer target.deinit(alloc);

    // SURGICAL SAVE: read the raw target file text and patch
    // only GUI-edited field lines in place. This preserves
    // (a) comments, (b) relative `config-file` paths (not
    // canonicalised), (c) the user's formatting / blank lines,
    // (d) fields we can't round-trip through the Config type
    // (RepeatableString, etc).
    //
    // For each GUI-edited field: scan the raw text for a line
    // matching `^<key> =` at column 0 (PLUS optional leading
    // whitespace) and replace the WHOLE line with the new
    // serialised `key = value` emission. If no matching line
    // exists, append to the file end.
    //
    // Edited fields that are not already present are appended by
    // `patchOrAppendEdits` below. No parsed-file baseline is needed:
    // unedited source lines remain byte-for-byte intact.
    const raw_before: []u8 = blk: {
        const f = std.fs.cwd().openFile(target.path, .{}) catch |err| switch (err) {
            error.FileNotFound => break :blk try alloc.dupe(u8, ""),
            else => return error.SerializeFailed,
        };
        defer f.close();
        const stat = f.stat() catch return error.SerializeFailed;
        const slice = alloc.alloc(u8, settingsFileSize(stat.size) catch return error.SerializeFailed) catch return error.OutOfMemory;
        errdefer alloc.free(slice);
        const n = f.readAll(slice) catch return error.SerializeFailed;
        break :blk try alloc.realloc(slice, n);
    };
    defer alloc.free(raw_before);
    if (settingsTextProblem(raw_before)) |problem| {
        try setSettingsFailureDetail(alloc, detail, "the config file {s}", .{target.path});
        return problem;
    }

    var patched: std.ArrayListUnmanaged(u8) = .{};
    defer patched.deinit(alloc);
    patchOrAppendEdits(
        alloc,
        raw_before,
        pending,
        user_edited,
        &patched,
    ) catch return error.SerializeFailed;

    // Ensure target's parent directory exists. `config_edit.openPath`
    // creates `%APPDATA%\ghostty\` for the default path, but a user
    // launched with `--config-file=D:\new-dir\custom.conf` could
    // target a directory that has never been created. Without this
    // step the first Save against that path would fail here with
    // `TempCreateFailed`.
    //
    // A parent that already opens is left alone: `makePath` rejects the
    // extended `\\?\` form that `save_target` keeps for long paths and for
    // names Win32 normalization would change, and a drive root, so a config
    // that exists there could otherwise never be saved.
    if (std.fs.path.dirname(target.path)) |parent| {
        if (std.fs.cwd().openDir(parent, .{})) |opened| {
            var dir = opened;
            dir.close();
        } else |_| std.fs.cwd().makePath(parent) catch |err| {
            std.log.warn("settings save: couldn't create parent dir path={s} err={}", .{ parent, err });
            return error.TempCreateFailed;
        };
    }

    var kept_copy: ?[]u8 = null;
    defer if (kept_copy) |path| alloc.free(path);
    save_target.write(alloc, target, patched.items, &kept_copy) catch |err| {
        if (err == error.IncompleteWrite) if (detail) |d| {
            // The complete text is in the kept copy; the status line says where.
            if (kept_copy) |path| d.set(alloc, path);
        };
        return err;
    };
}

/// Patch only edited assignments. Scalars keep last-wins semantics; repeatable
/// strings replace the full list at its last assignment and reset lower layers.
pub fn patchOrAppendEdits(
    alloc: std.mem.Allocator,
    raw: []const u8,
    pending: *const configpkg.Config,
    user_edited: SettingsEditedKeySet,
    out: *std.ArrayListUnmanaged(u8),
) !void {
    @setEvalBranchQuota(10_000);
    const keys_total = comptime std.enums.values(SettingsConfigKey).len;
    var last_line: [keys_total]usize = @splat(std.math.maxInt(usize));
    var lines: std.ArrayListUnmanaged([]const u8) = .{};
    defer lines.deinit(alloc);
    var crlf_count: usize = 0;
    var lf_count: usize = 0;
    // The loader skips a UTF-8 byte order mark, so the first assignment
    // behind one is matched like any other; the mark is written back first.
    const utf8_bom = "\xef\xbb\xbf";
    const text = if (std.mem.startsWith(u8, raw, utf8_bom)) bom: {
        try out.appendSlice(alloc, utf8_bom);
        break :bom raw[utf8_bom.len..];
    } else raw;
    var it = std.mem.splitScalar(u8, text, '\n');
    while (it.next()) |line| {
        try lines.append(alloc, line);
        if (it.index != null) {
            if (std.mem.endsWith(u8, line, "\r")) crlf_count += 1 else lf_count += 1;
        }
    }
    const dominant_ending: []const u8 = if (crlf_count > lf_count) "\r\n" else "\n";

    for (lines.items, 0..) |line, index| {
        const key = settingsAssignmentKey(line) orelse continue;
        if (user_edited.isSet(@intFromEnum(key))) last_line[@intFromEnum(key)] = index;
    }

    var written: SettingsEditedKeySet = .initEmpty();
    for (lines.items, 0..) |line, index| {
        var handled = false;
        const line_key = settingsAssignmentKey(line);
        inline for (@typeInfo(configpkg.Config).@"struct".fields) |field| {
            if (field.name[0] == '_') continue;
            const key = @field(SettingsConfigKey, field.name);
            if (line_key == key and user_edited.isSet(@intFromEnum(key))) {
                const repeatable = field.type == configpkg.Config.RepeatableString;
                if (settingsEditRemovesLines(pending, key)) {
                    // Every assignment goes, so none from earlier in the file
                    // takes over.
                    handled = true;
                } else if (last_line[@intFromEnum(key)] == index) {
                    var scratch: std.Io.Writer.Allocating = .init(alloc);
                    defer scratch.deinit();
                    try writeSettingsEntry(field, @field(pending, field.name), &scratch.writer);
                    const payload = std.mem.trimEnd(u8, scratch.written(), "\n");
                    const has_cr = std.mem.endsWith(u8, line, "\r");
                    const ending: []const u8 = if (has_cr) "\r\n" else if (index + 1 < lines.items.len) "\n" else dominant_ending;
                    try out.appendSlice(alloc, line[0..leadingIndentLen(line)]);
                    try appendSettingsPayload(alloc, out, payload, ending);
                    if (has_cr) try out.append(alloc, '\r');
                    if (index + 1 < lines.items.len) try out.append(alloc, '\n');
                    written.set(@intFromEnum(key));
                    handled = true;
                } else if (repeatable) {
                    // Remove the whole old assignment, including its newline.
                    handled = true;
                }
            }
        }
        if (!handled) {
            try out.appendSlice(alloc, line);
            if (index + 1 < lines.items.len) try out.append(alloc, '\n');
        }
    }

    inline for (@typeInfo(configpkg.Config).@"struct".fields) |field| {
        if (field.name[0] == '_') continue;
        const key = @field(SettingsConfigKey, field.name);
        if (user_edited.isSet(@intFromEnum(key)) and !written.isSet(@intFromEnum(key)) and
            !settingsEditRemovesLines(pending, key))
        {
            if (out.items.len > 0 and out.items[out.items.len - 1] != '\n')
                try out.appendSlice(alloc, dominant_ending);
            var scratch: std.Io.Writer.Allocating = .init(alloc);
            defer scratch.deinit();
            try writeSettingsEntry(field, @field(pending, field.name), &scratch.writer);
            try appendSettingsPayload(alloc, out, scratch.written(), dominant_ending);
        }
    }
}

/// Whether saving `key` takes its lines out of the file instead of writing
/// one: Settings' "Automatic" for `default-profile`, which is the absence of
/// the setting, not a value.
fn settingsEditRemovesLines(pending: *const configpkg.Config, comptime key: SettingsConfigKey) bool {
    return key == .@"default-profile" and pending.@"default-profile" == null;
}

/// One edited setting as config text, each line ending in a newline. A
/// repeatable list that is not empty starts with `<key> = `, which resets
/// what lower layers set; an empty list's formatter already emits that reset.
fn writeSettingsEntry(
    comptime field: std.builtin.Type.StructField,
    value: field.type,
    writer: *std.Io.Writer,
) !void {
    if (field.type == configpkg.Config.RepeatableString and value.list.items.len != 0)
        try writer.print("{s} = \n", .{field.name});
    try @import("../config/formatter.zig").formatEntry(field.type, field.name, value, writer);
}

test "win32 settings automatic command is not masked by default resolution" {
    var pending = try configpkg.Config.default(std.testing.allocator);
    defer pending.deinit();
    var reloaded = try configpkg.Config.default(std.testing.allocator);
    defer reloaded.deinit();
    try configpkg.pane_launch.useAutomatic(&reloaded);
    try std.testing.expect(reloaded.command != null);
    try std.testing.expect(!settingsEditedValueMasked(&pending, &reloaded, .command));
    try settingsTestLoadText(&reloaded, "command = direct:cmd.exe\n");
    try std.testing.expect(settingsEditedValueMasked(&pending, &reloaded, .command));
}

test "win32 settings save names the edited keys a later config layer overrides" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    // The file holds both edits; an included file loaded after the font size
    // sets it again, which is what a save reports as masked.
    try tmp.dir.writeFile(.{
        .sub_path = "config.ghostty",
        .data = "font-size = 14\ncopy-on-select = true\nconfig-file = later.conf\n",
    });
    try tmp.dir.writeFile(.{ .sub_path = "later.conf", .data = "font-size = 18\n" });
    const path = try tmp.dir.realpathAlloc(alloc, "config.ghostty");
    defer alloc.free(path);

    var original = try configpkg.Config.default(alloc);
    defer original.deinit();
    var pending = try original.clone(alloc);
    defer pending.deinit();
    pending.@"font-size" = 14;
    pending.@"copy-on-select" = .true;
    const edited = settingsUserEditedKeys(&original, &pending);
    try std.testing.expectEqual(@as(usize, 2), edited.count());

    var reloaded = try configpkg.Config.default(alloc);
    defer reloaded.deinit();
    try reloaded.loadFile(alloc, path);
    try reloaded.loadRecursiveFiles(alloc);
    var names_buf: [settings_masked_keys_capacity]u8 = undefined;
    try std.testing.expectEqualStrings("font-size", settingsMaskedKeyNames(&names_buf, edited, &pending, &reloaded));

    // Two keys masked are both named, in the order Settings lists them.
    try tmp.dir.writeFile(.{ .sub_path = "later.conf", .data = "copy-on-select = false\nfont-size = 18\n" });
    var both = try configpkg.Config.default(alloc);
    defer both.deinit();
    try both.loadFile(alloc, path);
    try both.loadRecursiveFiles(alloc);
    try std.testing.expectEqualStrings("font-size, copy-on-select", settingsMaskedKeyNames(&names_buf, edited, &pending, &both));

    // A reload that holds what was saved names nothing.
    try tmp.dir.writeFile(.{ .sub_path = "config.ghostty", .data = "font-size = 14\ncopy-on-select = true\n" });
    var clean = try configpkg.Config.default(alloc);
    defer clean.deinit();
    try clean.loadFile(alloc, path);
    try std.testing.expectEqual(@as(usize, 0), settingsMaskedKeyNames(&names_buf, edited, &pending, &clean).len);

    // Nearly every editable key masked at once still fits the buffer.
    var everything = try configpkg.Config.default(alloc);
    defer everything.deinit();
    try settingsTestLoadText(&everything,
        \\scrollback-limit = 123456
        \\font-size = 13.25
        \\background-opacity = 0.875
        \\window-padding-x = 5,7
        \\window-padding-y = 9,11
        \\clipboard-trim-trailing-spaces = false
        \\desktop-notifications = false
        \\app-notifications = no-clipboard-copy,no-config-reload
        \\confirm-close-surface = always
        \\copy-on-select = clipboard
        \\clipboard-read = deny
        \\clipboard-write = deny
        \\window-theme = dark
        \\shell-integration = none
        \\cursor-style = bar
        \\window-padding-balance = true
        \\auto-update = off
        \\auto-update-channel = tip
        \\font-family = Second Font
        \\theme = light:Light,dark:Dark
        \\command = direct:pwsh.exe -NoLogo
    );
    var all: SettingsEditedKeySet = .initEmpty();
    inline for (win32_settings.editable_keys) |key| all.set(@intFromEnum(key));
    var defaults = try configpkg.Config.default(alloc);
    defer defaults.deinit();
    const crowded = settingsMaskedKeyNames(&names_buf, all, &everything, &defaults);
    try std.testing.expect(std.mem.count(u8, crowded, ", ") >= 15);
    try std.testing.expect(std.mem.startsWith(u8, crowded, "scrollback-limit, font-size, "));
}

test "win32 config problems leave out the arguments that start the process" {
    const alloc = std.testing.allocator;
    var config = try configpkg.Config.default(alloc);
    defer config.deinit();
    // What a launch from an Action Center toast and a safe-mode launch leave in
    // argv for every later load, and two real mistakes among them.
    // The wrapper is what the loader reads argv through; it gives each
    // diagnostic its place on the command line.
    var args: cli_args.ArgsIterator(cli_args.SliceIterator) = .{ .iterator = cli_args.sliceIterator(&.{
        "--safe-mode",
        "wgh://activate?surface=12&tab=3",
        "--font-szie=14",
        "stray-word",
        "--theme=light:No1pkg22,dark:No2pkg22",
    }) };
    try config.loadIter(alloc, &args);
    try config.finalize();
    // The two launch arguments, the two mistakes and the missing light theme.
    try std.testing.expectEqual(@as(usize, 5), config._diagnostics.items().len);

    var kept: usize = 0;
    for (config._diagnostics.items()) |diag| {
        if (isLaunchArgumentDiagnostic(diag, true)) continue;
        kept += 1;
        // The mistakes, the stray word and the theme are still the user's to hear about.
        try std.testing.expect(!std.mem.eql(u8, diag.key, "safe-mode") and !std.mem.startsWith(u8, diag.key, "wgh:"));
    }
    try std.testing.expectEqual(@as(usize, 3), kept);

    // A process that was not started with --safe-mode has no such argument.
    const safe_mode_complaint: cli_diagnostics.Diagnostic = .{ .location = .{ .cli = 1 }, .key = "safe-mode", .message = "unknown field" };
    try std.testing.expect(isLaunchArgumentDiagnostic(safe_mode_complaint, true));
    try std.testing.expect(!isLaunchArgumentDiagnostic(safe_mode_complaint, false));

    // Conditional replay preserves the CLI locations and still filters
    // launch arguments without hiding the user's mistakes.
    var rebuilt = (try config.changeConditionalState(.{ .theme = .dark })).?;
    defer rebuilt.deinit();
    var rebuilt_kept: usize = 0;
    var rebuilt_cli: usize = 0;
    for (rebuilt._diagnostics.items()) |diag| {
        if (diag.location == .cli) rebuilt_cli += 1;
        for (config._diagnostics.items()) |original| {
            if (std.mem.eql(u8, original.key, diag.key)) {
                try std.testing.expectEqualDeep(original.location, diag.location);
            }
        }
        if (!isLaunchArgumentDiagnostic(diag, true)) rebuilt_kept += 1;
    }
    try std.testing.expectEqual(@as(usize, 4), rebuilt_cli);
    try std.testing.expectEqual(@as(usize, 3), rebuilt_kept);

    // A file's own line with the same text is a mistake in that file.
    try std.testing.expect(!isLaunchArgumentDiagnostic(.{
        .location = .{ .file = .{ .path = "C:\\c", .line = 1 } },
        .key = "safe-mode",
        .message = "unknown field",
    }, true));
}

test "win32 a config with an unknown key, a bad value, a missing include and a missing theme has four problems" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.writeFile(.{
        .sub_path = "config.ghostty",
        .data = "font-szie = 14\nfont-size = big\nconfig-file = missing-include.conf\ntheme = No-Such-Theme-pkg22\n",
    });
    const path = try tmp.dir.realpathAlloc(alloc, "config.ghostty");
    defer alloc.free(path);

    var config = try configpkg.Config.default(alloc);
    defer config.deinit();
    try config.loadFile(alloc, path);
    try config.loadRecursiveFiles(alloc);
    try config.finalize();

    var problems: win32_config_problems.Problems = .{};
    defer problems.deinit(alloc);
    try problems.addDiagnostics(alloc, config._diagnostics.items());
    var buf: [2048]u8 = undefined;
    const list = problems.listText(&buf);
    // The banner counts them, and the list names each with its file and line.
    try std.testing.expectEqual(@as(usize, 4), problems.count());
    try std.testing.expect(std.mem.indexOf(u8, list, "font-szie") != null);
    try std.testing.expect(std.mem.indexOf(u8, list, "font-size") != null);
    try std.testing.expect(std.mem.indexOf(u8, list, "missing-include.conf") != null);
    try std.testing.expect(std.mem.indexOf(u8, list, "No-Such-Theme-pkg22") != null);
    const banner = (try problems.bannerText(alloc)).?;
    defer alloc.free(banner);
    try std.testing.expect(std.mem.startsWith(u8, banner, "4 config problems: "));
}

/// Free what reporting config problems leaves on `app`: the banner text, then
/// the problems.
pub fn testFreeConfigProblems(app: *App, alloc: Allocator) void {
    if (app.config_problems_banner) |text| alloc.free(text);
    app.config_problems.deinit(alloc);
}

test "win32 config problems raise an error banner that only a clean load takes down" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;
    const alloc = std.testing.allocator;

    var core_app: CoreApp = undefined;
    var app: App = undefined;
    var host: Host = undefined;
    var surface: Surface = undefined;
    var session: TestSession = .{};
    try session.init(.{
        .core_app = &core_app,
        .app = &app,
        .hosts = &.{.{ .storage = &host, .register = true, .next_tab_id = 2 }},
        .surfaces = &.{.{ .storage = &surface, .host = &host, .register = true }},
        .tabs = &.{.{ .host = &host, .surface = &surface, .id = 1 }},
    });
    defer session.deinit();
    defer testFreeConfigProblems(&app, alloc);

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.writeFile(.{ .sub_path = "config.ghostty", .data = "font-szie = 14\nfont-size = big\n" });
    const path = try tmp.dir.realpathAlloc(alloc, "config.ghostty");
    defer alloc.free(path);
    var broken = try configpkg.Config.default(alloc);
    defer broken.deinit();
    try broken.loadFile(alloc, path);
    var clean = try configpkg.Config.default(alloc);
    defer clean.deinit();

    try std.testing.expect(app.reportConfigProblems(&broken));
    try std.testing.expectEqual(HostBannerKind.err, host.banner_kind);
    try std.testing.expect(std.mem.startsWith(u8, host.banner_text.?, "2 config problems: font-szie: "));

    // A load that finds nothing takes down this banner...
    try std.testing.expect(!app.reportConfigProblems(&clean));
    try std.testing.expectEqual(HostBannerKind.none, host.banner_kind);
    try std.testing.expect(host.banner_text == null);
    try std.testing.expectEqual(@as(usize, 0), app.config_problems.count());

    // ... and not another message that took its place.
    try std.testing.expect(app.reportConfigProblems(&broken));
    try host.setBanner(.err, "New window could not be opened.");
    try std.testing.expect(!app.reportConfigProblems(&clean));
    try std.testing.expectEqualStrings("New window could not be opened.", host.banner_text.?);
    try host.setBanner(.none, null);
}

