test "win32 settings every editable key round trips through a file" {
    const alloc = std.testing.allocator;
    const ConfigFormatter = @import("../config/formatter.zig");
    var defaults = try configpkg.Config.default(alloc);
    defer defaults.deinit();
    var pending = try configpkg.Config.default(alloc);
    defer pending.deinit();
    try settingsTestLoadText(&pending, @import("win32_settings_fields.zig").round_trip_config);
    inline for (win32_settings.editable_keys) |key| {
        try std.testing.expect(defaults.changed(&pending, key));
        var edited: SettingsEditedKeySet = .initEmpty();
        edited.set(@intFromEnum(key));
        var old: std.Io.Writer.Allocating = .init(alloc);
        defer old.deinit();
        const value = @field(defaults, @tagName(key));
        try ConfigFormatter.formatEntry(@TypeOf(value), @tagName(key), value, &old.writer);
        const duplicates = try std.fmt.allocPrint(alloc, "# preserve this comment\n{s}# between duplicates\r\n{s}", .{ old.written(), old.written() });
        defer alloc.free(duplicates);
        for ([_][]const u8{ "# preserve this comment\n", old.written(), duplicates }) |raw| {
            var out: std.ArrayListUnmanaged(u8) = .{};
            defer out.deinit(alloc);
            try patchOrAppendEdits(alloc, raw, &pending, edited, &out);
            var loaded = try configpkg.Config.default(alloc);
            defer loaded.deinit();
            try settingsTestLoadText(&loaded, out.items);
            try std.testing.expect(!settingsEditedValueMasked(&pending, &loaded, key));
            if (raw.ptr == duplicates.ptr) {
                try std.testing.expect(std.mem.startsWith(u8, out.items, "# preserve this comment\n"));
                try std.testing.expect(std.mem.indexOf(u8, out.items, "# between duplicates\r\n") != null);
            }
        }
    }
}

/// The lines of `text` that do not assign `key`, each with its line ending.
fn settingsTestOtherLines(alloc: Allocator, text: []const u8, key: SettingsConfigKey) !std.ArrayListUnmanaged([]const u8) {
    var lines: std.ArrayListUnmanaged([]const u8) = .{};
    errdefer lines.deinit(alloc);
    var start: usize = 0;
    while (start < text.len) {
        const end = if (std.mem.indexOfScalarPos(u8, text, start, '\n')) |newline| newline + 1 else text.len;
        const line = text[start..end];
        if (settingsAssignmentKey(std.mem.trimRight(u8, line, "\r\n")) != key) try lines.append(alloc, line);
        start = end;
    }
    return lines;
}

fn settingsTestKeyLines(text: []const u8, key: SettingsConfigKey) usize {
    var count: usize = 0;
    var lines = std.mem.splitScalar(u8, text, '\n');
    while (lines.next()) |line| count += @intFromBool(settingsAssignmentKey(std.mem.trimRight(u8, line, "\r")) == key);
    return count;
}

test "win32 settings a reset of each kind of field saves its default and leaves the rest of the file as it was" {
    @setEvalBranchQuota(100_000);
    const alloc = std.testing.allocator;
    const field_model = @import("win32_settings_fields.zig");
    // Every editable key away from its default, among text Settings does not
    // edit: comments, CRLF, an optional include, a key it has no row for. The
    // channel is the one this build is not: its own counts as the default,
    // and a reset of it keeps the saved value (`resetSettingValue`).
    const source = "# noctty config\r\nwindow-save-state = never\r\n" ++
        "config-file = ?missing-include.ghostty\n" ++
        field_model.round_trip_config ++
        "\n  # indented comment\nkeybind = ctrl+shift+a=new_tab\n";
    const text = try std.mem.replaceOwned(u8, alloc, source, "auto-update-channel = tip\n", if (build_config.release_channel == .tip)
        "auto-update-channel = stable\n"
    else
        "auto-update-channel = tip\n");
    defer alloc.free(text);
    var original = try configpkg.Config.default(alloc);
    defer original.deinit();
    try settingsTestLoadText(&original, text);
    var defaults = try configpkg.Config.default(alloc);
    defer defaults.deinit();
    var kinds: std.EnumSet(field_model.Kind) = .initEmpty();
    inline for (field_model.form_fields) |row| if (comptime row.resettable()) {
        errdefer std.debug.print("settings reset of {s}\n", .{row.native.binding});
        kinds.insert(row.descriptor.kind);
        const key: SettingsConfigKey = row.descriptor.key;
        var pending = try original.clone(alloc);
        defer pending.deinit();
        try win32_settings.resetDraftRow(&pending, &original, &defaults, row);
        // A reset is an edit of its key alone.
        const edited = settingsUserEditedKeys(&original, &pending);
        try std.testing.expectEqual(@as(usize, 1), edited.count());
        try std.testing.expect(edited.isSet(@intFromEnum(key)));

        const saved = try settingsTestSave(alloc, text, &original, &pending);
        defer alloc.free(saved);
        // Every line that does not assign the key is byte-identical, in order.
        var before = try settingsTestOtherLines(alloc, text, key);
        defer before.deinit(alloc);
        var after = try settingsTestOtherLines(alloc, saved, key);
        defer after.deinit(alloc);
        try std.testing.expectEqual(before.items.len, after.items.len);
        for (before.items, after.items) |a, b| try std.testing.expectEqualStrings(a, b);
        // The key is one line now (the two font lines became one reset), or
        // none for Default profile, whose default is the absence of the line.
        try std.testing.expectEqual(@as(usize, if (key == .@"default-profile") 0 else 1), settingsTestKeyLines(saved, key));
        // Read back, the row has its default and every other row what it had.
        var reloaded = try configpkg.Config.default(alloc);
        defer reloaded.deinit();
        try settingsTestLoadText(&reloaded, saved);
        inline for (win32_settings.editable_keys) |other| {
            try std.testing.expect(!pending.changed(&reloaded, other));
        }
        try std.testing.expect(!defaults.changed(&reloaded, row.descriptor.key) or row.descriptor.kind == .notifications);
    };
    // Every kind of field was reset but background blur, the only field of
    // its kind, which Windows does not support.
    inline for (comptime std.enums.values(field_model.Kind)) |kind| {
        try std.testing.expectEqual(kind != .blur, kinds.contains(kind));
    }
}

test "win32 settings fields found by a search and edited save themselves and leave the rest of the file as it was" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;
    try runOnHiddenDesktop(struct {
        fn body() !void {
            const alloc = std.testing.allocator;
            var core_app: CoreApp = undefined;
            var app: App = undefined;
            var host: Host = undefined;
            var session: TestSession = .{};
            try session.init(.{ .core_app = &core_app, .app = &app, .hosts = &.{.{ .storage = &host }} });
            defer session.deinit();
            defer testFreeConfigProblems(&app, alloc);
            const settings_class = comptime std.unicode.utf8ToUtf16LeStringLiteral("noctty.win32.settings");
            const viewport_class = comptime std.unicode.utf8ToUtf16LeStringLiteral("noctty.win32.settings.viewport");
            defer {
                app.settings_window.deinit();
                _ = sys.UnregisterClassW(settings_class, app.settings_window.handle.hinstance);
                _ = sys.UnregisterClassW(viewport_class, app.settings_window.handle.hinstance);
            }
            const wm_keydown = 0x0100;
            const vk_return = 0x0D;
            const bm_click = 0x00F5;
            const cb_setcursel = 0x014E;
            const cbn_selchange = 1;
            const settings = &app.settings_window;
            try settings.open();
            const search = settings.edit_search.?;

            // Text Settings does not edit around the lines it does: comments,
            // CRLF, an optional include, a key it has no row for, and lines
            // for two of the fields edited below, at the values the window
            // opened with.
            const text = "# noctty config\r\nwindow-save-state = never\r\n" ++
                "config-file = ?missing-include.ghostty\n" ++
                "scrollback-limit = 10000000\n" ++
                "\n  # indented comment\nkeybind = ctrl+shift+a=new_tab\n" ++
                "cursor-style = block\n";

            // Each field is found by a word of its own and reached with Enter,
            // one of each kind: a number, a dropdown, a checkbox and a text
            // field whose draft is staged when it is left.
            const Find = struct {
                fn go(window: *win32_settings.SettingsWindow, field: *const fn (*win32_settings.SettingsWindow) ?HWND, comptime query: []const u8) !HWND {
                    const box = window.edit_search.?;
                    _ = sys.SetFocus(box);
                    _ = sys.SetWindowTextW(box, std.unicode.utf8ToUtf16LeStringLiteral(query));
                    try std.testing.expect(window.handleAccelerator(box, wm_keydown, vk_return, 0));
                    const control = field(window).?;
                    try std.testing.expectEqual(control, sys.GetFocus().?);
                    return control;
                }
                fn scrollback(window: *win32_settings.SettingsWindow) ?HWND {
                    return window.fields.edit_scrollback;
                }
                fn cursor(window: *win32_settings.SettingsWindow) ?HWND {
                    return window.fields.combo_cursor_style;
                }
                fn trim(window: *win32_settings.SettingsWindow) ?HWND {
                    return window.fields.chk_trim_trail;
                }
                fn fonts(window: *win32_settings.SettingsWindow) ?HWND {
                    return window.fields.edit_font_family;
                }
            };
            const scrollback = try Find.go(settings, Find.scrollback, "history");
            _ = sys.SetWindowTextW(scrollback, std.unicode.utf8ToUtf16LeStringLiteral("5000"));
            const cursor = try Find.go(settings, Find.cursor, "caret");
            // Bar, where the default is Block.
            _ = sys.SendMessageW(cursor, cb_setcursel, 0, 0);
            const cursor_id: usize = @intCast(sys.GetDlgCtrlID(cursor));
            _ = sys.SendMessageW(settings.hwnd.?, c.WM_COMMAND, cursor_id | (@as(usize, cbn_selchange) << 16), @bitCast(@intFromPtr(cursor)));
            const trim = try Find.go(settings, Find.trim, "whitespace");
            _ = sys.SendMessageW(trim, bm_click, 0, 0);
            const fonts = try Find.go(settings, Find.fonts, "fallbacks");
            _ = sys.SetWindowTextW(fonts, std.unicode.utf8ToUtf16LeStringLiteral("Consolas"));
            // Leaving the field stages it.
            _ = sys.SetFocus(search);

            const original = &settings.original.?;
            const pending = &settings.pending.?;
            const edited = settingsUserEditedKeys(original, pending);
            const keys = [_]SettingsConfigKey{ .@"scrollback-limit", .@"cursor-style", .@"clipboard-trim-trailing-spaces", .@"font-family" };
            try std.testing.expectEqual(keys.len, edited.count());
            for (keys) |key| try std.testing.expect(edited.isSet(@intFromEnum(key)));

            const saved = try settingsTestSave(alloc, text, original, pending);
            defer alloc.free(saved);
            // Every line that assigns none of those keys is byte-identical,
            // in order.
            var before: std.ArrayListUnmanaged([]const u8) = .{};
            defer before.deinit(alloc);
            var after: std.ArrayListUnmanaged([]const u8) = .{};
            defer after.deinit(alloc);
            for ([_]struct { source: []const u8, lines: *std.ArrayListUnmanaged([]const u8) }{
                .{ .source = text, .lines = &before },
                .{ .source = saved, .lines = &after },
            }) |side| {
                var start: usize = 0;
                while (start < side.source.len) {
                    const end = if (std.mem.indexOfScalarPos(u8, side.source, start, '\n')) |newline| newline + 1 else side.source.len;
                    const line = side.source[start..end];
                    const key = settingsAssignmentKey(std.mem.trimRight(u8, line, "\r\n"));
                    if (key == null or std.mem.indexOfScalar(SettingsConfigKey, &keys, key.?) == null) try side.lines.append(alloc, line);
                    start = end;
                }
            }
            try std.testing.expectEqual(before.items.len, after.items.len);
            for (before.items, after.items) |a, b| try std.testing.expectEqualStrings(a, b);
            // Each key is one line, but the font list, which starts with the
            // line that clears what a lower layer sets; read back, the file
            // holds the drafts.
            for (keys) |key| try std.testing.expectEqual(@as(usize, if (key == .@"font-family") 2 else 1), settingsTestKeyLines(saved, key));
            try std.testing.expect(std.mem.indexOf(u8, saved, "font-family = \nfont-family = Consolas\n") != null);
            var reloaded = try configpkg.Config.default(alloc);
            defer reloaded.deinit();
            try settingsTestLoadText(&reloaded, saved);
            inline for (win32_settings.editable_keys) |key| {
                try std.testing.expect(!pending.changed(&reloaded, key));
            }
            try std.testing.expectEqual(@as(usize, 5000), reloaded.@"scrollback-limit");
            try std.testing.expect(reloaded.@"cursor-style" == .bar);
            try std.testing.expect(reloaded.@"clipboard-trim-trailing-spaces" != original.@"clipboard-trim-trailing-spaces");
        }
    }.body);
}

test "win32 settings patch persists optional command edits" {
    const testing = std.testing;

    var original = try configpkg.Config.default(testing.allocator);
    defer original.deinit();
    var pending = try configpkg.Config.default(testing.allocator);
    defer pending.deinit();

    var direct: configpkg.Config.Command = undefined;
    try direct.parseCLI(pending._arena.?.allocator(), "direct:pwsh.exe -NoLogo");
    pending.command = direct;

    const edited = settingsUserEditedKeys(&original, &pending);
    try testing.expect(edited.isSet(@intFromEnum(SettingsConfigKey.command)));

    var patched: std.ArrayListUnmanaged(u8) = .{};
    defer patched.deinit(testing.allocator);
    try patchOrAppendEdits(
        testing.allocator,
        "font-size = 12\n",
        &pending,
        edited,
        &patched,
    );
    try testing.expect(std.mem.indexOf(u8, patched.items, "command = direct:pwsh.exe -NoLogo") != null);

    patched.clearRetainingCapacity();
    try patchOrAppendEdits(
        testing.allocator,
        "# Keep this whole-line comment.\n  command = cmd.exe /c echo #old\nfont-size = 12\n",
        &pending,
        edited,
        &patched,
    );
    try testing.expectEqualStrings(
        "# Keep this whole-line comment.\n  command = direct:pwsh.exe -NoLogo\nfont-size = 12\n",
        patched.items,
    );

    patched.clearRetainingCapacity();
    try patchOrAppendEdits(
        testing.allocator,
        "command = cmd.exe /c echo ;old\nfont-size = 12\n",
        &pending,
        edited,
        &patched,
    );
    try testing.expectEqualStrings(
        "command = direct:pwsh.exe -NoLogo\nfont-size = 12\n",
        patched.items,
    );

    original.command = try pending.command.?.clone(original._arena.?.allocator());
    pending.command = null;
    const cleared = settingsUserEditedKeys(&original, &pending);
    try testing.expect(cleared.isSet(@intFromEnum(SettingsConfigKey.command)));
    patched.clearRetainingCapacity();
    try patchOrAppendEdits(
        testing.allocator,
        "command = cmd.exe\nfont-size = 12\n",
        &pending,
        cleared,
        &patched,
    );
    try testing.expect(std.mem.indexOf(u8, patched.items, "command = \n") != null);
    try testing.expect(std.mem.indexOf(u8, patched.items, "command = cmd.exe") == null);
}

/// A config with user profiles, an include, comments and odd bytes, which a
/// Settings save must leave as written outside the line it edits.
const settings_test_profiles_head =
    "# Profiles live here.\n" ++
    "config-file = ?profiles-extra.ghostty\n" ++
    "profile-command = py312: cmd.exe /k \"C:\\Tools Dir\\init.cmd\" \"a&b\" %PATH%\n" ++
    "profile-name = py312: Python 3.12 # not a comment\r\n" ++
    "  profile-env = py312: PATH=C:\\Python312;%PATH%\n" ++
    "profile-working-directory = py312: ~/src\n" ++
    "# profile-command = old: cmd.exe\n";
const settings_test_profiles_config = settings_test_profiles_head ++ "font-size = 12\n";

/// Run one Settings save of `pending` against `original` over a config file
/// holding `text`, and return what the file holds afterwards.
fn settingsTestSave(alloc: Allocator, text: []const u8, original: *const configpkg.Config, pending: *const configpkg.Config) ![]u8 {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.writeFile(.{ .sub_path = "config.ghostty", .data = text });
    const path = try tmp.dir.realpathAlloc(alloc, "config.ghostty");
    defer alloc.free(path);
    try persistSettings(alloc, path, pending, settingsUserEditedKeys(original, pending), null);
    return try tmp.dir.readFileAlloc(alloc, "config.ghostty", 1 << 20);
}

test "win32 settings save writes the chosen default profile as one line and reads it back" {
    const alloc = std.testing.allocator;
    var original = try configpkg.Config.default(alloc);
    defer original.deinit();
    var pending = try configpkg.Config.default(alloc);
    defer pending.deinit();
    pending.@"default-profile" = try pending._arena.?.allocator().dupeZ(u8, "user:py312");

    // A first choice is appended; nothing above it moves.
    const first = try settingsTestSave(alloc, settings_test_profiles_config, &original, &pending);
    defer alloc.free(first);
    try std.testing.expectEqualStrings(settings_test_profiles_config ++ "default-profile = user:py312\n", first);
    var loaded = try configpkg.Config.default(alloc);
    defer loaded.deinit();
    try settingsTestLoadText(&loaded, first);
    try std.testing.expectEqualStrings("user:py312", loaded.@"default-profile".?);
    try std.testing.expect(!pending.changed(&loaded, .@"default-profile"));

    // The next choice replaces that line in place, by key.
    original.@"default-profile" = try original._arena.?.allocator().dupeZ(u8, "user:py312");
    pending.@"default-profile" = try pending._arena.?.allocator().dupeZ(u8, "cmd.exe");
    const second = try settingsTestSave(alloc, first, &original, &pending);
    defer alloc.free(second);
    try std.testing.expectEqualStrings(settings_test_profiles_config ++ "default-profile = cmd.exe\n", second);
}

test "win32 settings save of Automatic removes the default profile lines" {
