    ));
}

test "win32 settings a saved Match Windows theme the reload makes system is not overridden" {
    const testing = std.testing;
    var pending = try configpkg.Config.default(testing.allocator);
    defer pending.deinit();
    var reloaded = try configpkg.Config.default(testing.allocator);
    defer reloaded.deinit();
    // A reset of Window theme saves `auto`; with a light/dark theme pair the
    // reload's finalize makes it `system`, which follows Windows the same way.
    pending.@"window-theme" = .auto;
    reloaded.@"window-theme" = .system;
    try testing.expect(!settingsEditedValueMasked(&pending, &reloaded, .@"window-theme"));
    reloaded.@"window-theme" = .dark;
    try testing.expect(settingsEditedValueMasked(&pending, &reloaded, .@"window-theme"));
    pending.@"window-theme" = .light;
    reloaded.@"window-theme" = .light;
    try testing.expect(!settingsEditedValueMasked(&pending, &reloaded, .@"window-theme"));
}

test "win32 settings patch persists optional auto update edits" {
    const testing = std.testing;

    var original = try configpkg.Config.default(testing.allocator);
    defer original.deinit();
    var pending = try configpkg.Config.default(testing.allocator);
    defer pending.deinit();

    pending.@"auto-update" = .download;
    const edited = settingsUserEditedKeys(&original, &pending);
    try testing.expect(edited.isSet(@intFromEnum(SettingsConfigKey.@"auto-update")));

    var patched: std.ArrayListUnmanaged(u8) = .{};
    defer patched.deinit(testing.allocator);
    try patchOrAppendEdits(testing.allocator, "", &pending, edited, &patched);
    try testing.expectEqualStrings("auto-update = download\n", patched.items);

    original.@"auto-update" = .check;
    pending.@"auto-update" = null;
    const cleared = settingsUserEditedKeys(&original, &pending);
    try testing.expect(cleared.isSet(@intFromEnum(SettingsConfigKey.@"auto-update")));
    patched.clearRetainingCapacity();
    try patchOrAppendEdits(
        testing.allocator,
        "auto-update = check\n",
        &pending,
        cleared,
        &patched,
    );
    try testing.expectEqualStrings("auto-update = \n", patched.items);
}

/// Strip HTML tags for the CF_UNICODETEXT fallback when core only
/// supplies `text/html`. Plain consumers get readable text; entity
/// references are preserved verbatim.
pub fn stripHtmlTags(alloc: std.mem.Allocator, html: []const u8) ![]u8 {
    var buf: std.ArrayList(u8) = .{};
    defer buf.deinit(alloc);
    try buf.ensureTotalCapacity(alloc, html.len);
    var i: usize = 0;
    while (i < html.len) {
        const char = html[i];
        if (char == '<') {
            if (std.mem.indexOfScalarPos(u8, html, i, '>')) |end| {
                i = end + 1;
                continue;
            }
            try buf.appendSlice(alloc, html[i..]);
            break;
        }
        try buf.append(alloc, char);
        i += 1;
    }
    return buf.toOwnedSlice(alloc);
}

test "stripHtmlTags drops tag brackets" {
    const testing = std.testing;
    const out = try stripHtmlTags(
        testing.allocator,
        "<span style=\"color:red\">hello</span> <b>world</b>",
    );
    defer testing.allocator.free(out);
    try testing.expectEqualStrings("hello world", out);
}

test "stripHtmlTags handles malformed (unclosed tag)" {
    const testing = std.testing;
    const out = try stripHtmlTags(testing.allocator, "pre<broken");
    defer testing.allocator.free(out);
    try testing.expectEqualStrings("pre<broken", out);
}

test "stripHtmlTags malformed in middle preserves fallback tail" {
    const testing = std.testing;
    const out = try stripHtmlTags(testing.allocator, "hello <world tail");
    defer testing.allocator.free(out);
    try testing.expectEqualStrings("hello <world tail", out);
}

test "stripHtmlTags preserves plain text" {
    const testing = std.testing;
    const out = try stripHtmlTags(testing.allocator, "no tags here");
    defer testing.allocator.free(out);
    try testing.expectEqualStrings("no tags here", out);
}

test "copied terminal text keeps only web and mail links as anchors" {
    const alloc = std.testing.allocator;

    var t = try terminal.Terminal.init(alloc, .{ .cols = 80, .rows = 4 });
    defer t.deinit(alloc);
    var stream = t.vtStream();
    defer stream.deinit();
    stream.nextSlice("\x1b]8;;javascript:alert(1)\x1b\\evil\x1b]8;;\x1b\\ ");
    stream.nextSlice("\x1b]8;;file://attacker/share/x\x1b\\unc\x1b]8;;\x1b\\ ");
    stream.nextSlice("\x1b]8;;https://example.com\x1b\\good\x1b]8;;\x1b\\");

    // The same formatter the mixed copy runs, then the CF_HTML envelope
    // `Surface.writeClipboardHtml` hands the clipboard, with no clipboard
    // involved.
    var aw: std.Io.Writer.Allocating = .init(alloc);
    defer aw.deinit();
    var formatter: terminal.formatter.ScreenFormatter = .init(
        t.screens.active,
        .{ .emit = .html },
    );
    try formatter.format(&aw.writer);

    const out = try win32_clipboard_html.wrapFragment(alloc, aw.writer.buffered());
    defer alloc.free(out);
    const range = win32_clipboard_html.fragmentRange(out).?;
    const fragment = out[range.start..range.end];

    try std.testing.expect(std.mem.indexOf(u8, fragment, "evil unc ") != null);
    try std.testing.expect(std.mem.indexOf(u8, fragment, "<a href=\"https://example.com\">good</a>") != null);
    try std.testing.expect(std.mem.indexOf(u8, fragment, "javascript:") == null);
    try std.testing.expect(std.mem.indexOf(u8, fragment, "file://") == null);
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, fragment, "<a "));
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, fragment, "</a>"));
}

/// Window procedure for the tab strip's title tooltip.
///
/// The popup is owned by the host but is a top-level window, so nothing about
/// it belongs to the host's own message flow beyond the paint.
pub fn tabTooltipProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    switch (msg) {
        c.WM_ERASEBKGND => return 1,
        c.WM_PAINT => {
            if (windowData(Host, hwnd)) |host| {
                host.paintTabTooltip(hwnd);
            } else {
                // No host behind the popup (teardown, or a paint that beat
                // `setWindowData`). The update region still has to be
                // validated or Windows keeps re-posting this message.
                var ps: PAINTSTRUCT = undefined;
                _ = sys.BeginPaint(hwnd, &ps);
                _ = sys.EndPaint(hwnd, &ps);
            }
            return 0;
        },
        c.WM_GETOBJECT => {
            const host = windowData(Host, hwnd) orelse
                return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
            if (!host.app.com_initialized) return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
            if (host.tab_tooltip_uia_provider) |provider| {
                if (win32_uia.returnChromeControlProvider(hwnd, wParam, lParam, provider)) |lr| return lr;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        // The popup lands between the pointer and the tab it describes. It must
        // never take a hit test or an activation away from the strip.
        c.WM_NCHITTEST => return c.HTTRANSPARENT,
        c.WM_MOUSEACTIVATE => return c.MA_NOACTIVATE,
        else => {},
    }
    return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
}

pub fn quickSelectProc(
    hwnd: HWND,
    msg: UINT,
    wParam: WPARAM,
    lParam: LPARAM,
) callconv(.winapi) LRESULT {
    const surface = getSurface(hwnd);
    switch (msg) {
        c.WM_ERASEBKGND => return 1,
        c.WM_PAINT => {
            if (surface) |value| value.paintQuickSelect();
            return 0;
        },
        c.WM_SETFOCUS => {
            if (surface) |value| if (value.quick_select_uia_provider) |provider| {
                win32_uia.events.raiseFocusChanged(&provider.base);
            };
            return 0;
        },
        c.WM_KILLFOCUS => {
            if (surface) |value| value.closeQuickSelect(false);
            return 0;
        },
        // Keep capture through the full click. Closing on button-down would
        // release capture early and let the matching button-up reach the
        // terminal underneath (including its context-menu/reporting paths).
        c.WM_LBUTTONDOWN, c.WM_RBUTTONDOWN, c.WM_MBUTTONDOWN => {
            return 0;
        },
        c.WM_XBUTTONDOWN => return 1,
        c.WM_LBUTTONUP => {
            if (surface) |value| {
                if (value.quick_select_session) |*session| {
                    if (consumeQuickSelectOpeningLeftButtonUp(
                        &session.suppress_opening_left_button_up,
                        &session.suppress_until_opening_keys_released,
                        anyVirtualKeyPressed(),
                    )) return 0;
                }
                value.closeQuickSelect(true);
            }
            return 0;
        },
        c.WM_RBUTTONUP, c.WM_MBUTTONUP => {
            if (surface) |value| value.closeQuickSelect(true);
            return 0;
        },
        c.WM_XBUTTONUP => {
            if (surface) |value| value.closeQuickSelect(true);
            // Windows requires TRUE for handled XButton messages.
            return 1;
        },
        // Scrolling would invalidate the immutable viewport snapshot behind
        // the visible labels, so the modal overlay owns wheel input too.
        c.WM_MOUSEWHEEL,
        c.WM_MOUSEHWHEEL,
        c.WM_POINTERWHEEL,
        c.WM_POINTERHWHEEL,
        => return 0,
        c.WM_CAPTURECHANGED => {
            if (surface) |value| value.closeQuickSelect(false);
            return 0;
        },
        c.WM_KEYDOWN, c.WM_SYSKEYDOWN => {
            if (surface) |value| value.handleQuickSelectKey(wParam, lParam);
            return 0;
        },
        c.WM_KEYUP, c.WM_SYSKEYUP => {
            if (surface) |value| value.handleQuickSelectKeyUp();
            return 0;
        },
        c.WM_CHAR, c.WM_SYSCHAR => {
            if (surface) |value| value.handleQuickSelectChar(wParam);
            return 0;
        },
        c.WM_DEADCHAR,
        c.WM_SYSDEADCHAR,
        => return 0,
        c.WM_GETOBJECT => {
            const value = surface orelse return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
            if (!value.app.com_initialized) return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
            value.ensureQuickSelectUiaProvider() catch |err| {
                log.warn("quick select UIA provider unavailable err={}", .{err});
                return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
            };
            const provider = value.quick_select_uia_provider orelse
                return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
            if (win32_uia.returnPaletteListProvider(
                hwnd,
                wParam,
                lParam,
                provider,
            )) |result| return result;
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_SETCURSOR => {
            _ = sys.SetCursor(sys.LoadCursorW(null, c.IDC_ARROW));
            return 1;
        },
        else => return sys.DefWindowProcW(hwnd, msg, wParam, lParam),
    }
}

pub fn scrollbarProc(
    hwnd: HWND,
    msg: UINT,
    wParam: WPARAM,
    lParam: LPARAM,
) callconv(.winapi) LRESULT {
    const surface = getSurface(hwnd);
    switch (msg) {
        c.WM_GETOBJECT => {
            if (surface) |value| {
                if (value.scrollbar_uia_provider) |provider| {
                    if (win32_uia.returnChromeControlProvider(hwnd, wParam, lParam, provider)) |lr| return lr;
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_ERASEBKGND => return 1,
        c.WM_PAINT => {
            if (surface) |value| value.paintScrollbar();
            return 0;
        },
        c.WM_MOUSEMOVE => {
            if (surface) |value| value.handleScrollbarMouseMove(hwnd, lParam);
            return 0;
        },
        c.WM_MOUSELEAVE => {
            if (surface) |value| value.handleScrollbarMouseLeave();
            return 0;
        },
        c.WM_LBUTTONDOWN => {
            if (surface) |value| value.handleScrollbarLeftButtonDown(hwnd, lParam);
            return 0;
        },
        c.WM_LBUTTONUP => {
            if (surface) |value| value.handleScrollbarLeftButtonUp(lParam);
            return 0;
        },
        c.WM_CAPTURECHANGED => {
            if (surface) |value| value.handleScrollbarCaptureChanged();
            return 0;
        },
        c.WM_SETCURSOR => {
            _ = sys.SetCursor(sys.LoadCursorW(null, c.IDC_ARROW));
            return 1;
        },
        else => return sys.DefWindowProcW(hwnd, msg, wParam, lParam),
    }
}

