pub fn paintPinnedSlotBadge(hdc: HDC, rect: RECT, digit: u8, border: u32, bg: u32, fg: u32, dpi: u32) void {
    const s = Host.scaledBy;
    const badge_rect = RECT{
        .left = rect.right - s(15, dpi),
        .top = rect.top + s(3, dpi),
        .right = rect.right - s(4, dpi),
        .bottom = rect.top + s(14, dpi),
    };
    drawRoundedRect(hdc, badge_rect, bg, border, s(3, dpi));
    var text_buf = [_]u16{ digit, 0 };
    _ = sys.SetBkMode(hdc, c.TRANSPARENT);
    _ = sys.SetTextColor(hdc, fg);
    var text_rect = badge_rect;
    _ = sys.DrawTextW(
        hdc,
        @ptrCast(&text_buf),
        1,
        &text_rect,
        c.DT_CENTER | c.DT_VCENTER | c.DT_SINGLELINE | c.DT_NOPREFIX,
    );
}

pub const profileOpenTargetMarkerColor = labels.profileOpenTargetMarkerColor;

