pub fn overlayButtonReleaseThunk(ctx: *anyopaque) void {
    const provider: *win32_uia.SettingsControlProvider = @ptrCast(@alignCast(ctx));
    _ = win32_uia.SettingsControlProvider.Release(&provider.base);
}

const OverlayButtonUiaProviders = struct {
    accept: ?*win32_uia.SettingsControlProvider,
    cancel: ?*win32_uia.SettingsControlProvider,
};

fn overlayButtonUiaProviderForHwnd(
    hwnd: HWND,
    accept_hwnd: ?HWND,
    cancel_hwnd: ?HWND,
    accept_provider: ?*win32_uia.SettingsControlProvider,
    cancel_provider: ?*win32_uia.SettingsControlProvider,
) ?*win32_uia.SettingsControlProvider {
    if (accept_hwnd) |accept| {
        if (hwnd == accept) return accept_provider;
    }
    if (cancel_hwnd) |cancel| {
        if (hwnd == cancel) return cancel_provider;
    }
    return null;
}

pub fn takeOverlayButtonUiaProviders(
    accept: *?*win32_uia.SettingsControlProvider,
    cancel: *?*win32_uia.SettingsControlProvider,
) OverlayButtonUiaProviders {
    const result: OverlayButtonUiaProviders = .{
        .accept = accept.*,
        .cancel = cancel.*,
    };
    accept.* = null;
    cancel.* = null;
    return result;
}

fn shouldRefocusAfterOverlayHide(
    focused: ?HWND,
    edit: ?HWND,
    accept: ?HWND,
    cancel: ?HWND,
    list: ?HWND,
) bool {
    const hwnd = focused orelse return false;
    return (edit != null and hwnd == edit.?) or
        (accept != null and hwnd == accept.?) or
        (cancel != null and hwnd == cancel.?) or
        (list != null and hwnd == list.?);
}

pub fn logUiActionError(comptime context: []const u8, err: anyerror) void {
    log.warn(context ++ " err={}", .{err});
}

pub fn runUiActionOrLog(comptime context: []const u8, action: anytype) void {
    _ = action catch |err| logUiActionError(context, err);
}

/// Run a chrome sync that reports "this changed", treating a failure as "no
/// change". The sync helpers work on terminal-controlled data and can fail on
/// it, and every `refreshChrome` call site already logs instead of
/// propagating. Paths reached from `App.tick` need the same containment: the
/// Win32 message loop calls `tick` with `try`, so an escaping error unwinds
/// `App.run` and exits the process rather than dropping one chrome update.
pub fn chromeSyncOrLog(comptime context: []const u8, sync: anytype) bool {
    return sync catch |err| {
        logUiActionError(context, err);
        return false;
    };
}

pub fn tabContainerProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    if (getHost(hwnd)) |host| {
        if (msg == c.WM_GETOBJECT) {
            if (host.tab_container_uia_provider) |provider| {
                if (win32_uia.returnChromeControlProvider(hwnd, wParam, lParam, provider)) |lr| return lr;
            }
        }
        if (msg == c.WM_NCHITTEST) return c.HTTRANSPARENT;
        if (host.tab_container_prev_proc) |previous| return sys.CallWindowProcW(previous, hwnd, msg, wParam, lParam);
    }
    return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
}

const BannerKey = enum { ignore, press, dismiss, other_button };

/// What a key does on a focused banner button, or null when the button
/// leaves it to the focus-region keys (F6, and Escape on the update notice,
/// which goes back to the terminal: Dismiss records that version as
/// dismissed, so it takes a deliberate press). Space is the BUTTON's own:
/// it clicks on release. A held Enter or Escape repeats, and a repeat must
/// not press whatever button the first press left focused.
pub fn bannerButtonKey(has_message: bool, vk: WPARAM, repeat: bool) ?BannerKey {
    return switch (vk) {
        c.VK_RETURN => if (repeat) .ignore else .press,
        c.VK_ESCAPE => if (!has_message) null else if (repeat) .ignore else .dismiss,
        c.VK_TAB, c.VK_LEFT, c.VK_RIGHT => .other_button,
        else => null,
    };
}

test "bannerButtonKey presses once, closes a message on Escape and leaves the notice's Escape alone" {
    try std.testing.expectEqual(@as(?BannerKey, .press), bannerButtonKey(true, c.VK_RETURN, false));
    try std.testing.expectEqual(@as(?BannerKey, .press), bannerButtonKey(false, c.VK_RETURN, false));
    try std.testing.expectEqual(@as(?BannerKey, .ignore), bannerButtonKey(false, c.VK_RETURN, true));
    try std.testing.expectEqual(@as(?BannerKey, .dismiss), bannerButtonKey(true, c.VK_ESCAPE, false));
    try std.testing.expectEqual(@as(?BannerKey, .ignore), bannerButtonKey(true, c.VK_ESCAPE, true));
    try std.testing.expectEqual(@as(?BannerKey, null), bannerButtonKey(false, c.VK_ESCAPE, false));
    for ([_]WPARAM{ c.VK_TAB, c.VK_LEFT, c.VK_RIGHT }) |vk| {
        try std.testing.expectEqual(@as(?BannerKey, .other_button), bannerButtonKey(false, vk, false));
    }
    try std.testing.expectEqual(@as(?BannerKey, null), bannerButtonKey(true, c.VK_SPACE, false));
    try std.testing.expectEqual(@as(?BannerKey, null), bannerButtonKey(true, c.VK_F6, false));
}

const ConfirmKey = enum { accept, cancel, other_button, ignore };

/// What a key does on a confirm prompt's Allow or Cancel button, or null to
/// leave it to the button. Enter presses the focused button and Escape
/// cancels from either. Space only cancels: it is the key someone typing in
/// the terminal most often has on its way when a prompt takes focus, and it
/// is swallowed on Allow so the BUTTON cannot click on its release either.
/// A held key repeats into the prompt that just took focus, so a repeat
/// presses nothing.
fn confirmButtonKey(vk: WPARAM, repeat: bool, on_accept: bool) ?ConfirmKey {
    return switch (vk) {
        c.VK_ESCAPE => .cancel,
        c.VK_TAB, c.VK_LEFT, c.VK_RIGHT => .other_button,
        c.VK_RETURN => if (repeat) .ignore else if (on_accept) .accept else .cancel,
        c.VK_SPACE => if (repeat or on_accept) .ignore else .cancel,
        else => null,
    };
}

test "confirmButtonKey accepts only a fresh Enter on Allow" {
    try std.testing.expectEqual(@as(?ConfirmKey, .accept), confirmButtonKey(c.VK_RETURN, false, true));
    try std.testing.expectEqual(@as(?ConfirmKey, .ignore), confirmButtonKey(c.VK_RETURN, true, true));
    try std.testing.expectEqual(@as(?ConfirmKey, .ignore), confirmButtonKey(c.VK_SPACE, false, true));
    try std.testing.expectEqual(@as(?ConfirmKey, .ignore), confirmButtonKey(c.VK_SPACE, true, true));
    try std.testing.expectEqual(@as(?ConfirmKey, .cancel), confirmButtonKey(c.VK_RETURN, false, false));
    try std.testing.expectEqual(@as(?ConfirmKey, .cancel), confirmButtonKey(c.VK_SPACE, false, false));
    try std.testing.expectEqual(@as(?ConfirmKey, .ignore), confirmButtonKey(c.VK_SPACE, true, false));
    for ([_]bool{ false, true }) |on_accept| {
        try std.testing.expectEqual(@as(?ConfirmKey, .cancel), confirmButtonKey(c.VK_ESCAPE, true, on_accept));
        try std.testing.expectEqual(@as(?ConfirmKey, .other_button), confirmButtonKey(c.VK_TAB, false, on_accept));
        try std.testing.expectEqual(@as(?ConfirmKey, null), confirmButtonKey('A', false, on_accept));
    }
}

/// How long an `.info` banner stays up, in milliseconds: the system's
/// notification time (`SPI_GETMESSAGEDURATION`), which Settings offers from
/// 5 seconds to 5 minutes and defaults to 5.
pub fn bannerMessageDurationMs() UINT {
    var seconds: u32 = 0;
    if (sys.SystemParametersInfoW(c.SPI_GETMESSAGEDURATION, 0, @ptrCast(&seconds), 0) == 0) seconds = 0;
    return std.math.clamp(seconds, 5, 300) * std.time.ms_per_s;
}

/// False only in a `-Drenderer-test-tools` build started with
/// `NOCTTY_RENDERER_KEEP_NOTICES`. A countdown starts at the banner's first
/// paint, but a harness's UIA client can be slower than the countdown (a cold
/// runner's first call) and read the banner only after it is gone; the
/// renderer harness's OpenGL startup fallback case sets this switch so it can
/// read the banner.
pub fn infoBannersExpire() bool {
    return infoBannersExpireIn(build_config.renderer_test_tools);
}

/// `infoBannersExpire` for a build with or without test tools, so that the
/// default test build, which is what CI runs, checks both.
fn infoBannersExpireIn(comptime test_tools: bool) bool {
    if (!test_tools) return true;
    return !std.process.hasEnvVarConstant("NOCTTY_RENDERER_KEEP_NOTICES");
}

test "infoBannersExpire reads NOCTTY_RENDERER_KEEP_NOTICES only with test tools" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;
    const name = std.unicode.utf8ToUtf16LeStringLiteral("NOCTTY_RENDERER_KEEP_NOTICES");
    defer _ = windows.kernel32.SetEnvironmentVariableW(name, null);
    _ = windows.kernel32.SetEnvironmentVariableW(name, null);
    try std.testing.expect(infoBannersExpireIn(true));
    try std.testing.expect(infoBannersExpireIn(false));
    if (windows.kernel32.SetEnvironmentVariableW(name, std.unicode.utf8ToUtf16LeStringLiteral("1")) == 0) return lastError();
    try std.testing.expect(!infoBannersExpireIn(true));
    try std.testing.expect(infoBannersExpireIn(false));
    try std.testing.expectEqual(infoBannersExpireIn(build_config.renderer_test_tools), infoBannersExpire());
}

/// Mouse on a banner button, or null for a message it leaves alone. The
/// BUTTON class takes keyboard focus on a press. A banner button must not:
/// every click would pull focus, and the focus reports a program asked for,
/// off the terminal, and a press dragged off before the release would leave
/// focus on the button. So the press, capture and click are done here.
fn bannerButtonMouse(host: *Host, hwnd: HWND, button: BannerButton, msg: UINT, lParam: LPARAM) ?LRESULT {
    switch (msg) {
        c.WM_LBUTTONDOWN, c.WM_LBUTTONDBLCLK => {
            _ = sys.SetCapture(hwnd);
            _ = sys.SendMessageW(hwnd, c.BM_SETSTATE, 1, 0);
            return 0;
        },
        c.WM_LBUTTONUP => {
            if (sys.GetCapture() != hwnd) return 0;
            var client: RECT = undefined;
            const inside = sys.GetClientRect(hwnd, &client) != 0 and pointInRect(.{
                .x = signedLowWord(lParamBits(lParam)),
                .y = signedHighWord(lParamBits(lParam)),
            }, client);
            // `WM_CAPTURECHANGED` clears the pressed look.
            _ = sys.ReleaseCapture();
            // May destroy every window (Install): touch nothing after.
            if (inside) host.activateBannerButton(button);
            return 0;
        },
        c.WM_CAPTURECHANGED => {
            _ = sys.SendMessageW(hwnd, c.BM_SETSTATE, 0, 0);
            return 0;
        },
        else => return null,
    }
}

fn paintBannerClient(host: *Host, hwnd: HWND, hdc: HDC) void {
    var client: RECT = undefined;
    if (sys.GetClientRect(hwnd, &client) != 0) host.paintBanner(hdc, client, isHighContrastActive());
}

pub fn hostBannerProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    if (getHost(hwnd)) |host| {
        switch (msg) {
            c.WM_GETOBJECT => {
                if (host.banner_uia_provider) |provider| {
                    if (win32_uia.returnChromeControlProvider(hwnd, wParam, lParam, provider)) |lr| return lr;
                }
            },
            // Opaque, so it answers for its own rect, except where the
            // resize edges of a frameless window reach into it, as the
            // terminal pane does.
            c.WM_NCHITTEST => return if (host.resizesFrom(lParam)) c.HTTRANSPARENT else c.HTCLIENT,
            c.WM_SETCURSOR => {
                if ((lParamBits(lParam) & 0xFFFF) == c.HTCLIENT) {
                    _ = sys.SetCursor(sys.LoadCursorW(null, c.IDC_ARROW));
                    return 1;
                }
            },
            c.WM_ERASEBKGND => return 1,
            c.WM_PAINT => {
                {
                    var ps: PAINTSTRUCT = undefined;
                    const hdc = sys.BeginPaint(hwnd, &ps) orelse return 0;
                    defer _ = sys.EndPaint(hwnd, &ps);
                    paintBannerClient(host, hwnd, hdc);
                }
                host.bannerPainted();
                return 0;
            },
            c.WM_PRINTCLIENT => {
                paintBannerClient(host, hwnd, @ptrFromInt(wParam));
                return 0;
            },
            c.WM_MOUSEMOVE => {
                host.bannerPointerMoved();
                return 0;
            },
            c.WM_MOUSELEAVE => {
                host.bannerPointerLeft();
                return 0;
            },
            // The banner's buttons are its own children, so their owner
            // draw and their clicks (and UIA Invoke, which posts the same
            // command) come here.
            c.WM_DRAWITEM => {
                const draw: *const DRAWITEMSTRUCT = @ptrFromInt(@as(usize, @bitCast(lParam)));
                if (host.drawBannerButton(draw)) return 1;
            },
            c.WM_COMMAND => {
                const child: ?HWND = @ptrFromInt(@as(usize, @bitCast(lParam)));
                if (((wParam >> 16) & 0xFFFF) == c.BN_CLICKED) {
                    if (host.bannerButtonOf(child)) |button| {
                        host.activateBannerButton(button);
                        return 0;
                    }
                }
            },
            else => {},
        }
        if (host.banner_prev_proc) |previous| return sys.CallWindowProcW(previous, hwnd, msg, wParam, lParam);
    }
    return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
}

/// The UIA name for one confirm prompt line, from the text its control
/// was last given.
///
/// Reporting the control's own cached text rather than re-deriving it is
/// what keeps the spoken name and the drawn line the same string. Two
/// rules ride along, and both matter enough to be testable without a
/// live `Host`:
///
///   * Outside `.confirm` the control is hidden and still holds the
///     previous overlay's text. That is not a name any client should
///     read, so the answer is empty.
///   * A name that does not fit the caller's buffer is shortened on a
///     UTF-8 boundary, never dropped. `bufPrint` returns an error there
///     and the obvious `catch ""` would report nothing at the moment a
///     live region is about to be announced. The body can carry banner
///     text, which is arbitrary, so this is reachable.
fn confirmPromptUiaName(
    mode: HostOverlayMode,
    cached: ?[:0]const u8,
    buf: []u8,
    fallback: []const u8,
) []const u8 {
    if (mode != .confirm) return "";
    const text = cached orelse return "";
    return std.fmt.bufPrint(buf, "{s}", .{paint_text.utf8BoundedPrefix(text, buf.len)}) catch fallback;
}

/// Whether a confirm prompt line is rendered by its own child window
/// rather than by chrome paint.
///
/// Per line, never for the pair: the title's rect is bounded by the query
/// frame and collapses on a narrow window while the body's still has
/// room, so a shared gate would answer that by taking the body out of the
/// UI Automation tree as well. The HWND is checked alongside the
/// placement because reading the placement alone is correct only for as
/// long as `layout` keeps touching it exclusively inside its null check.
pub fn confirmPromptLineOwnedByChild(
    mode: HostOverlayMode,
    hwnd: ?HWND,
    placement: child_window.ChildPlacement,
) bool {
    if (mode != .confirm) return false;
    return hwnd != null and placement.visible;
}

/// Foreground for one confirm prompt line: the overlay label colour for
/// the title, and the banner-kind-sensitive secondary colour for the
/// body, which is what keeps an error raised while a prompt is open
/// reading as an error. Mirrors the colours the chrome paint fallback
/// picks for the same two lines.
pub fn confirmPromptLineColor(
    theme: *const ThemeColors,
    title: bool,
    banner_kind: HostBannerKind,
    has_banner: bool,
) u32 {
    if (title) return theme.overlay_label_fg;
    return switch (if (has_banner) banner_kind else .none) {
        .none => theme.text_secondary,
        .info => theme.info_fg,
        .err => theme.error_fg,
    };
}

/// Subclass for the confirm prompt's title and body STATICs.
///
/// Exists for `WM_GETOBJECT`: a stock STATIC hands UIA only the default
/// HWND provider, which reports ControlType Text but no live-region
/// setting, so the prompt would appear in the tree without ever being
/// announced. `HTTRANSPARENT` keeps the two lines from eating clicks
/// aimed at the overlay band underneath them.
fn overlayPromptTextProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    if (getHost(hwnd)) |host| {
        if (msg == c.WM_GETOBJECT) {
            if (host.overlayPromptTextProvider(hwnd)) |provider| {
                if (win32_uia.returnChromeControlProvider(hwnd, wParam, lParam, provider)) |lr| return lr;
            }
        }
        if (msg == c.WM_NCHITTEST) return c.HTTRANSPARENT;
        if (host.overlayPromptTextPrevProc(hwnd)) |previous| {
            return sys.CallWindowProcW(previous, hwnd, msg, wParam, lParam);
        }
    }
    return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
}

pub const ButtonTooltipAction = enum {
    none,
    show,
    /// Hide, and keep hidden until a `.hide` for the same button: the pointer
    /// leaving it, or the button being hidden or destroyed.
    dismiss,
    hide,
};

/// What a message to a `hostButtonProc` button does to the search buttons'
/// hover tooltip. Only a button with a name to show (a search button, [+] or
/// [v]; see `Host.chromeButtonTooltipName`) arms the hover that shows one, and
/// a hide is a no-op for a button whose tooltip is not up, so the proc's other
/// buttons need no case of their own.
pub fn buttonTooltipAction(msg: UINT, wParam: WPARAM) ButtonTooltipAction {
    return switch (msg) {
        c.WM_MOUSEHOVER => .show,
        // A click answers the question the tooltip was there for. Hiding it
        // is not enough: the BUTTON class releases a left click's capture on
        // the button-up, the system follows that with a WM_MOUSEMOVE even
        // when the pointer has not moved, and that re-arms the hover, which
        // would bring the tooltip back under a still pointer.
        c.WM_LBUTTONDOWN, c.WM_RBUTTONDOWN, c.WM_MBUTTONDOWN => .dismiss,
        c.WM_MOUSELEAVE => .hide,
        // A button hidden under a resting pointer (Escape closing the search
        // bar, a tab switch) sends no WM_MOUSELEAVE, so its tooltip would
        // outlive it. `ShowWindow(SW_HIDE)` does send this, whatever hid the
        // button.
        c.WM_SHOWWINDOW => if (wParam == 0) .hide else .none,
        // A pane closing while its window stays open destroys its search
        // buttons (`Surface.destroy` -> `destroySearchBarControls`) without
        // hiding them first. `windowDestroyed` clears the hovered button
        // afterwards, which takes the popup down too, since the popup is only
        // up for the hovered button; this drops it with the button instead.
        // Closing the window reaches here as well: each button's own window
        // data still names the Host, which outlives the buttons, and the
        // Host's WM_DESTROY has already destroyed the popup
        // (`destroyChildControls`), so hiding finds no popup to hide.
        c.WM_DESTROY => .hide,
        else => .none,
    };
}

pub fn hostButtonProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    const host = getHost(hwnd);
    if (host) |v| {
        if (msg == c.WM_NCHITTEST and v.resizesFromTop(lParam)) return c.HTTRANSPARENT;
        if (msg == c.WM_GETOBJECT) {
            if (v.chromeUiaProviderForHwnd(hwnd)) |provider| {
                if (win32_uia.returnChromeControlProvider(hwnd, wParam, lParam, provider)) |lr| return lr;
            }
            // The overlay accept / cancel pair. Their providers were
            // built in `ensureOverlayControls` and torn down with the
            // rest, but `overlayButtonUiaProviderForHwnd` had no caller,
            // so UIA only ever saw the default HWND provider: measured
            // with `AutomationElement.FindAll` on a live clipboard-paste
            // prompt, "Allow" and "Cancel" came back as ControlType Pane
            // with no Invoke pattern. Returning the provider makes them
            // announce as buttons and gives assistive technology a way
            // to press them.
            if (overlayButtonUiaProviderForHwnd(
                hwnd,
                v.overlay_accept_hwnd,
                v.overlay_cancel_hwnd,
                v.overlay_accept_uia_provider,
                v.overlay_cancel_uia_provider,
            )) |provider| {
                if (win32_uia.returnSettingsControlProvider(hwnd, wParam, lParam, provider)) |lr| return lr;
            }
        }
        if (msg == c.WM_KEYDOWN) v.noteChromeKeyInput(wParam);
        if (msg == c.WM_LBUTTONDOWN or msg == c.WM_RBUTTONDOWN or msg == c.WM_MBUTTONDOWN) {
            v.noteChromePointerInput();
        }
        if (v.bannerButtonOf(hwnd)) |button| {
            // May destroy every window (Install): touch nothing after.
            if (bannerButtonMouse(v, hwnd, button, msg, lParam)) |result| return result;
        }
        switch (v.button_tooltip.apply(buttonTooltipAction(msg, wParam), hwnd)) {
            .none => {},
            .present => v.showChromeButtonTooltip(hwnd),
            .hide => v.hideTabTooltip(),
        }
        // Focus-region keys for the tab-strip action buttons and the
        // docked search controls. Overlay buttons are deliberately
        // excluded: they belong to a modal overlay, not to the window's
        // focus-region cycle.
        if (msg == c.WM_KEYDOWN) {
            if (v.bannerButtonOf(hwnd)) |button| {
                // May destroy every window (Install): touch nothing after.
                if (v.handleBannerButtonKey(hwnd, button, wParam, lParam)) return 0;
            }
        }
        if (msg == c.WM_KEYDOWN and !v.isOverlayButton(hwnd)) {
            // The docked search buttons already own Escape (it dismisses
            // the search), so only Ctrl+F6 is taken from them here.
            const allow_escape = v.searchControlSurface(hwnd) == null;
            if (v.handleFocusRegionKey(hwnd, wParam, allow_escape)) return 0;
        }
        // Keyboard routing for the overlay accept/cancel pair. In
        // confirm mode the EDIT control is hidden and focus lands on
        // the accept button; without this path Esc has no effect
        // because `overlayEditProc`'s Esc handler only runs when the
        // (hidden) EDIT has focus. Tab/Shift+Tab cycle between the
        // two buttons; arrow keys also cycle for screen-reader
        // users who navigate via arrows.
        if (msg == c.WM_KEYDOWN and v.isOverlayButton(hwnd)) {
            const reverse = if (wParam == c.VK_TAB) keyPressed(c.VK_SHIFT) else wParam == c.VK_LEFT;
            if (v.overlay_mode == .confirm) {
                const repeat = (lParamBits(lParam) & c.KF_REPEAT) != 0;
                const action = confirmButtonKey(wParam, repeat, hwnd == v.overlay_accept_hwnd);
                if (action != ConfirmKey.accept) v.holdProgramConfirmForKey(wParam);
                if (action) |key| {
                    switch (key) {
                        .accept => v.invokeConfirmAccept(),
                        .cancel => v.invokeConfirmCancel(),
                        .other_button => _ = v.focusRelativeOverlayControl(hwnd, reverse),
                        .ignore => {},
                    }
                    return 0;
                }
            } else switch (wParam) {
                c.VK_ESCAPE => {
                    v.hideOverlay();
                    return 0;
                },
                c.VK_TAB, c.VK_LEFT, c.VK_RIGHT => {
                    _ = v.focusRelativeOverlayControl(hwnd, reverse);
                    return 0;
                },
                else => {},
            }
        }
        // Enter and Tab on [+], [v] and the docked search buttons. May
        // click, so touch nothing after it.
        if (msg == c.WM_KEYDOWN and !v.isOverlayButton(hwnd) and v.bannerButtonOf(hwnd) == null) {
            if (v.handleChromeButtonKey(hwnd, wParam, chromeKeyMods(), lParam)) return 0;
        }
        if (search_controls.searchButtonKey(v, hwnd, msg, wParam, lParam)) |result| return result;
        switch (msg) {
            c.WM_SETFOCUS => {
                if (v.bannerButtonOf(hwnd) != null) {
                    v.banner_focused = true;
                    v.syncBannerExpiry();
                }
                if (v.searchControlSurface(hwnd)) |surface| {
                    v.app.activateSurfaceNoFocus(surface);
                }
                if (v.chromeUiaProviderForHwnd(hwnd)) |provider| {
                    provider.raiseFocusChanged();
                }
            },
            c.WM_KILLFOCUS => {
                if (v.bannerButtonOf(hwnd) != null) {
                    v.banner_focused = false;
                    v.syncBannerExpiry();
                }
                if (v.searchControlSurface(hwnd)) |surface| surface.search_toggle_keys = .{};
            },
            c.WM_MOUSEMOVE => {
                // The search bar's icon buttons and the tab strip's [+] and
                // [v] also arm TME_HOVER, as the tab buttons do for their
                // title tooltip, so a dwell names them.
                const named_button = v.chromeButtonTooltipName(hwnd) != null;
                var track: TRACKMOUSEEVENT = .{
                    .cbSize = @sizeOf(TRACKMOUSEEVENT),
                    .dwFlags = if (named_button) c.TME_LEAVE | c.TME_HOVER else c.TME_LEAVE,
                    .hwndTrack = hwnd,
                    .dwHoverTime = if (named_button) c.HOVER_DEFAULT else 0,
                };
                _ = sys.TrackMouseEvent(&track);
                v.setHoveredButton(hwnd);
            },
            c.WM_MOUSELEAVE => {
                if (v.isHoveredButton(hwnd)) v.setHoveredButton(null);
            },
            c.WM_RBUTTONUP => {
                if (v.new_tab_hwnd != null and hwnd == v.new_tab_hwnd.?) {
                    if (v.openSelectedProfileOrFallback(.window)) return 0;
                }
            },
            c.WM_MBUTTONUP => {
                if (v.new_tab_hwnd != null and hwnd == v.new_tab_hwnd.?) {
                    if (v.openSelectedProfileOrFallback(.split)) return 0;
                }
            },
            else => {},
        }

        const prev = if (v.isOverlayButton(hwnd))
            v.overlay_button_prev_proc
        else if (v.searchControlSurface(hwnd)) |surface|
            surface.searchBarButtonPrevProc(hwnd)
        else
            v.chrome_button_prev_proc;
        if (prev) |proc| {
            return sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
        }
    }
    return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
}

pub fn tabButtonProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    const host = getHost(hwnd);
    if (host) |v| {
        if (msg == c.WM_NCHITTEST and v.resizesFromTop(lParam)) return c.HTTRANSPARENT;
        if (v.tabIndexForButton(hwnd)) |index| {
            if (msg == c.WM_GETOBJECT) {
                if (v.tabs.items[index].uia_provider) |provider| {
                    if (win32_uia.returnChromeControlProvider(hwnd, wParam, lParam, provider)) |lr| return lr;
                }
            }
            switch (msg) {
                win32_uia.widgets.tab_close_message => {
                    // Revalidate closability after Invoke waited in the queue:
                    // the tab may have moved, scrolled out, or become hidden.
                    if (tabCloseAction(v.tabs.items.len) != .none and v.tabs.items[index].id == wParam and
                        v.shouldShowTabBar() and sys.IsWindowVisible(hwnd) != 0)
                    {
                        _ = v.closeTabFromStrip(index);
                    }
                    return 0;
                },
                c.WM_SETFOCUS => {
                    if (v.tabs.items[index].uia_provider) |provider| {
                        provider.raiseFocusChanged();
                    }
                },
                c.WM_LBUTTONDOWN => {
                    v.noteChromePointerInput();
                    // A click answers the question the tooltip was there to
                    // answer, and the strip is about to relayout under it.
                    v.hideTabTooltip();
                    const down_x = signedLowWord(lParamBits(lParam));
                    const down_y = signedHighWord(lParamBits(lParam));
                    var btn_rect: RECT = undefined;
                    _ = sys.GetClientRect(hwnd, &btn_rect);
                    const close_left = btn_rect.right - v.scaled(host_tab_close_zone_width);
                    if (tabButtonCloseHit(down_x, down_y, close_left, v.tabContentTopInset()) and tabCloseAction(v.tabs.items.len) != .none) {
                        // Click in close zone — capture for mouseup but don't start drag
                        _ = sys.SetCapture(hwnd);
                    } else {
                        // Start potential drag: record origin
                        v.tab_drag_index = index;
                        v.tab_drag_start_x = down_x;
                        v.tab_drag_start_y = down_y;
                        v.tab_drag_active = false;
                        _ = sys.SetCapture(hwnd);
                    }
                    return 0;
                },
                c.WM_LBUTTONUP => {
                    const drag_index = v.tab_drag_index;
                    const was_drag = v.tab_drag_active;
                    const drop_operation = v.tab_drop_operation;
                    const drop_target_surface = v.tab_drop_target_surface;
                    v.tab_drag_index = null;
                    v.tab_drag_active = false;
                    _ = sys.ReleaseCapture();
                    if (was_drag) {
                        if (drag_index) |source_index| {
                            v.tab_drop_operation = drop_operation;
                            v.tab_drop_target_surface = drop_target_surface;
                            const transferred = v.commitTabDropSplit(source_index);
                            v.hideTabDropPreview();
                            if (transferred) return 0;
                        }
                    }
                    v.hideTabDropPreview();
                    const click_x = signedLowWord(lParamBits(lParam));
                    var btn_rect: RECT = undefined;
                    _ = sys.GetClientRect(hwnd, &btn_rect);
                    const close_left = btn_rect.right - v.scaled(host_tab_close_zone_width);
                    switch (tabButtonMouseUpAction(
                        drag_index,
                        was_drag,
                        click_x,
                        signedHighWord(lParamBits(lParam)),
                        close_left,
                        v.tabContentTopInset(),
                        v.tabs.items.len,
                    )) {
                        .activate => {
                            _ = v.activateTabIndex(index);
                        },
                        .close => _ = v.closeTabFromStrip(index),
                        .none => {},
                    }
                    return 0;
                },
                c.WM_CAPTURECHANGED => {
                    v.tab_drag_index = null;
                    v.tab_drag_active = false;
                    v.hideTabDropPreview();
                },
                c.WM_MOUSEMOVE => {
                    // TME_HOVER arms WM_MOUSEHOVER for the title tooltip. The
                    // timer restarts on every move, so it only fires once the
                    // pointer has actually settled on the tab.
                    var track: TRACKMOUSEEVENT = .{
                        .cbSize = @sizeOf(TRACKMOUSEEVENT),
                        .dwFlags = c.TME_LEAVE | c.TME_HOVER,
                        .hwndTrack = hwnd,
                        .dwHoverTime = c.HOVER_DEFAULT,
                    };
                    _ = sys.TrackMouseEvent(&track);
                    v.setHoveredButton(hwnd);

                    // Handle tab drag reorder
                    if (v.tab_drag_index) |drag_idx| {
                        const mouse_x = signedLowWord(lParamBits(lParam));
                        const mouse_y = signedHighWord(lParamBits(lParam));
                        const dx = if (mouse_x > v.tab_drag_start_x)
                            mouse_x - v.tab_drag_start_x
                        else
                            v.tab_drag_start_x - mouse_x;
                        const dy = if (mouse_y > v.tab_drag_start_y)
                            mouse_y - v.tab_drag_start_y
                        else
                            v.tab_drag_start_y - mouse_y;

                        if (!v.tab_drag_active and win32_input.tabDragThresholdExceeded(
                            dx,
                            dy,
                            sys.GetSystemMetricsForDpi(c.SM_CXDRAG, v.current_dpi),
                            sys.GetSystemMetricsForDpi(c.SM_CYDRAG, v.current_dpi),
                        )) {
                            v.tab_drag_active = true;
                            v.hideTabTooltip();
                        }

                        if (v.tab_drag_active) {
                            // A vertical excursion resolves an exact pane and
                            // labeled split operation. Staying in the tab row
                            // keeps the established ordered-reorder gesture.
                            var pt: POINT = .{ .x = mouse_x, .y = mouse_y };
                            _ = sys.ClientToScreen(hwnd, &pt);
                            v.updateTabDropPreview(drag_idx, pt);
                            if (v.tab_drop_operation == .none) {
                                if (v.tabIndexAtScreenX(pt.x)) |target_idx| {
                                    if (target_idx != drag_idx and v.tabs.items.len > 1) {
                                        v.swapTabs(drag_idx, target_idx);
                                        v.tab_drag_index = target_idx;
                                        v.tab_drag_start_x = mouse_x;
                                        v.tab_drag_start_y = mouse_y;
                                    }
                                }
                            }
                        }
                    }
                },
                c.WM_MOUSEHOVER => {
                    v.showTabTooltip(hwnd);
                },
                c.WM_MOUSELEAVE => {
                    v.hideTabTooltip();
                    if (v.isHoveredButton(hwnd)) v.setHoveredButton(null);
                },
                c.WM_KEYDOWN => {
                    v.noteChromeKeyInput(wParam);
                    if (v.handleFocusRegionKey(hwnd, wParam, true)) return 0;
                    if (tabButtonKeyAction(wParam, chromeKeyMods())) |action| {
                        switch (action) {
                            // The menu key opens the same menu a right click
                            // does, on this tab, and its release is swallowed
                            // below. `v` may be gone when it returns.
                            .context_menu => {
                                if ((lParamBits(lParam) & c.KF_REPEAT) == 0 and
                                    v.showTabContextMenu(hwnd, index, .keyboard)) return 0;
                            },
                            // Tab only moves focus along the strip; Enter,
                            // Space and the arrows are what activate.
                            .focus_next, .focus_previous => {
                                _ = v.stepTabStripFocus(hwnd, action == .focus_previous);
                                return 0;
                            },
                            // Activating a tab moves focus into its
                            // terminal, which is what Enter on a tab
                            // should do. Arrow/Home/End navigation must
                            // not: it activates as it moves, so focus is
                            // pulled back to the strip afterwards or the
                            // next arrow press would go to the PTY.
                            .activate => {
                                _ = v.activateTabIndex(index);
                                return 0;
                            },
                            .previous => {
                                _ = v.activateTabByDirection(.previous);
                                v.restoreTabStripFocus();
                                return 0;
                            },
                            .next => {
                                _ = v.activateTabByDirection(.next);
                                v.restoreTabStripFocus();
                                return 0;
                            },
                            .first => {
                                _ = v.activateTabByDirection(@enumFromInt(1));
                                v.restoreTabStripFocus();
                                return 0;
                            },
                            .last => {
                                _ = v.activateTabByDirection(.last);
                                v.restoreTabStripFocus();
                                return 0;
                            },
                            .move_previous => {
                                if (v.activateTabIndex(index)) {
                                    if (v.activeSurface()) |surface| {
                                        runUiActionOrLog("tab key move previous failed", v.app.moveTab(.{ .surface = surface.core() }, .{ .amount = -1 }));
                                        return 0;
                                    }
                                }
                            },
                            .move_next => {
                                if (v.activateTabIndex(index)) {
                                    if (v.activeSurface()) |surface| {
                                        runUiActionOrLog("tab key move next failed", v.app.moveTab(.{ .surface = surface.core() }, .{ .amount = 1 }));
                                        return 0;
                                    }
                                }
                            },
                            .move_first => {
                                if (v.activateTabIndex(index)) {
                                    if (v.activeSurface()) |surface| {
                                        const amount = moveTabAmountToEdge(v.tabs.items.len, index, true);
                                        if (amount != 0) {
                                            runUiActionOrLog("tab key move first failed", v.app.moveTab(.{ .surface = surface.core() }, .{ .amount = amount }));
                                        }
                                        return 0;
                                    }
                                }
                            },
                            .move_last => {
                                if (v.activateTabIndex(index)) {
                                    if (v.activeSurface()) |surface| {
                                        const amount = moveTabAmountToEdge(v.tabs.items.len, index, false);
                                        if (amount != 0) {
                                            runUiActionOrLog("tab key move last failed", v.app.moveTab(.{ .surface = surface.core() }, .{ .amount = amount }));
                                        }
                                        return 0;
                                    }
                                }
                            },
                            .rename => {
                                if (v.activateTabIndex(index)) {
                                    if (v.activeSurface()) |surface| {
                                        runUiActionOrLog("tab key rename failed", surface.promptTitle(.tab));
                                        return 0;
                                    }
                                }
                            },
                            .close => {
                                if (v.closeTabFromStrip(index)) return 0;
                            },
                        }
                    }
                },
                // Shift+F10 is a system key, so it arrives here and not as a
                // WM_KEYDOWN. Plain F10 stays with the window.
                c.WM_SYSKEYDOWN => {
                    if (wParam == c.VK_F10 and tabButtonKeyAction(wParam, chromeKeyMods()) == .context_menu) {
                        v.noteChromeKeyInput(c.VK_APPS);
                        if ((lParamBits(lParam) & c.KF_REPEAT) == 0 and
                            v.showTabContextMenu(hwnd, index, .keyboard)) return 0;
                    }
                },
                // Without these, `DefWindowProc` posts a second
                // WM_CONTEXTMENU when the key comes back up.
                c.WM_KEYUP, c.WM_SYSKEYUP => {
                    if (labels.tabButtonSwallowsKeyUp(wParam, chromeKeyMods())) return 0;
                },
                // The keyboard form (-1, -1) was served on the key-down. A
                // right click opens the menu from WM_RBUTTONUP and never
                // gets here.
                c.WM_CONTEXTMENU => {
                    if (signedLowWord(lParamBits(lParam)) == -1 and signedHighWord(lParamBits(lParam)) == -1) return 0;
                },
                c.WM_MBUTTONUP => {
                    if (v.closeTabFromStrip(index)) return 0;
                },
                c.WM_LBUTTONDBLCLK => {
                    if (v.activateTabIndex(index)) {
                        if (v.activeSurface()) |surface| {
                            runUiActionOrLog("tab double-click rename failed", surface.promptTitle(.tab));
                            return 0;
                        }
                    }
                },
                c.WM_RBUTTONUP => {
                    if (v.showTabContextMenu(hwnd, index, .pointer)) return 0;
                },
                else => {},
            }

            if (v.tabs.items[index].button_prev_proc) |proc| {
                return sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
            }
        }
    }
    return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
}

fn overlayEditProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    const host = getHost(hwnd);
    // This proc is shared with the confirm preview pane, which is the
    // same EDIT class but a different control. The UIA provider below
    // belongs to the query field alone; handing it out for the preview
    // would report one control's name and selection for the other.
    const is_query_edit = if (host) |v|
        v.overlay_edit_hwnd != null and hwnd == v.overlay_edit_hwnd.?
    else
        false;
    if (msg == c.WM_GETOBJECT) {
        if (host) |v| {
            if (is_query_edit) {
                if (v.overlay_edit_uia_provider) |provider| {
                    if (win32_uia.returnTerminalProvider(hwnd, wParam, lParam, provider)) |lr| return lr;
                }
            } else if (v.overlay_preview_uia_provider) |provider| {
                if (win32_uia.returnSettingsControlProvider(hwnd, wParam, lParam, provider)) |lr| return lr;
            }
        }
    }
    if (host) |v| switch (msg) {
        c.WM_LBUTTONDOWN => v.noteChromePointerInput(),
        c.WM_CHAR => {
            if (wParam == c.VK_ESCAPE) return 0;
            if (wParam == c.VK_RETURN) {
                // The confirm preview pane accepts on Enter too, but not on
                // a held one (see `confirmButtonKey`), and never a
                // program's prompt: Tab from its Cancel lands here, and
                // Tab then Enter is how someone finishes typing a command.
                const repeat = (lParamBits(lParam) & c.KF_REPEAT) != 0;
                if (v.overlay_mode == .confirm and (repeat or v.programConfirmOpen())) return 0;
                if (v.overlay_mode != .profile) {
                    runUiActionOrLog("overlay submit failed", v.submitOverlay());
                }
                return 0;
            }
        },

        c.WM_KEYDOWN, c.WM_SYSKEYDOWN => {
            // Tab out of the query is how the keyboard reaches the Close
            // button; it has to show its ring when it gets there.
            v.noteChromeKeyInput(wParam);
            if (v.overlay_mode == .confirm) v.holdProgramConfirmForKey(wParam);
            if (v.commandPaletteToggleKeyMessage(msg, wParam, lParam)) {
                _ = v.dismissCommandPalette();
                return 0;
            }
            if (v.overlay_mode == .command_palette) {
                if (wParam == c.VK_UP or wParam == c.VK_DOWN) {
                    // Up/Down move through the live result list instead of
                    // editing the query text.
                    if (v.moveListSelection(wParam == c.VK_UP)) return 0;
                }
                if (wParam == c.VK_TAB) {
                    const reverse = keyPressed(c.VK_SHIFT);
                    if ((v.completeCommandPalette(reverse) catch false)) return 0;
                }
            }
            if (wParam == c.VK_TAB and v.focusRelativeOverlayControl(hwnd, keyPressed(c.VK_SHIFT))) return 0;
            if (v.overlay_mode == .tab_overview) {
                if (wParam == c.VK_UP or wParam == c.VK_DOWN) {
                    if ((v.stepTabOverviewSelection(wParam == c.VK_UP) catch false)) return 0;
                }
            }
            if (v.overlay_mode == .profile) {
                const profiles_ready = v.profilesForChrome();
                if (profiles_ready) {
                    if (clearQuickSlotPinsRequested(wParam, keyPressed(c.VK_MENU), keyPressed(c.VK_SHIFT))) {
                        if (v.clearQuickSlotPins()) return 0;
                    }
                    if (quickSlotPinOrdinalFromKey(wParam, keyPressed(c.VK_MENU), keyPressed(c.VK_SHIFT))) |slot_ordinal| {
                        if (v.assignSelectedProfileToQuickSlot(slot_ordinal)) return 0;
                    }
                    if (quickSlotShortcutProfileIndex(v.shownProfiles().?.len, v.selectedProfileIndex(), wParam, keyPressed(c.VK_MENU))) |index| {
                        if (v.quickOpenProfileIndex(index, v.app.launcher_profile_target)) return 0;
                    }
                }
                if (keyPressed(c.VK_CONTROL)) {
                    if (profileShortcutIndexFromKey(wParam)) |index| {
                        if (v.quickOpenProfileIndex(index, v.app.launcher_profile_target)) return 0;
                    }
                }
                if (wParam == c.VK_RETURN) {
                    runUiActionOrLog(
                        "profile overlay submit failed",
                        v.submitProfileOverlay(resolveProfileOpenTarget(
                            v.app.launcher_profile_target,
                            keyPressed(c.VK_SHIFT),
                            keyPressed(c.VK_CONTROL),
                        )),
                    );
                    return 0;
                }
                if (wParam == c.VK_UP or wParam == c.VK_DOWN) {
                    if ((v.stepProfileSelection(wParam == c.VK_UP) catch false)) return 0;
                }
            }
            if (wParam == c.VK_ESCAPE) {
                if (v.overlay_mode == .confirm) {
                    // Same no-access-after-dispatch discipline as
                    // the mouse-click confirm paths — cancel
                    // callbacks may tear down the Host.
                    v.invokeConfirmCancel();
                    return 0;
                }
                v.hideOverlay();
                runUiActionOrLog("overlay escape layout failed", v.layout());
                refocusActiveSurface(v);
                return 0;
            }
        },

        else => {},
    };

    const result = if (host) |v| blk: {
        const saved = if (is_query_edit) v.overlay_edit_prev_proc else v.overlay_preview_prev_proc;
        if (saved) |proc| {
            break :blk sys.CallWindowProcW(proc, hwnd, msg, wParam, lParam);
        }
        break :blk sys.DefWindowProcW(hwnd, msg, wParam, lParam);
    } else sys.DefWindowProcW(hwnd, msg, wParam, lParam);
    if (is_query_edit) {
        if (host) |v| {
            if (v.overlay_edit_uia_provider) |provider| switch (msg) {
                c.WM_SETFOCUS => win32_uia.events.raiseFocusChanged(&provider.base),
                c.WM_KEYUP, c.WM_LBUTTONUP, c.EM_SETSEL => v.raiseOverlayEditSelectionChangedIfNeeded(),
                else => {},
            };
        }
    }
    return result;
}

pub fn applyConsoleWindowVisibility(hwnd: HWND, visible: bool) void {
    if (visible) {
        if (sys.IsIconic(hwnd) == 0) return;
        _ = sys.DefWindowProcW(hwnd, c.WM_SYSCOMMAND, c.SC_RESTORE, 0);
    } else {
        if (sys.IsIconic(hwnd) != 0) return;
        _ = sys.DefWindowProcW(hwnd, c.WM_SYSCOMMAND, c.SC_MINIMIZE, 0);
    }
}

pub fn hostWindowProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    if (msg == c.WM_NCCREATE) {
        const cs: *const CREATESTRUCTW = @ptrFromInt(@as(usize, @bitCast(lParam)));
        if (cs.lpCreateParams) |ptr| {
            setWindowData(hwnd, ptr);
        }
    }

    const host = getHost(hwnd);
    switch (msg) {
        c.WM_WINHOSTTY_CONSOLE_VISIBILITY => {
            if (host != null) applyConsoleWindowVisibility(hwnd, wParam != 0);
            return 0;
        },
        c.WM_WINHOSTTY_HOST_NEW_TAB => {
            if (host) |v| v.dispatchDeferredNewTab(if (wParam == 0) null else @as(u64, @intCast(wParam)));
            return 0;
        },
        c.WM_NCACTIVATE => {
            if (host) |v| {
                v.setWindowActive(wParam != 0);
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_ACTIVATE => {
            // Cloak/uncloak (virtual-desktop switches, shell animations)
            // has NO window message -- the documented signal is the
            // EVENT_OBJECT_CLOAKED/UNCLOAKED WinEvent, which
            // `win32_power.Notifications` now hooks. This refresh is the
            // belt-and-braces path for a missed or unavailable hook: a
            // cloaked host renders nothing, so a stale `surfaces_visible`
            // would otherwise mean a permanently frozen window.
            if (host) |v| {
                v.refreshSurfaceVisibility();
                if ((wParam & 0xFFFF) != c.WA_INACTIVE) {
                    v.app.activations += 1;
                    v.activated = v.app.activations;
                    // The user brought this window forward: its active tab is
                    // seen even if focus lands on the chrome, not a terminal.
                    v.app.acknowledgeTab(v, v.active_tab);
                } else {
                    // The tab tooltip is a top-level popup, so losing the
                    // window is not enough to take it down: a pointer that
                    // never left the tab sends no WM_MOUSELEAVE, and the popup
                    // would sit over whatever the user switched to.
                    v.hideTabTooltip();
                    quick_terminal_host.autohideQuickTerminal(v, hwnd);
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        // Per-host tween heartbeat. Runs at ~16 ms while any chrome
        // animation is active; stops as soon as the scheduler empties.
        // Separate from the App-level quit timer, which uses
        // `sys.SetTimer(null, …)` on the thread queue.
        c.WM_TIMER => {
            if (wParam == c.TWEEN_TIMER_ID) {
                if (host) |v| v.tickTweens();
                return 0;
            }
            if (wParam == c.SEARCH_TIMER_ID) {
                if (host) |v| v.tickSearchBars();
                return 0;
            }
            if (wParam == c.SCROLLBAR_TIMER_ID) {
                if (host) |v| v.tickScrollbars();
                return 0;
            }
            if (wParam == c.RESIZE_SETTLE_TIMER_ID) {
                if (host) |v| v.tickResizeSettleRepaint();
                return 0;
            }
            if (wParam == c.BANNER_TIMER_ID) {
                if (host) |v| v.bannerExpiryTick();
                return 0;
            }
            if (wParam == c.INPUT_MODE_TIMER_ID) {
                _ = sys.KillTimer(hwnd, c.INPUT_MODE_TIMER_ID);
                if (host) |v| {
                    v.mode_timer_active = false;
                    runUiActionOrLog("input mode timer failed", v.refreshModeIndicator());
                }
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_DRAWITEM => {
            if (host) |v| {
                const draw: *const DRAWITEMSTRUCT = @ptrFromInt(@as(usize, @bitCast(lParam)));
                if (v.drawConfirmPromptText(draw)) return 1;
                if (v.drawSearchBarBackground(draw)) return 1;
                v.drawButton(draw);
                return 1;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_ERASEBKGND => return 1,
        // Integrated-titlebar non-client handlers. All gated on the
        // host actively using the integrated titlebar (Win11 build /
        // config gate + visible tab/caption row); otherwise they fall
        // through to DefWindowProcW and the system paints its default
        // caption.
        c.WM_NCCALCSIZE => {
            if (host) |v| {
                if (v.handleNcCalcSize(hwnd, wParam, lParam)) |lr| return lr;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_NCHITTEST => {
            if (host) |v| {
                if (v.usingIntegratedTitlebar()) {
                    if (dispatchDwmNcMessage(hwnd, msg, wParam, lParam)) |lr| return lr;
                }
                if (v.handleNcHitTest(hwnd, lParam)) |lr| return lr;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_NCMOUSEMOVE => {
            if (host) |v| {
                if (v.handleNcMouseMove(hwnd, wParam)) |lr| return lr;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_NCMOUSELEAVE => {
            if (host) |v| {
                const dwm_result = if (v.usingIntegratedTitlebar())
                    dispatchDwmNcMessage(hwnd, msg, wParam, lParam)
                else
                    null;
                v.handleNcMouseLeave();
                if (dwm_result) |lr| return lr;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        // Integrated-titlebar caption-button click dispatch. The
        // custom NC frame still returns HTMINBUTTON / HTMAXBUTTON for
        // shell affordances such as Snap Layout hover, but it cannot
        // rely on DefWindowProc owning the full caption-button mouse
        // loop once WM_NCCALCSIZE has removed the top NC margin.
        c.WM_NCLBUTTONDOWN => {
            if (host) |v| {
                if (v.usingIntegratedTitlebar()) {
                    const ht: i32 = @intCast(@as(i64, @bitCast(wParam)));
                    v.caption_pressed = titlebarCaptionFromHitTest(ht);
                    if (v.caption_pressed != .none) v.repaintTopChrome();
                    if (captionButtonSysCommand(ht, sys.IsZoomed(hwnd) != 0)) |cmd| {
                        v.clearCaptionPressed();
                        _ = sys.SendMessageW(hwnd, c.WM_SYSCOMMAND, cmd, lParam);
                        return 0;
                    }
                    if (ht == c.HTCLOSE) return 0;
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_NCLBUTTONUP => {
            if (host) |v| {
                if (v.usingIntegratedTitlebar()) {
                    if (dispatchDwmNcMessage(hwnd, msg, wParam, lParam)) |lr| return lr;
                    const ht: i32 = @intCast(@as(i64, @bitCast(wParam)));
                    if (captionButtonSysCommand(ht, sys.IsZoomed(hwnd) != 0) != null) {
                        v.clearCaptionPressed();
                        return 0;
                    }
                    switch (ht) {
                        c.HTCLOSE => {
                            v.clearCaptionPressed();
                            _ = sys.SendMessageW(hwnd, c.WM_SYSCOMMAND, c.SC_CLOSE, lParam);
                            return 0;
                        },
                        else => v.clearCaptionPressed(),
                    }
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        // Right-click on the integrated titlebar's empty strip or on an
        // undecorated window's tab strip: the window menu, as on a stock
        // caption. See `captionRightClick`. No DwmDefWindowProc first:
        // only HTCAPTION is handled here, and every other code, the
        // caption buttons included, goes to DefWindowProc as before.
        c.WM_NCRBUTTONDOWN, c.WM_NCRBUTTONDBLCLK, c.WM_NCRBUTTONUP => {
            if (host) |v| {
                const ht: i32 = @intCast(@as(i64, @bitCast(wParam)));
                if (captionRightClick(msg, ht, v.clientCaptionHeight())) |action| {
                    if (action == .open_menu) openWindowMenuAt(hwnd, lParam);
                    return 0;
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_WINHOSTTY_UIA_CAPTION_SYNC => {
            if (host) |v| v.syncCaptionUiaState();
            return 0;
        },
        // UIA root object request. Screen readers (Narrator, NVDA) call
        // `AccessibleObjectFromWindow` which turns into WM_GETOBJECT on
        // the target HWND. We only handle the UIA root-object ID; MSAA
        // and other IDs fall through to the default proc.
        c.WM_GETOBJECT => {
            if (host) |v| {
                const provider = v.root_uia_provider orelse provider: {
                    const created = win32_uia.RootProvider.create(
                        std.heap.page_allocator,
                        hwnd,
                    ) catch |err| {
                        log.warn("uia: root provider init failed err={}", .{err});
                        return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
                    };
                    created.setCaptionButtons(v.captionButtonsUiaState());
                    v.root_uia_provider = created;
                    break :provider created;
                };
                if (win32_uia.returnRootProvider(hwnd, wParam, lParam, provider)) |lr| return lr;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_SETTINGCHANGE => {
            if (host) |v| {
                v.app.refreshSystemWheelSettings();
                v.app.refreshSystemScrollbarPreference();
                if (settingChangeAffectsTheme(lParam)) v.app.reconfigureSystemTheme();
                if (settingChangeIsImmersiveColorSet(lParam)) {
                    v.app.syncSystemColorScheme() catch |err| {
                        log.warn("win32 color scheme sync failed err={}", .{err});
                    };
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_THEMECHANGED, c.WM_SYSCOLORCHANGE => {
            if (host) |v| {
                v.app.reconfigureSystemTheme();
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_GETDPISCALEDSIZE => {
            // Sent before the resize Windows makes for a DPI change, which
            // then reaches us ahead of `WM_DPICHANGED` (measured in real
            // drags). Hold the terminals' grid from here; see
            // `dpi_change_pending`. FALSE keeps Windows' linear scaling.
            if (host) |v| v.dpi_change_pending = true;
            return 0;
        },
        c.WM_DPICHANGED => {
            if (host) |v| {
                // Also held when no `WM_GETDPISCALEDSIZE` came first.
                v.dpi_change_pending = true;
                const new_dpi = sys.GetDpiForWindow(hwnd);
                if (new_dpi > 0) v.current_dpi = new_dpi;
                v.recreateChromeFont();

                // QT placement/tween frames own their physical-pixel rect.
                // Keep scale and layout updates even when the OS's resized
                // suggestion would override that rect on a DPI crossing.
                // SWP_FRAMECHANGED either way: in a drag across monitors
                // Windows resizes the window before this message, so
                // `WM_NCCALCSIZE` laid the frame out at the old DPI (22x11 px,
                // 144 DPI's, on a 96 DPI monitor whose frame is 16x8), and the
                // suggestion is that same rect. Without a fresh layout the
                // client stayed that far off, and the configured grid size
                // resized from the stale frame.
                const flags = c.SWP_NOZORDER | c.SWP_NOACTIVATE | c.SWP_FRAMECHANGED;
                if (!v.quick_terminal_placing and !v.restore_placing and v.quick_terminal_animation == null) {
                    const suggested: *const RECT = @ptrFromInt(@as(usize, @bitCast(lParam)));
                    _ = sys.SetWindowPos(hwnd, null, suggested.left, suggested.top, suggested.right - suggested.left, suggested.bottom - suggested.top, flags);
                } else {
                    _ = sys.SetWindowPos(hwnd, null, 0, 0, 0, 0, flags | c.SWP_NOMOVE | c.SWP_NOSIZE);
                }

                // Lay the children out while still held (a frame change
                // need not send WM_SIZE), then each terminal takes its new
                // font and settled size as one resize. Building a font can
                // outlast termio's 25 ms resize coalescing, so a size sent
                // ahead of it was laid out in the old font.
                runUiActionOrLog("DPI update layout failed", v.layout());
                v.applyDpiChangeToVisibleSurfaces();
                v.dpi_change_pending = false;
                v.syncVisibleSurfaceCoreSizesFromClientRects();
                v.app.resizeShellCompositorWindow(hwnd);
                v.invalidateTopChromeText();
            }
            return 0;
        },
        c.WM_CTLCOLOREDIT, c.WM_CTLCOLORSTATIC, c.WM_CTLCOLORBTN => {
            if (host) |v| {
                v.ensureThemeBrushes() catch return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
                const hdc: HDC = @ptrFromInt(@as(usize, @intCast(wParam)));
                const child: HWND = @ptrFromInt(@as(usize, @intCast(lParam)));
                switch (msg) {
                    c.WM_CTLCOLOREDIT => {
                        _ = sys.SetBkMode(hdc, c.OPAQUE);
                        _ = sys.SetBkColor(hdc, v.app.resolved_theme.edit_bg);
                        _ = sys.SetTextColor(hdc, v.app.resolved_theme.edit_fg);
                        return @as(LRESULT, @bitCast(@as(usize, @intFromPtr(v.edit_brush.?))));
                    },
                    c.WM_CTLCOLORSTATIC => {
                        _ = sys.SetBkMode(hdc, c.TRANSPARENT);
                        _ = sys.SetTextColor(hdc, if (v.isSearchBarResultsLabel(child))
                            if (v.searchControlSurface(child)) |surface|
                                searchBarResultsVisual(&v.app.resolved_theme, &surface.search_bar).fg
                            else
                                v.app.resolved_theme.text_secondary
                        else if (v.overlay_hint_hwnd != null and child == v.overlay_hint_hwnd.?)
                            v.app.resolved_theme.text_secondary
                        else
                            v.app.resolved_theme.text_primary);
                        return @as(LRESULT, @bitCast(@as(usize, @intFromPtr(v.overlay_brush.?))));
                    },
                    c.WM_CTLCOLORBTN => {
                        _ = sys.SetBkMode(hdc, c.TRANSPARENT);
                        if (v.isOverlayStyledButton(child)) {
                            _ = sys.SetTextColor(hdc, v.app.resolved_theme.button_overlay_fg);
                            return @as(LRESULT, @bitCast(@as(usize, @intFromPtr(v.overlay_brush.?))));
                        }
                        _ = sys.SetTextColor(hdc, if (v.isActiveChromeButton(child))
                            v.app.resolved_theme.button_active_fg
                        else
                            v.app.resolved_theme.button_chrome_fg);
                        return @as(LRESULT, @bitCast(@as(usize, @intFromPtr(v.chrome_brush.?))));
                    },
                    else => {},
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_COMMAND => {
            if (host) |v| {
                const command_id = lowWord(wParam);
                const notify_code = highWord(wParam);
                const child_hwnd = wmCommandChildHwnd(lParam);
                switch (command_id) {
                    2002 => {
                        if (notify_code == c.EN_CHANGE) {
                            // Skip re-entry from our own programmatic
                            // `SetWindowTextW` on the edit HWND. The
                            // caller already wraps the write in
                            // `suppress_edit_events` and drives its
                            // own sync pass afterward; letting this
                            // handler run would invalidate
                            // `cached_overlay_edit` mid-write and
                            // racing borrows across the sync cascade
                            // caused palette edit re-entry crashes.
                            if (v.suppress_edit_events) return 0;
                            runUiActionOrLog(
                                "overlay edit cache clear failed",
                                appendOwnedString(v.app.core_app.alloc, &v.cached_overlay_edit, null),
                            );
                            if (v.overlay_edit_uia_provider) |provider| {
                                provider.raiseTextChanged();
                                provider.raiseValueChanged();
                            }
                            v.raiseOverlayEditSelectionChangedIfNeeded();
                            if (v.overlay_mode == .command_palette) {
                                runUiActionOrLog("overlay completion sync failed", v.syncOverlayCompletionState());
                                runUiActionOrLog("command palette banner sync failed", v.syncCommandPaletteBanner());
                            } else {
                                _ = v.syncOverlayLabel() catch false;
                                _ = v.syncOverlayHint() catch false;
                                _ = v.syncOverlayButtons() catch false;
                            }
                            return 0;
                        }
                    },
                    c.SEARCH_EDIT_ID => {
                        if (notify_code == c.EN_CHANGE) {
                            if (v.suppress_edit_events) return 0;
                            if (child_hwnd) |child| {
                                if (v.searchControlSurface(child)) |surface| {
                                    if (surface.search_bar_edit_uia_provider) |provider| {
                                        provider.raiseTextChanged();
                                        provider.raiseValueChanged();
                                    }
                                    surface.raiseSearchEditSelectionChangedIfNeeded();
                                    _ = surface.handleSearchBarEditChanged() catch |err| {
                                        logUiActionError("docked search edit update failed", err);
                                    };
                                    return 0;
                                }
                            }
                        }
                    },
                    2003 => if (expectedButtonClick(notify_code, child_hwnd, v.overlay_accept_hwnd)) {
                        if (v.overlay_mode == .confirm) {
                            // MUST NOT touch `v` after the callback
                            // — a destructive accept (close-surface)
                            // fires `DestroyWindow`, which triggers
                            // the Host's WM_DESTROY path + frees the
                            // Host struct. `invokeConfirmAccept`
                            // itself documents this ordering invariant.
                            v.invokeConfirmAccept();
                            return 0;
                        }
                        if (v.overlay_mode == .profile) {
                            runUiActionOrLog("profile overlay submit failed", v.submitProfileOverlay(resolveProfileOpenTarget(
                                v.app.launcher_profile_target,
                                keyPressed(c.VK_SHIFT),
                                keyPressed(c.VK_CONTROL),
                            )));
                        } else {
                            runUiActionOrLog("overlay submit failed", v.submitOverlay());
                        }
                        return 0;
                    },
                    2004 => if (expectedButtonClick(notify_code, child_hwnd, v.overlay_cancel_hwnd)) {
                        if (v.overlay_mode == .confirm) {
                            // Cancel callbacks can mutate or destroy
                            // the Host. Use the same no-access-after
                            // discipline as the accept path for safety.
                            v.invokeConfirmCancel();
                            return 0;
                        }
                        v.hideOverlay();
                        runUiActionOrLog("overlay dismiss layout refresh failed", v.layout());
                        refocusActiveSurface(v);
                        return 0;
                    },
                    c.SEARCH_PREV_ID => {
                        if (notify_code == c.BN_CLICKED) {
                            if (child_hwnd) |child| {
                                if (v.searchControlSurface(child)) |surface| {
                                    if (dockedSearchButtonDirection(command_id)) |dir| {
                                        _ = surface.navigateDockedSearch(dir) catch |err| {
                                            logUiActionError("docked search previous failed", err);
                                        };
                                    }
                                    return 0;
                                }
                            }
                        }
                    },
                    c.SEARCH_NEXT_ID => {
                        if (notify_code == c.BN_CLICKED) {
                            if (child_hwnd) |child| {
                                if (v.searchControlSurface(child)) |surface| {
                                    if (dockedSearchButtonDirection(command_id)) |dir| {
                                        _ = surface.navigateDockedSearch(dir) catch |err| {
                                            logUiActionError("docked search next failed", err);
                                        };
                                    }
                                    return 0;
                                }
                            }
                        }
                    },
                    c.SEARCH_REGEX_ID, c.SEARCH_CASE_ID, c.SEARCH_WORD_ID => {
                        if (notify_code == c.BN_CLICKED) {
                            if (child_hwnd) |child| {
                                if (v.searchControlSurface(child)) |surface| {
                                    _ = surface.handleSearchToggleClick(command_id) catch |err| {
                                        logUiActionError("docked search toggle failed", err);
                                    };
                                    return 0;
                                }
                            }
                        }
                    },
                    c.SEARCH_CLOSE_ID => {
                        if (notify_code == c.BN_CLICKED) {
                            if (child_hwnd) |child| {
                                if (v.searchControlSurface(child)) |surface| {
                                    surface.closeDockedSearchBar(true, true) catch |err| {
                                        logUiActionError("docked search close failed", err);
                                    };
                                    return 0;
                                }
                            }
                        }
                    },
                    // Foreground-free harness hooks also used by interactive
                    // verification; these have no visible toolbar controls.
                    1901 => {
                        if (v.activeSurface()) |surface| {
                            runUiActionOrLog("toolbar command palette failed", surface.toggleCommandPalette());
                        }
                        return 0;
                    },
                    1907 => {
                        _ = v.activateTabByDirection(.previous);
                        return 0;
                    },
                    1908 => {
                        _ = v.activateTabByDirection(.next);
                        return 0;
                    },
                    1904 => {
                        v.postDeferredNewTab();
                        return 0;
                    },
                    1911 => {
                        v.showOverflowMenu();
                        return 0;
                    },
                    else => {},
                }
                for (v.tabs.items, 0..) |*tab, i| {
                    if (child_hwnd) |child| {
                        if (tab.button_hwnd == child) {
                            _ = v.activateTabIndex(i);
                            return 0;
                        }
                    }
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_SETFOCUS => {
            if (host) |v| {
                refocusHostAfterActivation(v);
            }
            return 0;
        },

        c.WM_KEYDOWN, c.WM_SYSKEYDOWN, c.WM_KEYUP, c.WM_SYSKEYUP => {
            if (host) |v| {
                if (v.handleEmptyHostKeyMessage(msg, wParam, lParam)) return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_MENUCHAR => {
            // An Alt chord typed into a chrome control (a tab button, the
            // search field) reaches DefWindowProc as WM_SYSCHAR, becomes
            // SC_KEYMENU, and lands here with MF_POPUP clear: no menu is
            // open, nothing can match, and the default answer is the shell's
            // beep. Close that phantom loop silently. With a menu actually
            // open (MF_POPUP: the window menu after Alt+Space, or one of
            // this window's own TrackPopupMenu menus) the default reply
            // stays. The terminal surface consumes its own WM_SYSCHAR
            // (#250) except for Alt+Space, whose menu is a real popup.
            const menu_flags: u32 = @intCast((wParam >> 16) & 0xFFFF);
            if (win32_input.menuCharClosesPhantomMenu(menu_flags)) {
                return @as(LRESULT, c.MNC_CLOSE) << 16;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_GETMINMAXINFO => {
            if (host) |v| {
                if (v.activeSurface()) |surface| {
                    surface.updateMinMaxInfo(lParam);
                    return 0;
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_SIZE => {
            if (host) |v| {
                // Defensive: maximize / minimize jumps don't always
                // route through WM_ENTERSIZEMOVE → WM_EXITSIZEMOVE, so
                // a flag set on an earlier interactive drag might be
                // left stuck `true` after a window-button size change.
                // Clear it here so the renderer doesn't stay in
                // coarse-mode after the user clicks maximize.
                const size_kind: u32 = @truncate(wParam);
                if (size_kind == c.SIZE_MAXIMIZED or size_kind == c.SIZE_MINIMIZED) {
                    v.is_live_resize.store(false, .release);
                    // Win32 silently cancels NC mouse tracking when
                    // the window minimises or its maximised state
                    // flips — WM_NCMOUSELEAVE is NOT guaranteed to
                    // fire in those paths. Force-clear the caption
                    // state here so the next NC re-entry re-arms
                    // `TrackMouseEvent` and hover paint stays correct.
                    v.caption_track_armed = false;
                    if (v.caption_hover != .none or v.caption_pressed != .none) {
                        v.caption_hover = .none;
                        v.caption_pressed = .none;
                        v.repaintTopChrome();
                    }
                }
                runUiActionOrLog("window resize layout failed", v.layout());
                v.scheduleCaptionUiaSync();
                v.app.resizeShellCompositorWindow(hwnd);
                if (size_kind == c.SIZE_MAXIMIZED or
                    (size_kind == c.SIZE_RESTORED and !v.is_live_resize.load(.acquire)))
                {
                    v.startResizeSettleRepaints();
                }
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        win32_power.WM_POWERBROADCAST => {
            // Only the power-setting notifications we registered for are
            // ours. Suspend/resume and the legacy APM query messages must
            // keep reaching DefWindowProcW.
            if (wParam != win32_power.PBT_POWERSETTINGCHANGE) {
                return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
            }
            _ = win32_power.handlePowerSettingChange(lParam);
            return 1;
        },

        // Sign-out, shutdown and reboot, and an installer's Restart Manager
        // close (`ENDSESSION_CLOSEAPP`), which noctty agrees to only when a
        // quit would ask nothing, and then saves every window and quits from
        // the message loop. The app answers for every window it owns
        // (`App.onQueryEndSession`, `App.onEndSession`).
        c.WM_QUERYENDSESSION => {
            if (host) |v| return @intFromBool(v.app.onQueryEndSession(lParam));
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_ENDSESSION => {
            if (host) |v| v.app.onEndSession(wParam != 0, lParam);
            return 0;
        },
        // Saved from the message loop rather than inside this sent message,
        // which can arrive while the thread waits in the middle of other
        // work.
        c.WM_DISPLAYCHANGE => {
            _ = sys.PostMessageW(hwnd, c.WM_WINHOSTTY_SESSION_CHECKPOINT, 0, 0);
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_WINHOSTTY_SESSION_CHECKPOINT => {
            if (host) |v| v.app.checkpointSessionState();
            return 0;
        },
        c.WM_WINHOSTTY_QUIT => {
            // wParam: whether the quit came from this window. May destroy
            // this window: nothing after the call reads `v`.
            if (host) |v| v.app.requestQuit(if (wParam != 0) v.activeSurface() else null);
            return 0;
        },

        c.WM_SHOWWINDOW => {
            const result = sys.DefWindowProcW(hwnd, msg, wParam, lParam);
            if (host) |v| {
                if (wParam != 0) v.hidden_by_toggle = false;
                v.refreshSurfaceVisibility();
                // Hiding or showing a window changes no size, so WM_SIZE
                // never fires and this is the only notice that the caption
                // children just appeared or disappeared.
                v.scheduleCaptionUiaSync();
            }
            return result;
        },

        c.WM_WINDOWPOSCHANGED => {
            const result = sys.DefWindowProcW(hwnd, msg, wParam, lParam);
            // This fires once per mouse-move during a drag-move/resize and
            // the visibility query costs a DWM round-trip, so skip it while
            // a drag is in flight -- a window being dragged is by definition
            // visible. The drag loop emits its last WM_WINDOWPOSCHANGED just
            // BEFORE WM_EXITSIZEMOVE, so that one is skipped too and the
            // WM_EXITSIZEMOVE arm does the catch-up refresh.
            if (host) |v| {
                if (!v.is_live_resize.load(.acquire)) {
                    v.refreshSurfaceVisibility();
                    // Covers the SetWindowPos show/hide flags, which do not
                    // always produce a WM_SHOWWINDOW. The post coalesces.
                    v.scheduleCaptionUiaSync();
                }
            }
            return result;
        },

        c.WM_ENTERSIZEMOVE => {
            // User started a drag-resize or drag-move. We don't know
            // which yet, but setting the flag on both is harmless —
            // pure move generates no WM_SIZE so the throttle has
            // nothing to coalesce. WM_EXITSIZEMOVE clears it either
            // way.
            if (host) |v| v.is_live_resize.store(true, .release);
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_EXITSIZEMOVE => {
            if (host) |v| {
                // A drag that ends without the `WM_DPICHANGED` its
                // `WM_GETDPISCALEDSIZE` announced must not hold the grid; the
                // forced sync below catches it up.
                v.dpi_change_pending = false;
                v.is_live_resize.store(false, .release);
                v.defer_surface_repaints_until_flush = true;
                runUiActionOrLog("resize completion layout failed", v.layout());
                v.defer_surface_repaints_until_flush = false;
                v.flushDeferredVisibleSurfaceRepaints();
                v.startResizeSettleRepaints();
                v.forceVisibleSurfaceRepaintsNow();
                v.forceHostCompositionPaint();
                // The last WM_WINDOWPOSCHANGED of the drag was skipped by
                // the live-resize guard, so re-check here.
                v.refreshSurfaceVisibility();
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_MOUSEWHEEL, c.WM_MOUSEHWHEEL, c.WM_POINTERWHEEL, c.WM_POINTERHWHEEL => {
            if (host) |v| {
                var point = POINT{
                    .x = signedLowWord(lParamBits(lParam)),
                    .y = signedHighWord(lParamBits(lParam)),
                };
                if (sys.ScreenToClient(hwnd, &point) != 0 and point.y >= 0 and point.y < v.tabBarHeight()) {
                    v.scrollTabStrip(msg == c.WM_MOUSEHWHEEL or msg == c.WM_POINTERHWHEEL, wheelDeltaFromWParam(wParam));
                    return 0;
                }
                v.tab_wheel_steps = .{};
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_PAINT => {
            if (host) |v| {
                v.chrome_paint_pending = false;
                v.chrome_paint_mask = .{};
                v.paintChrome();
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_CLOSE => {
            if (host) |v| {
                // A committed Restart Manager close quits every window at
                // once from the message loop; its fallback WM_CLOSE must not
                // close them one at a time first.
                if (!v.app.end_session_quit_pending) v.close();
                return 0;
            }
            _ = sys.DestroyWindow(hwnd);
            return 0;
        },

        c.WM_DESTROY => {
            if (host) |v| {
                v.destroyChildControls();
                v.app.detachShellCompositorWindow(hwnd);
                v.power_notifications.deinit();
                v.hwnd = null;
            }
            return 0;
        },

        else => return sys.DefWindowProcW(hwnd, msg, wParam, lParam),
    }
}

pub fn desiredTabIndex(total: usize, current: usize, goto: apprt.action.GotoTab) ?usize {
    if (total == 0 or current >= total) return null;

    return switch (goto) {
        .previous => if (current == 0) total - 1 else current - 1,
        .next => (current + 1) % total,
        .last => total - 1,
        // `goto_tab:N` is 1-based, as the GTK and macOS apprts read it.
        _ => blk: {
            const raw: c_int = @intFromEnum(goto);
            if (raw < 1) return null;
            const idx: usize = @intCast(raw - 1);
            break :blk @min(idx, total - 1);
        },
    };
}

fn tabButtonCloseHit(x: i32, y: i32, close_left: i32, close_top: i32) bool {
    return x >= close_left and y >= close_top;
}

test "TABGAP added top rows exclude the close zone on mouse down and up" {
    for ([_]u32{ 96, 120, 144, 192 }) |dpi| {
        const inset = win32_chrome_state.scaled(3, dpi);
        for ([_]usize{ 1, 2, 20 }) |count| {
            for (0..@intCast(inset)) |row| {
                const y: i32 = @intCast(row);
                try std.testing.expect(!tabButtonCloseHit(110, y, 100, inset));
                try std.testing.expectEqual(TabButtonMouseUpAction.none, tabButtonMouseUpAction(null, false, 110, y, 100, inset, count));
                try std.testing.expectEqual(TabButtonMouseUpAction.activate, tabButtonMouseUpAction(0, false, 110, y, 100, inset, count));
            }
            try std.testing.expect(tabButtonCloseHit(110, inset, 100, inset));
            try std.testing.expectEqual(TabButtonMouseUpAction.close, tabButtonMouseUpAction(null, false, 110, inset, 100, inset, count));
            // Restored tabs keep their old close target at button row zero.
            try std.testing.expect(tabButtonCloseHit(110, 0, 100, 0));
            try std.testing.expect(!tabButtonCloseHit(99, inset, 100, inset));
        }
    }
}

const TabButtonMouseUpAction = enum {
    none,
    activate,
    close,
};

fn tabButtonMouseUpAction(
    drag_index: ?usize,
    was_drag: bool,
    click_x: i32,
    click_y: i32,
    close_left: i32,
    close_top: i32,
    tab_count: usize,
) TabButtonMouseUpAction {
    if (drag_index != null) {
        return if (was_drag) .none else .activate;
    }
    if (tabCloseAction(tab_count) != .none and tabButtonCloseHit(click_x, click_y, close_left, close_top)) return .close;
    return .none;
}

const TabCloseAction = enum {
    /// There is no tab to close.
    none,
    /// Close that tab and leave the window to the others.
    close_tab,
    /// The tab is the window's only one: close the window.
    close_window,
};

/// What a window with `tab_count` tabs does when its tab strip closes a tab:
/// the X, a middle click, Delete on a focused tab, the context menu's
/// "Close Tab" and a UIA Invoke of the close element. Every tab has the
/// close X, the only one included, since an undecorated window has no caption
/// button to close it with. The only tab closes the window the way the window's
/// own close button does, because `close_tab:this` on it keeps an empty frame
/// on screen for `undo-timeout` (measured, TABX).
pub fn tabCloseAction(tab_count: usize) TabCloseAction {
    return switch (tab_count) {
        0 => .none,
        1 => .close_window,
        else => .close_tab,
    };
}

pub fn desiredMoveIndex(total: usize, current: usize, amount: isize) ?usize {
    if (total <= 1 or current >= total or amount == 0) return null;
    const total_i: isize = @intCast(total);
    const current_i: isize = @intCast(current);
    const normalized = @mod(current_i + amount, total_i);
    return @intCast(normalized);
}

pub fn movedIndexAfterReorder(active: usize, from: usize, to: usize) usize {
    if (active == from) return to;
    if (from < to and active > from and active <= to) return active - 1;
    if (from > to and active >= to and active < from) return active + 1;
    return active;
}

pub fn applyQuickSlotPreferenceOrder(
    profiles: []windows_shell.Profile,
    slot_keys: [3]?[]const u8,
) void {
    var insert_at: usize = 0;
    for (slot_keys) |key_opt| {
        const key = key_opt orelse continue;
        var found: ?usize = null;
        for (profiles, 0..) |profile, index| {
            if (profileKeyEquals(profile, key)) {
                found = index;
                break;
            }
        }
        const found_index = found orelse continue;
        if (found_index == insert_at) {
            insert_at += 1;
            continue;
        }
        const chosen = profiles[found_index];
        var move_index = found_index;
        while (move_index > insert_at) : (move_index -= 1) {
            profiles[move_index] = profiles[move_index - 1];
        }
        profiles[insert_at] = chosen;
        insert_at += 1;
    }
}

pub const findLauncherQuickSlotOrdinal = labels.findLauncherQuickSlotOrdinal;

pub fn launcherQuickSlotAssignmentNeedsChange(
    slot_keys: [3]?[:0]const u8,
    slot_ordinal: usize,
    key: []const u8,
) bool {
    if (slot_ordinal >= slot_keys.len) return false;
    return findLauncherQuickSlotOrdinal(slot_keys, key) != slot_ordinal;
}

pub fn launcherQuickSlotPinsAlreadyClear(slot_keys: [3]?[:0]const u8) bool {
    for (slot_keys) |slot_key| {
        if (slot_key != null) return false;
    }
    return true;
}

pub fn selectedProfileSelectionNeedsChange(
    current_index: usize,
    next_index: usize,
    selected_profile_key: ?[:0]const u8,
    launcher_profile_key: ?[:0]const u8,
    next_key: []const u8,
) bool {
    return current_index != next_index or
        !paint_text.ownedStringEquals(selected_profile_key, next_key) or
        !paint_text.ownedStringEquals(launcher_profile_key, next_key);
}

fn startupProfilePickerEnabled(raw: []const u8) bool {
    return std.mem.eql(u8, raw, "1") or
        std.ascii.eqlIgnoreCase(raw, "true") or
        std.ascii.eqlIgnoreCase(raw, "yes") or
        std.ascii.eqlIgnoreCase(raw, "on");
}

pub fn detectStartupProfilePicker(alloc: Allocator) bool {
    const raw = std.process.getEnvVarOwned(alloc, "NOCTTY_WIN32_STARTUP_PROFILE_PICKER") catch
        return false;
    defer alloc.free(raw);
    return startupProfilePickerEnabled(raw);
}

pub fn detectDefaultProfileHint(alloc: Allocator) ?[:0]const u8 {
    const raw = std.process.getEnvVarOwned(alloc, "NOCTTY_WIN32_DEFAULT_PROFILE") catch
        return null;
    if (raw.len == 0) {
        alloc.free(raw);
        return null;
    }
    const value = alloc.dupeZ(u8, raw) catch {
        alloc.free(raw);
        return null;
    };
    alloc.free(raw);
    return value;
}

pub fn detectDefaultProfileTarget(alloc: Allocator) ProfileOpenTarget {
    const raw = std.process.getEnvVarOwned(alloc, "NOCTTY_WIN32_DEFAULT_PROFILE_TARGET") catch
        return .tab;
    defer alloc.free(raw);
    return parseProfileOpenTarget(raw) orelse .tab;
}

pub fn isSafeStartupCwd(path: []const u8) bool {
    return path.len >= 3 and
        std.ascii.isAlphabetic(path[0]) and
        path[1] == ':' and
        (path[2] == '\\' or path[2] == '/');
}

fn pointInRect(point: POINT, rect: RECT) bool {
    return point.x >= rect.left and
        point.x < rect.right and
        point.y >= rect.top and
        point.y < rect.bottom;
}

pub const lParamBits = win32_input.lParamBits;

fn lowWord(value: usize) u16 {
    return @truncate(value & 0xFFFF);
}

pub const highWord = win32_input.highWord;

pub fn signedLowWord(value: usize) i16 {
    return @bitCast(lowWord(value));
}

pub fn signedHighWord(value: usize) i16 {
    return @bitCast(highWord(value));
}

pub fn cursorPosFromLParam(lParam: LPARAM) apprt.CursorPos {
    const bits = lParamBits(lParam);
    return .{
        .x = @floatFromInt(signedLowWord(bits)),
        .y = @floatFromInt(signedHighWord(bits)),
    };
}

const ImeWindowForms = struct {
    composition: COMPOSITIONFORM,
    candidate: CANDIDATEFORM,
};

var ime_window_forms_trace_path_loaded = false;
var ime_window_forms_trace_path: ?[]const u8 = null;

fn scaledImeCoord(value: f64, scale: f32) i32 {
    const scale_f64: f64 = @floatCast(scale);
    return @intFromFloat(value * scale_f64);
}

pub fn imeWindowForms(ime_pos: apprt.IMEPos, content_scale: apprt.ContentScale) ImeWindowForms {
    const point: POINT = .{
        .x = scaledImeCoord(ime_pos.x, content_scale.x),
        .y = scaledImeCoord(ime_pos.y, content_scale.y),
    };
    const caret_height = @max(@as(i32, 1), scaledImeCoord(ime_pos.height, content_scale.y));

    return .{
        .composition = .{
            .dwStyle = c.CFS_POINT,
            .ptCurrentPos = point,
            .rcArea = .{ .left = 0, .top = 0, .right = 0, .bottom = 0 },
        },
        .candidate = .{
            .dwIndex = 0,
            .dwStyle = c.CFS_EXCLUDE,
            .ptCurrentPos = point,
            .rcArea = .{
                .left = point.x,
                .top = point.y - caret_height,
                .right = point.x + 1,
                .bottom = point.y,
            },
        },
    };
}

fn imeWindowFormsTracePath(alloc: Allocator) ?[]const u8 {
    if (!ime_window_forms_trace_path_loaded) {
        ime_window_forms_trace_path_loaded = true;
        ime_window_forms_trace_path = internal_os.getEnvVarOwnedTrimmedNotEmpty(
            alloc,
            "NOCTTY_WIN32_IME_FORM_TRACE_FILE",
        ) catch null;
    }

    return ime_window_forms_trace_path;
}

pub fn deinitImeWindowFormsTracePath(alloc: Allocator) void {
    if (ime_window_forms_trace_path) |path| alloc.free(path);
    ime_window_forms_trace_path = null;
    ime_window_forms_trace_path_loaded = false;
}

pub fn writeImeWindowFormsTrace(
    alloc: Allocator,
    ime_pos: apprt.IMEPos,
    content_scale: apprt.ContentScale,
    forms: ImeWindowForms,
) void {
    const trace_path = imeWindowFormsTracePath(alloc) orelse return;

    const file = std.fs.createFileAbsolute(trace_path, .{ .truncate = true }) catch |err| {
        log.warn("win32 IME form trace create failed path={s} err={}", .{ trace_path, err });
        return;
    };
    defer file.close();

    var buffer: [1024]u8 = undefined;
    var writer = file.writer(&buffer);
    const stream = &writer.interface;
    stream.print("{f}", .{std.json.fmt(.{
        .ime_pos = .{
            .x = ime_pos.x,
            .y = ime_pos.y,
            .width = ime_pos.width,
            .height = ime_pos.height,
        },
        .content_scale = .{
            .x = content_scale.x,
            .y = content_scale.y,
        },
        .composition = .{
            .dwStyle = forms.composition.dwStyle,
            .ptCurrentPos = .{
                .X = forms.composition.ptCurrentPos.x,
                .Y = forms.composition.ptCurrentPos.y,
            },
            .rcArea = .{
                .Left = forms.composition.rcArea.left,
                .Top = forms.composition.rcArea.top,
                .Right = forms.composition.rcArea.right,
                .Bottom = forms.composition.rcArea.bottom,
            },
        },
        .candidate = .{
            .dwIndex = forms.candidate.dwIndex,
            .dwStyle = forms.candidate.dwStyle,
            .ptCurrentPos = .{
                .X = forms.candidate.ptCurrentPos.x,
                .Y = forms.candidate.ptCurrentPos.y,
            },
            .rcArea = .{
                .Left = forms.candidate.rcArea.left,
                .Top = forms.candidate.rcArea.top,
                .Right = forms.candidate.rcArea.right,
                .Bottom = forms.candidate.rcArea.bottom,
            },
        },
    }, .{})}) catch |err| {
        log.warn("win32 IME form trace write failed path={s} err={}", .{ trace_path, err });
        return;
    };
    stream.flush() catch |err| {
        log.warn("win32 IME form trace flush failed path={s} err={}", .{ trace_path, err });
        return;
    };
}

pub const readSystemWheelSetting = win32_input.readSystemWheelSetting;

const wheelDeltaFromWParam = win32_input.wheelDeltaFromWParam;

const normalizeWheelDelta = win32_input.normalizeWheelDelta;

pub const keyPressed = win32_input.keyPressed;

const currentMods = win32_input.currentMods;

pub const hotkeySpecForTrigger = win32_input.hotkeySpecForTrigger;

pub const hotkeySpecEql = win32_input.hotkeySpecEql;

pub const hotkeyRegistrationFailureReason = win32_input.hotkeyRegistrationFailureReason;
pub const quickSelectAsciiFromKey = win32_input.quickSelectAsciiFromKey;

pub fn quitTimerDelayMs(delay: configpkg.Config.Duration) UINT {
    const clamped_ns = @max(delay.duration, std.time.ns_per_s);
    const delay_ms_u64 = @max(1, std.math.divCeil(u64, clamped_ns, std.time.ns_per_ms) catch std.math.maxInt(u64));
    return @intCast(@min(delay_ms_u64, std.math.maxInt(UINT)));
}

pub fn mouseButtonFromMessage(msg: UINT) ?input.MouseButton {
    return switch (msg) {
        c.WM_LBUTTONDOWN, c.WM_LBUTTONUP => .left,
        c.WM_RBUTTONDOWN, c.WM_RBUTTONUP => .right,
        c.WM_MBUTTONDOWN, c.WM_MBUTTONUP => .middle,
        else => null,
    };
}

pub fn mouseButtonStateFromMessage(msg: UINT) ?input.MouseButtonState {
    return switch (msg) {
        c.WM_LBUTTONDOWN, c.WM_RBUTTONDOWN, c.WM_MBUTTONDOWN => .press,
        c.WM_LBUTTONUP, c.WM_RBUTTONUP, c.WM_MBUTTONUP => .release,
        else => null,
    };
}

fn rightClickShowsMenu(action: configpkg.Config.RightClickAction, press_consumed: bool) bool {
    return action == .@"context-menu" and !press_consumed;
}

test "win32 right click menu honors consumed presses and every configured action" {
    const expect = std.testing.expect;
    try expect(rightClickShowsMenu(.@"context-menu", false));
    try expect(!rightClickShowsMenu(.@"context-menu", true));
    inline for (.{ .ignore, .paste, .copy, .@"copy-or-paste" }) |action| {
        try expect(!rightClickShowsMenu(action, false));
        try expect(!rightClickShowsMenu(action, true));
    }
}

pub fn mouseModsFromWParam(wParam: WPARAM) input.Mods {
    const bits = @as(usize, @intCast(wParam));
    var mods = currentMods();
    if ((bits & c.MK_SHIFT) != 0) mods.shift = true;
    if ((bits & c.MK_CONTROL) != 0) mods.ctrl = true;
    _ = bits & (c.MK_LBUTTON | c.MK_RBUTTON | c.MK_MBUTTON);
    return mods;
}

pub const ScrollbarProxyPoint = struct {
    local_x: f32,
    local_y: f32,
    over_band: bool,
};

pub fn scrollbarProxyPointFromSurfaceCoords(
    pane_rect: RECT,
    hover_width: i32,
    surface_x: i32,
    surface_y: i32,
) ScrollbarProxyPoint {
    const pane_width: i32 = @max(@as(i32, 1), pane_rect.right - pane_rect.left);
    const pane_height: i32 = @max(@as(i32, 1), pane_rect.bottom - pane_rect.top);
    const band_left: i32 = @max(@as(i32, 0), pane_width - @max(@as(i32, 1), hover_width));
    return .{
        .local_x = @floatFromInt(surface_x - band_left),
        .local_y = @floatFromInt(surface_y),
        .over_band = surface_x >= band_left and surface_x <= pane_width and
            surface_y >= 0 and surface_y <= pane_height,
    };
}

pub fn scrollbarProxyPointFromSurfaceCursor(
    pane_rect: RECT,
    hover_width: i32,
    lParam: LPARAM,
) ScrollbarProxyPoint {
    return scrollbarProxyPointFromSurfaceCoords(
        pane_rect,
        hover_width,
        signedLowWord(lParamBits(lParam)),
        signedHighWord(lParamBits(lParam)),
    );
}

pub const DeferredCharState = win32_input.DeferredCharState;

pub const keyEventFromWin32Message = win32_input.keyEventFromWin32Message;

pub fn windowProc(hwnd: HWND, msg: UINT, wParam: WPARAM, lParam: LPARAM) callconv(.winapi) LRESULT {
    if (msg == c.WM_NCCREATE) {
        const cs: *const CREATESTRUCTW = @ptrFromInt(@as(usize, @bitCast(lParam)));
        if (cs.lpCreateParams) |ptr| {
            setWindowData(hwnd, ptr);
        }
    }

    const surface = getSurface(hwnd);

    // Record only F9 key-down at the terminal HWND, before character
    // collection can pump sent messages. This is input observation; the
    // performAction hook records actual open_config dispatch separately.
    if ((msg == c.WM_KEYDOWN or msg == c.WM_SYSKEYDOWN) and wParam == c.VK_F1 + 8) {
        if (surface) |v| if (v.app.settings_open_trace.enabled()) {
            v.app.settings_open_trace.note(if (v.core_initialized) .f9_keydown else .f9_before_core_initialized);
        };
    }

    switch (msg) {
        c.WM_WINHOSTTY_WAKE => return 0,

        c.WM_NCHITTEST => {
            if (surface) |v| if (v.host) |host| if (host.resizesFrom(lParam)) return c.HTTRANSPARENT;
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_WINHOSTTY_RENDER_TRACE_SNAPSHOT => {
            if (surface) |v| v.render_trace.requestSnapshot();
            return 0;
        },

        c.WM_WINHOSTTY_RENDER_TRACE_TARGET => {
            if (surface) |v| v.render_trace.setTargetOutputBytes(@intCast(wParam));
            return 0;
        },

        c.WM_WINHOSTTY_UIA_QUERY_REFRESH => {
            if (surface) |v| {
                v.drainTerminalAccessibilityOutput();
                if (v.terminal_accessibility) |session| {
                    if (wParam == 2) {
                        session.handleScroll();
                        return 1;
                    }
                    if (wParam == 3) {
                        session.handleViewportRefresh();
                        return 1;
                    }
                    session.handleQueryRefresh(wParam != 0);
                }
            }
            return 0;
        },

        c.WM_SETFOCUS => {
            if (surface) |v| v.focusChanged(true);
            return 0;
        },

        c.WM_KILLFOCUS => {
            if (surface) |v| {
                v.deferred_char.clear();
                v.focusChanged(false);
            }
            return 0;
        },

        c.WM_SIZE => {
            if (surface) |v| v.windowSizeChanged();
            return 0;
        },

        c.WM_TIMER => {
            if (wParam == c.TERMINAL_UIA_TIMER_ID) {
                if (surface) |v| {
                    v.drainTerminalAccessibilityOutput();
                    if (v.terminal_accessibility) |session| session.handleTimer();
                }
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_GETOBJECT => {
            if (surface) |v| {
                // UIA may query the child HWND reentrantly while DestroyWindow
                // is unwinding. Surface.destroy clears this flag before it
                // releases the owner context, so never recreate that context
                // once teardown has begun (or before init completes).
                if (!v.destroy_on_wm_destroy) return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
                const provider = v.terminalUiaProvider() catch |err| {
                    log.warn("uia: terminal provider init failed err={}", .{err});
                    return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
                };
                if (win32_uia.returnTerminalProvider(
                    hwnd,
                    wParam,
                    lParam,
                    provider,
                )) |lr| return lr;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_GETMINMAXINFO => {
            if (surface) |v| {
                v.updateMinMaxInfo(lParam);
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_KEYDOWN, c.WM_SYSKEYDOWN, c.WM_KEYUP, c.WM_SYSKEYUP => {
            // The pump has already run TranslateMessage, so the characters
            // this key typed are queued. Take them before the surface is
            // resolved: PeekMessage runs cross-thread sent messages.
            const typed: win32_input.TypedChars = if (msg == c.WM_KEYDOWN or msg == c.WM_SYSKEYDOWN)
                win32_input.takeTypedChars(hwnd)
            else
                .{};
            if (getSurface(hwnd)) |v| {
                // VK_APPS (Menu key) -> show context menu when not mouse reporting
                const vk: UINT = @intCast(wParam & 0xFFFF);
                if (vk == c.VK_APPS and (msg == c.WM_KEYDOWN or msg == c.WM_SYSKEYDOWN)) {
                    if (!v.core_initialized or v.core_surface.io.terminal.flags.mouse_event == .none) {
                        if (v.host) |h| {
                            // Keyboard invoke: use center of surface
                            var rect: RECT = undefined;
                            if (sys.GetClientRect(hwnd, &rect) != 0) {
                                var pt: POINT = .{
                                    .x = @divTrunc(rect.right, 2),
                                    .y = @divTrunc(rect.bottom, 2),
                                };
                                _ = sys.ClientToScreen(hwnd, &pt);
                                h.showContextMenu(pt.x, pt.y);
                            }
                        }
                        return 0;
                    }
                }
                v.handleKeyMessage(msg, wParam, lParam, &typed);
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_IME_STARTCOMPOSITION => {
            if (surface) |v| {
                v.deferred_char.clear();
                v.ime_composing = true;
                v.positionImeWindow();
            }
            return 0;
        },

        c.WM_IME_COMPOSITION => {
            if (surface) |v| {
                v.deferred_char.clear();
                const parts: u32 = @intCast(lParam);
                if ((parts & c.GCS_RESULTSTR) != 0) {
                    // Committing into a pane whose child has exited closes
                    // the pane, which frees the surface before this returns.
                    if (v.handleImeResult() == .closed) return 0;
                }
                switch (win32_input.imeCompositionAction(parts)) {
                    .refresh => v.handleImeComposition(),
                    .cancel => if (v.core_initialized) {
                        v.core_surface.preeditCallback(null) catch {};
                    },
                    .none => {},
                }
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_IME_ENDCOMPOSITION => {
            if (surface) |v| {
                v.deferred_char.clear();
                v.ime_composing = false;
                v.core_surface.preeditCallback(null) catch {};
            }
            return 0;
        },

        c.WM_IME_SETCONTEXT => {
            // We handle preedit via the core renderer.
            const masked_lParam = lParam & ~c.ISC_SHOWUICOMPOSITIONWINDOW;
            return sys.DefWindowProcW(hwnd, msg, wParam, masked_lParam);
        },

        c.WM_CHAR, c.WM_DEADCHAR, c.WM_SYSDEADCHAR => {
            if (surface) |v| v.handleCharMessage(msg, wParam, lParam);
            return 0;
        },

        c.WM_SYSCHAR => {
            // `TranslateMessage` turns an Alt chord's WM_SYSKEYDOWN into
            // this. The chord was already encoded from the key message (an
            // Alt chord never defers its text to a character message), so
            // the character carries nothing the terminal still needs, and
            // handed to DefWindowProc it becomes SC_KEYMENU: a window with
            // no menu bar answers that with a menu loop that matches nothing
            // and the shell's default beep (#250). Swallowed outright, and
            // left out of `takeTypedChars`: committing it would type the
            // chord's character a second time after the chord. Alt+Space
            // alone still opens the window menu, which
            // Windows reserves for moving and resizing from the keyboard,
            // and only on a window that has one.
            if (surface) |v| {
                if (!win32_input.sysCharOpensWindowMenu(@intCast(wParam & 0xFFFF))) return 0;
                if (!v.hasWindowMenu()) return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_MOUSEMOVE => {
            if (surface) |v| {
                v.armScrollbarLeaveTracking(hwnd);
                if (v.handleScrollbarProxyMouseMove(hwnd, lParam)) return 0;
                v.handleMouseMove(lParam, mouseModsFromWParam(wParam));
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_MOUSELEAVE => {
            if (surface) |v| {
                v.handleMouseLeave();
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_RBUTTONUP => {
            if (surface) |v| {
                // Balance the core's press even when the click opens a menu.
                // Snapshot and clear before releasing capture, which can send
                // synchronous window messages. A reporting TUI consumes the
                // press; Shift bypasses it unless the TUI captures Shift too.
                const show_menu = v.core_initialized and rightClickShowsMenu(
                    v.core_surface.config.right_click_action,
                    v.right_press_consumed,
                );
                v.right_press_consumed = false;
                _ = v.handleMouseButton(msg, wParam, lParam);
                if (!show_menu) return 0;
                if (v.host) |h| {
                    var pt: POINT = .{
                        .x = signedLowWord(lParamBits(lParam)),
                        .y = signedHighWord(lParamBits(lParam)),
                    };
                    _ = sys.ClientToScreen(hwnd, &pt);
                    h.showContextMenu(pt.x, pt.y);
                }
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_LBUTTONDOWN, c.WM_LBUTTONUP => {
            if (surface) |v| {
                if (v.handleScrollbarProxyButton(hwnd, msg, lParam)) return 0;
                _ = v.handleMouseButton(msg, wParam, lParam);
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_RBUTTONDOWN => {
            if (surface) |v| {
                v.right_press_consumed = v.handleMouseButton(msg, wParam, lParam);
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_MBUTTONDOWN, c.WM_MBUTTONUP => {
            if (surface) |v| {
                _ = v.handleMouseButton(msg, wParam, lParam);
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_XBUTTONDOWN, c.WM_XBUTTONUP => {
            if (surface) |v| {
                v.handleXMouseButton(msg, wParam, lParam);
            }
            // Windows requires TRUE for XButton messages
            return 1;
        },

        c.WM_DROPFILES => {
            if (surface) |v| {
                v.handleDropFiles(wParam);
            }
            return 0;
        },

        c.WM_MOUSEWHEEL, c.WM_POINTERWHEEL => {
            if (surface) |v| {
                v.updateWheelCursorPos(hwnd, lParam);
                v.handleMouseWheel(normalizeWheelDelta(
                    v.wheelNormalizationContext(),
                    .vertical,
                    wheelDeltaFromWParam(wParam),
                ));
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_MOUSEHWHEEL, c.WM_POINTERHWHEEL => {
            if (surface) |v| {
                v.updateWheelCursorPos(hwnd, lParam);
                v.handleMouseWheel(normalizeWheelDelta(
                    v.wheelNormalizationContext(),
                    .horizontal,
                    wheelDeltaFromWParam(wParam),
                ));
                return 0;
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_ERASEBKGND => return 1,

        c.WM_SETTINGCHANGE => {
            if (surface) |v| v.app.refreshSystemWheelSettings();
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_SETCURSOR => {
            if (surface) |v| {
                if (lowWord(@as(usize, @intCast(lParam))) == c.HTCLIENT) {
                    const now_ms = sys.GetTickCount64();
                    const was_hovered = v.scrollbar_state.hovered;
                    const was_visibility = v.scrollbar_state.visibility;
                    const over_scrollbar = v.updateScrollbarHoverFromScreenCursor(hwnd, now_ms);
                    if (over_scrollbar or
                        v.scrollbar_state.hovered != was_hovered or
                        v.scrollbar_state.visibility != was_visibility)
                    {
                        v.syncScrollbarWindowNow(now_ms) catch |err| {
                            log.warn("win32 scrollbar cursor refresh failed err={}", .{err});
                        };
                    }
                    if (over_scrollbar or v.scrollbar_state.dragging) {
                        _ = sys.SetCursor(sys.LoadCursorW(null, c.IDC_ARROW));
                        return 1;
                    }
                    if (v.applyCursor()) {
                        return 1;
                    }
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        c.WM_CAPTURECHANGED => {
            if (surface) |v| v.handleScrollbarCaptureChanged();
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },

        0x8050, 0x8051, 0x8052, 0x8053, 0x8054, 0x8058 => { // Test-only renderer lifecycle actions.
            if (build_config.renderer_test_tools and build_config.d3d11) {
                if (surface) |v| {
                    if (!v.core_initialized) return 0;
                    if (msg == 0x8052 or msg == 0x8053 or msg == 0x8058) {
                        if (!v.core_surface.renderer.setTestFailures(msg == 0x8052, msg == 0x8053)) return 0;
                    }
                    if (msg == 0x8054) {
                        if (!v.core_surface.renderer.failNextPresent()) return 0;
                    } else if (msg != 0x8051 and !v.core_surface.renderer.requestDeviceLoss()) return 0;
                    v.redraw() catch return 0;
                    return 1;
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        0x8059 => { // Test-only IME composition, past the IMM read only.
            if (build_config.renderer_test_tools) {
                if (surface) |v| {
                    if (!v.core_initialized) return 0;
                    // 3 is wider than any test window: a-z repeated.
                    var long: [208]u16 = undefined;
                    for (&long, 0..) |*unit, i| unit.* = 'a' + @as(u16, @intCast(i % 26));
                    // 4-7 are Japanese-shaped: kana, a kanji clause, another
                    // kanji clause, with no attributes (4), the target on
                    // the first kanji clause (5) or the second (6), and
                    // attributes one short of the string (7).
                    const kana = std.unicode.utf8ToUtf16LeStringLiteral("\u{304B}\u{306A}\u{6F22}\u{5B57}\u{5909}\u{63DB}");
                    const I = c.ATTR_INPUT;
                    const T = c.ATTR_TARGET_CONVERTED;
                    const C = c.ATTR_CONVERTED;
                    const units: []const u16, const attrs: ?[]const u8 = switch (wParam) {
                        0 => .{ &.{}, null },
                        1 => .{ std.unicode.utf8ToUtf16LeStringLiteral("zhongguo"), null },
                        2 => .{ std.unicode.utf8ToUtf16LeStringLiteral("\u{4E2D}\u{56FD}\u{4EBA}"), null },
                        3 => .{ &long, null },
                        4 => .{ kana, null },
                        5 => .{ kana, &.{ I, I, T, T, C, C } },
                        6 => .{ kana, &.{ I, I, C, C, T, T } },
                        7 => .{ kana, &.{ I, I, T, T, C } },
                        else => return 0,
                    };
                    var utf8_stack: [512]u8 = undefined;
                    win32_input.applyImeComposition(
                        Surface.KeyTarget{ .surface = v },
                        v.app.core_app.alloc,
                        units,
                        @truncate(@as(isize, lParam)),
                        attrs,
                        &utf8_stack,
                    );
                    return 1;
                }
            }
            return 0;
        },
        0x8056 => { // Test-only actions through the production binding path.
            if (build_config.renderer_test_tools) {
                if (surface) |v| {
                    if (!v.core_initialized) return 0;
                    const action: input.Binding.Action = switch (wParam) {
                        1 => .new_tab,
                        2 => .{ .new_split = .right },
                        3 => .{ .new_split = .down },
                        4 => .previous_tab,
                        5 => .next_tab,
                        6 => .close_surface,
                        7 => .reload_config,
                        8 => .{ .goto_split = .previous },
                        9 => .toggle_split_zoom,
                        else => return 0,
                    };
                    return @intFromBool(v.core_surface.performBindingAction(action) catch false);
                }
            }
            return 0;
        },
        0x8057 => { // Test-only DPI scale notification, without moving monitors.
            if (build_config.renderer_test_tools) {
                if (surface) |v| {
                    // Down to half of 96, so a 96 DPI host can scale down too.
                    if (!v.core_initialized or wParam < 48 or wParam > 384) return 0;
                    const scale: f32 = @as(f32, @floatFromInt(wParam)) / 96;
                    v.content_scale = .{ .x = scale, .y = scale };
                    v.core_surface.contentScaleCallback(v.content_scale) catch return 0;
                    return 1;
                }
            }
            return 0;
        },
        0x0317, 0x0318 => { // Test-only in-app GPU readback (no DWM evidence).
            if (build_config.renderer_test_tools and build_config.d3d11) {
                if (surface) |v| {
                    if (v.core_initialized and wParam != 0) {
                        v.core_surface.renderer.capture(@ptrFromInt(wParam)) catch return 0;
                        return 1;
                    }
                }
            }
            return sys.DefWindowProcW(hwnd, msg, wParam, lParam);
        },
        c.WM_PAINT => {
            var ps: PAINTSTRUCT = undefined;
            _ = sys.BeginPaint(hwnd, &ps) orelse return 0;
            defer _ = sys.EndPaint(hwnd, &ps);

            if (surface) |v| {
                const draw_content = v.shouldDrawRendererPaintContent();
                v.paint_pending = false;
                if (draw_content) {
                    const paint_start_ms = if (v.render_trace.enabled()) sys.GetTickCount64() else 0;
                    v.render_trace.notePaintDraw();
                    defer v.finishRendererRepaintRequest();
                    defer if (paint_start_ms != 0) {
                        const paint_end_ms = sys.GetTickCount64();
                        if (paint_end_ms > paint_start_ms) {
                            v.render_trace.notePaintDrawDuration(paint_end_ms - paint_start_ms);
                        }
                    };
                    v.redraw() catch |err| {
                        log.err("win32 paint redraw failed err={}", .{err});
                    };
                } else {
                    v.render_trace.notePaintRetry();
                    v.requestRendererFrameNow(.apprt_paint_retry);
                    // The OS asked for pixels and the renderer had none
                    // reserved. `.apprt_paint_retry` above only wakes the
                    // renderer; it cannot help if the renderer still thinks
                    // this surface is occluded, and it does not re-arm the
                    // update region. See `win32/first_frame.zig` (#224).
                    v.noteFirstFrame(.paint_without_content);
                }
            }

            return 0;
        },

        c.WM_CLOSE => {
            if (surface) |v| _ = v.requestClose();
            return 0;
        },

        c.WM_DESTROY => {
            if (surface) |v| {
                if (v.destroy_on_wm_destroy) {
                    v.destroy();
                } else if (v.hwnd == hwnd) {
                    // The chrome children die with this window. Detach their
                    // providers here rather than leaving them to decide
                    // availability from `IsWindow`, which can answer yes again
                    // once the system recycles the handle value.
                    detachChromeControlProvider(v.app, &v.scrollbar_uia_provider);
                    v.destroySearchBarControls();
                    v.hwnd = null;
                }
            }
            return 0;
        },

        else => return sys.DefWindowProcW(hwnd, msg, wParam, lParam),
    }
}

fn getSurface(hwnd: HWND) ?*Surface {
    return windowData(Surface, hwnd);
}

pub fn terminalAccessibilityHwnd(ctx: *anyopaque) ?HWND {
    const surface: *Surface = @ptrCast(@alignCast(ctx));
    return surface.hwnd;
}

pub fn terminalAccessibilityName(ctx: *anyopaque, buf: []u8) []const u8 {
    const surface: *Surface = @ptrCast(@alignCast(ctx));
    const title = surface.effectiveTitle() orelse "Terminal";
    return std.fmt.bufPrint(buf, "Terminal: {s}", .{title}) catch "Terminal";
}

pub fn terminalAccessibilityFocused(ctx: *anyopaque) bool {
    const surface: *Surface = @ptrCast(@alignCast(ctx));
    return surface.app.isSurfaceFocused(surface);
}

pub fn terminalAccessibilityCapture(
    ctx: *anyopaque,
    alloc: Allocator,
) !win32_terminal_accessibility.Capture {
    const surface: *Surface = @ptrCast(@alignCast(ctx));
    if (!surface.core_initialized) return error.SurfaceNotInitialized;

    // This runs on the UI thread, reached from `windowProc` via WM_GETOBJECT,
    // and UIA can re-enter `windowProc` while the UI thread already holds the
    // renderer lock. Blocking here stops the message loop for as long as the
    // lock is held -- indefinitely in the re-entrant case. Take the lock only
    // if it is free and let the caller keep its cached snapshot otherwise.
    if (!surface.core_surface.renderer_state.mutex.tryLock()) return error.WouldBlock;
    const snapshot = win32_uia.snapshotTerminalAccessiblePlainText(
        alloc,
        surface.core_surface.renderer_state.terminal,
    ) catch |err| {
        surface.core_surface.renderer_state.mutex.unlock();
        return err;
    };
    const renderer_size = surface.core_surface.size;
    surface.core_surface.renderer_state.mutex.unlock();
    return .{
        .snapshot = snapshot,
        .cell_width = @floatFromInt(renderer_size.cell.width),
        .cell_height = @floatFromInt(renderer_size.cell.height),
        .origin_x = @floatFromInt(renderer_size.padding.left),
        .origin_y = @floatFromInt(renderer_size.padding.top),
    };
}

pub fn terminalAccessibilityViewport(ctx: *anyopaque) !win32_uia.widgets.TerminalViewportGeometry {
    const surface: *Surface = @ptrCast(@alignCast(ctx));
    if (!surface.core_initialized) return error.ElementNotAvailable;
    const core = &surface.core_surface;
    if (!core.renderer_state.mutex.tryLock()) return error.WouldBlock;
    defer core.renderer_state.mutex.unlock();
    const state = core.renderer_state.terminal;
    const pages = &state.screens.active.pages;
    const viewport = pages.pointFromPin(.screen, pages.getTopLeft(.viewport)) orelse return error.UnknownPoint;
    return .{
        .row_numbering = @import("win32_uia/text.zig").rowNumbering(state),
        .viewport_y = viewport.screen.y,
        .cell_width = @floatFromInt(core.size.cell.width),
        .cell_height = @floatFromInt(core.size.cell.height),
        .origin_x = @floatFromInt(core.size.padding.left),
        .origin_y = @floatFromInt(core.size.padding.top),
    };
}

pub fn terminalAccessibilityDeferProviderRelease(
    ctx: *anyopaque,
    provider: *win32_uia.TerminalProvider,
) void {
    const surface: *Surface = @ptrCast(@alignCast(ctx));
    scheduleDeferredUiaDisconnect(
        surface.app,
        @ptrCast(provider),
        &terminalDisconnectThunk,
        &terminalReleaseThunk,
    );
}

pub fn terminalAccessibilityScroll(ctx: *anyopaque, request: win32_uia.widgets.ScrollRequest) !void {
    const surface: *Surface = @ptrCast(@alignCast(ctx));
    if (!surface.core_initialized) return error.ElementNotAvailable;
    const core = &surface.core_surface;
    if (!core.renderer_state.mutex.tryLock()) return error.WouldBlock;
    const scrolled = scrolled: {
        // Unlocked before the refresh below.
        defer core.renderer_state.mutex.unlock();
        break :scrolled try @import("win32_uia/text.zig").scrollFrozenRange(
            core.alloc,
            core.renderer_state.terminal,
            request.token,
            request.document_window,
            request.absolute_row,
            request.align_to_top,
        );
    };
    if (scrolled) try core.refreshCallback();
}

pub fn terminalAccessibilityOutputCallback(
    ctx: *anyopaque,
    item: apprt.surface.TerminalOutputTransport.Item,
) void {
    const session: *win32_terminal_accessibility.TerminalAccessibilitySession =
        @ptrCast(@alignCast(ctx));
    switch (item) {
        .reset => session.resetSemanticOutputContinuity(),
        .data => |output| session.noteSemanticOutput(output),
        .omitted => session.noteOutputOmitted(),
    }
}

pub fn quickSelectLabelDisplayUnit(byte: u8) u16 {
    return if (byte == ' ') 0x2423 else byte;
}

/// Opening a modal overlay transfers focus while its shortcut is still held.
/// Snapshotting this as a boolean is sufficient because the overlay ignores
/// every label input until a key-up observes that no virtual key remains down.
pub fn anyVirtualKeyPressed() bool {
    for (0..256) |vk| {
        if (win32_input.keyPressed(@intCast(vk))) return true;
    }
    return false;
}

test "quick select label renders spaces visibly" {
    try std.testing.expectEqual(@as(u16, 0x2423), quickSelectLabelDisplayUnit(' '));
    try std.testing.expectEqual(@as(u16, 'a'), quickSelectLabelDisplayUnit('a'));
}

pub fn quickSelectCanActivate(window_visible: bool, hwnd_visible: bool) bool {
    return window_visible and hwnd_visible;
}

test "quick select activates only for a visible surface" {
    try std.testing.expect(quickSelectCanActivate(true, true));
    try std.testing.expect(!quickSelectCanActivate(false, true));
    try std.testing.expect(!quickSelectCanActivate(true, false));
}

fn consumeQuickSelectOpeningLeftButtonUp(
    suppress_button_up: *bool,
    suppress_keys: *bool,
    any_key_pressed: bool,
) bool {
    if (!suppress_button_up.*) return false;
    suppress_button_up.* = false;
    suppress_keys.* = any_key_pressed;
    return true;
}

test "quick select consumes only the opening left button release" {
    var suppress_button_up = true;
    var suppress_keys = true;
    try std.testing.expect(consumeQuickSelectOpeningLeftButtonUp(
        &suppress_button_up,
        &suppress_keys,
        false,
    ));
    try std.testing.expect(!suppress_button_up);
    try std.testing.expect(!suppress_keys);
    try std.testing.expect(!consumeQuickSelectOpeningLeftButtonUp(
        &suppress_button_up,
        &suppress_keys,
        false,
    ));

    suppress_button_up = true;
    try std.testing.expect(consumeQuickSelectOpeningLeftButtonUp(
        &suppress_button_up,
        &suppress_keys,
        true,
    ));
    try std.testing.expect(suppress_keys);
}

pub const Surface = terminal_window_module.Surface;

pub const uninitializedInertStorage = test_support.uninitializedInertStorage;

pub const TestSession = test_support.TestSession;

fn pushUndoAndRedoBranch(
    stack: *win32_undo.UndoStack,
    alloc: Allocator,
    seed: u8,
) !void {
    const first = try alloc.alloc(u8, 1);
    first[0] = seed;
    try stack.push(.{
        .kind = .clear_screen,
        .snapshot = .{ .clear_screen = .{ .state_bytes = first } },
        .timestamp_ms = seed,
    });

    const second = try alloc.alloc(u8, 1);
    second[0] = seed + 1;
    try stack.push(.{
        .kind = .reset,
        .snapshot = .{ .reset = .{ .state_bytes = second } },
        .timestamp_ms = seed + 1,
    });

    try std.testing.expect((try stack.popForUndo()) != null);
    try std.testing.expectEqual(@as(usize, 1), stack.undoDepth());
    try std.testing.expectEqual(@as(usize, 1), stack.redoDepth());
}

test "win32 undo history ordering uses sequence when timestamps tie" {
    try std.testing.expect(win32_structural_history.sortsAfter(10, 2, 10, 1));
    try std.testing.expect(!win32_structural_history.sortsAfter(10, 1, 10, 2));
    try std.testing.expect(win32_structural_history.sortsAfter(11, 1, 10, 99));
}

test "win32 undo prune expires local and structural histories" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    var core_app: CoreApp = undefined;
    var app: App = undefined;
    var host: Host = undefined;
    var surface_a: Surface = undefined;
    var surface_b: Surface = undefined;
    var session: TestSession = .{};
    try session.init(.{
        .core_app = &core_app,
        .app = &app,
        .hosts = &.{.{ .storage = &host, .register = true }},
        .surfaces = &.{
            .{ .storage = &surface_a, .register = true },
            .{ .storage = &surface_b },
        },
    });
    defer session.deinit();

    try surface_a.undo_stack.push(.{
        .kind = .clear_screen,
        .snapshot = .{ .clear_screen = .{ .state_bytes = try std.testing.allocator.alloc(u8, 1) } },
        .timestamp_ms = 10,
    });
    try surface_a.undo_stack.push(.{
        .kind = .reset,
        .snapshot = .{ .reset = .{ .state_bytes = try std.testing.allocator.alloc(u8, 1) } },
        .timestamp_ms = 200,
    });
    _ = try surface_a.undo_stack.popForUndo();

    try host.structural_undo_entries.append(std.testing.allocator, .{
        .kind = .split_create,
        .timestamp_ms = 20,
        .payload = .{ .split_create = .{
            .source_surface = &surface_a,
            .created_surface = &surface_b,
        } },
    });
    try host.structural_undo_entries.append(std.testing.allocator, .{
        .kind = .split_create,
        .timestamp_ms = 220,
        .payload = .{ .split_create = .{
            .source_surface = &surface_a,
            .created_surface = &surface_b,
        } },
    });
    try host.structural_redo_entries.append(std.testing.allocator, .{
        .kind = .split_create,
        .timestamp_ms = 30,
        .payload = .{ .split_create = .{
            .source_surface = &surface_a,
            .created_surface = &surface_b,
        } },
    });
    try host.structural_redo_entries.append(std.testing.allocator, .{
        .kind = .split_create,
        .timestamp_ms = 230,
        .payload = .{ .split_create = .{
            .source_surface = &surface_a,
            .created_surface = &surface_b,
        } },
    });

    _ = app.pruneUndoHistoryBefore(100);

    try std.testing.expectEqual(@as(usize, 0), surface_a.undo_stack.undoDepth());
    try std.testing.expectEqual(@as(usize, 1), surface_a.undo_stack.redoDepth());
    try std.testing.expectEqual(@as(usize, 1), host.structural_undo_entries.items.len);
    try std.testing.expectEqual(@as(u64, 220), host.structural_undo_entries.items[0].timestamp_ms);
    try std.testing.expectEqual(@as(usize, 1), host.structural_redo_entries.items.len);
    try std.testing.expectEqual(@as(u64, 230), host.structural_redo_entries.items[0].timestamp_ms);
    try std.testing.expectEqual(@as(?u64, 200), app.oldestUndoTimestamp());
}

