    // Ids for the lookups Settings makes when it closes. The inert fixture
    // cores are otherwise only read for `readonly`, which `needsConfirmQuit`
    // checks before anything else and which stands in for a busy terminal.
    surface_a.core_surface.id = 1;
    surface_b.core_surface.id = 2;
    surface_b.core_surface.readonly = true;

    // The busy terminal is in the other window; the prompt still shows
    // where the quit came from.
    surface_b.core_initialized = true;
    try std.testing.expect(try app.performAction(.{ .surface = surface_a.core() }, .quit, {}));
    try std.testing.expectEqual(HostOverlayMode.confirm, host_a.overlay_mode);
    try std.testing.expectEqual(HostOverlayMode.none, host_b.overlay_mode);
    try std.testing.expectEqualStrings("Quit noctty?", host_a.confirm_payload.?.title);
    try std.testing.expect(app.running);
    // Asking again from the other window keeps the one prompt.
    try std.testing.expect(try app.performAction(.{ .surface = surface_b.core() }, .quit, {}));
    try std.testing.expectEqual(HostOverlayMode.none, host_b.overlay_mode);
    host_a.invokeConfirmCancel();

    // `close_all_windows` quits too, and asks the same way. With no window
    // named and none focused, the window with the running process asks.
    try std.testing.expect(try app.performAction(.app, .close_all_windows, {}));
    surface_b.core_initialized = false;
    try std.testing.expectEqual(HostOverlayMode.confirm, host_b.overlay_mode);
    try std.testing.expect(app.running);
    try std.testing.expectEqual(@as(usize, 2), app.registry.hosts.items.len);
    host_b.invokeConfirmCancel();

    // Save or Discard in a Settings prompt that a quit raised resumes it,
    // on the window Settings hands focus back to.
    app.settings_window.quit_after_close = true;
    surface_b.core_initialized = true;
    settingsOnClosedThunk(@ptrCast(&app));
    surface_b.core_initialized = false;
    try std.testing.expect(!app.settings_window.quit_after_close);
    try std.testing.expectEqual(HostOverlayMode.confirm, host_a.overlay_mode);
    host_a.invokeConfirmCancel();
    try std.testing.expect(app.running);

    // With a window to post to, the quit waits for the message loop: core
    // keeps using the terminal whose key asked for it after this returns.
    const hwnd = try createTestHostWindow();
    defer _ = sys.DestroyWindow(hwnd);
    host_a.hwnd = hwnd;
    defer host_a.hwnd = null;
    surface_b.core_initialized = true;
    try std.testing.expect(try app.performAction(.{ .surface = surface_a.core() }, .quit, {}));
    surface_b.core_initialized = false;
    try std.testing.expectEqual(HostOverlayMode.none, host_a.overlay_mode);
    var msg: sys.MSG = undefined;
    try std.testing.expect(sys.PeekMessageW(&msg, hwnd, c.WM_WINHOSTTY_QUIT, c.WM_WINHOSTTY_QUIT, c.PM_REMOVE) != 0);
    try std.testing.expectEqual(@as(WPARAM, 1), msg.wParam);

    // A post that fails declines the quit rather than running it under
    // the key handler. The non-null edit handle stands in for the overlay
    // controls, so a quit run in place would open its prompt here.
    const dead_hwnd = try createTestHostWindow();
    _ = sys.DestroyWindow(dead_hwnd);
    host_a.hwnd = dead_hwnd;
    host_a.overlay_edit_hwnd = dead_hwnd;
    defer host_a.overlay_edit_hwnd = null;
    surface_b.core_initialized = true;
    try std.testing.expect(try app.performAction(.{ .surface = surface_a.core() }, .quit, {}));
    surface_b.core_initialized = false;
    try std.testing.expectEqual(HostOverlayMode.none, host_a.overlay_mode);
    try std.testing.expectEqual(HostOverlayMode.none, host_b.overlay_mode);
    try std.testing.expect(app.running);
}

test "win32 Install asks about running terminals on the window whose button was pressed" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    var core_app: CoreApp = undefined;
    var app: App = undefined;
    var host_a: Host = undefined;
    var host_b: Host = undefined;
    var surface_a: Surface = undefined;
    var surface_b: Surface = undefined;
    var session: TestSession = .{};
    try session.init(.{
        .core_app = &core_app,
        .app = &app,
        .hosts = &.{
            .{ .storage = &host_a, .id = 1, .register = true },
            .{ .storage = &host_b, .id = 2, .register = true },
        },
        .surfaces = &.{
            .{ .storage = &surface_a, .host = &host_a, .register = true },
            .{ .storage = &surface_b, .host = &host_b, .register = true },
        },
        .tabs = &.{
            .{ .host = &host_a, .surface = &surface_a, .id = 1 },
            .{ .host = &host_b, .surface = &surface_b, .id = 2 },
        },
    });
    defer session.deinit();
    app.running = true;
    // `readonly` stands in for a busy terminal, as in the quit test above.
    surface_b.core_surface.readonly = true;

    // The busy terminal is in the other window; the prompt shows where the
    // banner button was pressed. Never answer it here: Install would apply
    // whatever update the real state directory has staged.
    surface_b.core_initialized = true;
    defer surface_b.core_initialized = false;
    const ask = app.pendingCloseAsk(&updateApplyConfirmAccept, &host_a).?;
    try std.testing.expectEqual(&host_a, ask.host);
    try std.testing.expectEqual(@as(usize, 1), ask.count);
    ask.host.askBeforeClosing(.update, ask.count, &updateApplyConfirmAccept, &app);
    try std.testing.expectEqual(HostOverlayMode.confirm, host_a.overlay_mode);
    try std.testing.expectEqual(HostOverlayMode.none, host_b.overlay_mode);
    try std.testing.expectEqualStrings("Install the update?", host_a.confirm_payload.?.title);
    try std.testing.expectEqualStrings("Install", host_a.confirm_payload.?.accept_label);
    try std.testing.expect(std.mem.indexOf(u8, host_a.confirm_payload.?.body, "terminate it") != null);
    // Pressed again from the other window, the one prompt stays.
    try std.testing.expectEqual(&host_a, app.pendingCloseAsk(&updateApplyConfirmAccept, &host_b).?.host);
    host_a.invokeConfirmCancel();
    try std.testing.expectEqual(HostOverlayMode.none, host_a.overlay_mode);

    // The real entry point asks the same way and applies nothing until the
    // answer (it would apply whatever the real state directory has staged).
    // The in-flight flag is set so that, were the prompt ever skipped, the
    // request it falls through to queues nothing.
    app.update_action_host = &host_b;
    defer app.update_action_host = null;
    app.update_apply_in_flight = true;
    try app.requestApplyStagedUpdate();
    app.update_apply_in_flight = false;
    try std.testing.expectEqual(HostOverlayMode.confirm, host_b.overlay_mode);
    try std.testing.expectEqual(HostOverlayMode.none, host_a.overlay_mode);
    host_b.invokeConfirmCancel();

    // Nothing running anywhere: Install goes straight through.
    surface_b.core_initialized = false;
    try std.testing.expect(app.pendingCloseAsk(&updateApplyConfirmAccept, &host_a) == null);

    // A press that gets in while one apply is under way (`ShellExecuteW`
    // pumps messages) does nothing, so it cannot raise a second elevation
    // prompt and start a second Setup. It returns before reading any state.
    app.update_apply_in_flight = true;
    try app.applyStagedUpdate();
    try std.testing.expect(app.update_apply_in_flight);
}

test "win32 an install waits for unsaved Settings edits, also when the notice cannot be shown" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    var core_app: CoreApp = undefined;
    var app: App = undefined;
    var host: Host = undefined;
    var session: TestSession = .{};
    try session.init(.{
        .core_app = &core_app,
        .app = &app,
        .hosts = &.{.{ .storage = &host, .id = 1, .register = true }},
    });
    defer session.deinit();

    // Settings counts as open with a pending edit; nothing here touches the
    // window handle.
    app.settings_window.hwnd = @ptrFromInt(0x1000);
    defer app.settings_window.hwnd = null;
    app.settings_window.raw_scalar_dirty[0] = true;
    defer app.settings_window.raw_scalar_dirty[0] = false;

    // Asking for the install says so and queues nothing.
    try app.requestApplyStagedUpdate();
    try std.testing.expectEqual(@as(usize, 0), app.deferred_opens.items.len);
    try std.testing.expectEqualStrings(
        "Save or discard your Settings changes first, then press Install again.",
        host.banner_text.?,
    );

    // When the banner cannot be allocated the install is held all the same.
    try host.setBanner(.none, null);
    var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{ .fail_index = 0 });
    const alloc = core_app.alloc;
    core_app.alloc = failing.allocator();
    defer core_app.alloc = alloc;
    try std.testing.expect(app.settingsHoldInstall());
    try std.testing.expect(failing.has_induced_failure);

    // Saved or discarded, nothing holds it.
    app.settings_window.raw_scalar_dirty[0] = false;
    try std.testing.expect(!app.settingsHoldInstall());
}

/// A headless prompt with the real outbound IO mailbox. Only the core fields
/// used by OSC 52 completion and the deny gate are initialized; no renderer,
/// process or system clipboard is started. The pane stays hidden throughout.
const ClipboardReplyFixture = struct {
    core_app: CoreApp = undefined,
    app: App = undefined,
    host: Host = undefined,
    surface: Surface = undefined,
    session: TestSession = .{},
    mutex: std.Thread.Mutex = .{},

    fn init(self: *ClipboardReplyFixture) !void {
        try self.session.init(.{
            .core_app = &self.core_app,
            .app = &self.app,
            .hosts = &.{.{ .storage = &self.host, .register = true }},
            .surfaces = &.{.{ .storage = &self.surface, .host = &self.host, .register = true, .window_visible = false }},
            .tabs = &.{.{ .host = &self.host, .surface = &self.surface, .id = 1 }},
        });
        errdefer self.session.deinit();
        const core = &self.surface.core_surface;
        core.alloc = self.core_app.alloc;
        core.config.clipboard_read = .ask;
        core.readonly = false;
        core.rt_surface = &self.surface;
        core.io.mailbox = try @import("../termio.zig").Mailbox.initSPSC(self.core_app.alloc);
        errdefer core.io.mailbox.deinit(self.core_app.alloc);
        // The terminal's modes decide whether a paste is bracketed.
        core.io.terminal = try terminal.Terminal.init(self.core_app.alloc, .{ .cols = 10, .rows = 10 });
        core.renderer_state = .{ .mutex = &self.mutex, .terminal = &core.io.terminal };
        self.surface.core_initialized = true;
    }

    fn deinit(self: *ClipboardReplyFixture) void {
        self.host.hideOverlay();
        self.surface.core_initialized = false;
        if (self.surface.pending_clipboard_op) |*op| op.deinit(self.core_app.alloc);
        self.surface.pending_clipboard_op = null;
        self.surface.core_surface.io.terminal.deinit(self.core_app.alloc);
        self.surface.core_surface.io.mailbox.deinit(self.core_app.alloc);
        self.session.deinit();
    }

    fn setBracketedPaste(self: *ClipboardReplyFixture, on: bool) void {
        self.surface.core_surface.io.terminal.modes.set(.bracketed_paste, on);
    }

    fn expectSilent(self: *ClipboardReplyFixture) !void {
        const message = self.surface.core_surface.io.mailbox.spsc.queue.pop();
        if (message) |value| value.deinit();
        try std.testing.expect(message == null);
    }

    fn expectReply(self: *ClipboardReplyFixture, expected: []const u8) !void {
        const message = self.surface.core_surface.io.mailbox.spsc.queue.pop() orelse return error.MissingClipboardReply;
        defer message.deinit();
        switch (message) {
            .write_small => |v| try std.testing.expectEqualStrings(expected, v.data[0..v.len]),
            .write_stable => |v| try std.testing.expectEqualStrings(expected, v),
            .write_alloc => |v| try std.testing.expectEqualStrings(expected, v.data),
            else => return error.UnexpectedClipboardReply,
        }
        try self.expectSilent();
    }
};

test "win32 OSC 52 read explicit Cancel replies empty once with the requested selection" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;
    var fixture: ClipboardReplyFixture = .{};
