    defer fixture.deinit();
    const cases = .{
        .{ apprt.Clipboard.standard, "\x1b]52;c;\x1b\\" },
        .{ apprt.Clipboard.selection, "\x1b]52;s;\x1b\\" },
        .{ apprt.Clipboard.primary, "\x1b]52;p;\x1b\\" },
