test "win32 createHost frames an undecorated host for its Windows build" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    // Per-monitor aware, so the hosts are laid out at the monitor's DPI. A
    // DPI-unaware thread gets 96, where the linearly scaled frame happens to
    // equal the system's and the maximized check below could not fail.
    const previous_dpi_context = sys.SetThreadDpiAwarenessContext(-4);
    defer _ = sys.SetThreadDpiAwarenessContext(previous_dpi_context);

    var fixture: SafeModeAppFixture = .{};
    try fixture.init();
    defer fixture.deinit();
    const app = &fixture.app;
    app.config.@"window-decoration" = .none;

    // `createHost` as a `new_window` clone calls it: the decoration state
    // comes from the source window rather than the config. The rest of the
    // clone path (`inheritWindowStateFrom`) is not exercised here.
    var source: Surface = undefined;
    source.host = null;
    source.decorations_visible = false;
    source.fullscreen = false;

    // Both builds run against this machine's window manager; only the
    // build-gated choices differ.
    for ([_]u32{ 19045, c.OS_BUILD_WIN11_21H2 }) |os_build| {
        app.os_build = os_build;
        for ([_]bool{ true, false }) |integrated| {
            app.use_integrated_titlebar = integrated;
            // Hosts stay hidden, so the test never touches the foreground.
            const first = try app.createHost(std.unicode.utf8ToUtf16LeStringLiteral(""), &app.config, .{});
            const clone = try app.createHost(std.unicode.utf8ToUtf16LeStringLiteral(""), &app.config, .{ .clone_state_from = &source });
            const quick = try app.createHost(std.unicode.utf8ToUtf16LeStringLiteral(""), &app.config, .{ .quick_terminal = true });
            for ([_]*Host{ first, clone, quick }) |host| {
                const hwnd = host.hwnd.?;
                const keeps_frame = undecoratedKeepsFrame(os_build, host.quick_terminal);
                try std.testing.expect(sys.IsWindowVisible(hwnd) == 0);
                try std.testing.expect(!host.usingIntegratedTitlebar());
                // What `Surface.applyWindowStyle` writes for an undecorated
                // window, the style every clone and runtime toggle ends with.
                // Before #270 the first window came back with WS_CAPTION.
                const applied = effectiveHostWindowStyle(keeps_frame, false, true) & ~@as(u32, c.WS_VISIBLE);
                try std.testing.expectEqual(applied, testWindowStyle(hwnd) & ~@as(u32, c.WS_CLIPSIBLINGS));
                var window_rect: RECT = undefined;
                try std.testing.expect(sys.GetWindowRect(hwnd, &window_rect) != 0);
                var client: RECT = undefined;
                try std.testing.expect(sys.GetClientRect(hwnd, &client) != 0);
                var client_origin: POINT = .{ .x = 0, .y = 0 };
                try std.testing.expect(sys.ClientToScreen(hwnd, &client_origin) != 0);
                // No caption either way: the client starts at the top edge.
                try std.testing.expectEqual(window_rect.top, client_origin.y);
                const mid_x = @divTrunc(window_rect.left + window_rect.right, 2);
                const mid_y = @divTrunc(window_rect.top + window_rect.bottom, 2);
                if (!keeps_frame) {
                    // Windows 10, and the quick terminal: frameless, as before.
                    try std.testing.expectEqual(@as(?i32, null), host.clientCaptionHeight());
                    try std.testing.expectEqual(window_rect.right - window_rect.left, client.right - client.left);
                    try std.testing.expectEqual(window_rect.bottom - window_rect.top, client.bottom - client.top);
                    try std.testing.expect(!host.resizesFrom(testPoint(mid_x, window_rect.top + 1)));
                    continue;
                }
                // Windows 11 keeps the side and bottom frame, whose invisible
                // margins resize the window, and a 4 DIP top band inside the
                // client. The corners keep their 8 DIP square.
                try std.testing.expectEqual(@as(?i32, 0), host.clientCaptionHeight());
                try std.testing.expect(client.right - client.left < window_rect.right - window_rect.left);
                const dpi: i32 = @intCast(host.current_dpi);
                const band = @divTrunc(4 * dpi + 48, 96);
                const corner = @divTrunc(8 * dpi + 48, 96);
                try std.testing.expectEqual(@as(LRESULT, c.HTTOP), testHitTest(hwnd, mid_x, window_rect.top + band - 1));
                try std.testing.expectEqual(@as(LRESULT, c.HTTOPLEFT), testHitTest(hwnd, window_rect.left + corner - 1, window_rect.top + corner - 1));
                try std.testing.expectEqual(@as(LRESULT, c.HTTOPRIGHT), testHitTest(hwnd, window_rect.right - corner, window_rect.top + corner - 1));
                try std.testing.expectEqual(@as(LRESULT, c.HTLEFT), testHitTest(hwnd, window_rect.left + 1, window_rect.top + corner));
                try std.testing.expectEqual(@as(LRESULT, c.HTRIGHT), testHitTest(hwnd, window_rect.right - 2, mid_y));
                try std.testing.expectEqual(@as(LRESULT, c.HTBOTTOM), testHitTest(hwnd, mid_x, window_rect.bottom - 2));
                try std.testing.expectEqual(@as(LRESULT, c.HTBOTTOMRIGHT), testHitTest(hwnd, window_rect.right - 2, window_rect.bottom - 2));
                // No caption row: below the band, the tab strip (shown by
                // default) stands in for the title bar; below it is terminal.
                const strip_bottom = client_origin.y + host.tabBarHeight();
                try std.testing.expect(client_origin.y + band < strip_bottom);
                try std.testing.expectEqual(@as(LRESULT, c.HTCAPTION), testHitTest(hwnd, mid_x, window_rect.top + band));
                try std.testing.expectEqual(@as(LRESULT, c.HTCAPTION), testHitTest(hwnd, mid_x, strip_bottom - 1));
                try std.testing.expectEqual(@as(LRESULT, c.HTCLIENT), testHitTest(hwnd, mid_x, strip_bottom));
                try std.testing.expectEqual(@as(LRESULT, c.HTCLIENT), testHitTest(hwnd, mid_x, mid_y));
                try std.testing.expect(!host.resizesFrom(testPoint(mid_x, window_rect.top + band)));

                // The strip has no caption buttons: its right end, where the
                // integrated titlebar puts [x], is caption up to the edge.
                const strip_mid_y = client_origin.y + @divTrunc(host.tabBarHeight(), 2);
                try std.testing.expectEqual(@as(LRESULT, c.HTCAPTION), testHitTest(hwnd, window_rect.right - corner - 1, strip_mid_y));
                try std.testing.expectEqual(@as(LRESULT, c.HTRIGHT), testHitTest(hwnd, window_rect.right - corner, strip_mid_y));
                // The tabs and the [+] / [▾] buttons are BUTTON children over
                // the strip. Windows asks the topmost visible, enabled child
                // under the point first, so the caption never reaches them,
                // and they hand the band's rows above them back to the host.
                // A stand-in running their window procedures: the real
                // strip's tab container is a layered child, which a test
                // binary without the app manifest cannot create.
                const button = try createTestChromeChild(hwnd, prompt_button_class);
                defer _ = sys.DestroyWindow(button);
                try std.testing.expect(sys.SetWindowPos(
                    button,
                    null,
                    0,
                    host.scaled(3),
                    host.scaled(host_tab_max_button_width),
                    host.tabBarHeight() - host.scaled(6),
                    c.SWP_NOZORDER | c.SWP_NOACTIVATE,
                ) != 0);
                var button_point: POINT = .{ .x = host.scaled(10), .y = strip_mid_y - client_origin.y };
                try std.testing.expectEqual(@as(?HWND, button), sys.ChildWindowFromPointEx(
                    hwnd,
                    button_point,
                    c.CWP_SKIPINVISIBLE | c.CWP_SKIPDISABLED | c.CWP_SKIPTRANSPARENT,
                ));
                try std.testing.expect(sys.ClientToScreen(hwnd, &button_point) != 0);
                try std.testing.expectEqual(@as(LRESULT, c.HTTOP), testHitTest(hwnd, button_point.x, window_rect.top + band - 1));
                // Only the top band: the left strip is measured linearly from
                // the window rect and the client starts at DWP's frame, so
                // above 96 DPI the strip's inner columns are the button's
                // first, which keeps them. At 96 DPI the two are equally wide
                // and this point lies in the frame left of the button, so it
                // pins the procedures' answer rather than that overlap.
                const side_x = window_rect.left + corner - 1;
                try std.testing.expectEqual(@as(LRESULT, c.HTLEFT), testHitTest(hwnd, side_x, button_point.y));
                for ([_]WNDPROC{ &tabButtonProc, &hostButtonProc }) |proc| {
                    var previous: ?*const anyopaque = null;
                    host.subclassButton(button, proc, &previous);
                    defer _ = sys.SetWindowLongPtrW(button, c.GWLP_WNDPROC, @as(LONG_PTR, @intCast(@intFromPtr(previous))));
                    try std.testing.expectEqual(@as(LRESULT, c.HTTRANSPARENT), testHitTest(button, button_point.x, window_rect.top + band - 1));
                    try std.testing.expectEqual(@as(LRESULT, c.HTCLIENT), testHitTest(button, button_point.x, window_rect.top + band));
                    try std.testing.expectEqual(@as(LRESULT, c.HTCLIENT), testHitTest(button, button_point.x, button_point.y));
                    try std.testing.expect(testHitTest(button, side_x, button_point.y) != c.HTTRANSPARENT);
                }

                // With the tab bar off there is no drag handle: the terminal
                // pane covers the band and hands only the band to the host.
                {
                    const show_tab_bar = app.config.@"window-show-tab-bar";
                    app.config.@"window-show-tab-bar" = .never;
                    defer app.config.@"window-show-tab-bar" = show_tab_bar;
                    try std.testing.expectEqual(@as(LRESULT, c.HTTOP), testHitTest(hwnd, mid_x, window_rect.top + band - 1));
                    try std.testing.expectEqual(@as(LRESULT, c.HTCLIENT), testHitTest(hwnd, mid_x, window_rect.top + band));
                    try std.testing.expectEqual(@as(LRESULT, c.HTCLIENT), testHitTest(hwnd, mid_x, strip_bottom - 1));
                    try std.testing.expect(host.resizesFrom(testPoint(mid_x, window_rect.top + band - 1)));
                    try std.testing.expect(host.resizesFrom(testPoint(window_rect.left + corner - 1, window_rect.top + corner - 1)));
                    try std.testing.expect(!host.resizesFrom(testPoint(mid_x, window_rect.top + band)));
                    try std.testing.expect(!host.resizesFrom(testPoint(mid_x, mid_y)));
                }

                // Maximized, the client starts where the monitor does: the top
                // inset equals the frame the window overhangs it by, which is
                // the side frame DWP lays out. Only the zoom bit is set, so the
                // window stays hidden.
                _ = sys.SetWindowLongPtrW(hwnd, c.GWL_STYLE, @bitCast(@as(usize, testWindowStyle(hwnd) | c.WS_MAXIMIZE)));
                var rect: RECT = window_rect;
                _ = sys.SendMessageW(hwnd, c.WM_NCCALCSIZE, 0, @bitCast(@intFromPtr(&rect)));
                try std.testing.expect(rect.left > window_rect.left);
                try std.testing.expectEqual(rect.left - window_rect.left, rect.top - window_rect.top);
                // Nothing resizes a maximized window, so the strip drags from
                // its top row; the drag restores the window.
                try std.testing.expect(sys.SetWindowPos(
                    hwnd,
                    null,
                    0,
                    0,
                    0,
                    0,
                    c.SWP_NOMOVE | c.SWP_NOSIZE | c.SWP_NOZORDER | c.SWP_NOACTIVATE | c.SWP_FRAMECHANGED,
                ) != 0);
                // Applying the frame can also move the window: Windows fits a
                // maximized window that covers its monitor's work area to the
                // monitor's maximized rect. The 1280x800 host covers the work
                // area of a screen no larger than itself, a CI runner's among
                // them. So the client is measured against the window rect as
                // it is now: the inset computed above, on the side and on top.
                var zoomed_rect: RECT = undefined;
                try std.testing.expect(sys.GetWindowRect(hwnd, &zoomed_rect) != 0);
                var zoomed_origin: POINT = .{ .x = 0, .y = 0 };
                try std.testing.expect(sys.ClientToScreen(hwnd, &zoomed_origin) != 0);
                try std.testing.expectEqual(rect.left - window_rect.left, zoomed_origin.x - zoomed_rect.left);
                try std.testing.expectEqual(rect.top - window_rect.top, zoomed_origin.y - zoomed_rect.top);
                const zoomed_mid_x = @divTrunc(zoomed_rect.left + zoomed_rect.right, 2);
                try std.testing.expectEqual(@as(LRESULT, c.HTCAPTION), testHitTest(hwnd, zoomed_mid_x, zoomed_origin.y));
                try std.testing.expectEqual(@as(LRESULT, c.HTCAPTION), testHitTest(hwnd, zoomed_mid_x, zoomed_origin.y + host.tabBarHeight() - 1));
                try std.testing.expectEqual(@as(LRESULT, c.HTCLIENT), testHitTest(hwnd, zoomed_mid_x, zoomed_origin.y + host.tabBarHeight()));
            }
        }
    }
}

fn testPoint(x: i32, y: i32) LPARAM {
    const point: u32 = @as(u32, @as(u16, @bitCast(@as(i16, @intCast(x))))) |
        (@as(u32, @as(u16, @bitCast(@as(i16, @intCast(y))))) << 16);
    return @intCast(point);
}

pub fn testHitTest(hwnd: HWND, x: i32, y: i32) LRESULT {
    return sys.SendMessageW(hwnd, c.WM_NCHITTEST, 0, testPoint(x, y));
}

test "win32 layoutChromeForRect hides tab-strip chrome when the tab bar is off" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    const alloc = std.testing.allocator;

    // `IsWindowVisible` -- which is what the residue, `focusableHwnd` and
    // UIA all key off -- is false for every child of an invisible parent, so
    // this host has to be shown. Off-screen plus WS_EX_TOOLWINDOW keeps it
    // off the desktop and out of the taskbar while the test runs.
    const hwnd = sys.CreateWindowExW(
        c.WS_EX_TOOLWINDOW,
        prompt_label_class,
        std.unicode.utf8ToUtf16LeStringLiteral(""),
        c.WS_POPUP,
        -32_000,
        -32_000,
        800,
        600,
        null,
        null,
        sys.GetModuleHandleW(null),
        null,
    ) orelse return lastError();
    defer _ = sys.DestroyWindow(hwnd);
    _ = sys.ShowWindow(hwnd, c.SW_SHOWNOACTIVATE);

    var app: App = undefined;
    app.config = try configpkg.Config.default(alloc);
    defer app.config.deinit();
    app.use_integrated_titlebar = false;

    var surface: Surface = undefined;
    surface.decorations_visible = true;
    surface.inspector_visible = false;

    var host: Host = .{ .app = &app, .id = 244 };
    host.hwnd = hwnd;
    host.current_dpi = 96;
    host.tabs = .empty;
    host.active_tab = 0;
    defer deinitTestHostWindowFixture(&host);
    // Reserve first: a failing `append` between `Tab.init` and the list
    // taking ownership would leak the tab's split tree past the teardown.
    try host.tabs.ensureTotalCapacity(alloc, 1);
    host.tabs.appendAssumeCapacity(try Tab.init(alloc, 1, &surface));

    // Every tab-strip child as the runtime creates it: WS_VISIBLE, parented
    // to the host. `Tab.deinit` owns the tab button; the rest are destroyed
    // with the host window.
    host.tabs.items[0].button_hwnd = try createTestChromeChild(hwnd, prompt_button_class);
    host.tab_container_hwnd = try createTestChromeChild(hwnd, prompt_label_class);
    host.new_tab_hwnd = try createTestChromeChild(hwnd, prompt_button_class);
    host.overflow_hwnd = try createTestChromeChild(hwnd, prompt_button_class);

    const rect: RECT = .{ .left = 0, .top = 0, .right = 800, .bottom = 600 };
    var changed = false;

    // Regression for #244: a zero-height strip used to lay its children out
    // anyway, at `button_height = @max(1, 0 - scaled(6))`, so a 1 px row of
    // tab buttons and the [+] / [▾] cluster painted itself over the terminal
    // of every tab but the first.
    app.config.@"window-show-tab-bar" = .never;
    try std.testing.expectEqual(@as(i32, 0), host.tabBarHeight());
    try std.testing.expect(host.layoutChromeForRect(rect, &changed));
    const strip = [_]HWND{
        host.tabs.items[0].button_hwnd.?,
        host.tab_container_hwnd.?,
        host.new_tab_hwnd.?,
        host.overflow_hwnd.?,
    };
    for (strip) |child| try std.testing.expectEqual(@as(i32, 0), sys.IsWindowVisible(child));
    // A hidden button is not a focus-cycle target either.
    try std.testing.expectEqual(@as(?HWND, null), host.tabStripFocusHwnd());
    // The [▾] rect still tracks the window: `showOverflowMenu` anchors its
    // popup to it and must not read the creation rect at x = 0.
    var host_rect: RECT = undefined;
    try std.testing.expect(sys.GetWindowRect(hwnd, &host_rect) != 0);
    var overflow_rect: RECT = undefined;
    try std.testing.expect(sys.GetWindowRect(host.overflow_hwnd.?, &overflow_rect) != 0);
    try std.testing.expect(overflow_rect.left - host_rect.left > 600);

    // Turning the tab bar back on at runtime (a config reload) has to bring
    // all of it back, at the strip's real height.
    app.config.@"window-show-tab-bar" = .always;
    try std.testing.expect(host.tabBarHeight() > 0);
    try std.testing.expect(host.layoutChromeForRect(rect, &changed));
    for (strip) |child| try std.testing.expect(sys.IsWindowVisible(child) != 0);
    try std.testing.expectEqual(host.tabs.items[0].button_hwnd, host.tabStripFocusHwnd());
    var button_rect: RECT = undefined;
    try std.testing.expect(sys.GetWindowRect(strip[0], &button_rect) != 0);
    try std.testing.expect(button_rect.bottom - button_rect.top > 1);
}

pub const createTestChromeChild = test_support.createTestChromeChild;

pub const createTestHostWindow = test_support.createTestHostWindow;

const expectTestChildOrder = test_support.expectTestChildOrder;

test "win32 chrome is raised over the panes, and a pane's own child sits directly above its pane" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;
    const parent = try createTestHostWindow();
    defer _ = sys.DestroyWindow(parent);
    // A new child goes in at the bottom, so the first pane is on top and
    // chrome made later, the palette list or a pane's scrollbar, is under it.
    const pane = try createTestChromeChild(parent, prompt_label_class);
    const chrome = try createTestChromeChild(parent, prompt_label_class);
    const bar = try createTestChromeChild(parent, prompt_label_class);
    try expectTestChildOrder(parent, &.{ pane, chrome, bar });

    stackChildAbove(bar, pane);
    try expectTestChildOrder(parent, &.{ bar, pane, chrome });
    stackChildAbove(bar, pane);
    try expectTestChildOrder(parent, &.{ bar, pane, chrome });

    raiseChildToTop(parent, chrome);
    try expectTestChildOrder(parent, &.{ chrome, bar, pane });
    raiseChildToTop(parent, chrome);
    try expectTestChildOrder(parent, &.{ chrome, bar, pane });

    // From the bottom, the bar goes back directly above its pane, under the
    // chrome rather than over it.
    const hwnd_bottom: ?*anyopaque = @ptrFromInt(1);
    _ = sys.SetWindowPos(bar, hwnd_bottom, 0, 0, 0, 0, c.SWP_NOMOVE | c.SWP_NOSIZE | c.SWP_NOACTIVATE);
    try expectTestChildOrder(parent, &.{ chrome, pane, bar });
    stackChildAbove(bar, pane);
    try expectTestChildOrder(parent, &.{ chrome, bar, pane });
}

const initTestHostWindowFixture = test_support.initTestHostWindowFixture;

const deinitTestHostWindowFixture = test_support.deinitTestHostWindowFixture;

test "win32 hostPresentShowCommand skips redundant maximize for visible hosts" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    try std.testing.expectEqual(@as(?i32, c.SW_SHOW), hostPresentShowCommand(false, false, false));
    try std.testing.expectEqual(@as(?i32, c.SW_MAXIMIZE), hostPresentShowCommand(false, false, true));
    try std.testing.expectEqual(@as(?i32, c.SW_RESTORE), hostPresentShowCommand(true, true, false));
    try std.testing.expectEqual(@as(?i32, null), hostPresentShowCommand(true, false, true));
}

test "win32 forwardedActivationExtraArgCount counts args bundled with activation" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    const activation_only = [_][:0]const u8{"wgh://activate?surface=1"};
    try std.testing.expectEqual(@as(usize, 0), forwardedActivationExtraArgCount(&activation_only));

    const bundled = [_][:0]const u8{
        "wgh://activate?surface=1",
        "--config-file",
        "manual.conf",
    };
    try std.testing.expectEqual(@as(usize, 2), forwardedActivationExtraArgCount(&bundled));

    const malformed = [_][:0]const u8{"wgh://activate?surface=abc"};
    try std.testing.expectEqual(@as(usize, 0), forwardedActivationExtraArgCount(&malformed));
}

test "automation-window-list win32 json includes host tab and pane ids" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    var app: App = undefined;
    app.registry.windows = .empty;
    app.registry.hosts = .empty;
    app.ipc_namespace = "lane_9";
    app.test_automation_pwd = &struct {
        fn query(alloc: Allocator, surface: *Surface) !?[]const u8 {
            return switch (surface.core().id) {
                701 => null,
                702 => try alloc.dupe(u8, "C:\\work\\\"quote\"\t\r\n"),
                703 => try alloc.dupe(u8, "home"),
                else => error.UnexpectedSurface,
            };
        }
    }.query;
    defer app.registry.deinit(std.testing.allocator);

    var host: Host = undefined;
    host.id = 17;
    host.hwnd = null;
    host.tabs = .empty;
    host.active_tab = 1;
    host.cached_window_title = "host \"quote\"\\slash\t\r\n";
    defer {
        for (host.tabs.items) |*tab| tab.deinit();
        host.tabs.deinit(std.testing.allocator);
    }

    var tab0_surface: Surface = undefined;
    tab0_surface.core_surface = undefined;
    tab0_surface.core_surface.id = 701;
    tab0_surface.host = &host;
    tab0_surface.host_id = host.id;
    tab0_surface.title = null;
    tab0_surface.title_override = null;
    tab0_surface.tab_title_override = null;

    var tab1_primary: Surface = undefined;
    tab1_primary.core_surface = undefined;
    tab1_primary.core_surface.id = 702;
    tab1_primary.host = &host;
    tab1_primary.host_id = host.id;
    tab1_primary.window_focused = true;
    tab1_primary.title = "terminal title";
    tab1_primary.title_override = "surface title";
    tab1_primary.tab_title_override = "tab \"title\"\\\t\r\n";

    var tab1_split: Surface = undefined;
    tab1_split.core_surface = undefined;
    tab1_split.core_surface.id = 703;
    tab1_split.host = &host;
    tab1_split.host_id = host.id;
    tab1_split.title = "split title";
    tab1_split.title_override = null;
    tab1_split.tab_title_override = null;

    try host.tabs.append(std.testing.allocator, try Tab.init(std.testing.allocator, 3, &tab0_surface));
    try host.tabs.append(std.testing.allocator, try Tab.init(std.testing.allocator, 4, &tab1_primary));

    const inserted = try SplitTreeSurface.init(std.testing.allocator, &tab1_split);
    defer {
        var cleanup = inserted;
        cleanup.deinit();
    }
    var prev_tree = host.tabs.items[1].tree;
    const next_tree = try prev_tree.split(
        std.testing.allocator,
        host.tabs.items[1].focused,
        .right,
        0.5,
        &inserted,
    );
    host.tabs.items[1].tree = next_tree;
    host.tabs.items[1].focused = host.tabs.items[1].findHandle(&tab1_primary) orelse host.tabs.items[1].focused;
    prev_tree.deinit();

    try app.registry.addHost(std.testing.allocator, &host);
    try app.registry.addWindow(std.testing.allocator, &tab0_surface);
    try app.registry.addWindow(std.testing.allocator, &tab1_primary);

    const json = try app.buildAutomationWindowListJson(std.testing.allocator);
    defer std.testing.allocator.free(json);

    var parsed = try std.json.parseFromSlice(std.json.Value, std.testing.allocator, json, .{});
    defer parsed.deinit();
    const root = parsed.value.object;
    try std.testing.expectEqualStrings("noctty.windows.v3", apprt.ipc.automation_window_list_schema);
    try std.testing.expectEqual(@as(u32, 3), apprt.ipc.automation_window_list_api_version);
    try std.testing.expectEqualStrings("noctty.windows.v3", root.get("schema").?.string);
    try std.testing.expectEqual(@as(i64, 3), root.get("api_version").?.integer);
    const instance = root.get("instance").?.object;
    try std.testing.expectEqual(@as(i64, sys.GetCurrentProcessId()), instance.get("pid").?.integer);
    try std.testing.expectEqualStrings(build_config.version_string, instance.get("version").?.string);
    try std.testing.expectEqualStrings("lane_9", instance.get("class").?.string);

    const windows_json = root.get("windows").?.array.items;
    try std.testing.expectEqual(@as(usize, 1), windows_json.len);
    const window = windows_json[0].object;
    try std.testing.expectEqual(@as(i64, 17), window.get("window_id").?.integer);
    try std.testing.expectEqualStrings("host \"quote\"\\slash\t\r\n", window.get("title").?.string);
    try std.testing.expect(window.get("focused").?.bool);
    try std.testing.expectEqual(@as(i64, 4), window.get("active_tab_id").?.integer);
    try std.testing.expectEqual(@as(i64, 2), window.get("tab_count").?.integer);
    try std.testing.expectEqual(@as(i64, 3), window.get("pane_count").?.integer);
    const tabs = window.get("tabs").?.array.items;
    try std.testing.expectEqual(@as(usize, 2), tabs.len);
    try std.testing.expectEqual(@as(i64, 3), tabs[0].object.get("tab_id").?.integer);
    try std.testing.expect(!tabs[0].object.get("active").?.bool);
    try std.testing.expectEqual(@as(i64, 701), tabs[0].object.get("focused_surface_id").?.integer);
    try std.testing.expectEqual(@as(i64, 1), tabs[0].object.get("pane_count").?.integer);
    const null_pane = tabs[0].object.get("panes").?.array.items[0].object;
    try std.testing.expectEqual(@as(i64, 701), null_pane.get("surface_id").?.integer);
    try std.testing.expect(null_pane.get("focused").?.bool);
    try std.testing.expect(!null_pane.get("active").?.bool);
    try std.testing.expect(null_pane.get("title").? == .null);
    try std.testing.expect(null_pane.get("working_directory").? == .null);
    const active_panes = tabs[1].object.get("panes").?.array.items;
    try std.testing.expectEqual(@as(i64, 4), tabs[1].object.get("tab_id").?.integer);
    try std.testing.expect(tabs[1].object.get("active").?.bool);
    try std.testing.expectEqual(@as(i64, 702), tabs[1].object.get("focused_surface_id").?.integer);
    try std.testing.expectEqual(@as(i64, 2), tabs[1].object.get("pane_count").?.integer);
    try std.testing.expectEqual(@as(usize, 2), active_panes.len);
    try std.testing.expectEqual(@as(i64, 703), active_panes[0].object.get("surface_id").?.integer);
    try std.testing.expectEqualStrings("split title", active_panes[0].object.get("title").?.string);
    try std.testing.expectEqualStrings("home", active_panes[0].object.get("working_directory").?.string);
