test "win32 recovery ledger lock excludes a second holder until released" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try tmp.dir.realpathAlloc(std.testing.allocator, ".");
    defer std.testing.allocator.free(root);
    const target = try std.fs.path.join(std.testing.allocator, &.{ root, "startup-attempts.json" });
    defer std.testing.allocator.free(target);

    var first = (try RecoveryLedgerLock.acquire(std.testing.allocator, target, 0)) orelse
        return error.TestUnexpectedResult;
    // A second acquisition against the same ledger must time out rather than
    // succeed, and must time out promptly: the wait is the bound on how long
    // a startup can be held behind a sibling.
    const started = std.time.milliTimestamp();
    try std.testing.expectEqual(
        @as(?RecoveryLedgerLock, null),
        try RecoveryLedgerLock.acquire(std.testing.allocator, target, 50),
    );
    try std.testing.expect(std.time.milliTimestamp() - started < 1000);
    first.release();

    // Released, the next taker gets it. The sibling file is left behind on
    // purpose so every instance keeps locking the same inode.
    var second = (try RecoveryLedgerLock.acquire(std.testing.allocator, target, 0)) orelse
        return error.TestUnexpectedResult;
    second.release();
    const lock_path = try std.mem.concat(std.testing.allocator, u8, &.{ target, ".lock" });
    defer std.testing.allocator.free(lock_path);
    const lock_file = try std.fs.openFileAbsolute(lock_path, .{});
    lock_file.close();
}

test "win32 recovery startup fails open when the ledger lock is held" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try tmp.dir.realpathAlloc(std.testing.allocator, ".");
    defer std.testing.allocator.free(root);
    const target = try std.fs.path.join(std.testing.allocator, &.{ root, "startup-attempts.json" });
    defer std.testing.allocator.free(target);
    const pending = try std.mem.concat(std.testing.allocator, u8, &.{ target, ".pending-feed" });
    defer std.testing.allocator.free(pending);

    // Three unresolved attempts on disk: enough for `decide` to pick safe
    // mode, so the read-only decision is observable even when nothing is
    // recorded.
    const disk_attempts = [_]win32_recovery.StartupAttempt{
        .{ .started_at_unix_ms = 100 },
        .{ .started_at_unix_ms = 110 },
        .{ .started_at_unix_ms = 120 },
    };
    const disk_json = try win32_recovery.encodeAlloc(std.testing.allocator, .{ .attempts = &disk_attempts });
    defer std.testing.allocator.free(disk_json);
    try win32_session_persistence.writeFileInPlace(target, disk_json);
    try win32_session_persistence.writeFileInPlace(pending, disk_json);

    var held = (try RecoveryLedgerLock.acquire(std.testing.allocator, target, 0)) orelse
        return error.TestUnexpectedResult;
    const blocked = beginRecoveryStartupAtPath(std.testing.allocator, target, null, 200, 20);
    held.release();

    // Decision still made from the ledger; nothing appended, nothing
    // replaced, nothing folded away.
    try std.testing.expectEqual(win32_recovery.Decision.safe_mode, blocked.decision);
    try std.testing.expectEqual(@as(usize, 0), blocked.count);
    const untouched = try std.fs.cwd().readFileAlloc(std.testing.allocator, target, 64 * 1024);
    defer std.testing.allocator.free(untouched);
    try std.testing.expectEqualStrings(disk_json, untouched);
    const pending_file = try std.fs.openFileAbsolute(pending, .{});
    pending_file.close();

    // With the lock free the same launch records itself and folds the
    // retained record.
    const recorded = beginRecoveryStartupAtPath(std.testing.allocator, target, null, 200, recovery_ledger_lock_wait_ms);
    try std.testing.expectEqual(@as(usize, 4), recorded.count);
    try std.testing.expectError(error.FileNotFound, std.fs.openFileAbsolute(pending, .{}));
}

const ConcurrentStartupWorker = struct {
    target: []const u8,
    now: u64,
    count: usize = 0,

    fn run(self: *ConcurrentStartupWorker) void {
        const startup = beginRecoveryStartupAtPath(std.testing.allocator, self.target, null, self.now, recovery_ledger_lock_wait_ms);
        self.count = startup.count;
    }
};

test "win32 recovery concurrent startups never lose each other's attempt" {
    // The Greptile reproduction: independent ledger readers that append and
    // replace the same target. Each worker is a full `beginRecoveryStartupAtPath`
    // transaction, all released at once; without the lock the final ledger
    // holds fewer attempts than workers, because a later replace carries only
    // its own snapshot. One shared timestamp keeps `appendBounded`'s ordering
    // check out of the picture, so the only thing that can shrink the count
    // is a lost update.
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try tmp.dir.realpathAlloc(std.testing.allocator, ".");
    defer std.testing.allocator.free(root);
    const target = try std.fs.path.join(std.testing.allocator, &.{ root, "startup-attempts.json" });
    defer std.testing.allocator.free(target);

    const worker_count = 6;
    var workers: [worker_count]ConcurrentStartupWorker = undefined;
    var threads: [worker_count]std.Thread = undefined;
    for (&workers) |*worker| worker.* = .{ .target = target, .now = 500 };
    for (&threads, &workers) |*thread, *worker| {
        thread.* = try std.Thread.spawn(.{}, ConcurrentStartupWorker.run, .{worker});
    }
    for (&threads) |*thread| thread.join();

    // Every worker got in (nobody timed out), and every worker's snapshot
    // was one larger than the previous one's — the serialised order.
    var seen = [_]bool{false} ** worker_count;
    for (workers) |worker| {
        try std.testing.expect(worker.count >= 1 and worker.count <= worker_count);
        try std.testing.expect(!seen[worker.count - 1]);
        seen[worker.count - 1] = true;
    }

    const final = try std.fs.cwd().readFileAlloc(std.testing.allocator, target, 64 * 1024);
    defer std.testing.allocator.free(final);
    var parsed = try win32_recovery.parseAlloc(std.testing.allocator, final);
    defer parsed.deinit();
    try std.testing.expectEqual(@as(usize, worker_count), parsed.value.attempts.len);
    // Same clock reading, distinct attempts: a marker targets one by its start.
    for (parsed.value.attempts[1..], 1..) |attempt, i| {
        try std.testing.expect(attempt.started_at_unix_ms > parsed.value.attempts[i - 1].started_at_unix_ms);
    }
}

test "win32 recovery fallback failure is consumed by next startup" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try tmp.dir.realpathAlloc(std.testing.allocator, ".");
    defer std.testing.allocator.free(root);
    const target = try std.fs.path.join(std.testing.allocator, &.{ root, "startup-attempts.json" });
    defer std.testing.allocator.free(target);
    const disk_attempts = [_]win32_recovery.StartupAttempt{
        .{ .started_at_unix_ms = 100, .phase = .window_created },
    };
    const disk_json = try win32_recovery.encodeAlloc(std.testing.allocator, .{ .attempts = &disk_attempts });
    defer std.testing.allocator.free(disk_json);
    try win32_session_persistence.writeFileInPlace(target, disk_json);

    const target_w = try std.unicode.utf8ToUtf16LeAllocZ(std.testing.allocator, target);
    defer std.testing.allocator.free(target_w);
    const held = windows.kernel32.CreateFileW(
        target_w.ptr,
        windows.GENERIC_READ,
        windows.FILE_SHARE_READ,
        null,
        windows.OPEN_EXISTING,
        windows.FILE_ATTRIBUTE_NORMAL,
        null,
    );
    if (held == windows.INVALID_HANDLE_VALUE) return error.TestUnexpectedResult;
    var ready_attempts = [_]win32_recovery.StartupAttempt{
        .{
            .started_at_unix_ms = 100,
            .ready_at_unix_ms = 150,
            .phase = .ready,
        },
    };
    if (persistRecoveryRecordAtPath(std.testing.allocator, target, &ready_attempts)) {
        _ = windows.CloseHandle(held);
        return error.TestExpectedError;
    } else |_| {
        _ = windows.CloseHandle(held);
    }
    try std.testing.expectEqual(win32_recovery.StartupPhase.ready_persist_failed, ready_attempts[0].phase);
    try std.testing.expect(ready_attempts[0].last_win32_error != null);

    const startup = beginRecoveryStartupAtPath(std.testing.allocator, target, null, 200, recovery_ledger_lock_wait_ms);
    try std.testing.expectEqual(win32_recovery.Decision.normal, startup.decision);
    try std.testing.expectEqual(@as(usize, 2), startup.count);
    try std.testing.expectEqual(@as(?u64, 150), startup.attempts[0].ready_at_unix_ms);
    try std.testing.expectEqual(win32_recovery.StartupPhase.ready_persist_failed, startup.attempts[0].phase);
    try std.testing.expect(startup.attempts[0].last_win32_error != null);

    // The dead replacement source is dropped by the writer, and the folded
    // `.pending-` diagnosis is dropped by the next startup: no leftovers.
    var root_dir = try std.fs.openDirAbsolute(root, .{ .iterate = true });
    defer root_dir.close();
    var entries = root_dir.iterate();
    while (try entries.next()) |entry| {
        try std.testing.expect(!std.mem.startsWith(u8, entry.name, "startup-attempts.json.tmp-"));
        try std.testing.expect(!std.mem.startsWith(u8, entry.name, "startup-attempts.json.pending-"));
    }
}

// Why the ready-marker retry below exists.
//
// Observed: a ledger write fails in one of two shapes, and only one of them
// leaves anything behind for a later launch.
//
//   C2  `ReplaceFileW`/`MoveFileExW` failed and the in-place fallback also
//       failed. `writeFileAtomicOrInPlace` has already set `atomic_failure`,
//       so `persistRecoveryRecordAtPath` takes its retention branch, writes a
//       `.pending-` record, and the next startup folds it back in. Covered by
//       "win32 recovery fallback failure is consumed by next startup".
//
//   C1  The write failed *before* the replacement was ever attempted: the
//       temp file could not be created, written or synced. `atomic_failure`
//       is still null, so `if (atomic_failure) |failure|` is skipped, no
//       `.pending-` record is written, and the ready marker exists nowhere.
//       That is what this test pins.
//
// What follows from it, separately: the `.pending-` fold is a C2 mechanism
// only, so C1 has no cross-launch recovery at all and the in-session retry is
// its only mitigation. A retry rebuilds the temp path from a fresh nonce, so a
// transient hold on the ledger directory — an anti-virus or backup agent,
// `ERROR_DELETE_PENDING` on a leftover name, a redirected-profile hiccup — can
// clear before the next attempt runs.
//
// Also inference, not observation: C1 is consistent with #149's reported
// symptom, a ledger holding 16 attempts and zero ready markers with no
// recorded cause. It was never confirmed to be C1 — the pre-fix schema
// recorded no error — so treat this as a reason not to remove the mitigation,
// not as a diagnosis.
//
// Two consequences for anyone editing this area:
//
//   - Do not delete the retry on the grounds that the `.pending-` fold already
//     recovers a failed write. It recovers C2. This test is C1.
//   - Retaining a `.pending-` record unconditionally, rather than only when
//     `atomic_failure` is set, looks like a cheaper close but is only partial:
//     in C1 the directory itself is usually what failed, so writing
//     `.pending-` into that same directory fails too. It would cover only the
//     narrow case where one temp filename was unusable but another works.
test "win32 recovery ready-write failure before atomic replace leaves nothing for the pending fold" {
    // Hermetic: everything lives under a temp dir this test owns, and
    // `tmp.cleanup()` runs on the failure path too. The real
    // `%LOCALAPPDATA%\noctty\` is never touched — `persistRecoveryRecordAtPath`
    // takes its path as a parameter precisely so this is possible.
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try tmp.dir.realpathAlloc(std.testing.allocator, ".");
    defer std.testing.allocator.free(root);

    // A regular file where the ledger's parent directory should be. That makes
    // `makeDirAbsolute` report PathAlreadyExists, which is swallowed, and then
    // makes the temp-file creation fail — a failure strictly before
    // `replaceFileAtomic`, so `atomic_failure` is never set. This is the only
    // way found to reach C1 deterministically; a sharing violation on the temp
    // name cannot be staged, because the name carries a fresh pid+nonce.
    {
        var blocker = try tmp.dir.createFile("blocker", .{});
        blocker.close();
    }
    const target = try std.fs.path.join(
        std.testing.allocator,
        &.{ root, "blocker", "startup-attempts.json" },
    );
    defer std.testing.allocator.free(target);

    var ready = [_]win32_recovery.StartupAttempt{
        .{ .started_at_unix_ms = 100, .ready_at_unix_ms = 150, .phase = .ready },
    };
    // The error must escape: it is what drives `resolveRecoveryStartup` to
    // spend a retry rather than treat the launch as resolved. The identity of
    // the error is not the contract — which one Windows reports for a path
    // under a regular file is its business — only that it is not swallowed.
    if (persistRecoveryRecordAtPath(std.testing.allocator, target, &ready)) {
        return error.TestExpectedError;
    } else |_| {}

    // And nothing was left behind for a later startup to fold, which is the
    // whole point: without the retry this ready marker is simply gone.
    var dir = try std.fs.openDirAbsolute(root, .{ .iterate = true });
    defer dir.close();
    var entries = dir.iterate();
    while (try entries.next()) |entry| {
        try std.testing.expect(std.mem.indexOf(u8, entry.name, recovery_pending_suffix) == null);
        try std.testing.expect(std.mem.indexOf(u8, entry.name, ".tmp-") == null);
    }
}

test "win32 recovery ready marker will not spend an attempt before its deadline" {
    // No retry armed yet: the first attempt runs on the startup tick.
    try std.testing.expect(recoveryRetryDue(null, 0));
    try std.testing.expect(recoveryRetryDue(null, std.math.maxInt(u64)));

    // A retry is armed for `now + delay`. Unrelated ticks — PTY output, a
    // keystroke — reach `resolveRecoveryStartup` first on a busy terminal and
    // must be refused, or the budget is spent with no spacing at all.
    const armed_at: u64 = 1_000;
    const deadline: u64 = armed_at + recovery_ready_retry_delay_ms;
    try std.testing.expect(!recoveryRetryDue(deadline, armed_at));
    try std.testing.expect(!recoveryRetryDue(deadline, deadline - 1));
    try std.testing.expect(recoveryRetryDue(deadline, deadline));
    try std.testing.expect(recoveryRetryDue(deadline, deadline + 1));
}

test "win32 recovery gives up rather than busy-retrying when no timer can be armed" {
    // Budget survives and a spaced retry was armed: keep going.
    try std.testing.expectEqual(
        RecoveryFailureAction.retry_scheduled,
        recoveryFailurePolicy(false, true),
    );

    // Budget survives but nothing could be armed. Falling back to an
    // immediate wake would re-tick with no delay and burn every remaining
    // attempt in microseconds, which is the busy retry the delay exists to
    // prevent — and it would still end unresolved. Stop instead, so the
    // safe-mode notice is released once with an honest single failure.
    try std.testing.expectEqual(
        RecoveryFailureAction.give_up_unschedulable,
        recoveryFailurePolicy(false, false),
    );

    // Exhaustion wins regardless of whether a timer could have been armed.
    try std.testing.expectEqual(
        RecoveryFailureAction.give_up_exhausted,
        recoveryFailurePolicy(true, false),
    );
    try std.testing.expectEqual(
        RecoveryFailureAction.give_up_exhausted,
        recoveryFailurePolicy(true, true),
    );
}

test "win32 recovery safe mode always has a visible notice" {
    try std.testing.expectEqual(@as(?[:0]const u16, null), recoverySafeModeNotice(.normal, false));
    try std.testing.expectEqualSlices(u16, recovery_safe_mode_banner_w, recoverySafeModeNotice(.safe_mode, false).?);
    // The notice names the moved session only when it was moved.
    try std.testing.expectEqualSlices(
        u16,
        recovery_session_set_aside_banner_w,
        recoverySafeModeNotice(.quarantine_session, true).?,
    );
    try std.testing.expectEqualSlices(u16, recovery_safe_mode_banner_w, recoverySafeModeNotice(.quarantine_session, false).?);
}

test "win32 a sign-out latches the session snapshot, and a Restart Manager close saves once and leaves the quit to the loop" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    var core_app: CoreApp = undefined;
    var app: App = undefined;
    var host: Host = undefined;
    var surface: Surface = undefined;
    var session: TestSession = .{};
    try session.init(.{
        .core_app = &core_app,
        .app = &app,
        .hosts = &.{.{ .storage = &host, .register = true }},
        .surfaces = &.{.{ .storage = &surface, .host = &host, .register = true }},
        .tabs = &.{.{ .host = &host, .surface = &surface, .id = 1 }},
    });
    defer session.deinit();
    app.running = true;
    // Not an owner, so the saves themselves write nothing here.
    const close_app: LPARAM = @bitCast(c.ENDSESSION_CLOSEAPP);

    // Called off after the query agreed: nothing is saved, latched or closed.
    app.end_session_prepared = true;
    app.onEndSession(false, close_app);
    try std.testing.expect(!app.end_session_prepared);
    try std.testing.expect(!app.session_ending);
    try std.testing.expect(!app.end_session_quit_pending);
    try std.testing.expectEqual(@as(u32, 0), app.test_session_saves_as_it_ends);

    // Committed: every window is saved once, while whole, the snapshot is
    // latched, and the quit is left to the message loop.
    app.onEndSession(true, close_app);
    try std.testing.expect(app.session_ending);
    try std.testing.expect(app.end_session_quit_pending);
    try std.testing.expectEqual(@as(u32, 1), app.test_session_saves_as_it_ends);
    try std.testing.expectEqual(@as(usize, 1), app.registry.hosts.items.len);
    try std.testing.expect(app.running);
    // Another window's copy of the message saves nothing more, and a query
    // that follows the commit agrees.
    app.onEndSession(true, close_app);
    try std.testing.expectEqual(@as(u32, 1), app.test_session_saves_as_it_ends);
    try std.testing.expect(app.onQueryEndSession(close_app));

    // A real sign-out is final: nothing saves after it, a Restart Manager
    // close included, and nothing quits.
    app.session_ending = false;
    app.end_session_quit_pending = false;
    app.session_state_saved_before_last_host_close = false;
    try std.testing.expect(app.onQueryEndSession(0));
    app.onEndSession(true, 0);
    try std.testing.expect(app.session_ending);
    try std.testing.expect(!app.end_session_quit_pending);
    app.onEndSession(true, close_app);
    try std.testing.expect(!app.end_session_quit_pending);
    try std.testing.expectEqual(@as(u32, 1), app.test_session_saves_as_it_ends);

    // The display-change checkpoint every host receives saves once a second.
    const now = sys.GetTickCount64();
    app.session_checkpoint_ms = now - 500;
    app.checkpointSessionState();
    try std.testing.expectEqual(now - 500, app.session_checkpoint_ms.?);
    app.session_checkpoint_ms = now - 1500;
    app.checkpointSessionState();
    try std.testing.expect(app.session_checkpoint_ms.? >= now);
}

test "win32 a Restart Manager query agrees only when a quit would ask nothing, and never waits for a renderer lock" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    var core_app: CoreApp = undefined;
    var app: App = undefined;
    var host_a: Host = undefined;
    var host_b: Host = undefined;
    var quick: Host = undefined;
    var front: Surface = undefined;
    var behind: Surface = undefined;
    var other: Surface = undefined;
    var dropdown: Surface = undefined;
    var session: TestSession = .{};
    try session.init(.{
        .core_app = &core_app,
        .app = &app,
        .hosts = &.{
            .{ .storage = &host_a, .id = 1, .register = true },
            .{ .storage = &host_b, .id = 2, .register = true },
            .{ .storage = &quick, .id = 3, .register = true },
        },
        .surfaces = &.{
            .{ .storage = &front, .host = &host_a, .register = true },
            .{ .storage = &behind, .host = &host_a, .register = true, .window_visible = false },
            .{ .storage = &other, .host = &host_b, .register = true },
            .{ .storage = &dropdown, .host = &quick, .register = true },
        },
        .tabs = &.{
            .{ .host = &host_a, .surface = &front, .id = 1 },
            .{ .host = &host_a, .surface = &behind, .id = 2 },
            .{ .host = &host_b, .surface = &other, .id = 3 },
            .{ .host = &quick, .surface = &dropdown, .id = 4 },
        },
    });
    defer session.deinit();
    quick.quick_terminal = true;
    app.running = true;
    app.message_loop_started = true;

    // The query reaches window A's procedure, as Restart Manager sends it.
    const hwnd = try createTestHostWindow();
    defer _ = sys.DestroyWindow(hwnd);
    setWindowData(hwnd, &host_a);
    defer setWindowData(hwnd, null);
    const close_app: LPARAM = @bitCast(c.ENDSESSION_CLOSEAPP);
    const Query = struct {
        fn send(window: HWND, lParam: LPARAM) LRESULT {
            return hostWindowProc(window, c.WM_QUERYENDSESSION, 0, lParam);
        }
    };

    // Nothing running anywhere: agree.
    try std.testing.expectEqual(@as(LRESULT, 1), Query.send(hwnd, close_app));
    try std.testing.expect(app.end_session_prepared);

    // A terminal a quit would ask about declines: in another window, in a
    // tab behind, or in the quick terminal. A sign-out is never declined.
    // `readonly` stands in for a busy terminal; the cores are cleared before
    // anything else reads them.
    for ([_]*Surface{ &other, &behind, &dropdown }) |busy| {
        busy.core_surface.readonly = true;
        busy.core_initialized = true;
        const answer = Query.send(hwnd, close_app);
        const sign_out = Query.send(hwnd, 0);
        busy.core_initialized = false;
        busy.core_surface.readonly = false;
        try std.testing.expectEqual(@as(LRESULT, 0), answer);
        try std.testing.expectEqual(@as(LRESULT, 1), sign_out);
        try std.testing.expect(!app.end_session_prepared);
    }

    // A terminal whose renderer lock is held counts as busy, and the query
    // does not wait for it: the holder can be this thread, below the sent
    // message. The lock is held here, so the core is read no further.
    var renderer_mutex: std.Thread.Mutex = .{};
    other.core_surface.renderer_state.mutex = &renderer_mutex;
    other.core_surface.config.confirm_close_surface = .true;
    other.core_surface.child_exited = false;
    renderer_mutex.lock();
    other.core_initialized = true;
    const locked = Query.send(hwnd, close_app);
    other.core_initialized = false;
    renderer_mutex.unlock();
    try std.testing.expectEqual(@as(LRESULT, 0), locked);

    // Unsaved Settings edits decline: a value typed and not saved, and a
    // conflict with the file. Nothing here touches the window handle.
    app.settings_window.hwnd = @ptrFromInt(0x1000);
    defer app.settings_window.hwnd = null;
    app.settings_window.raw_scalar_dirty[0] = true;
    const dirty = Query.send(hwnd, close_app);
    app.settings_window.raw_scalar_dirty[0] = false;
    app.settings_window.owned_conflict[0] = true;
    const conflict = Query.send(hwnd, close_app);
    app.settings_window.owned_conflict[0] = false;
    try std.testing.expectEqual(@as(LRESULT, 0), dirty);
    try std.testing.expectEqual(@as(LRESULT, 0), conflict);
    try std.testing.expectEqual(@as(LRESULT, 1), Query.send(hwnd, close_app));

    // Before the message loop starts, the startup restore or the first
    // window is still being made.
    app.message_loop_started = false;
    try std.testing.expectEqual(@as(LRESULT, 0), Query.send(hwnd, close_app));
    app.message_loop_started = true;

    // A quit or an update apply already under way agrees: it ends the process
    // itself, whatever is running.
    other.core_surface.readonly = true;
    other.core_initialized = true;
    app.update_apply_in_flight = true;
    const applying = Query.send(hwnd, close_app);
    app.update_apply_in_flight = false;
    app.running = false;
    const quitting = Query.send(hwnd, close_app);
    app.running = true;
    other.core_initialized = false;
    other.core_surface.readonly = false;
    try std.testing.expectEqual(@as(LRESULT, 1), applying);
    try std.testing.expectEqual(@as(LRESULT, 1), quitting);

    // The session's owner declines when the snapshot cannot be written (a
    // test has no LOCALAPPDATA, so every write fails here)...
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try tmp.dir.realpathAlloc(std.testing.allocator, ".");
    defer std.testing.allocator.free(root);
    const state_path = try std.fs.path.join(std.testing.allocator, &.{ root, "session-state.json" });
    defer std.testing.allocator.free(state_path);
    app.config.@"window-save-state" = .always;
    app.session_owner = (try SessionOwnerLock.acquire(std.testing.allocator, state_path)).?;
    defer app.releaseSessionOwnership();
    app.end_session_prepared = false;
    app.session_checkpoint_ms = null;
    try std.testing.expectEqual(@as(LRESULT, 0), Query.send(hwnd, close_app));
    try std.testing.expect(app.session_checkpoint_ms != null);
    // ...and a later query of a round that agreed does not save again.
    app.end_session_prepared = true;
    app.session_checkpoint_ms = null;
    try std.testing.expectEqual(@as(LRESULT, 1), Query.send(hwnd, close_app));
    try std.testing.expectEqual(@as(?u64, null), app.session_checkpoint_ms);
    // With nothing left to write (the last window saved as it went), it
    // agrees.
    app.end_session_prepared = false;
    app.session_state_saved_before_last_host_close = true;
    try std.testing.expectEqual(@as(LRESULT, 1), Query.send(hwnd, close_app));
}

test "win32 the lifecycle window is a top-level window that never shows and answers end-session messages for the app" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;
    // On a desktop of its own: if the window did show, nobody would see it.
    try runOnHiddenDesktop(struct {
        extern "user32" fn GetDesktopWindow() callconv(.winapi) HWND;
        const ga_parent: u32 = 1;

        fn body() !void {
            var core_app: CoreApp = undefined;
            var app: App = undefined;
            var host: Host = undefined;
            var surface: Surface = undefined;
            var session: TestSession = .{};
            try session.init(.{
                .core_app = &core_app,
                .app = &app,
                .hosts = &.{.{ .storage = &host, .register = true }},
                .surfaces = &.{.{ .storage = &surface, .host = &host, .register = true }},
                .tabs = &.{.{ .host = &host, .surface = &surface, .id = 1 }},
            });
            defer session.deinit();
            // The same call `run` makes in every mode, so the lifecycle
            // window comes with the message window or not at all.
            try app.openAppWindows();
            defer {
                const delivery = app.delivery;
                app.closeAppWindows();
                app.delivery = null;
                if (delivery) |d| d.release();
            }
            const hwnd = app.lifecycle_hwnd orelse return error.TestUnexpectedResult;
            const message_hwnd = app.registry.message_hwnd orelse return error.TestUnexpectedResult;

            // A child of the desktop, not of the message-only parent, so
            // Windows sends it what it sends every top-level window; a tool
            // window, kept off the taskbar and Alt+Tab. The message window
            // stays message-only.
            try std.testing.expectEqual(GetDesktopWindow(), sys.GetAncestor(hwnd, ga_parent).?);
            try std.testing.expect(sys.GetAncestor(message_hwnd, ga_parent) != GetDesktopWindow());
            const ex_style: usize = @bitCast(sys.GetWindowLongPtrW(hwnd, c.GWL_EXSTYLE));
            try std.testing.expect(ex_style & c.WS_EX_TOOLWINDOW != 0);
            try std.testing.expect(sys.IsWindowVisible(hwnd) == 0);
            // Asked to show, whichever way, it stays hidden.
            _ = sys.ShowWindow(hwnd, c.SW_SHOWNOACTIVATE);
            try std.testing.expect(sys.IsWindowVisible(hwnd) == 0);
            _ = sys.SetWindowPos(hwnd, null, 0, 0, 0, 0, c.SWP_NOMOVE | c.SWP_NOSIZE | c.SWP_NOZORDER | c.SWP_NOACTIVATE | c.SWP_SHOWWINDOW);
            try std.testing.expect(sys.IsWindowVisible(hwnd) == 0);
            // A Restart Manager query reaches the app's controller: with
            // nothing running it agrees, and a terminal a quit would ask about
            // declines. `readonly` stands in for a busy terminal; the core is
            // cleared before anything else reads it.
            app.running = true;
            app.message_loop_started = true;
            const close_app: LPARAM = @bitCast(c.ENDSESSION_CLOSEAPP);
            try std.testing.expectEqual(@as(LRESULT, 1), sys.SendMessageW(hwnd, c.WM_QUERYENDSESSION, 0, close_app));
            try std.testing.expect(app.end_session_prepared);
            surface.core_surface.readonly = true;
            surface.core_initialized = true;
            const busy = sys.SendMessageW(hwnd, c.WM_QUERYENDSESSION, 0, close_app);
            const sign_out = sys.SendMessageW(hwnd, c.WM_QUERYENDSESSION, 0, 0);
            surface.core_initialized = false;
            surface.core_surface.readonly = false;
            try std.testing.expectEqual(@as(LRESULT, 0), busy);
            try std.testing.expectEqual(@as(LRESULT, 1), sign_out);
            try std.testing.expect(!app.end_session_prepared);

            // So does WM_ENDSESSION: called off, then committed.
            try std.testing.expectEqual(@as(LRESULT, 1), sys.SendMessageW(hwnd, c.WM_QUERYENDSESSION, 0, close_app));
            _ = sys.SendMessageW(hwnd, c.WM_ENDSESSION, 0, close_app);
            try std.testing.expect(!app.end_session_prepared);
            try std.testing.expect(!app.end_session_quit_pending);
            _ = sys.SendMessageW(hwnd, c.WM_ENDSESSION, 1, close_app);
            try std.testing.expect(app.end_session_quit_pending);
            try std.testing.expect(app.session_ending);

            // Restart Manager's fallback WM_CLOSE after a committed close
            // closes nothing: the loop is about to quit.
            try std.testing.expectEqual(@as(LRESULT, 0), sys.SendMessageW(hwnd, c.WM_CLOSE, 0, 0));
            try std.testing.expect(sys.IsWindow(hwnd) != 0);
            try std.testing.expectEqual(hwnd, app.lifecycle_hwnd.?);
            // Any other WM_CLOSE (`taskkill` without /F) reaches
            // DefWindowProc, and the app forgets the destroyed window.
            app.end_session_quit_pending = false;
            _ = sys.SendMessageW(hwnd, c.WM_CLOSE, 0, 0);
            try std.testing.expect(sys.IsWindow(hwnd) == 0);
            try std.testing.expect(app.lifecycle_hwnd == null);
        }
    }.body);
}

test "win32 an -Embedding server agrees to a Restart Manager close only once its class object is revoked, and takes it back when the close does not happen" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    var core_app: CoreApp = undefined;
    var app: App = undefined;
    var host: Host = undefined;
    var surface: Surface = undefined;
    var session: TestSession = .{};
    try session.init(.{
        .core_app = &core_app,
        .app = &app,
        .hosts = &.{.{ .storage = &host, .register = true }},
        .surfaces = &.{.{ .storage = &surface, .host = &host, .register = true }},
        .tabs = &.{.{ .host = &host, .surface = &surface, .id = 1 }},
    });
    defer session.deinit();
    app.running = true;
    app.message_loop_started = true;

    // A stand-in for COM's class table: the real class object is never
    // published, so no default-terminal handoff on this machine can reach
    // the test.
    var table: win32_terminal_handoff.TestClassTable = .{};
    win32_terminal_handoff.test_class_table = &table;
    defer win32_terminal_handoff.test_class_table = null;
    const Queue = struct {
        fn call(_: *anyopaque, _: *win32_terminal_handoff.PendingSession) bool {
            return false;
        }
    };
    var context: u8 = 0;
    var server = win32_terminal_handoff.Server.init(std.testing.allocator, &context, Queue.call);
    try server.register();
    app.terminal_handoff_server = &server;
    defer app.terminal_handoff_server = null;
    const close_app: LPARAM = @bitCast(c.ENDSESSION_CLOSEAPP);
    const Busy = struct {
        fn query(a: *App, s: *Surface) bool {
            s.core_surface.readonly = true;
            s.core_initialized = true;
            defer {
                s.core_initialized = false;
                s.core_surface.readonly = false;
            }
            return a.onQueryEndSession(close_app);
        }
    };

    // A client part way through a handoff (it holds LockServer) declines,
    // and the class object stays registered.
    server.lock_count.store(1, .release);
    try std.testing.expect(!app.onQueryEndSession(close_app));
    server.lock_count.store(0, .release);
    try std.testing.expectEqual(@as(u32, 0), table.revoked);
    try std.testing.expect(server.cookie != null);
    // So does a terminal a quit would ask about, before the class object is
    // touched.
    try std.testing.expect(!Busy.query(&app, &surface));
    try std.testing.expectEqual(@as(u32, 0), table.revoked);

    // Idle: revoked, and the query agrees; another window's query of the
    // same round agrees as well.
    try std.testing.expect(app.onQueryEndSession(close_app));
    try std.testing.expectEqual(@as(u32, 1), table.revoked);
    try std.testing.expect(server.cookie == null);
    try std.testing.expect(app.onQueryEndSession(close_app));
    try std.testing.expectEqual(@as(u32, 1), table.revoked);

    // The close is called off: the class object is registered again, once.
    app.onEndSession(false, close_app);
    try std.testing.expectEqual(@as(u32, 2), table.registered);
    try std.testing.expect(server.cookie != null);
    app.onEndSession(false, close_app);
    try std.testing.expectEqual(@as(u32, 2), table.registered);

    // A later query of the round declines after one agreed: registered again
    // at once, whether or not WM_ENDSESSION(FALSE) follows.
    try std.testing.expect(app.onQueryEndSession(close_app));
    try std.testing.expectEqual(@as(u32, 2), table.revoked);
    try std.testing.expect(!Busy.query(&app, &surface));
    try std.testing.expectEqual(@as(u32, 3), table.registered);
    try std.testing.expect(server.cookie != null);

    // Committed: it stays revoked, and the quit ends the server.
    try std.testing.expect(app.onQueryEndSession(close_app));
    app.onEndSession(true, close_app);
    try std.testing.expect(app.end_session_quit_pending);
    try std.testing.expectEqual(@as(u32, 3), table.registered);
    try std.testing.expect(server.cookie == null);
}

test "win32 agreeing to a Restart Manager close registers the session owner for Setup's restart, once, and nothing else does" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    var core_app: CoreApp = undefined;
    var app: App = undefined;
    var host: Host = undefined;
    var surface: Surface = undefined;
    var session: TestSession = .{};
    try session.init(.{
        .core_app = &core_app,
        .app = &app,
        .hosts = &.{.{ .storage = &host, .register = true }},
        .surfaces = &.{.{ .storage = &surface, .host = &host, .register = true }},
        .tabs = &.{.{ .host = &host, .surface = &surface, .id = 1 }},
    });
    defer session.deinit();
    app.running = true;
    app.message_loop_started = true;

    // kernel32 stand-ins that record each call.
    const Fake = struct {
        var registers: u32 = 0;
        var unregisters: u32 = 0;
        var flags: DWORD = 0;
        var null_line: bool = false;
        var line: [128]u16 = undefined;
        var line_len: usize = 0;
        fn register(cmdline: ?LPCWSTR, dwFlags: DWORD) callconv(.winapi) windows.HRESULT {
            registers += 1;
            flags = dwFlags;
            null_line = cmdline == null;
            line_len = 0;
            if (cmdline) |text| {
                const value = std.mem.span(text);
                @memcpy(line[0..value.len], value);
                line_len = value.len;
            }
            return 0;
        }
        fn unregister() callconv(.winapi) windows.HRESULT {
            unregisters += 1;
            return 0;
        }
    };
    Fake.registers = 0;
    Fake.unregisters = 0;
    app.restart_api = .{ .register = &Fake.register, .unregister = &Fake.unregister };

    // The queries and ends reach the window's procedure, as Restart Manager
    // sends them.
    const hwnd = try createTestHostWindow();
    defer _ = sys.DestroyWindow(hwnd);
    setWindowData(hwnd, &host);
    defer setWindowData(hwnd, null);
    const Rm = struct {
        fn query(window: HWND) LRESULT {
            return hostWindowProc(window, c.WM_QUERYENDSESSION, 0, @bitCast(c.ENDSESSION_CLOSEAPP));
        }
        fn cancel(window: HWND) void {
            _ = hostWindowProc(window, c.WM_ENDSESSION, 0, @bitCast(c.ENDSESSION_CLOSEAPP));
        }
    };

    // The session's owner. A test cannot write the session (no LOCALAPPDATA),
    // so the query's snapshot is the one with nothing to write: the last
    // window saved as it went.
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try tmp.dir.realpathAlloc(std.testing.allocator, ".");
    defer std.testing.allocator.free(root);
    const state_path = try std.fs.path.join(std.testing.allocator, &.{ root, "session-state.json" });
    defer std.testing.allocator.free(state_path);
    app.config.@"window-save-state" = .always;
    app.session_owner = (try SessionOwnerLock.acquire(std.testing.allocator, state_path)).?;
    defer app.releaseSessionOwnership();
    app.session_state_saved_before_last_host_close = true;
    var config_path = "C:\\Users\\A B\\noctty.conf".*;
    var class = "work".*;
    app.cli_config_override_path = &config_path;
    defer app.cli_config_override_path = null;
    app.cli_class = &class;
    defer app.cli_class = null;

    // A decline (a program running in a terminal) registers nothing, and has
    // nothing to take back.
    surface.core_surface.readonly = true;
    surface.core_initialized = true;
    const first_declined = Rm.query(hwnd);
    surface.core_initialized = false;
    surface.core_surface.readonly = false;
    try std.testing.expectEqual(@as(LRESULT, 0), first_declined);
    try std.testing.expectEqual(@as(u32, 0), Fake.registers);
    try std.testing.expectEqual(@as(u32, 0), Fake.unregisters);
    try std.testing.expect(!app.restart_registered);

    // Agreeing registers once, with flags 11 and the launch's config file and
    // class; the other windows' queries of the round do not register again.
    try std.testing.expectEqual(@as(LRESULT, 1), Rm.query(hwnd));
    try std.testing.expectEqual(@as(LRESULT, 1), Rm.query(hwnd));
    try std.testing.expectEqual(@as(u32, 1), Fake.registers);
    try std.testing.expectEqual(@as(DWORD, 11), Fake.flags);
    const expected_line = std.unicode.utf8ToUtf16LeStringLiteral("\"--config-file=C:\\Users\\A B\\noctty.conf\" --class=work");
    try std.testing.expectEqualSlices(u16, expected_line, Fake.line[0..Fake.line_len]);
    // Called off: the registration goes, once.
    Rm.cancel(hwnd);
    Rm.cancel(hwnd);
    try std.testing.expectEqual(@as(u32, 1), Fake.unregisters);

    // Nothing to replay: a NULL command line.
    app.cli_config_override_path = null;
    app.cli_class = null;
    try std.testing.expectEqual(@as(LRESULT, 1), Rm.query(hwnd));
    try std.testing.expectEqual(@as(u32, 2), Fake.registers);
    try std.testing.expect(Fake.null_line);
    // A later query of the round that declines (a program started in a
    // terminal) takes the registration back.
    surface.core_surface.readonly = true;
    surface.core_initialized = true;
    const declined = Rm.query(hwnd);
    surface.core_initialized = false;
    surface.core_surface.readonly = false;
    try std.testing.expectEqual(@as(LRESULT, 0), declined);
    try std.testing.expectEqual(@as(u32, 2), Fake.registers);
    try std.testing.expectEqual(@as(u32, 2), Fake.unregisters);
    try std.testing.expect(!app.restart_registered);

    // An update apply queued or under way relaunches through Setup's
    // /RELAUNCH=1: its query agrees, registers nothing, and takes back a
    // registration an earlier round left.
    try std.testing.expectEqual(@as(LRESULT, 1), Rm.query(hwnd));
    try std.testing.expectEqual(@as(u32, 3), Fake.registers);
    app.update_apply_in_flight = true;
    try std.testing.expectEqual(@as(LRESULT, 1), Rm.query(hwnd));
    app.update_apply_in_flight = false;
    try std.testing.expectEqual(@as(u32, 3), Fake.unregisters);
    app.update_apply_queued = true;
    try std.testing.expectEqual(@as(LRESULT, 1), Rm.query(hwnd));
    app.update_apply_queued = false;
    try std.testing.expectEqual(@as(u32, 3), Fake.registers);
    try std.testing.expectEqual(@as(u32, 3), Fake.unregisters);

    // So does another noctty process's in-app Install: while its Setup runs,
    // an idle owner beside it agrees and is not restarted, and a
    // registration an earlier round left is taken back.
    const OtherInstall = struct {
        var running = false;
        fn probe(_: Allocator) bool {
            return running;
        }
    };
    app.restart_api.installer_apply_running = &OtherInstall.probe;
    try std.testing.expectEqual(@as(LRESULT, 1), Rm.query(hwnd));
    try std.testing.expectEqual(@as(u32, 4), Fake.registers);
    OtherInstall.running = true;
    try std.testing.expectEqual(@as(LRESULT, 1), Rm.query(hwnd));
    try std.testing.expectEqual(@as(u32, 4), Fake.unregisters);
    try std.testing.expect(!app.restart_registered);
    try std.testing.expectEqual(@as(LRESULT, 1), Rm.query(hwnd));
    try std.testing.expectEqual(@as(u32, 4), Fake.registers);
    try std.testing.expectEqual(@as(u32, 4), Fake.unregisters);
    OtherInstall.running = false;

    // A process that does not restore the session agrees and is not
    // restarted: no owner, the default-terminal server, safe mode, and an
    // owner whose only window holds nothing the session records. An owner
    // that registered and then stopped qualifying takes the registration back
    // at its next agreeing query.
    try std.testing.expectEqual(@as(LRESULT, 1), Rm.query(hwnd));
    try std.testing.expectEqual(@as(u32, 5), Fake.registers);
    const owner = app.session_owner;
    app.session_owner = null;
    try std.testing.expectEqual(@as(LRESULT, 1), Rm.query(hwnd));
    try std.testing.expectEqual(@as(u32, 5), Fake.unregisters);
    try std.testing.expect(!app.restart_registered);
    app.session_owner = owner;
    app.embedding_mode = true;
    try std.testing.expectEqual(@as(LRESULT, 1), Rm.query(hwnd));
    app.embedding_mode = false;
    app.safe_mode = true;
    try std.testing.expectEqual(@as(LRESULT, 1), Rm.query(hwnd));
    app.safe_mode = false;
    host.quick_terminal = true;
    try std.testing.expectEqual(@as(LRESULT, 1), Rm.query(hwnd));
    host.quick_terminal = false;
    try std.testing.expectEqual(@as(u32, 5), Fake.registers);

    // A command line too long to register: the close still goes ahead.
    var long_path: [1100]u8 = undefined;
    @memset(&long_path, 'x');
    app.cli_config_override_path = &long_path;
    try std.testing.expectEqual(@as(LRESULT, 1), Rm.query(hwnd));
    app.cli_config_override_path = null;
    try std.testing.expectEqual(@as(u32, 5), Fake.registers);
    try std.testing.expect(!app.restart_registered);

    // A quit under way (the user's, not a committed installer close) ends
    // the process itself and is not restarted: its query agrees and takes
    // back a registration an earlier round left. Likewise once the message
    // loop has stopped.
    try std.testing.expectEqual(@as(LRESULT, 1), Rm.query(hwnd));
    try std.testing.expectEqual(@as(u32, 6), Fake.registers);
    app.quitting = true;
    const quitting_query = Rm.query(hwnd);
    app.quitting = false;
    try std.testing.expectEqual(@as(LRESULT, 1), quitting_query);
    try std.testing.expectEqual(@as(u32, 6), Fake.unregisters);
    try std.testing.expect(!app.restart_registered);
    try std.testing.expectEqual(@as(LRESULT, 1), Rm.query(hwnd));
    try std.testing.expectEqual(@as(u32, 7), Fake.registers);
    app.running = false;
    const stopped_query = Rm.query(hwnd);
    app.running = true;
    try std.testing.expectEqual(@as(LRESULT, 1), stopped_query);
    try std.testing.expectEqual(@as(u32, 7), Fake.registers);
    try std.testing.expectEqual(@as(u32, 7), Fake.unregisters);
    try std.testing.expect(!app.restart_registered);

    // A sign-out, shutdown or reboot (no ENDSESSION_CLOSEAPP) takes back a
    // registration a round left, at its query or at its end, so Windows'
    // option to restart apps at sign-in does not restart noctty.
    try std.testing.expectEqual(@as(LRESULT, 1), Rm.query(hwnd));
    try std.testing.expectEqual(@as(u32, 8), Fake.registers);
    const logoff: LPARAM = @bitCast(@as(usize, 0x80000000)); // ENDSESSION_LOGOFF
    try std.testing.expectEqual(@as(LRESULT, 1), hostWindowProc(hwnd, c.WM_QUERYENDSESSION, 0, logoff));
    try std.testing.expectEqual(@as(u32, 8), Fake.unregisters);
    try std.testing.expect(!app.restart_registered);
    try std.testing.expectEqual(@as(LRESULT, 1), Rm.query(hwnd));
    try std.testing.expectEqual(@as(u32, 9), Fake.registers);
    _ = hostWindowProc(hwnd, c.WM_ENDSESSION, 1, 0);
    try std.testing.expect(app.session_ending);
    app.session_ending = false;
    try std.testing.expectEqual(@as(u32, 9), Fake.unregisters);
    try std.testing.expect(!app.restart_registered);

    // A committed close keeps the registration, since Setup's restart step
    // reads it after noctty has gone: not taken back by the commit
    // (WM_ENDSESSION(TRUE) with ENDSESSION_CLOSEAPP), by a later query of
    // the same round, or by one after the quit began.
    try std.testing.expectEqual(@as(LRESULT, 1), Rm.query(hwnd));
    try std.testing.expectEqual(@as(u32, 10), Fake.registers);
    try std.testing.expectEqual(@as(u32, 9), Fake.unregisters);
    defer {
        app.session_ending = false;
        app.end_session_quit_pending = false;
        app.quitting = false;
        app.running = true;
    }
    _ = hostWindowProc(hwnd, c.WM_ENDSESSION, 1, @bitCast(c.ENDSESSION_CLOSEAPP));
    try std.testing.expect(app.session_ending);
    try std.testing.expect(app.end_session_quit_pending);
    try std.testing.expect(app.restart_registered);
    try std.testing.expectEqual(@as(LRESULT, 1), Rm.query(hwnd));
    app.quitting = true;
    app.running = false;
    try std.testing.expectEqual(@as(LRESULT, 1), Rm.query(hwnd));
    try std.testing.expectEqual(@as(u32, 10), Fake.registers);
    try std.testing.expectEqual(@as(u32, 9), Fake.unregisters);
    try std.testing.expect(app.restart_registered);
    // A sign-out, shutdown or reboot that begins before noctty has gone
    // still takes it back.
    _ = hostWindowProc(hwnd, c.WM_ENDSESSION, 1, 0);
    try std.testing.expectEqual(@as(u32, 10), Fake.unregisters);
    try std.testing.expect(!app.restart_registered);
}

test "win32 a saved window rect on a monitor that is gone moves to the nearest work area" {
    const grab = restore_grab;
    // A laptop's screen with a second monitor to its left, taskbar at the bottom.
    const left: RECT = .{ .left = -1920, .top = 0, .right = 0, .bottom = 1040 };
    const main_work: RECT = .{ .left = 0, .top = 0, .right = 1920, .bottom = 1040 };
    const works = [_]RECT{ main_work, left };
    const wide: RECT = .{ .left = 100, .top = 100, .right = 900, .bottom = 700 };

    // Where there is a monitor, the rect is kept as saved.
    try std.testing.expectEqualDeep(wide, restoredRectOnScreen(wide, &works, grab));
    const straddling: RECT = .{ .left = -400, .top = 50, .right = 400, .bottom = 650 };
    try std.testing.expectEqualDeep(straddling, restoredRectOnScreen(straddling, &works, grab));
    // A snapped window overhangs its monitor by its invisible frame.
    const snapped: RECT = .{ .left = -7, .top = 0, .right = 967, .bottom = 1047 };
    try std.testing.expectEqualDeep(snapped, restoredRectOnScreen(snapped, &works, grab));
    // The caption on a monitor and the body hanging off the bottom stays too.
    const hanging: RECT = .{ .left = 100, .top = 900, .right = 900, .bottom = 1500 };
    try std.testing.expectEqualDeep(hanging, restoredRectOnScreen(hanging, &works, grab));

    // Saved on a monitor to the right that was unplugged.
    const unplugged: RECT = .{ .left = 2100, .top = 200, .right = 2900, .bottom = 800 };
    try std.testing.expectEqualDeep(
        RECT{ .left = 1120, .top = 200, .right = 1920, .bottom = 800 },
        restoredRectOnScreen(unplugged, &works, grab),
    );
    // Below every monitor, and above them.
    try std.testing.expectEqualDeep(
        RECT{ .left = 100, .top = 440, .right = 900, .bottom = 1040 },
        restoredRectOnScreen(.{ .left = 100, .top = 3000, .right = 900, .bottom = 3600 }, &works, grab),
    );
    try std.testing.expectEqualDeep(
        RECT{ .left = 100, .top = 0, .right = 900, .bottom = 600 },
        restoredRectOnScreen(.{ .left = 100, .top = -900, .right = 900, .bottom = -300 }, &works, grab),
    );
    // Only a sliver of the title bar on a monitor is not enough to grab.
    try std.testing.expectEqualDeep(
        RECT{ .left = 1120, .top = 100, .right = 1920, .bottom = 700 },
        restoredRectOnScreen(.{ .left = 1900, .top = 100, .right = 2700, .bottom = 700 }, &works, grab),
    );
    // The nearest is the monitor to the left when that is where it was.
    try std.testing.expectEqualDeep(
        RECT{ .left = -1920, .top = 100, .right = -1120, .bottom = 700 },
        restoredRectOnScreen(.{ .left = -4000, .top = 100, .right = -3200, .bottom = 700 }, &works, grab),
    );
    // Larger than the monitor it lands on: capped to it.
    try std.testing.expectEqualDeep(
        left,
        restoredRectOnScreen(.{ .left = -9000, .top = -50, .right = -4000, .bottom = 3000 }, &works, grab),
    );
    // No monitor list, no opinion.
    try std.testing.expectEqualDeep(unplugged, restoredRectOnScreen(unplugged, &.{}, grab));

    // The file can say anything an i32 holds, and a window cannot be that far
    // away: no differences of these overflow.
    const min: i32 = std.math.minInt(i32);
    const max: i32 = std.math.maxInt(i32);
    try std.testing.expectEqualDeep(
        RECT{ .left = -1920, .top = 100, .right = -1120, .bottom = 700 },
        restoredRectOnScreen(.{ .left = min, .top = 100, .right = min + 800, .bottom = 700 }, &works, grab),
    );
    try std.testing.expectEqualDeep(
        RECT{ .left = 1120, .top = 440, .right = 1920, .bottom = 1040 },
        restoredRectOnScreen(.{ .left = max - 800, .top = max - 600, .right = max, .bottom = max }, &works, grab),
    );
    try std.testing.expectEqualDeep(
        main_work,
        restoredRectOnScreen(.{ .left = min, .top = min, .right = -1, .bottom = -1 }, &.{main_work}, grab),
    );
}

test "win32 session state file write replaces through temp file" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    try tmp.dir.writeFile(.{
        .sub_path = "session-state.json",
        .data = "old",
    });
    const path = try tmp.dir.realpathAlloc(std.testing.allocator, "session-state.json");
    defer std.testing.allocator.free(path);

    try writePersistentFileAlloc(std.testing.allocator, path, "new");

    const contents = try tmp.dir.readFileAlloc(std.testing.allocator, "session-state.json", 1024);
    defer std.testing.allocator.free(contents);
    try std.testing.expectEqualStrings("new", contents);
    var iterable_dir = try tmp.dir.openDir(".", .{ .iterate = true });
    defer iterable_dir.close();
    var entries = iterable_dir.iterate();
    while (try entries.next()) |entry| {
        try std.testing.expect(!std.mem.startsWith(u8, entry.name, "session-state.json.tmp-"));
    }
}

test "win32 taskbar progress mapping preserves state and percent" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    const mapped = win32_taskbar_progress.mapProgressReport(.{
        .state = .pause,
        .progress = 35,
    });

    try std.testing.expectEqual(win32_taskbar_progress.TBPF_PAUSED, mapped.flags);
    try std.testing.expectEqual(@as(u64, 35), mapped.value.?.completed);
    try std.testing.expectEqual(@as(u64, 100), mapped.value.?.total);
}

test "win32 taskbar progress mapping removes progress cleanly" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    const mapped = win32_taskbar_progress.mapProgressReport(.{
        .state = .remove,
    });

    try std.testing.expectEqual(win32_taskbar_progress.TBPF_NOPROGRESS, mapped.flags);
    try std.testing.expect(mapped.value == null);
}

test "win32 taskbar progress mapping covers set error and indeterminate" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    const normal = win32_taskbar_progress.mapProgressReport(.{
        .state = .set,
        .progress = 80,
    });
    try std.testing.expectEqual(win32_taskbar_progress.TBPF_NORMAL, normal.flags);
    try std.testing.expectEqual(@as(u64, 80), normal.value.?.completed);
    try std.testing.expectEqual(@as(u64, 100), normal.value.?.total);

    const failed = win32_taskbar_progress.mapProgressReport(.{
        .state = .@"error",
        .progress = 12,
    });
    try std.testing.expectEqual(win32_taskbar_progress.TBPF_ERROR, failed.flags);
    try std.testing.expectEqual(@as(u64, 12), failed.value.?.completed);
    try std.testing.expectEqual(@as(u64, 100), failed.value.?.total);

    const busy = win32_taskbar_progress.mapProgressReport(.{
        .state = .indeterminate,
    });
    try std.testing.expectEqual(win32_taskbar_progress.TBPF_INDETERMINATE, busy.flags);
    try std.testing.expect(busy.value == null);
}

test "win32 activeSurfaceForHost isolates taskbar progress by host and tab" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    var app: App = undefined;
    app.registry.hosts = .empty;
    defer app.registry.hosts.deinit(std.testing.allocator);

    var host_a: Host = undefined;
    host_a.id = 11;
    host_a.tabs = .empty;
    host_a.active_tab = 0;
    defer {
        for (host_a.tabs.items) |*tab| tab.deinit();
        host_a.tabs.deinit(std.testing.allocator);
    }

    var host_b: Host = undefined;
    host_b.id = 22;
    host_b.tabs = .empty;
    host_b.active_tab = 0;
    defer {
        for (host_b.tabs.items) |*tab| tab.deinit();
        host_b.tabs.deinit(std.testing.allocator);
    }

    var host_a_progress: Surface = undefined;
    host_a_progress.core_surface = undefined;
    host_a_progress.core_surface.id = 1001;
    host_a_progress.host = &host_a;
    host_a_progress.host_id = host_a.id;
    host_a_progress.taskbar_progress = .{ .state = .set, .progress = 30 };

    var host_a_idle: Surface = undefined;
    host_a_idle.core_surface = undefined;
    host_a_idle.core_surface.id = 1002;
    host_a_idle.host = &host_a;
    host_a_idle.host_id = host_a.id;
    host_a_idle.taskbar_progress = null;

    var host_b_progress: Surface = undefined;
    host_b_progress.core_surface = undefined;
    host_b_progress.core_surface.id = 2001;
    host_b_progress.host = &host_b;
    host_b_progress.host_id = host_b.id;
    host_b_progress.taskbar_progress = .{ .state = .@"error", .progress = 80 };

    try host_a.tabs.append(std.testing.allocator, try Tab.init(std.testing.allocator, 1, &host_a_progress));
    try host_a.tabs.append(std.testing.allocator, try Tab.init(std.testing.allocator, 2, &host_a_idle));
    try host_b.tabs.append(std.testing.allocator, try Tab.init(std.testing.allocator, 3, &host_b_progress));
    try app.registry.addHost(std.testing.allocator, &host_a);
    try app.registry.addHost(std.testing.allocator, &host_b);

    const host_a_report = app.registry.activeSurfaceForHost(host_a.id).?.taskbar_progress.?;
    try std.testing.expectEqual(win32_taskbar_progress.ProgressState.set, host_a_report.state);
    try std.testing.expectEqual(@as(?u8, 30), host_a_report.progress);

    const host_b_report = app.registry.activeSurfaceForHost(host_b.id).?.taskbar_progress.?;
    try std.testing.expectEqual(win32_taskbar_progress.ProgressState.@"error", host_b_report.state);
    try std.testing.expectEqual(@as(?u8, 80), host_b_report.progress);

    host_a.active_tab = 1;
    try std.testing.expect(app.registry.activeSurfaceForHost(host_a.id).?.taskbar_progress == null);

    const host_b_after_tab_switch = app.registry.activeSurfaceForHost(host_b.id).?.taskbar_progress.?;
    try std.testing.expectEqual(win32_taskbar_progress.ProgressState.@"error", host_b_after_tab_switch.state);
    try std.testing.expectEqual(@as(?u8, 80), host_b_after_tab_switch.progress);
}

