    const max_hover = titlebarButtonVisual(&theme, .maximize, theme.chrome_bg, 1.0, false, false, true);
    try std.testing.expect(max_hover.bg != null);
    try std.testing.expect(max_hover.bg.? != theme.chrome_bg);

    const close_hover = titlebarButtonVisual(&theme, .close, theme.chrome_bg, 1.0, false, false, true);
    try std.testing.expectEqual(rgb(0xC4, 0x2B, 0x1C), close_hover.bg.?);
    try std.testing.expectEqual(rgb(0xFF, 0xFF, 0xFF), close_hover.glyph);

    const hc_close = titlebarButtonVisual(&theme, .close, theme.chrome_bg, 1.0, false, true, true);
    try std.testing.expectEqual(theme.button_active_bg, hc_close.bg.?);
    try std.testing.expectEqual(theme.button_active_fg, hc_close.glyph);
}

test "win32 desiredMoveIndex wraps tab order" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    try std.testing.expectEqual(@as(?usize, 2), desiredMoveIndex(4, 1, 1));
    try std.testing.expectEqual(@as(?usize, 0), desiredMoveIndex(4, 1, -1));
    try std.testing.expectEqual(@as(?usize, 0), desiredMoveIndex(4, 3, 1));
    try std.testing.expectEqual(@as(?usize, 3), desiredMoveIndex(4, 0, -1));
}

test "win32 ordered tab reorder keeps active identity" {
    try std.testing.expectEqual(@as(usize, 3), movedIndexAfterReorder(1, 1, 3));
    try std.testing.expectEqual(@as(usize, 1), movedIndexAfterReorder(2, 0, 3));
    try std.testing.expectEqual(@as(usize, 2), movedIndexAfterReorder(1, 3, 0));
    try std.testing.expectEqual(@as(usize, 0), movedIndexAfterReorder(0, 1, 3));
}

test "win32 goto_split out of a zoomed pane unzooms, or moves the zoom" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    var core_app: CoreApp = undefined;
    var app: App = undefined;
    var host: Host = undefined;
    var surface_a: Surface = undefined;
    var surface_b: Surface = undefined;
    var session: TestSession = .{};
    try session.init(.{
        .core_app = &core_app,
        .app = &app,
        .hosts = &.{.{ .storage = &host, .register = true }},
        .surfaces = &.{
            .{ .storage = &surface_a, .host = &host, .register = true },
            .{ .storage = &surface_b, .host = &host, .register = true },
        },
        .tabs = &.{.{ .host = &host, .surface = &surface_a, .id = 1 }},
    });
    defer session.deinit();
    var inserted = try SplitTreeSurface.init(std.testing.allocator, &surface_b);
    defer inserted.deinit();
    const tab = &host.tabs.items[0];
    const next_tree = try tab.tree.split(std.testing.allocator, .root, .right, 0.5, &inserted);
    tab.tree.deinit();
    tab.tree = next_tree;
    tab.focused = tab.findHandle(&surface_a).?;
    tab.tree.zoom(tab.focused);
    try pushUndoAndRedoBranch(&surface_a.undo_stack, std.testing.allocator, 80);

    // Default: moving to B unzooms, so B is not left hidden behind A. The
    // zoom change is a structural edit and drops the redo branch.
    try std.testing.expect(try app.performAction(.{ .surface = surface_a.core() }, .goto_split, .right));
    try std.testing.expectEqual(@as(?*Surface, &surface_b), tab.focusedSurface());
    try std.testing.expect(tab.tree.zoomed == null);
    try std.testing.expectEqual(@as(usize, 0), surface_a.undo_stack.redoDepth());

    // `split-preserve-zoom = navigation`: the zoom follows to the pane.
    tab.tree.zoom(tab.focused);
    app.config.@"split-preserve-zoom".navigation = true;
    try std.testing.expect(try app.performAction(.{ .surface = surface_b.core() }, .goto_split, .left));
    try std.testing.expectEqual(@as(?*Surface, &surface_a), tab.focusedSurface());
    try std.testing.expectEqual(tab.focused, tab.tree.zoomed.?);
}

test "win32 command palette action parser accepts simple actions" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    const action = try input.Binding.Action.parse("toggle_fullscreen");
    try std.testing.expect(action == .toggle_fullscreen);
}

test "win32 tab overview parser accepts one-based tab numbers" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    try std.testing.expectEqual(@as(usize, 2), try std.fmt.parseUnsigned(usize, "2", 10));
}
